TURATH_CHUNK(4,[{"num":800,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: آتِي بَابَ الْجَنَّةِ يَوْمَ الْقِيَامَةِ فَأَسْتَفْتِحُ فَيَقُولُ الْخَازِنُ: مَنْ أَنْتَ؟ فَأَقُولُ: مُحَمَّدٌ، فَيَقُولُ: بِكَ أُمِرْتُ، لَا أَفْتَحُ لِأَحَدٍ قَبْلَكَ."],"takhrij":"صحيح: رواه مسلم في الإيمان (197) من طرق عن هاشم بن القاسم، حدّثنا سليمان بن المغيرة، عن ثابت، عن أنس بن مالك، فذكره.","grade":"صحيح","chapter_ar":"باب أن النبي ﷺ أول من يفتح له باب الجنة","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (197).","chapter_en":"The Prophet ﷺ Will Be the First for Whom the Gate of Paradise Is Opened","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":21,"content":{"translation":{"en":["Anas ibn Mālik may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “I will come to the gate of Paradise on the Day of Resurrection and ask for it to be opened. The gatekeeper will ask: ‘Who are you?’ I will reply: ‘Muḥammad.’ He will say: ‘I was commanded concerning you; I am not to open it for anyone before you.’”"]}},"tuhfa":{},"full":1,"rep":[647,16344],"tks":"صحيح: رواه مسلم (197)."},{"num":801,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: بُعِثْتُ بِجَوَامِعِ الْكَلِمِ وَنُصِرْتُ بِالرُّعْبِ فَبَيْنَا أَنَا نَائِمٌ أُتِيتُ بِمَفَاتِيحِ خَزَائِنِ الْأَرْضِ فَوُضِعَتْ فِي يَدِي، قَالَ أَبُو هُرَيْرَةَ: وَقَدْ ذَهَبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَنْتُمْ تَنْتَثِلُونَهَا."],"takhrij":"متفق عليه: رواه البخاريّ في الجهاد (2977)، ومسلم في المساجد (523) كلاهما من طرق عن ابن شهاب، عن سعيد بن المسيب، عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب أن النبي ﷺ أُعطي مفاتيح خزائن الأرض","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2977) and Muslim (523).","chapter_en":"The Prophet ﷺ Was Given the Keys to the Treasuries of the Earth","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":22,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “I was sent with concise yet comprehensive speech, and I was aided by fear cast into the enemy. While I was asleep, the keys to the treasuries of the earth were brought to me and placed in my hand.” Abū Hurayrah, may Allah be pleased with him, said: “The Messenger of Allah ﷺ has passed away, and now you are drawing forth those treasures.”"]}},"tuhfa":{},"full":1,"rep":[7832,9632,11714],"tks":"متفق عليه: رواه البخاري (2977)، ومسلم (523)."},{"num":802,"demo":false,"sanad":"","matn":["عَنْ أَبِي عُبَيْدَةَ، عَنْ عَائِشَةَ قَالَ: سَأَلْتُهَا عَنْ قَوْلِهِ تَعَالَى: ﴿إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ﴾ [سورة الكوثر: 1] قَالَتْ: نَهَرٌ أُعْطِيَهُ نَبِيُّكُمْ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَاطِئَاهُ عَلَيْهِ دُرٌّ مُجَوَّفٌ آنِيَتُهُ كَعَدَدِ النُّجُومِ."],"takhrij":"صحيح: رواه البخاريّ (4965) عن خالد بن يزيد الكاهليّ، حدّثنا إسرائيل، عن أبي إسحاق، عن أبي عبيدة، فذكره.","grade":"صحيح","chapter_ar":"باب ذكر الكوثر الذي أعطاه الله نبيه ﷺ وصفاته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (4965).","chapter_en":"Mention of al-Kawthar, Which Allah Gave His Prophet ﷺ, and Its Description","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":23,"content":{"translation":{"en":["Abū ʿUbaydah narrated from ʿĀʾishah may Allah be pleased with her: I asked her about the statement of Allah Most High: “Indeed, We have granted you al-Kawthar.” [Sūrat al-Kawthar 108:1] She replied: “It is a river which your Prophet ﷺ was given. Along its two banks are hollowed pearls, and its vessels are as numerous as the stars.”"]},"intro":{"ar":["قال الله تعالى:","﴿إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ﴾","[الكوثر: ١]"],"en":["Allah Most High said:","“Indeed, We have granted you al-Kawthar.”","[Sūrat al-Kawthar 108:1]"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (4965)."},{"num":803,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: لَمَّا عُرِجَ بِالنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى السَّمَاءِ قَالَ: أَتَيْتُ عَلَى نَهَرٍ حَافَتَاهُ قِبَابُ اللُّؤْلُؤِ مُجَوَّفًا، فَقُلْتُ: مَا هَذَا يَا جِبْرِيلُ؟ قَالَ: هَذَا الْكَوْثَرُ."],"takhrij":"صحيح: رواه البخاريّ في التفسير (4964) عن آدم، حدّثنا شيبان، حدّثنا قتادة، عن أنس، فذكره.","grade":"صحيح","chapter_ar":"باب ذكر الكوثر الذي أعطاه الله نبيه ﷺ وصفاته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī in al-Tafsīr (4964).","chapter_en":"Mention of al-Kawthar, Which Allah Gave His Prophet ﷺ, and Its Description","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":23,"content":{"translation":{"en":["Anas ibn Mālik, may Allah be pleased with him, reported: When the Prophet ﷺ was taken up into heaven, he said: “I came upon a river whose two banks were domes of hollowed pearl. I asked: ‘What is this, O Jibrīl?’ He replied: ‘This is al-Kawthar.’”"]},"buhuth":{"en":["Al-Tirmidhī (3360) also narrated it and added:","“Then he struck his hand into its clay and brought out musk. Then Sidrat al-Muntahā was raised before me, and I saw beside it a tremendous light.”","Al-Tirmidhī said:","“Ḥasan Ṣaḥīḥ.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (4964)."},{"num":804,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: بَيْنَمَا أَنَا أَسِيرُ فِي الْجَنَّةِ، إِذَا أَنَا بِنَهَرٍ حَافَتَاهُ قِبَابُ الدُّرِّ الْمُجَوَّفِ، قُلْتُ: مَا هَذَا يَا جِبْرِيلُ؟ قَالَ: هَذَا الْكَوْثَرُ الَّذِي أَعْطَاكَ رَبُّكَ، فَإِذَا طِينُهُ أَوْ طِيبُهُ مِسْكٌ أَذْفَرُ."],"takhrij":"صحيح: رواه البخاريّ في الرّقاق (6581) عن أبي الوليد وهدبة بن خالد، كلاهما عن همّام، حدّثنا قتادة، حدّثنا أنس بن مالك، فذكره.","grade":"صحيح","chapter_ar":"باب ذكر الكوثر الذي أعطاه الله نبيه ﷺ وصفاته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (6581).","chapter_en":"Mention of al-Kawthar, Which Allah Gave His Prophet ﷺ, and Its Description","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":23,"content":{"translation":{"en":["Anas ibn Mālik may Allah be pleased with him reported that the Prophet ﷺ said: “While I was walking in Paradise, I came upon a river whose two banks were domes of hollowed pearl. I asked: ‘What is this, O Jibrīl?’ He replied: ‘This is al-Kawthar which your Lord has given you.’ Its clay — or its fragrance — was intensely fragrant musk.” Hudbah was uncertain as to which wording was used."]}},"tuhfa":{},"full":1,"rep":[16236],"tks":"صحيح: رواه البخاري (6581)."},{"num":805,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ يَقُولُ: لَيْلَةَ أُسْرِيَ بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ مَسْجِدِ الْكَعْبَةِ. فَذَكَرَ حَدِيثَ الإِسْرَاءِ وَالمِعْرَاجِ بِطُولِه وَجَاءَ فِيهِ: فَإِذَا هُوَ فِي السَّمَاءِ الدُّنْيَا بِنَهَرَيْنِ يَطَّرِدَانِ، فَقَالَ: مَا هَذَانِ النَّهَرَانِ يَا جِبْرِيلُ؟ قَالَ: هَذَا النِّيلُ وَالْفُرَاتُ عُنْصُرُهُمَا، ثُمَّ مَضَى بِهِ فِي السَّمَاءِ، فَإِذَا هُوَ بِنَهَرٍ آخَرَ عَلَيْهِ قَصْرٌ مِنْ لُؤْلُؤٍ وَزَبَرْجَدٍ، فَضَرَبَ يَدَهُ، فَإِذَا هُوَ مِسْكٌ أَذْفَرُ، قَالَ: مَا هَذَا يَا جِبْرِيلُ؟ قَالَ: هَذَا الْكَوْثَرُ الَّذِي خَبَأَ لَكَ رَبُّكَ."],"takhrij":"متفق عليه: رواه البخاريّ في التوحيد (7517)، ومسلم في الإيمان (162) كلاهما من حديث سليمان بن بلال، عن شريك بن عبدالله أنه قال: سمعت ابن مالك يقول: فذكر الحديث بطوله، انظره كاملاً في الإسراء والمعراج.","grade":"متفق عليه","chapter_ar":"باب ذكر الكوثر الذي أعطاه الله نبيه ﷺ وصفاته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7517) and Muslim (162).","chapter_en":"Mention of al-Kawthar, Which Allah Gave His Prophet ﷺ, and Its Description","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":23,"content":{"translation":{"en":["Anas ibn Mālik, may Allah be pleased with him, reported: On the night when the Messenger of Allah ﷺ was taken on the Night Journey from the Sacred Mosque, he mentioned the lengthy ḥadīth of the Night Journey and Ascension. In it is: “In the lowest heaven there were two rivers flowing. He asked: ‘What are these two rivers, O Jibrīl?’ He replied: ‘These are the Nile and the Euphrates at their source.’ Then he took him onward through heaven, and there was another river upon which stood a palace of pearl and emerald. He struck his hand into it, and it was fragrant musk. He asked: ‘What is this, O Jibrīl?’ He replied: ‘This is al-Kawthar which your Lord has stored for you.’”"]},"buhuth":{"en":["The expression:","“their ʿunṣur”","means their source or origin."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (7517)، ومسلم (162)."},{"num":806,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: بَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ بَيْنَ أَظْهُرِنَا، إِذْ أَغْفَى إِغْفَاءَةً، ثُمَّ رَفَعَ رَأْسَهُ مُتَبَسِّمًا، فَقُلْنَا: مَا أَضْحَكَكَ يَا رَسُولَ اللَّهِ؟ قَالَ: أُنْزِلَتْ عَلَيَّ آنِفًا سُورَةٌ، فَقَرَأَ: ﴿بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ. إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ (1) فَصَلِّ لِرَبِّكَ وَانْحَرْ (2) إِنَّ شَانِئَكَ هُوَ الْأَبْتَرُ (3)﴾ [سورة الكوثر: 1، 3]. ثُمَّ قَالَ: أَتَدْرُونَ مَا الْكَوْثَرُ؟ فَقُلْنَا: اللَّهُ وَرَسُولُهُ أَعْلَمُ، قَالَ: فَإِنَّهُ نَهْرٌ، وَعَدَنِيهِ رَبِّي عَزَّ وَجَلَّ عَلَيْهِ خَيْرٌ كَثِيرٌ، هُوَ حَوْضٌ تَرِدُ عَلَيْهِ أُمَّتِي يَوْمَ الْقِيَامَةِ، آنِيَتُهُ عَدَدُ النُّجُومِ، فَيُخْتَلَجُ الْعَبْدُ مِنْهُمْ، فَأَقُولُ: رَبِّ إِنَّهُ مِنْ أُمَّتِي، فَيَقُولُ: مَا تَدْرِي مَا أَحْدَثَتْ بَعْدَكَ ؟."],"takhrij":"صحيح: رواه مسلم في الصّلاة (400) من طرق عن علي بن مسهر، أخبرنا المختار بن فلفل، عن أنس بن مالك، فذكره.","grade":"صحيح","chapter_ar":"باب ذكر الكوثر الذي أعطاه الله نبيه ﷺ وصفاته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (400).","chapter_en":"Mention of al-Kawthar, Which Allah Gave His Prophet ﷺ, and Its Description","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":23,"content":{"translation":{"en":["Anas, may Allah be pleased with him, reported: While the Messenger of Allah ﷺ was among us one day, he briefly dozed off and then raised his head smiling. We asked: “What made you smile, O Messenger of Allah?” He replied: “A sūrah has just been revealed to me.” Then he recited: “Indeed, We have granted you al-Kawthar. So pray to your Lord and sacrifice. Indeed, your enemy is the one cut off.” [Sūrat al-Kawthar 108:1–3] Then he asked: “Do you know what al-Kawthar is?” We replied: “Allah and His Messenger know best.” He said: “It is a river which my Lord, Mighty and Majestic, has promised me. In it is abundant good. It is a Basin to which my Ummah will come on the Day of Resurrection. Its vessels are as numerous as the stars. A servant from among them will then be seized away, and I will say: ‘My Lord, he is from my Ummah.’ He will say: ‘You do not know what he introduced after you.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (400)."},{"num":807,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّهُ قَرَأَ هَذِهِ الْآيَةَ: إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ [سورة الكوثر: 1] قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أُعْطِيتُ الْكَوْثَرَ، فَإِذَا هُوَ نَهَرٌ يَجْرِي وَلَمْ يُشَقَّ شَقًّا، فَإِذَا حَافَتَاهُ قِبَابُ اللُّؤْلُؤِ، فَضَرَبْتُ بِيَدِي إِلَى تُرْبَتِهِ، فَإِذَا هُوَ مِسْكَةٌ ذَفِرَةٌ، وَإِذَا حَصَاهُ اللُّؤْلُؤُ."],"takhrij":"صحيح: رواه الإمام أحمد (13578)، وأبو يعلى (3529) كلاهما من حديث عفّان بن مسلم، حدّثنا حمّاد، أخبرنا ثابت، عن أنس، فذكره.","grade":"صحيح","chapter_ar":"باب ذكر الكوثر الذي أعطاه الله نبيه ﷺ وصفاته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Imām Aḥmad (13578), Abū Yaʿlā (3529), and Ibn Ḥibbān (6471).","chapter_en":"Mention of al-Kawthar, Which Allah Gave His Prophet ﷺ, and Its Description","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":23,"content":{"translation":{"en":["Anas may Allah be pleased with him recited the verse: “Indeed, We have granted you al-Kawthar.” [Sūrat al-Kawthar 108:1] He then said that the Messenger of Allah ﷺ said: “I was given al-Kawthar. It is a river flowing without having been dug out. Its two banks are domes of pearl. I struck my hand into its soil and found intensely fragrant musk, and its pebbles are pearls.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (13578)، وأبو يعلى (3529)، وابن حبان (6471)."},{"num":808,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: دَخَلْتُ الْجَنَّةَ، فَإِذَا أَنَا بِنَهْرٍ حَافَتَاهُ خِيَامُ اللُّؤْلُؤِ، فَضَرَبْتُ بِيَدِي إِلَى مَا يَجْرِي فِيهِ الْمَاءُ فَإِذَا مِسْكٌ أَذْفَرُ، قُلْتُ: مَا هَذَا يَا جِبْرِيلُ؟ قَالَ: هَذَا الْكَوْثَرُ الَّذِي أَعْطَاكَهُ اللَّهُ."],"takhrij":"صحيح: رواه الإمام أحمد (12008) عن ابن أبي عدي، عن حميد، عن أنس ابن مالك، فذكره.ورواه ابن حبان في صحيحه (6473)، والحاكم (266) كلاهما من طريق حميد وهو ابن أبي حميد الطّويل به.","grade":"صحيح","chapter_ar":"باب ذكر الكوثر الذي أعطاه الله نبيه ﷺ وصفاته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Imām Aḥmad (12008), Ibn Ḥibbān (6473), and al-Ḥākim (266).","chapter_en":"Mention of al-Kawthar, Which Allah Gave His Prophet ﷺ, and Its Description","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":23,"content":{"translation":{"en":["Anas may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “I entered Paradise and came upon a river whose two banks were tents of pearl. I struck my hand into that over which its water flowed, and it was intensely fragrant musk. I asked: ‘What is this, O Jibrīl?’ He replied: ‘This is al-Kawthar which Allah has given you.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (12008)، وابن حبان (6473)، والحاكم (266)."},{"num":809,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: سُئِلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا الْكَوْثَرُ؟ قَالَ: ذَاكَ نَهْرٌ أَعْطَانِيهِ اللَّهُ، يَعْنِي فِي الْجَنَّةِ، أَشَدُّ بَيَاضًا مِنَ اللَّبَنِ، وَأَحْلَى مِنَ الْعَسَلِ، فِيهَا طَيْرٌ أَعْنَاقُهَا كَأَعْنَاقِ الْجُزُرِ.","قَالَ عُمَرُ: إِنَّ هَذِهِ لَنَاعِمَةٌ، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَكَلَتُهَا أَنْعَمُ مِنْهَا."],"takhrij":"حسن: رواه الترمذيّ (2542) عن عبدبن حميد، أخبرنا عبدالله بن مسلمة، عن محمد بن عبدالله بن مسلم، عن أبيه، عن أنس بن مالك، فذكره.","grade":"حسن","chapter_ar":"باب ذكر الكوثر الذي أعطاه الله نبيه ﷺ وصفاته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Tirmidhī (2542), who graded it Ḥasan, and Aḥmad (13475).","chapter_en":"Mention of al-Kawthar, Which Allah Gave His Prophet ﷺ, and Its Description","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":23,"content":{"translation":{"en":["Anas ibn Mālik, may Allah be pleased with him, reported: The Messenger of Allah ﷺ was asked: “What is al-Kawthar?” He replied: “It is a river which Allah has given me — meaning in Paradise — whiter than milk and sweeter than honey. In it are birds whose necks are like the necks of camels.” Abū Bakr, may Allah be pleased with him, said:","“Those must indeed be delightful!” The Messenger of Allah ﷺ replied: “Eating them is even more delightful.”"]},"buhuth":{"en":["The one who said:","“Those must indeed be delightful”","was Abū Bakr, not ʿUmar."]}},"tuhfa":{},"full":1,"dr":1,"rep":[13478,16321],"tks":"حسن: رواه الترمذي (2542) وحسنه، وأحمد (13475)."},{"num":810,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْكَوْثَرُ نَهْرٌ فِي الْجَنَّةِ حَافَّتَاهُ مِنْ ذَهَبٍ، وَمَجْرَاهُ عَلَى الدُّرِّ وَالْيَاقُوتِ، تُرْبَتُهُ أَطْيَبُ مِنَ الْمِسْكِ، وَمَاؤُهُ أَحْلَى مِنَ الْعَسَلِ وَأَبْيَضُ مِنَ الثَّلْجِ."],"takhrij":"حسن: رواه الترمذيّ (3361)، وابن ماجه (4334) كلاهما من حديث محمد بن فضيل، عن عطاء بن السّائب، عن محارب بن دثار، عن ابن عمر، فذكره، ولفظهما سواء.","grade":"حسن","chapter_ar":"باب ذكر الكوثر الذي أعطاه الله نبيه ﷺ وصفاته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Tirmidhī (3361) and Ibn Mājah (4334).","chapter_en":"Mention of al-Kawthar, Which Allah Gave His Prophet ﷺ, and Its Description","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":23,"content":{"translation":{"en":["Ibn ʿUmar may Allah be pleased with them reported that the Messenger of Allah ﷺ said: “Al-Kawthar is a river in Paradise. Its two banks are of gold, and its channel flows over pearls and rubies. Its soil is more fragrant than musk, its water is sweeter than honey, and whiter than snow.”"]},"buhuth":{"en":["Al-Tirmidhī said:","“Ḥasan Ṣaḥīḥ.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (3361)، وابن ماجه (4334)."},{"num":811,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ: لَمَّا أُنْزِلَتْ: ﴿إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ﴾ [ سورة الكوثر: 1] قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هُوَ نَهَرٌ فِي الْجَنَّةِ، حَافَتَاهُ مِنْ ذَهَبٍ، يَجْرِي عَلَى جَنَادِلِ الدُّرِّ وَالْيَاقُوتِ، شَرَابُهُ أَحْلَى مِنَ الْعَسَلِ، وَأَشَدُّ بَيَاضًا مِنَ اللَّبَنِ، وَأَبْرَدُ مِنَ الثَّلْجِ، وَأَطْيَبُ مِنْ رِيحِ الْمِسْكِ."],"takhrij":"صحيح: رواه الإمام أحمد (5913)، والطيالسي (2045)، وصحّحه الحاكم (6308) كلهم من طرق عن حماد بن زيد، حدّثنا عطاء بن السائب، قال: قال لي محارب بن دثار: ما سمعتَ سعيد بن جبير يذكر عن ابن عباس في الكوثر؟ فقلت: سمعته يقول: قال ابن عباس: هذا الخير الكثير. فقال محاربٌ: سبحان الله! ما أقلّ ما يسقط لابن عباس قولٌ، سمعتُ ابنَ عمر يقول: فذكره.","grade":"صحيح","chapter_ar":"باب ذكر الكوثر الذي أعطاه الله نبيه ﷺ وصفاته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Imām Aḥmad (5913) and al-Ṭayālisī (2045), and authenticated by al-Ḥākim (3/543).","chapter_en":"Mention of al-Kawthar, Which Allah Gave His Prophet ﷺ, and Its Description","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":23,"content":{"translation":{"en":["Ibn ʿUmar, may Allah be pleased with them, reported: When the verse was revealed: “Indeed, We have granted you al-Kawthar,” [Sūrat al-Kawthar 108:1] the Messenger of Allah ﷺ said: “It is a river in Paradise. Its two banks are of gold, and it flows over large stones of pearls and rubies. Its drink is sweeter than honey, whiter than milk, colder than snow, and more fragrant than musk.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (5913)، والطيالسي (2045)، وصححه الحاكم (6308)."},{"num":812,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَيَرِدَنَّ عَلَيَّ نَاسٌ مِنْ أَصْحَابِي الْحَوْضَ، حَتَّى عَرَفْتُهُمُ اخْتُلِجُوا دُونِي فَأَقُولُ: أَصْحَابِي؟ فَيَقُولُ: لَا تَدْرِي مَا أَحْدَثُوا بَعْدَكَ."],"takhrij":"متفق عليه: رواه البخاريّ في الرقاق (6582)، ومسلم في الفضائل (2304) كلاهما من حديث وُهيب، حدّثنا عبدالعزيز بن صهيب، يحدّث قال: حدّثنا أنس بن مالك، فذكر الحديث. ولفظهما سواء إلاّ أنّ في لفظ مسلم: أُصْيحابي أُصْيحابي! فلْيُقالنَّ لي: إنّك لا تدري ما أحدثوا بعدك.","grade":"متفق عليه","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6582) and Muslim (2304).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["Anas ibn Mālik may Allah be pleased with him reported that the Prophet ﷺ said: “Some people from my Companions will certainly come to me at the Basin. When I recognize them, they will be seized away from me. I will say: ‘My Companions?’ Then it will be said: ‘You do not know what they introduced after you.’”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6582)، ومسلم (2304)."},{"num":813,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ قَدْرَ حَوْضِي كَمَا بَيْنَ أَيْلَةَ وصَنْعَاءَ مِنْ الْيَمَنِ، وَإِنَّ فِيهِ مِنَ الْأَبَارِيقِ كَعَدَدِ نُجُومِ السَّمَاءِ."],"takhrij":"متفق عليه: رواه البخاريّ في الرّقاق (6580)، ومسلم في الفضائل (2303) كلاهما من حديث ابن وهب، عن يونس، عن ابن شهاب، قال: حدّثني أنس بن مالك، فذكره.","grade":"متفق عليه","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6580) and Muslim (2303).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["Anas may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “The extent of my Basin is like the distance between Aylah and Ṣanʿāʾ in Yemen, and its pitchers are as numerous as the stars of the sky.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6580)، ومسلم (2303)."},{"num":814,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا بَيْنَ نَاحِيَتَيْ حَوْضِي كَمَا بَيْنَ صَنْعَاءَ، وَالْمَدِينَةِ.","وَفِي رِوَايَةِ: أَوْ مِثْلَ مَا بَيْنَ الْمَدِينَةِ وَعَمَّانَ.","وَفِي رِوَايَةِ: مَا بَيْنَ لَابَتَيْ حَوْضِي."],"takhrij":"صحيح: رواه مسلم في الفضائل (2303) من طرق عن معتمر، قال: سمعت أبي، حدثنا قتادة، عن أنس، فذكره.","grade":"صحيح","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2303).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["Anas ibn Mālik may Allah be pleased with him reported that the Prophet ﷺ said: “The distance between the two sides of my Basin is like the distance between Ṣanʿāʾ and Madinah.” In another narration:","“Or like the distance between Madinah and ʿAmmān.” And in another narration:","“The distance between the two sides of my Basin.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2303)."},{"num":815,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: قَالَ النَّبِيِّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: تُرَى فِيهِ أَبَارِيقُ الذَّهَبِ وَالْفِضَّةِ كَعَدَدِ نُجُومِ السَّمَاءِ."],"takhrij":"صحيح: رواه مسلم في الفضائل (2303: 43) من طرق عن خالد بن الحارث، عن سعيد، عن قتادة، قال: قال أنس، فذكره.","grade":"صحيح","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2303:43).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["Anas may Allah be pleased with him reported that the Prophet ﷺ said: “In it will be seen pitchers of gold and silver as numerous as the stars of the sky.”"]},"buhuth":{"en":["In another narration:","“Or more numerous than the stars of the sky.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2303: 43)."},{"num":816,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: وَالَّذِي نَفْسِي بِيَدِهِ لَأَذُودَنَّ رِجَالًا عَنْ حَوْضِي، كَمَا تُذَادُ الْغَرِيبَةُ مِنَ الْإِبِلِ عَنِ الْحَوْضِ."],"takhrij":"متفق عليه: رواه البخاريّ في المساقاة (2367)، ومسلم في الفضائل (2302) كلاهما من حديث شعبة، عن محمد بن زياد، قال: سمعت أبا هريرة، قال (فذكره).","grade":"متفق عليه","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2367) and Muslim (2302).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Prophet ﷺ said: “By the One in whose Hand is my soul, I will certainly drive men away from my Basin just as a stray camel is driven away from a watering place.”"]},"buhuth":{"en":["The expression:","“I will certainly drive away”","means: I will repel men from among you.","It has been said that they are the innovators, or the oppressors, and other views have also been mentioned concerning them."]}},"tuhfa":{},"full":1,"dr":1,"rep":[16237],"tks":"متفق عليه: رواه البخاري (2367)، ومسلم (2302)."},{"num":817,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّهُ كَانَ يُحَدِّثُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَرِدُ عَلَيَّ يَوْمَ الْقِيَامَةِ رَهْطٌ مِنْ أَصْحَابِي، فَيُحَلَّئُونَ عَنِ الْحَوْضِ، فَأَقُولُ: يَا رَبِّ أَصْحَابِي؟ فَيَقُولُ: إِنَّكَ لَا عِلْمَ لَكَ بِمَا أَحْدَثُوا بَعْدَكَ، إِنَّهُمُ ارْتَدُّوا عَلَى أَدْبَارِهِمُ الْقَهْقَرَى."],"takhrij":"صحيح: رواه البخاريّ في الرقاق (6585) قال: وقال أحمد بن شبيب بن سعيد الحَبْطي، حدّثنا أبي، عن يونس، عن ابن شهاب، عن سعيد بن المسيب، عن أبي هريرة، أنه كان يحدّث، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī in al-Riqāq (6585).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him used to relate that the Messenger of Allah ﷺ said: “A group from my Companions will come to me on the Day of Resurrection, but they will be driven away from the Basin. I will say: ‘My Lord, my Companions?’ He will say: ‘You have no knowledge of what they introduced after you. They turned back upon their heels.’”"]},"buhuth":{"en":["The word:","“yujlawna”","means that they will be turned away and removed."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (6585)."},{"num":818,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: بَيْنَا أَنَا قَائِمٌ إِذَا زُمْرَةٌ حَتَّى إِذَا عَرَفْتُهُمْ خَرَجَ رَجُلٌ مِنْ بَيْنِي وَبَيْنِهِمْ، فَقَالَ: هَلُمَّ، فَقُلْتُ: أَيْنَ؟ قَالَ: إِلَى النَّارِ، وَاللَّهِ قُلْتُ: وَمَا شَأْنُهُمْ؟ قَالَ: إِنَّهُمُ ارْتَدُّوا بَعْدَكَ عَلَى أَدْبَارِهِمُ الْقَهْقَرَى، ثُمَّ إِذَا زُمْرَةٌ حَتَّى إِذَا عَرَفْتُهُمْ خَرَجَ رَجُلٌ مِنْ بَيْنِي وَبَيْنِهِمْ، فَقَالَ: هَلُمَّ، قُلْتُ: أَيْنَ؟ قَالَ: إِلَى النَّارِ، وَاللَّهِ قُلْتُ: مَا شَأْنُهُمْ؟ قَالَ: إِنَّهُمُ ارْتَدُّوا بَعْدَكَ عَلَى أَدْبَارِهِمُ الْقَهْقَرَى، فَلَا أُرَاهُ يَخْلُصُ مِنْهُمْ إِلَّا مِثْلُ هَمَلِ النَّعَمِ."],"takhrij":"صحيح: رواه البخاريّ في الرقاق (6587) عن إبراهيم بن المنذر، حدّثنا محمد بن فليح، حدّثنا أبي، قال: حدثني هلال، عن عطاء بن يسار، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (6587).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Prophet ﷺ said: “While I was asleep, I saw a group. When I recognized them, a man came out between me and them and said: ‘Come.’ I asked: ‘Where?’ He replied: ‘To the Fire, by Allah.’ I asked: ‘What is the matter with them?’ He replied: ‘They turned back after you upon their heels.’ Then another group appeared. When I recognized them, a man came out between me and them and said: ‘Come.’ I asked: ‘Where?’ He replied: ‘To the Fire, by Allah.’ I asked: ‘What is the matter with them?’ He replied: ‘They turned back after you upon their heels.’ I do not think that any of them will escape except as few as stray, ownerless camels.”"]}},"tuhfa":{},"full":1,"rep":[16495],"tks":"صحيح: رواه البخاري (6587)."},{"num":819,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَتَى الْمَقْبُرَةَ فَقَالَ: السَّلَامُ عَلَيْكُمْ دَارَ قَوْمٍ مُؤْمِنِينَ، وَإِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لَاحِقُونَ، وَدِدْتُ أَنَّا قَدْ رَأَيْنَا إِخْوَانَنَا، قَالُوا: أَوَلَسْنَا إِخْوَانَكَ يَا رَسُولَ اللَّهِ؟ قَالَ: أَنْتُمْ أَصْحَابِي، وَإِخْوَانُنَا الَّذِينَ لَمْ يَأْتُوا بَعْدُ، فَقَالُوا: كَيْفَ تَعْرِفُ مَنْ لَمْ يَأْتِ بَعْدُ مِنْ أُمَّتِكَ يَا رَسُولَ اللَّهِ؟ فَقَالَ: أَرَأَيْتَ لَوْ أَنَّ رَجُلًا لَهُ خَيْلٌ غُرٌّ، مُحَجَّلَةٌ بَيْنَ ظَهْرَيْ خَيْلٍ دُهْمٍ بُهْمٍ، أَلَا يَعْرِفُ خَيْلَهُ؟ قَالُوا: بَلَى يَا رَسُولَ اللَّهِ، قَالَ: فَإِنَّهُمْ يَأْتُونَ غُرًّا، مُحَجَّلِينَ مِنَ الْوُضُوءِ، وَأَنَا فَرَطُهُمْ عَلَى الْحَوْضِ، أَلَا لَيُذَادَنَّ رِجَالٌ عَنْ حَوْضِي، كَمَا يُذَادُ الْبَعِيرُ الضَّالُّ أُنَادِيهِمْ، أَلَا هَلُمَّ؟ فَيُقَالُ: إِنَّهُمْ قَدْ بَدَّلُوا بَعْدَكَ، فَأَقُولُ: سُحْقًا، سُحْقًا."],"takhrij":"صحيح: رواه مسلم في الطّهارة (249) من طرق عن إسماعيل بن جعفر، أخبرني العلاء، عن أبيه، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (249).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ came to the graveyard and said: “Peace be upon you, abode of believing people. Indeed, if Allah wills, we will join you. I wish that we had seen our brothers.” They asked: “Are we not your brothers, O Messenger of Allah?” He replied: “You are my Companions. Our brothers are those who have not yet come.” They asked: “How will you recognize those from your Ummah who have not yet come, O Messenger of Allah?” He replied: “Suppose a man had horses with bright white markings on their foreheads and legs among completely black horses. Would he not recognize his own horses?” They replied: “Certainly, O Messenger of Allah.” He said: “They will come with radiant marks on their faces and limbs from the effects of wuḍūʾ, and I will precede them to the Basin. Indeed, men will certainly be driven away from my Basin just as a stray camel is driven away. I will call to them: ‘Come here!’ But it will be said: ‘They changed after you.’ Then I will say: ‘Away with them! Away with them!’”"]},"buhuth":{"en":["The statement:","“I will precede them to the Basin”","means that he will arrive there before them. It comes from faraṭa–yafruṭu, meaning to hasten and go ahead, as in the statement of Allah Most High:","“They said: ‘Our Lord, indeed we fear that he may hasten against us or transgress.’”","[Sūrat Ṭā Hā 20:45]","That is, that he may hasten to punish them.","The word al-faraṭ is most commonly used for one who goes ahead of others to water in order to prepare it for them."]}},"tuhfa":{},"full":1,"dr":1,"rep":[132],"tks":"صحيح: رواه مسلم (249)."},{"num":820,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ حَوْضِي أَبْعَدُ مِنْ أَيْلَةَ مِنْ عَدَنٍ، لَهُوَ أَشَدُّ بَيَاضًا مِنَ الثَّلْجِ، وَأَحْلَى مِنَ الْعَسَلِ بِاللَّبَنِ، وَلَآنِيَتُهُ أَكْثَرُ مِنْ عَدَدِ النُّجُومِ، وَإِنِّي لَأَصُدُّ النَّاسَ عَنْهُ، كَمَا يَصُدُّ الرَّجُلُ إِبِلَ النَّاسِ عَنْ حَوْضِهِ، قَالُوا: يَا رَسُولَ اللَّهِ، أَتَعْرِفُنَا يَوْمَئِذٍ؟ قَالَ: نَعَمْ، لَكُمْ سِيمَا، لَيْسَتْ لِأَحَدٍ مِنَ الأُمَمِ تَرِدُونَ عَلَيَّ غُرًّا مُحَجَّلِينَ مِنْ أَثَرِ الْوُضُوءِ.","وَفِي رِوَايَةِ: تَرِدُ عَلَيَّ أُمَّتِي الْحَوْضَ وَأَنَا أَذُودُ النَّاسَ عَنْهُ كَمَا يَذُودُ الرَّجُلُ إِبِلَ الرَّجُلِ عَنْ إِبِلِهِ، قَالُوا: يَا نَبِيَّ اللَّهِ، أَتَعْرِفُنَا؟ قَالَ: نَعَمْ، لَكُمْ سِيمَا لَيْسَتْ لِأَحَدٍ غَيْرِكُمْ، تَرِدُونَ عَلَيَّ غُرًّا مُحَجَّلِينَ مِنْ آثَارِ الْوُضُوءِ، وَلَيُصَدَّنَّ عَنِّي طَائِفَةٌ مِنْكُمْ، فَلَا يَصِلُونَ، فَأَقُولُ: يَا رَبِّ، هَؤُلَاءِ مِنْ أَصْحَابِي، فَيُجِيبُنِي مَلَكٌ، فَيَقُولُ: وَهَلْ تَدْرِي مَا أَحْدَثُوا بَعْدَكَ؟."],"takhrij":"صحيح: رواه مسلم في الطّهارة (247) من طرق عن مروان الفزاريّ، عن أبي مالك الأشجعيّ سعد بن طارق، عن أبي حازم، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (247).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “My Basin is greater in extent than the distance from Aylah to ʿAdan. It is whiter than snow and sweeter than honey mixed with milk. Its vessels are more numerous than the stars, and I will keep people away from it just as a man keeps other people’s camels away from his watering place.” They asked: “O Messenger of Allah, will you recognize us on that day?” He replied: “Yes. You will have a distinguishing mark which no other nation possesses. You will come to me with radiant faces and limbs from the effects of wuḍūʾ.” In another narration: “My Ummah will come to me at the Basin, and I will drive other people away from it just as a man drives another person’s camels away from his own camels.”","They asked: “O Prophet of Allah, will you recognize us?” He replied: “Yes. You will have a distinguishing mark which no one else possesses. You will come to me with radiant faces and limbs from the effects of wuḍūʾ. A group from among you will certainly be turned away from me and will not reach me. I will say: ‘My Lord, these are from my Companions.’ Then an angel will come to me and say: ‘Do you know what they introduced after you?’”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[16238],"tks":"صحيح: رواه مسلم (247)."},{"num":821,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ أَمَامَكُمْ حَوْضًا كَمَا بَيْنَ جَرْبَاءَ وَأَذْرُحَ."],"takhrij":"متفق عليه: رواه البخاريّ في الرّقاق (6577)، ومسلم في الفضائل (2299) كلاهما من حديث يحيى القطّان، عن عبيد الله، أخبرني نافع، عن ابن عمر، فذكره.","grade":"متفق عليه","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6577) and Muslim (2299).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["Ibn ʿUmar may Allah be pleased with them reported that the Prophet ﷺ said: “Indeed, ahead of you is a Basin whose extent is like the distance between Jarbāʾ and Adhruḥ.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6577)، ومسلم (2299)."},{"num":822,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ أَمَامَكُمْ حَوْضًا كَمَا بَيْنَ جَرْبَاءَ وَأَذْرُحَ، فِيهِ أَبَارِيقُ كَنُجُومِ السَّمَاءِ، مَنْ وَرَدَهُ فَشَرِبَ مِنْهُ لَمْ يَظْمَأْ بَعْدَهَا أَبَدًا."],"takhrij":"صحيح: رواه مسلم في الفضائل (2299) عن حرملة بن يحيى، حدّثنا عبدالله بن وهب، حدّثني عمر بن محمد، عن نافع، عن عبدالله بن عمر، فذكره.","grade":"صحيح","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2299:35).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["Ibn ʿUmar may Allah be pleased with them reported that the Messenger of Allah ﷺ said: “Indeed, ahead of you is a Basin whose extent is like the distance between Jarbāʾ and Adhruḥ. In it are pitchers like the stars of the sky. Whoever comes to it and drinks from it will never thirst afterward.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2299: 35)."},{"num":823,"demo":false,"sanad":"","matn":["عَنْ حَارِثَةَ بْنِ وَهْبٍ الْخُزَاعِيِّ، أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: حَوْضُهُ مَا بَيْنَ صَنْعَاءَ، وَالْمَدِينَةِ.","فَقَالَ لَهُ الْمُسْتَوْرِدُ: أَلَمْ تَسْمَعْهُ؟ قَالَ: الْأَوَانِي، قَالَ: لَا، فَقَالَ الْمُسْتَوْرِدُ: تُرَى فِيهِ الْآنِيَةُ مِثْلَ الْكَوَاكِبِ."],"takhrij":"متفق عليه: رواه البخاريّ في الرّقاق (6591)، ومسلم في الفضائل (2298) كلاهما من حديث حرمي بن عمارة، حدّثنا شعبة، عن معبدبن خالد، أنّه سمع حارثة بن وهب يقول: فذكره.","grade":"متفق عليه","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6591) and Muslim (2298).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["Ḥārithah ibn Wahb al-Khuzāʿī may Allah be pleased with him reported that he heard the Prophet ﷺ say: “His Basin is as extensive as the distance between Ṣanʿāʾ and Madinah.”","Al-Mustawrid asked him: “Did you not hear him mention the vessels?” He replied: “No.” Al-Mustawrid said: “The vessels in it will be seen like the stars.”"]},"buhuth":{"en":["The word “āniyah” is the plural of ināʾ, meaning a vessel. What is intended here are the cups from which people will drink at the Basin.","His statement:","“Like the stars”","means like the stars in the sky in their abundance and brightness."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6591)، ومسلم (2298)."},{"num":824,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَنَا فَرَطُكُمْ عَلَى الْحَوْضِ وَلَيُرْفَعَنَّ مَعِي رِجَالٌ مِنْكُمْ، ثُمَّ لَيُخْتَلَجُنَّ دُونِي، فَأَقُولُ: يَا رَبِّ أَصْحَابِي؟ فَيُقَالُ: إِنَّكَ لَا تَدْرِي مَا أَحْدَثُوا بَعْدَكَ."],"takhrij":"متفق عليه: رواه البخاريّ في الرقاق (6576)، ومسلم في الفضائل (2297) كلاهما من حديث شعبة، عن المغيرة، قال: سمعت أبا وائل، عن عبدالله، فذكره، واللفظ للبخاري. وفي لفظ مسلم: ولأُنازعَنَّ أقواماً، ثم لأُغْلَبَنَّ عليهم....","grade":"متفق عليه","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6576) and Muslim (2297).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd may Allah be pleased with him reported that the Prophet ﷺ said: “I will precede you to the Basin. Men from among you will certainly be brought forward, then they will be seized away from me. I will say: ‘My Lord, my Companions?’ It will be said: ‘You do not know what they introduced after you.’”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6576)، ومسلم (2297)."},{"num":825,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ قَالَ: صَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى قَتْلَى أُحُدٍ بَعْدَ ثَمَانِي سِنِينَ كَالْمُوَدِّعِ لِلْأَحْيَاءِ وَالْأَمْوَاتِ، ثُمَّ طَلَعَ الْمِنْبَرَ فَقَالَ: إِنِّي بَيْنَ أَيْدِيكُمْ فَرَطٌ، وَأَنَا عَلَيْكُمْ شَهِيدٌ، وَإِنَّ مَوْعِدَكُمُ الْحَوْضُ وَإِنِّي لَأَنْظُرُ إِلَيْهِ مِنْ مَقَامِي هَذَا، وَإِنِّي لَسْتُ أَخْشَى عَلَيْكُمْ أَنْ تُشْرِكُوا وَلَكِنِّي أَخْشَى عَلَيْكُمُ الدُّنْيَا أَنْ تَنَافَسُوهَا، قَالَ: فَكَانَتْ آخِرَ نَظْرَةٍ نَظَرْتُهَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"متفق عليه: رواه البخاريّ في المغازي (4042)، ومسلم في الفضائل (2296) كلاهما من حديث يزيد بن أبي حبيب، عن أبي الخير، عن عقبة بن عامر، فذكره.","grade":"متفق عليه","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4042) and Muslim (2296).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["ʿUqbah ibn ʿĀmir, may Allah be pleased with him, reported: The Messenger of Allah ﷺ prayed over those who had been martyred at Uḥud eight years later, like one bidding farewell to the living and the dead. Then he ascended the pulpit and said: “I will precede you, and I am a witness over you. Your appointed meeting is at the Basin, and I can see it from where I stand now. I do not fear that you will associate partners with Allah after me, but I fear that you will compete with one another for the worldly life.” ʿUqbah said: “That was the last time I looked upon the Messenger of Allah ﷺ.”"]}},"tuhfa":{},"full":1,"rep":[3759],"tks":"متفق عليه: رواه البخاري (4042)، ومسلم (2296)."},{"num":826,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: حَوْضِي مَسِيرَةُ شَهْرٍ، مَاؤُهُ أَبْيَضُ مِنَ اللَّبَنِ، وَرِيحُهُ أَطْيَبُ مِنَ الْمِسْكِ، وَكِيزَانُهُ كَنُجُومِ السَّمَاءِ، مَنْ شَرِبَ مِنْهَا فَلَا يَظْمَأُ أَبَدًا."],"takhrij":"متفق عليه: رواه البخاريّ في الرّقاق (6579)، ومسلم في الفضائل (2292) كلاهما من حديث نافع بن عمر الجمحيّ، عن ابن أبي مليكة، قال: قال عبدالله بن عمرو بن العاص، فذكره. واللّفظ للبخاريّ.","grade":"متفق عليه","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6579) and Muslim (2292).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr may Allah be pleased with them reported that the Prophet ﷺ said: “My Basin is the distance of a month’s journey. Its water is whiter than milk, its fragrance more pleasant than musk, and its cups are like the stars of the sky. Whoever drinks from it will never thirst again.”"]},"buhuth":{"en":["The wording above is that of al-Bukhārī.","Muslim adds:","“Its corners are equal.”","That is, its length is like its width."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6579)، ومسلم (2292)."},{"num":827,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: حَوْضِي مَسِيرَةَ شَهْرٍ زَوَايَاهُ سَوَاءٌ أَكْوازُهُ عَدَدُ نُجُومِ السَّمَاءِ، مَاؤُهُ أَبْيَضُ مِنَ الثَّلْجِ، وَأَحْلَى مِنَ الْعَسَلِ، وَأَطْيَبُ مِنَ الْمِسْكِ مَنْ شَرِبَ مِنْهُ شَرْبَةً لَمْ يَظْمَأْ بَعْدَهَا أَبَدًا."],"takhrij":"حسن: رواه الطبرانيّ في الكبير (11249) عن إبراهيم بن هاشم البغويّ، ثنا محمد بن عبدالوهاب الحارثي، ثنا عبدالله بن عبيد بن عمير، عن ابن أبي مليكة، عن ابن عباس، فذكره.","grade":"حسن","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Kabīr (11/125).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās may Allah be pleased with them reported that the Messenger of Allah ﷺ said: “My Basin is the distance of a month’s journey. Its corners are equal. Its cups are as numerous as the stars of the sky. Its water is whiter than snow, sweeter than honey, and more fragrant than musk. Whoever drinks a single drink from it will never thirst afterward.”"]},"buhuth":{"en":["Among the Important Benefits","Al-Qurṭubī, may Allah have mercy on him, said:","“His statement, ‘My Basin is the distance of a month; its corners are equal,’ means that its extremities are equal—that is, the distance between its sides is equal—so that it is evenly proportioned.","The expressions describing the dimensions of the Basin differ, as is clear from the narrations cited in the original work. Some people of limited understanding have imagined this to be inconsistency, but that is not the case.","Rather, the Prophet ﷺ spoke about the Basin on many different occasions and used these various descriptions to indicate approximation rather than an exact measurement. All of them establish that it is immensely large and spacious, with widely separated sides and corners.","Perhaps the reason he mentioned different locations when describing the Basin’s size was that he addressed those present according to the places familiar to them, speaking to each people using geographical references that they knew.","And Allah knows best.”","Al-Mufhim (6/91–92)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (11249)."},{"num":828,"demo":false,"sanad":"","matn":["عَنْ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ قَالَتْ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنِّي عَلَى الْحَوْضِ حَتَّى أَنْظُرَ مَنْ يَرِدُ عَلَيَّ مِنْكُمْ، وَسَيُؤْخَذُ نَاسٌ دُونِي، فَأَقُولُ: يَا رَبِّ مِنِّي وَمِنْ أُمَّتِي، فَيُقَالُ: هَلْ شَعَرْتَ مَا عَمِلُوا بَعْدَكَ، وَاللَّهِ مَا بَرِحُوا يَرْجِعُونَ عَلَى أَعْقَابِهِمْ.","فَكَانَ ابْنُ أَبِي مُلَيْكَةَ يَقُولُ: اللَّهُمَّ إِنَّا نَعُوذُ بِكَ أَنْ نَرْجِعَ عَلَى أَعْقَابِنَا أَوْ نُفْتَنَ عَنْ دِينِنَا. ﴿أَعْقَابِكُمْ تَنْكِصُونَ﴾ [المؤمنون: 66] تَرْجِعُونَ عَلَى الْعَقِبِ."],"takhrij":"متفق عليه: رواه البخاريّ في الرّقاق (6593)، ومسلم في الفضائل (2293) كلاهما من حديث نافع بن عمر، قال: حدّثني ابن أبي مليكة، عن أسماء بنت أبي بكر، فذكرته.","grade":"متفق عليه","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6593) and Muslim (2293).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["Asmāʾ bint Abī Bakr may Allah be pleased with them reported that the Prophet ﷺ said: “I will be at the Basin, watching to see which of you comes to me. Some people will be taken away from me, and I will say: ‘My Lord, they are from me and from my Ummah!’ It will be said: ‘Do you know what they did after you? By Allah, they never ceased turning back upon their heels.’” Ibn Abī Mulaykah used to say: “O Allah, we seek refuge in You from turning back upon our heels or being tempted away from our religion.”","Regarding the statement of Allah Most High: “If he dies or is killed, will you turn back upon your heels?” [Āl ʿImrān 3:144] that is: will you turn back and retreat?"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6593)، ومسلم (2293)."},{"num":829,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ بْنِ سَعْدٍ يَقُولُ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: أَنَا فَرَطُكُمْ عَلَى الْحَوْضِ، فَمَنْ وَرَدَهُ شَرِبَ مِنْهُ، وَمَنْ شَرِبَ مِنْهُ لَمْ يَظْمَأْ بَعْدَهُ أَبَدًا، لَيَرِدُ عَلَيَّ أَقْوَامٌ أَعْرِفُهُمْ وَيَعْرِفُونِي، ثُمَّ يُحَالُ بَيْنِي وَبَيْنَهُمْ.","قَالَ أَبُو حَازِمٍ: فَسَمِعَنِي النُّعْمَانُ بْنُ أَبِي عَيَّاشٍ وَأَنَا أُحَدِّثُهُمْ هَذَا، فَقَالَ: هَكَذَا سَمِعْتَ سَهْلًا؟ فَقُلْتُ: نَعَمْ، قَالَ: وَأَنَا أَشْهَدُ عَلَى أَبِي سَعِيدٍ الْخُدْرِيِّ لَسَمِعْتُهُ يَزِيدُ فِيهِ، قَالَ: إِنَّهُمْ مِنِّي، فَيُقَالُ: إِنَّكَ لَا تَدْرِي مَا بَدَّلُوا بَعْدَكَ، فَأَقُولُ: سُحْقًا سُحْقًا لِمَنْ بَدَّلَ بَعْدِي."],"takhrij":"متفق عليه: رواه البخاريّ في الفتن (7050، 7051)، ومسلم في الفضائل (2290) كلاهما من حديث يعقوب بن عبدالرحمن، عن أبي حازم، سمعت سهل بن سعد، فذكره.","grade":"متفق عليه","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7050, 7051) and Muslim (2290).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["Abū Ḥāzim reported: I heard Sahl ibn Saʿd may Allah be pleased with him say: I heard the Prophet ﷺ say: “I will precede you to the Basin. Whoever comes to it will drink from it, and whoever drinks from it will never thirst afterward. Certain people whom I recognize and who recognize me will come to me, but then a barrier will be placed between me and them.”","Abū Ḥāzim said: Al-Nuʿmān ibn Abī ʿAyyāsh heard me narrating this and asked: “Is this how you heard Sahl narrate it?” I replied: “Yes.” He said: “And I testify that I heard Abū Saʿīd al-Khudrī may Allah be pleased with him add that the Prophet ﷺ said: ‘They are from me.’ Then it will be said: ‘You do not know what they changed after you.’ So I will say: ‘Away with them! Away with those who changed after me!’”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (7050، 7051)، ومسلم (2290)."},{"num":830,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ بْنِ سَعْدٍ، عَنِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: أَنَا فَرَطُكُمْ عَلَى الْحَوْضِ، مَنْ وَرَدَهُ شَرِبَ مِنْهُ، وَمَنْ شَرِبَ مِنْهُ لَمْ يَظْمَأْ بَعْدَهُ أَبَدًا، لَيَرِدُ عَلَيَّ أَقْوَامٌ أَعْرِفُهُمْ وَيَعْرِفُونِي، ثُمَّ يُحَالُ بَيْنِي وَبَيْنَهُمْ.","وَفِي رِوَايَةِ: عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، فَأَقُولُ: إِنَّهُمْ مِنِّي فَيُقَالُ: إِنَّكَ لَا تَدْرِي مَا أَحْدَثُوا بَعْدَكَ، فَأَقُولُ: سُحْقًا سُحْقًا لِمَنْ غَيَّرَ بَعْدِي."],"takhrij":"متفق عليه: رواه مسلم (2291)، والبخاري في الرقاق (6584)،في الفتن (7051) كلاهما من طريق النّعمان بن أبي عياش، عن أبي سعيد الخدريّ قال: فذكره. إلا أنهما لم يذكرا الجزء الأول من الحديث بل أحالا إلى لفظ حديث سهل بن سعد المتقدم، وزادا في آخره: فأقول: إنهم مني... الحديث.","grade":"متفق عليه","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (2291) and al-Bukhārī (6584).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī may Allah be pleased with him reported that the Prophet ﷺ said: “I will precede you to the Basin. Whoever comes to it will drink from it, and whoever drinks from it will never thirst afterward. Certain people whom I recognize and who recognize me will come to me, but then a barrier will be placed between me and them.”","I will say: “They are from me.” It will be said: “You do not know what they introduced after you.” Then I will say: “Away with them! Away with those who changed after me!”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مسلم (2291)، والبخاري (6584)."},{"num":831,"demo":false,"sanad":"","matn":["عَنْ جُنْدَبِ بْنِ عَبْدِ اللَّهِ الْبَجَلِيِّ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: أَنَا فَرَطُكُمْ على الْحَوْضِ."],"takhrij":"متفق عليه: رواه البخاريّ في الرّقاق (6589)، ومسلم في الفضائل (2289) كلاهما من حديث شعبة، عن عبدالملك بن عمير، قال: سمعتُ جندباً قال (فذكره).","grade":"متفق عليه","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6589) and Muslim (2289).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["Jundub ibn ʿAbdullāh ibn Sufyān al-Bajalī, may Allah be pleased with him, said: I heard the Prophet ﷺ say: “I will precede you to the Basin.”"]},"buhuth":{"en":["Regarding the word:","“your forerunner,”","the scholars of language said that al-faraṭ or al-fāriṭ is the one who goes ahead of people coming to water in order to prepare the watering place, buckets, and other matters needed for drawing water.","Thus:","“I will be your forerunner at the Basin”","means: I will precede you to it, like one preparing it for those who follow."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6589)، ومسلم (2289)."},{"num":832,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ تَقُولُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ وَهُوَ بَيْنَ ظَهْرَانَيْ أَصْحَابِهِ: إِنِّي عَلَى الْحَوْضِ أَنْتَظِرُ مَنْ يَرِدُ عَلَيَّ مِنْكُمْ، فَوَاللَّهِ لَيُقْتَطَعَنَّ دُونِي رِجَالٌ، فَلَأَقُولَنَّ: أَيْ رَبِّ مِنِّي وَمِنْ أُمَّتِي، فَيَقُولُ: إِنَّكَ لَا تَدْرِي مَا عَمِلُوا بَعْدَكَ، مَا زَالُوا يَرْجِعُونَ عَلَى أَعْقَابِهِمْ."],"takhrij":"صحيح: رواه مسلم في الفضائل (2294) عن أبي عمر، حدّثنا يحيى بن سُليم، عن ابن خُثيم، عن عبدالله بن عبيد الله بن أبي مُليكة، أنّه سمع عائشة تقول: فذكرتْه.","grade":"صحيح","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2294).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["ʿĀʾishah may Allah be pleased with her said: I heard the Messenger of Allah ﷺ say while he was among his Companions: “I will be at the Basin waiting for those among you who come to me. By Allah, men will certainly be taken away from me, and I will say: ‘My Lord, they are from me and from my Ummah!’ He will say: ‘You do not know what they did after you. They never ceased turning back upon their heels.’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2294)."},{"num":833,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهَا قَالَتْ: كُنْتُ أَسْمَعُ النَّاسَ يَذْكُرُونَ الْحَوْضَ، وَلَمْ أَسْمَعْ ذَلِكَ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا كَانَ يَوْمًا مِنْ ذَلِكَ وَالْجَارِيَةُ تَمْشُطُنِي، فَسَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ: أَيُّهَا النَّاسُ، فَقُلْتُ لِلْجَارِيَةِ: اسْتَأْخِرِي عَنِّي، قَالَتْ: إِنَّمَا دَعَا الرِّجَالَ، وَلَمْ يَدْعُ النِّسَاءَ، فَقُلْتُ: إِنِّي مِنَ النَّاسِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنِّي لَكُمْ فَرَطٌ عَلَى الْحَوْضِ، فَإِيَّايَ لَا يَأْتِيَنَّ أَحَدُكُمْ فَيُذَبُّ عَنِّي كَمَا يُذَبُّ الْبَعِيرُ الضَّالُّ، فَأَقُولُ: فِيمَ هَذَا ؟، فَيُقَالُ: إِنَّكَ لَا تَدْرِي مَا أَحْدَثُوا بَعْدَكَ، فَأَقُولُ: سُحْقًا."],"takhrij":"صحيح: رواه مسلم في الفضائل (2295) عن يونس بن عبدالأعلى الصّدفيّ، أخبرنا عبدالله بن وهب، أخبرني عمرو بن الحارث، أنّ بكيراً حدّثه عن القاسم بن عباس الهاشميّ، عن عبدالله بن رافع مولى أمِّ سلمة زوج النبيّ صلى الله عليه وسلم، فذكرت مثله.","grade":"صحيح","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2295).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["Umm Salamah, the wife of the Prophet ﷺ, may Allah be pleased with her said: I used to hear the people mentioning the Basin, but I had not heard anything about it directly from the Messenger of Allah ﷺ. Then one day, while a servant-girl was combing my hair, I heard the Messenger of Allah ﷺ say: “O people!” I said to the servant-girl: “Move away from me.” She replied: “He only called the men; he did not call the women.” I said: “I am among the people.” Then the Messenger of Allah ﷺ said: “I will precede you to the Basin. Beware that one of you should come and then be driven away from me as a stray camel is driven away. I will say: ‘Why is this?’ It will be said: ‘You do not know what they introduced after you.’ Then I will say: ‘Away with them!’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2295)."},{"num":834,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَنَا فَرَطُكُمْ عَلَى الْحَوْضِ، وَلَأُنَازِعَنَّ أَقْوَامًا ثُمَّ لَأُغْلَبَنَّ عَلَيْهِمْ، فَأَقُولُ: يَا رَبِّ أَصْحَابِي! أَصْحَابِي! فَيُقَالُ: إِنَّكَ لَا تَدْرِي مَا أَحْدَثُوا بَعْدَكَ."],"takhrij":"صحيح: رواه مسلم في الفضائل (2297) ومن طرق عن حصين، عن أبي وائل، عن حذيفة، عن النّبيّ صلى الله عليه وسلم نحو حديث الأعمش ومغيرة.","grade":"صحيح","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2297).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["Ḥudhayfah may Allah be pleased with him reported that the Prophet ﷺ said: “I will precede you to the Basin. I will contend for certain people, but they will be taken away despite me. I will say: ‘My Lord, my Companions! My Companions!’ It will be said: ‘You do not know what they introduced after you.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2297)."},{"num":835,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ حَوْضِي لَأَبْعَدُ مِنْ أَيْلَةَ مِنْ عَدَنٍ وَالَّذِي نَفْسِي بِيَدِهِ، إِنِّي لَأَذُودُ عَنْهُ الرِّجَالَ، كَمَا يَذُودُ الرَّجُلُ الإِبِلَ الْغَرِيبَةَ، عَنْ حَوْضِهِ، قَالُوا: يَا رَسُولَ اللَّهِ، وَتَعْرِفُنَا؟ قَالَ: نَعَمْ، تَرِدُونَ عَلَيَّ غُرًّا، مُحَجَّلِينَ مِنْ آثَارِ الْوُضُوءِ، لَيْسَتْ لِأَحَدٍ غَيْرِكُمْ."],"takhrij":"صحيح: رواه مسلم في الطّهارة (248) عن عثمان بن أبي شيبة، حدّثنا علي ابن مسهر، عن سعد بن طارق، عن ربعي بن حراش، عن حذيفة، فذكره.","grade":"صحيح","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (248).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["Ḥudhayfah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “My Basin is greater in extent than the distance from Aylah to ʿAdan. By the One in whose Hand is my soul, I will drive men away from it just as a man drives unfamiliar camels away from his watering place.” They asked: “O Messenger of Allah, will you recognize us?” He replied: “Yes. You will come to me with radiant faces and limbs from the traces of wuḍūʾ—a distinction belonging to none other than you.”"]}},"tuhfa":{},"full":1,"rep":[1574],"tks":"صحيح: رواه مسلم (248)."},{"num":836,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: بيْنَ حَوْضِي كَمَا بيْنَ أَيْلَةَ وَمُضَرَ، آنِيَتُهُ أَكْثَرُ أَوْ قَالَ: مِثْلُ عَدَدِ نُجُومِ السَّمَاءِ، مَاؤُهُ أَحْلَى مِنَ الْعَسَلِ، وَأَشَدُّ بيَاضًا مِنَ اللَّبنِ، وَأَبرَدُ مِنَ الثَّلْجِ، وَأَطْيَب مِنَ الْمِسْكِ، مَنْ شَرِب مِنْهُ لَمْ يَظْمَأْ بعْدَهُ."],"takhrij":"حسن: رواه الإمام أحمد (23317)، والبزّار (2911) كلاهما من حديث عبدالصمد بن عبدالوارث، حدثنا حماد، عن عاصم، عن زرّ، عن حذيفة، فذكره.","grade":"حسن","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (23317), al-Bazzār (2911), and Ibn Abī ʿĀṣim in al-Sunnah (724, 725).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["Ḥudhayfah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “The extent of my Basin is like the distance between Aylah and Muḍar. Its vessels are more numerous than—or he said as numerous as—the stars of the sky. Its water is sweeter than honey, whiter than milk, colder than snow, and more fragrant than musk. Whoever drinks from it will never thirst afterward.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (23317)، والبزار (2911)، وابن أبي عاصم في السنة (724، 725)."},{"num":837,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، مَا آنِيَةُ الْحَوْضِ؟ قَالَ: وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ لَآنِيَتُهُ أَكْثَرُ مِنْ عَدَدِ نُجُومِ السَّمَاءِ وَكَوَاكِبِهَا، أَلَا فِي اللَّيْلَةِ الْمُظْلِمَةِ الْمُصْحِيَةِ آنِيَةُ الْجَنَّةِ، مَنْ شَرِبَ مِنْهَا لَمْ يَظْمَأْ، آخِرَ مَا عَلَيْهِ يَشْخَبُ فِيهِ مِيزَابَانِ مِنَ الْجَنَّةِ، مَنْ شَرِبَ مِنْهُ لَمْ يَظْمَأْ، عَرْضُهُ مِثْلُ طُولِهِ مَا بَيْنَ عَمَّانَ إِلَى أَيْلَةَ، مَاؤُهُ أَشَدُّ بَيَاضًا مِنَ اللَّبَنِ وَأَحْلَى مِنَ الْعَسَلِ."],"takhrij":"صحيح: رواه مسلم في الفضائل (2300) من طرق عن عبدالعزيز بن عبدالصمد العَمّي، عن أبي عمران الجوني، عن عبدالله بن الصّامت، عن أبي ذر، فذكره.","grade":"صحيح","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2300).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["Abū Dharr, may Allah be pleased with him, said: I asked: “O Messenger of Allah, what are the vessels of the Basin?” He replied: “By the One in whose Hand is the soul of Muḥammad, its vessels are more numerous than the stars and constellations of the sky on a dark, clear night. They are vessels of Paradise. Whoever drinks from it will never thirst again. Two channels from Paradise pour into it. Whoever drinks from it will never thirst. Its width is equal to its length, extending like the distance from ʿAmmān to Aylah. Its water is whiter than milk and sweeter than honey.”"]}},"tuhfa":{},"full":1,"rep":[16235],"tks":"صحيح: رواه مسلم (2300)."},{"num":838,"demo":false,"sanad":"","matn":["عَنْ ثَوْبَانَ، أَنَّ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنِّي لَبِعُقْرِ حَوْضِي أَذُودُ النَّاسَ لِأَهْلِ الْيَمَنِ، أَضْرِبُ بِعَصَايَ حَتَّى يَرْفَضَّ عَلَيْهِمْ، فَسُئِلَ عَنْ عَرْضِهِ؟ فَقَالَ: مِنْ مَقَامِي إِلَى عَمَّانَ، وَسُئِلَ عَنْ شَرَابِهِ؟ فَقَالَ: أَشَدُّ بَيَاضًا مِنَ اللَّبَنِ، وَأَحْلَى مِنَ الْعَسَلِ، يَغُتُّ فِيهِ مِيزَابَانِ يَمُدَّانِهِ مِنَ الْجَنَّةِ، أَحَدُهُمَا مِنْ ذَهَبٍ وَالْآخَرُ مِنْ وَرِقٍ."],"takhrij":"صحيح: رواه مسلم في الفضائل (2301) من طرق عن معاذ بن هشام، حدّثني أبي، عن قتادة، عن سالم بن أبي الجعد، عن معدان بن أبي طلحة اليعمريّ، عن ثوبان، فذكره.","grade":"صحيح","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2301).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["Thawbān may Allah be pleased with him reported that the Prophet of Allah ﷺ said: “I will be at the central part of my Basin, driving the people away so that the people of Yemen may drink. I will strike with my staff until the water pours out for them.” He was asked about its width and replied: “From where I stand to ʿAmmān.” He was asked about its drink and said: “Whiter than milk and sweeter than honey. Two channels gush into it and supply it from Paradise: one of them is of gold and the other of silver.”"]},"buhuth":{"en":["Regarding the expression:","“Two channels gush into it and supply it,”","al-Nawawī said:","“This is how Thābit, al-Khaṭṭābī, al-Harawī, the author of al-Taḥrīr, and the majority recorded it: yaghuttu. This is likewise how it appears in most of the copies in our lands, and al-Qāḍī transmitted it from most scholars.”","Al-Harawī said:","“It means that they pour water into it in a strong, continuous succession.”","They said that the word derives from one thing following another.","It has also been said that they continuously pour into it with a powerful flow."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2301)."},{"num":839,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ سَمُرَةَ، عَنِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَلَا إِنِّي فَرَطٌ لَكُمْ عَلَى الْحَوْضِ، وَإِنَّ بُعْدَ مَا بَيْنَ طَرَفَيْهِ كَمَا بَيْنَ صَنْعَاءَ وَأَيْلَةَ، كَأَنَّ الْأَبَارِيقَ فِيهِ النُّجُومُ."],"takhrij":"صحيح: رواه مسلم في الفضائل (2305) عن الوليد بن شجاع بن الوليد السكوني، حدثني أبي، حدثني زياد بن خيثمة، عن سماك بن حرب، عن جابر بن سمرة، فذكره.","grade":"صحيح","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim in al-Faḍāʾil (2305).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["Jābir ibn Samurah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Indeed, I will precede you to the Basin. The distance between its two ends is like the distance between Ṣanʿāʾ and Aylah, and its pitchers are like the stars.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2305)."},{"num":840,"demo":false,"sanad":"","matn":["عَنْ عَامِرِ بْنِ سَعْدِ بْنِ أَبِي وَقَّاصٍ قَالَ: كَتَبْتُ إِلَى جَابِرِ بْنِ سَمُرَةَ مَعَ غُلَامِي نَافِعٍ، أَخْبِرْنِي بِشَيْءٍ سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: فَكَتَبَ إِلَيَّ إِنِّي سَمِعْتُهُ، يَقُولُ: أَنَا الْفَرَطُ عَلَى الْحَوْضِ."],"takhrij":"صحيح: رواه مسلم في الفضائل (2305: 45) من طرق عن حاتم بن إسماعيل، عن المهاجر بن مسمار، عن عامر بن سعد بن أبي وقاص، فذكره.","grade":"صحيح","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2305:45).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["ʿĀmir ibn Saʿd ibn Abī Waqqāṣ said: I wrote to Jābir ibn Samurah through my servant Nāfiʿ: “Tell me something that you heard from the Messenger of Allah ﷺ.” He wrote back to me: “I heard him say: ‘I am the forerunner at the Basin.’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2305: 45)."},{"num":841,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: أَنَا فَرَطُكُمْ بَيْنَ أَيْدِيكُمْ، فَإِنْ لَمْ تَجِدُونِي فَأَنَا عَلَى الْحَوْضِ مَا بَيْنَ أَيْلَةَ إِلَى مَكَّةَ، وَسَيَأْتِي رِجَالٌ وَنِسَاءٌ بِآنِيَةٍ وَقِرَبٍ ثُمَّ لا يَذُوقُونَ مِنْهُ شَيْئًا."],"takhrij":"حسن: رواه ابن حبان في صحيحه (6449) عن عبدالله بن أحمد بن موسى بعسكر مكرم، قال: حدّثنا محمد بن معمر، قال: حدّثنا أبو عاصم، عن ابن جريج، قال: حدثني أبو الزبير، قال: سمعت جابر بن عبدالله، فذكر الحديث.","grade":"حسن","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Ibn Ḥibbān in his Ṣaḥīḥ (6449).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh, may Allah be pleased with them, said: I heard the Messenger of Allah ﷺ say: “I will go ahead of you as your forerunner. If you do not find me, then I will be at the Basin, whose extent is from Aylah to Makkah. Men and women will come carrying vessels and waterskins, yet they will not taste anything from it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن حبان في صحيحه (6449)."},{"num":842,"demo":false,"sanad":"","matn":["عَنِ الصُّنَابِحِ الْأَحْمَسِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَلا إِنِّي فَرَطُكُمْ عَلَى الْحَوْضِ، وَإِنِّي مُكَاثِرٌ بِكُمُ الأُمَمَ، فَلا تَقْتَتِلُنَّ بَعْدِي."],"takhrij":"صحيح: رواه ابن ماجه (3944) عن محمد بن عبدالله بن نمير، قال: حدّثنا أبي ومحمد بن بشر، قالا: حدّثنا إسماعيل، عن قيس، عن الصّنابح، فذكره.","grade":"صحيح","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Ibn Mājah (3944), Aḥmad (19069), and Ibn Abī ʿĀṣim in al-Sunnah (739).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["Al-Ṣunābiḥ al-Aḥmasī may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Indeed, I will precede you to the Basin, and I will take pride in your great numbers before the other nations. So do not fight one another after me.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (3944)، وأحمد (19069)، وابن أبي عاصم في السنة (739)."},{"num":843,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَكْرٍ الصِّدِّيقِ قَالَ (فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ): قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَيْ رَبِّ خَلَقْتَنِي، سَيِّدَ وَلَدِ آدَمَ، وَلَا فَخْرَ، وَأَوَّلَ مَنْ تَنْشَقُّ عَنْهُ الْأَرْضُ يَوْمَ الْقِيَامَةِ، وَلَا فَخْرَ، حَتَّى إِنَّهُ لَيَرِدُ عَلَيَّ الْحَوْضَ أَكْثَرُ مِمَّا بَيْنَ صَنْعَاءَ، وَأَيْلَةَ."],"takhrij":"حسن: رواه الإمام أحمد (15) عن إبراهيم بن إسحاق الطّالقانيّ، قال: حدّثني النّضر بن شميل المازنيّ، قال: حدّثني أبو نعامة، قال حدّثني أبو هنيدة البراء بن نوفل، عن والان العدويّ، عن حذيفة، عن أبي بكر الصديق في حديث طويل.","grade":"حسن","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (15).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["Abū Bakr al-Ṣiddīq may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “O my Lord, You created me as the leader of the children of Adam—and I say this without boasting—and I will be the first for whom the earth is split open on the Day of Resurrection—and I say this without boasting. Indeed, the Basin to which I will come is greater in extent than the distance between Ṣanʿāʾ and Aylah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (15)."},{"num":844,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: سَأَلْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَشْفَعَ لِي يَوْمَ الْقِيَامَةِ، فَقَالَ: أَنَا فَاعِلٌ قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ فَأَيْنَ أَطْلُبُكَ؟ قَالَ: اطْلُبْنِي أَوَّلَ مَا تَطْلُبُنِي عَلَى الصِّرَاطِ، قَالَ: قُلْتُ: فَإِنْ لَمْ أَلْقَكَ عَلَى الصِّرَاطِ؟ قَالَ: فَاطْلُبْنِي عِنْدَ الْمِيزَانِ، قُلْتُ: فَإِنْ لَمْ أَلْقَكَ عِنْدَ الْمِيزَانِ؟ قَالَ: فَاطْلُبْنِي عِنْدَ الْحَوْضِ، فَإِنِّي لَا أُخْطِئُ هَذِهِ الثَّلَاثَ الْمَوَاطِنَ."],"takhrij":"حسن: رواه الترمذيّ (2433) عن عبدالله بن الصّباح الهاشميّ، حدّثنا بدل بن المحبرَّ، حدّثنا حرب بن ميمون الأنصاريّ أبو الخطّاب، حدّثنا النّضر بن أنس، عن أبيه، فذكره.","grade":"حسن","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Tirmidhī (2433) and Aḥmad (12825).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["Anas, may Allah be pleased with him, said: I asked the Prophet ﷺ to intercede for me on the Day of Resurrection. He replied: “I will do so.” I asked: “O Messenger of Allah, where should I look for you?” He said: “First look for me at the Ṣirāṭ.” I asked: “What if I do not find you at the Ṣirāṭ?” He replied: “Then look for me at the Scale.” I asked: “What if I do not find you at the Scale?” He replied: “Then look for me at the Basin, for I will not be absent from these three places.”"]},"buhuth":{"en":["Al-Tirmidhī said:","“A Ḥasan Gharīb ḥadīth.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (2433)، وأحمد (12825)."},{"num":845,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ الْبَاهِلِيِّ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ اللَّهَ وَعَدَنِي أَنْ يُدْخِلَ مِنْ أُمَّتِي الْجَنَّةَ سَبْعِينَ أَلْفًا بِغَيْرِ حِسَابٍ.","فَقَالَ يَزِيدُ بْنُ الْأَخْنسَ السُّلَمِيُّ: وَاللَّهِ مَا أُولَئِكَ فِي أُمَّتِكَ إِلَّا كَالذُّبَابِ الْأَصْهَبِ فِي الذِّبَّانِ! فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فَإِنَّ رَبِّي قَدْ وَعَدَنِي سَبْعِينَ أَلْفًا مَعَ كُلِّ أَلْفٍ سَبْعُونَ أَلْفًا، وَزَادَنِي ثَلَاثَ حَثَيَاتٍ.","قَالَ: فَمَا سِعَةُ حَوْضِكَ يَا نَبِيَّ اللَّهِ؟ قَالَ: كَمَا بَيْنَ عَدَنَ إِلَى عُمَانَ، وَأَوْسَعَ وَأَوْسَعَ يُشِيرُ بِيَدِهِ، قَالَ: فِيهِ مَثْعَبَانِ مِنْ ذَهَبٍ وَفِضَّةٍ، قَالَ: فَمَا حَوْضُكَ يَا نَبِيَّ اللَّهِ؟ قَالَ: مَاءٌ أَشَدُّ بَيَاضًا مِنَ اللَّبَنِ، وَأَحْلَى مَذَاقَةً مِنَ الْعَسَلِ، وَأَطْيَبُ رَائِحَةً مِنَ الْمِسْكِ، مَنْ شَرِبَ مِنْهُ لَمْ يَظْمَأْ بَعْدَهَا، وَلَمْ يَسْوَدَّ وَجْهُهُ أَبَدًا."],"takhrij":"حسن: رواه أحمد (22156) قال: حدّثنا عصام بن خالد، حدّثني صفوان بن عمرو، عن سُليم بن عامر الخبائريّ وأبي اليمان الهوزَنيّ، عن أبي أمامة، فذكره.","grade":"حسن","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan due to supporting narration: Narrated by Aḥmad (22156), al-Ṭabarānī in al-Muʿjam al-Kabīr (7672), and Ibn Ḥibbān (6457, 7246).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["Abū Umāmah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Indeed, Allah has promised me that He will admit seventy thousand from my Ummah into Paradise without reckoning.”","It was asked: “How vast is your Basin, O Prophet of Allah?” He replied: “Like the distance from ʿAdan to ʿAmmān—and wider, and wider,” gesturing with his hand. He said: “In it are two channels, one of gold and one of silver.”","It was asked: “What is the water of your Basin like, O Prophet of Allah?” He replied: “Water whiter than milk, sweeter in taste than honey, and more fragrant than musk. Whoever drinks from it will never thirst afterward, and his face will never become darkened.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (22156)، والطبراني في الكبير (7672)، وابن حبان (6457، 7246)."},{"num":846,"demo":false,"sanad":"","matn":["عَنْ عُتْبَةَ بْنِ عَبْدٍ السُّلَمِيِّ يَقُولُ: قَامَ أَعْرَابِيٌّ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: مَا حَوْضُكَ الَّذِي تُحَدِّثُ عَنْهُ؟ فَقَالَ: هُوَ كَمَا بَيْنَ صَنْعَاءَ إِلَى بُصْرَى، ثُمَّ يُمِدُّنِي اللَّهُ فِيهِ بِكُرَاعٍ لا يَدْرِي بَشَرٌ مِمَّنْ خُلِقَ أَيُّ طَرَفَيْهِ.","قَالَ فَكَبَّرَ عُمَرُ، فَقَالَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَمَّا الْحَوْضُ فَيَزْدَحِمُ عَلَيْهِ فُقَرَاءُ الْمُهَاجِرِينَ الَّذِينَ يُقْتُلُونَ فِي سَبِيلِ اللَّهِ وَيَمُوتُونَ فِي سَبِيلِ اللَّهِ، وَأَرْجُو أَنْ يُورِدَنِيَ اللَّهُ الْكُرَاعَ فَأَشْرَبَ مِنْهُ."],"takhrij":"حسن: رواه ابن حبان في صحيحه (6450) من طريق معمر بن يعمر، قال: حدّثنا معاوية بن سلاّم، قال: حدّثنا أخي زيد بن سلاّم، أنه سمع أبا سلاّم، قال: حدّثني عامر بن زيد البكالي أنه سمع عتبة بن عبدالسلمي، فذكره.","grade":"حسن","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Ibn Ḥibbān in his Ṣaḥīḥ (6450) and Ibn Abī ʿĀṣim in al-Sunnah (715).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["ʿUtbah ibn ʿAbd al-Sulamī, may Allah be pleased with him, said: A Bedouin stood before the Messenger of Allah ﷺ and asked: “What is this Basin of yours that you speak about?” He replied: “It is like the distance between Ṣanʿāʾ and Buṣrā. Then Allah will extend to me within it a projecting channel whose two ends no human being among creation knows.”","ʿUmar, may Allah be pleased with him, said: “Allāhu Akbar!” The Prophet ﷺ then said: “As for the Basin, the poor among the Muhājirūn will crowd around it—those who fight in the path of Allah and die in the path of Allah. And I hope that Allah will bring me to that channel so that I may drink from it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن حبان في صحيحه (6450)، وابن أبي عاصم في السنة (715)."},{"num":847,"demo":false,"sanad":"","matn":["عَنْ يُحَنَّسَ، أَنَّ حَمْزَةَ بْنَ عَبْدِ الْمُطَّلِبِ لَمَّا قَدِمَ الْمَدِينَةَ، تَزَوَّجَ خَوْلَةَ بِنْتَ قَيْسِ بْنِ قَهْدٍ الْأَنْصَارِيَّةَ مِنْ بَنِي النَّجَّارِ، قَالَ: وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَزُورُ حَمْزَةَ فِي بَيْتِهَا، وَكَانَتْ تُحَدِّثُهُ عَنْهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَحَادِيثَ، قَالَتْ: جَاءَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمًا، فَقُلْتُ: يَا رَسُولَ اللَّهِ، بَلَغَنِي عَنْكَ أَنَّكَ تُحَدِّثُ أَنَّ لَكَ يَوْمَ الْقِيَامَةِ حَوْضًا مَا بَيْنَ كَذَا إِلَى كَذَا؟ قَالَ: أَجَلْ، وَأَحَبُّ النَّاسِ إِلَيَّ أَنْ يَرْوَى مِنْهُ قَوْمُكِ، قَالَتْ: فَقَدَّمْتُ إِلَيْهِ بُرْمَةً فِيهَا خُبْزَةٌ أَوْ حَرِيرَةٌ، فَوَضَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدَهُ فِي الْبُرْمَةِ لِيَأْكُلَ، فَاحْتَرَقَتْ أَصَابِعُهُ، فَقَالَ: حَسِّ، ثُمَّ قَالَ: ابْنُ آدَمَ إِنْ أَصَابَهُ الْبَرْدُ، قَالَ: حَسِّ، وَإِنْ أَصَابَهُ الْحَرُّ قَالَ: حَسِّ."],"takhrij":"صحيح: رواه الإمام أحمد (27316) عن حسين بن محمد، قال: حدثنا جرير، يعني ابن حازم، عن يحى بن سعيد، عن يُحَنَّس، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Imām Aḥmad (27316).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["Yaḥnas reported: When Ḥamzah ibn ʿAbd al-Muṭṭalib may Allah be pleased with him came to Madinah, he married Khawlah bint Qays ibn Qahd al-Anṣāriyyah of Banū al-Najjār. The Messenger of Allah ﷺ used to visit Ḥamzah at her house, and she would narrate reports concerning the Prophet ﷺ. She said: The Messenger of Allah ﷺ came to us one day, and I said: “O Messenger of Allah, it has reached me that you mention that on the Day of Resurrection you will have a Basin extending from such-and-such to such-and-such.” He replied: “Yes, and the people most beloved to me to be given their fill from it are your people.” She said: I then brought him a cooking pot containing bread—or khazīrah. The Messenger of Allah ﷺ placed his hand into the pot to eat, and his fingers were burned by its heat. He said: “Ḥass!” Then he said: “The son of Adam, when cold afflicts him, says, ‘Ḥass!’ and when heat afflicts him, he says, ‘Ḥass!’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (27316)."},{"num":848,"demo":false,"sanad":"","matn":["عَنْ أَبِي الدَّرْدَاءِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَا فَرَطُكُمْ عَلَى الْحَوْضِ، فَلَأَعْرِفَنَّ مَا نُوزِعْتُ فِي أَحَدٍ مِنْكُمْ.","وَفِي رِوَايَةِ: لَأُلْفَيَنَّ مَا نُوزِعْتُ أَحَدًا مِنْكُمْ عَلَى الْحَوْضِ، فَأَقُولُ: أُنَاسٌ مِنْ أَصْحَابِي . فَيُقَالُ: إِنَّكَ لَا تَدْرِي مَا أَحْدَثُوا بَعْدَكَ. قَالَ أَبُو الدَّرْدَاءِ: يَا رَسُولَ اللَّهِ، ادْعُ اللَّهَ أَنْ لَا يَجْعَلَنِي مِنْهُمْ . قَالَ: لَسْتَ مِنْهُمْ."],"takhrij":"حسن: رواه ابن أبي عاصم في السنة (737، 767) عن هشام بن عمار، ثنا يحيى بن حمزة، ثنا يزيد بن أبي مريم، أنّ أبا عبيدالله حدّثه عن أبي الدّرداء، فذكره.","grade":"حسن","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Ibn Abī ʿĀṣim in al-Sunnah (737, 767, 768).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["Abū al-Dardāʾ may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “I will precede you to the Basin, and I will certainly recognize when one of you is disputed with me.” In another narration:","“I will certainly find myself disputed over one of you at the Basin, and I will say: ‘This is one of my Companions.’ Then it will be said: ‘You do not know what they introduced after you.’” Abū al-Dardāʾ said: “O Messenger of Allah, ask Allah not to make me one of them.” He replied: “You are not among them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن أبي عاصم في السنة (737، 767، 768)."},{"num":849,"demo":false,"sanad":"","matn":["عَنْ عُمَرَ بْنِ الْخَطَّابِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَا مُمْسِكٌ بِحُجَزِكُمْ عَنِ النَّارِ، وَتَغْلِبُونَ، تَقَاحَمُونَ فِيهَا تَقَاحُمَ الْفَرَاشِ وَالْجَنَادِبِ، وَأُوشِكُ أَنْ أُرْسِلَ بِحُجَزِكُمْ، وَأَفْرُطَ لَكُمْ عَلَى الْحَوْضِ، وَتُرَدُّونَ عَلَيَّ جَمْعًا وَأَشْتَاتًا."],"takhrij":"حسن: رواه ابن أبي شيبة في المصنف (11/451، 452)، وعنه ابنُ أبي عاصم في السنة (744) عن مالك بن إسماعيل، ثنا يعقوب بن عبدالله القميّ، عن حفص بن حُميد، عن عكرمة، عن ابن عباس، عن عمر بن الخطاب، فذكره.","grade":"حسن","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Ibn Abī Shaybah in al-Muṣannaf (11/451–452), and through him by Ibn Abī ʿĀṣim in al-Sunnah (744).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["ʿUmar may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “I am holding you back by your waistbands from the Fire, while you overpower me and rush into it as moths and locusts rush forward. Soon I will release your waistbands and precede you to the Basin, and you will come to me both together and separately.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن أبي شيبة في المصنف (31678)، وعنه ابن أبي عاصم في السنة (744)."},{"num":850,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: سَمِعْتُ رَسُولَ اللَّهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ عَلَى هَذَا الْمِنْبَرِ: مَا بَالُ رِجَالٍ يَقُولُونَ: إِنَّ رَحِمَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَا تَنْفَعُ قَوْمَهُ؟ بَلَى وَاللَّهِ إِنَّ رَحِمِي مَوْصُولَةٌ فِي الدُّنْيَا وَالْآخِرَةِ، وَإِنِّي يَا أَيُّهَا النَّاسُ فَرَطٌ لَكُمْ عَلَى الْحَوْضِ، فَإِذَا جِئْتُمْ قَالَ رَجُلٌ: يَا رَسُولَ اللَّهِ أَنَا فُلَانُ بْنُ فُلَانٍ، وَقَالَ آخَرُ: أَنَا فُلَانُ بْنُ فُلَانٍ، فَأَقُولُ: أَمَّا النَّسَبُ فَقَدْ عَرَفْتُهُ وَلَكِنَّكُمْ أَحْدَثْتُمْ بَعْدِي وَارْتَدَدْتُمُ الْقَهْقَرَى."],"takhrij":"حسن: رواه أبو يعلى (1238) عن زهير، حدّثنا أبو عامر، عن زهير، عن عبدالله بن محمد، عن عبدالرحمن بن أبي سعيد، عن أبيه، فذكره.","grade":"حسن","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Abū Yaʿlā (1238) and al-Ḥākim (6958).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī, may Allah be pleased with him, said: I heard the Messenger of Allah ﷺ say from this pulpit: “What is the matter with men who say that kinship with the Messenger of Allah ﷺ will not benefit his relatives? Rather, by Allah, my ties of kinship remain connected in this world and in the Hereafter. Indeed, O people, I will precede you to the Basin. When you come to me, one man will say: ‘O Messenger of Allah, I am so-and-so son of so-and-so.’ Another will say: ‘I am so-and-so son of so-and-so.’ I will say: ‘As for your lineage, I recognize it. But you introduced changes after me and turned backward upon your heels.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو يعلى (1238)، والحاكم (4/74–75)."},{"num":851,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَرْزَةَ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ لِي حَوْضًا مَا بَيْنَ أَيْلَةَ إِلَى صَنْعَاءَ، عَرْضُهُ كَطُولِهِ، فِيهِ مِيزَابَانِ يَنْثَعِبَانِ مِنَ الْجَنَّةِ، مِنْ وَرِقٍ، وَالْآخَرُ مِنْ ذَهَبٍ، أَحْلَى مِنَ الْعَسَلِ، وَأَبْرَدُ مِنَ الثَّلْجِ، وَأَبْيَضُ مِنَ اللَّبَنِ، مَنْ شَرِبَ مِنْهُ لَمْ يَظْمَأْ حَتَّى يَدْخُلَ الْجَنَّةَ، فِيهِ أَبَارِيقُ عَدَدَ نُجُومِ السَّمَاءِ."],"takhrij":"حسن: رواه الإمام أحمد (19804)، والبزار (3849)، وابن أبي عاصم في السنة (722) كلهم من طريق شدّاد بن سعيد أبي طلحة، قال: حدّثنا جابر بن عمرو أبو الوازع أنه سمع أبا برزة الأسلمي يقول (فذكره).","grade":"حسن","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Aḥmad (19804), al-Bazzār (3849), Ibn Abī ʿĀṣim in al-Sunnah (722), and Ibn Ḥibbān (6458).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["Abū Barzah, may Allah be pleased with him, said: I heard the Messenger of Allah ﷺ say: “Indeed, I have a Basin extending from Aylah to Ṣanʿāʾ, its width equal to its length. Into it pour two channels from Paradise, one of silver and the other of gold. Its water is sweeter than honey, colder than snow, and whiter than milk. Whoever drinks from it will not thirst until he enters Paradise. In it are pitchers as numerous as the stars of the sky.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (19804)، والبزار (3849)، وابن أبي عاصم في السنة (722)، وابن حبان (6458)."},{"num":852,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ الْأَسْلَمِيِّ قَالَ: شَكَّ عُبَيْدُ اللَّهِ بْنُ زِيَادٍ فِي الْحَوْضِ، وَكَانَتْ فِيهِ حَرُورِيَّةٌ، فَقَالَ: أَرَأَيْتُمُ الْحَوْضَ الَّذِي يُذْكَرُ، مَا أُرَاهُ شَيْئًا، قَالَ: فَقَالَ لَهُ نَاسٌ مِنْ صَحَابَتِهِ: فَإِنَّ عِنْدَكَ رَهْطًا مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَرْسِلْ إِلَيْهِمْ فَاسْأَلْهُمْ، فَأَرْسَلَ إِلَى رَجُلٍ مِنْ مُزَيْنَةَ فَسَأَلَهُ عَنِ الْحَوْضِ، فَحَدَّثَهُ ثُمَّ قَالَ: أَرْسِلْ إِلَى أَبِي بَرْزَةَ الْأَسْلَمِيِّ فَأَتَاهُ وَعَلَيْهِ ثَوْبَا حِبَرٍ، قَدِ ائْتَزَرَ بِوَاحِدٍ، وَارْتَدَى بِالْآخَرِ، قَالَ: وَكَانَ رَجُلًا لَحِيمًا إِلَى الْقِصَرِ، فَلَمَّا رَآهُ عُبَيْدُ اللَّهِ ضَحِكَ، ثُمَّ قَالَ: إِنَّ مُحَمَّدِيَّكُمْ هَذَا لَدَحْدَاحٌ، قَالَ: فَفَهِمَهَا الشَّيْخُ، فَقَالَ: وَاعَجَبَاهُ! أَلَا أُرَانِي فِي قَوْمِي يَعُدُّونَ صَحَابَةَ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَارًا، قَالَ: فَقَالَ لَهُ جُلَسَاءُ عُبَيْدِ اللَّهِ: إِنَّمَا أَرْسَلَ إِلَيْكَ الْأَمِيرُ لِيَسْأَلَكَ عَنِ الْحَوْضِ، هَلْ سَمِعْتَ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيهِ شَيْئًا؟ قَالَ: نَعَمْ، سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَذْكُرُهُ فَمَنْ كَذَبَ بِهِ فَلَا سَقَاهُ اللَّهُ مِنْهُ، قَالَ: ثُمَّ نَفَضَ رِدَاءَهُ وَانْصَرَفَ غَضْبَانَ، قَالَ: فَأَرْسَلَ عُبَيْدُ اللَّهِ إِلَى زَيْدِ بْنِ الْأَرْقَمِ فَسَأَلَهُ عَنِ الْحَوْضِ، فَحَدَّثَهُ حَدِيثًا مُونَقًا أَعْجَبَهُ، فَقَالَ: إِنَّمَا سَمِعْتُ هَذَا مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: لَا، وَلَكِنْ حَدَّثَنِيهِ أَخِي، قَالَ: فَلَا حَاجَةَ لَنَا فِي حَدِيثِ أَخِيكَ! فَقَالَ أَبُو سَبْرَةَ، رَجُلٌ مِنْ صَحَابَةِ عُبَيْدِ اللَّهِ: فَإِنَّ أَبَاكَ حِينَ انْطَلَقَ وَافِدًا إِلَى مُعَاوِيَةَ انْطَلَقْتُ مَعَهُ، فَلَقِيتُ عَبْدَ اللَّهِ بْنَ عَمْرِو بْنِ الْعَاصِ فَحَدَّثَنِي مِنْ فِيهِ إِلَى فِيَّ حَدِيثًا سَمِعَهُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَمْلَاهُ عَلَيَّ وَكَتَبْتُهُ، قَالَ: فَإِنِّي أَقْسَمْتُ عَلَيْكَ لَمَا أَعْرَقْتَ هَذَا الْبِرْذَوْنَ حَتَّى تَأْتِيَنِي بِالْكِتَابِ، قَالَ: فَرَكِبْتُ الْبِرْذَوْنَ فَرَكَضْتُهُ حَتَّى عَرِقَ، فَأَتَيْتُهُ بِالْكِتَابِ، فَإِذَا فِيهِ هَذَا مَا حَدَّثَنِي عَبْدُ اللَّهِ بْنُ عَمْرِو بْنِ الْعَاصِ أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ اللَّهَ يُبْغِضُ الْفُحْشَ وَالتَّفَحُّشَ، وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ لَا تَقُومُ السَّاعَةُ حَتَّى يَظْهَرَ الْفُحْشُ وَالتَّفَحُّشُ، وَسُوءُ الْجِوَارِ، وَقَطِيعَةُ الْأَرْحَامِ، وَحَتَّى يُخَوَّنَ الْأَمِينُ، وَيُؤْتَمَنَ الْخَائِنُ، وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ إِنَّ أَسْلَمَ الْمُسْلِمِينَ، لَمَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ، وَإِنَّ أَفْضَلَ الْهِجْرَةِ لَمَنْ هَجَرَ مَا نَهَاهُ اللَّهُ عَنْهُ، وَالَّذِي نَفْسِي بِيَدِهِ إِنَّ مَثَلَ الْمُؤْمِنِ كَمَثَلِ الْقِطْعَةِ مِنَ الذَّهَبِ نَفَخَ عَلَيْهَا صَاحِبُهَا فَلَمْ تَتَغَيَّرْ وَلَمْ تَنْقُصْ، وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ، إِنَّ مَثَلَ الْمُؤْمِنِ كَمَثَلِ النَّخْلَةِ أَكَلَتْ طَيِّبًا وَوَضَعَتْ طَيِّبًا، وَوَقَعَتْ فَلَمْ تُكْسَرْ وَلَمْ تَفْسُدْ، أَلَا وَإِنَّ لِي حَوْضًا مَا بَيْنَ نَاحِيَتَيْهِ كَمَا بَيْنَ أَيْلَةَ إِلَى مَكَّةَ أَوْ قَالَ: صَنْعَاءَ إِلَى الْمَدِينَةِ، وَإِنَّ فِيهِ مِنَ الْأَبَارِيقِ مَثَلَ الْكَوَاكِبِ، هُوَ أَشَدُّ بَيَاضًا مِنَ اللَّبَنِ، وَأَحْلَى مِنَ الْعَسَلِ، مَنْ شَرِبَ مِنْهُ لَمْ يَظْمَأْ بَعْدَهَا أَبَدًا.","قَالَ أَبُو سَبْرَةَ: فَأَخَذَ عُبَيْدُ اللَّهِ الْكِتَابَ، فَجَزِعْتُ عَلَيْهِ، فَلَقِيَ يَحْيَى بْنَ يَعْمُرَ فَشَكَوْتُ ذَلِكَ إِلَيْهِ، فَقَالَ: وَاللَّهِ لَأَنَا أَحْفَظُ لَهُ مِنِّي لِسُورَةٍ مِنَ الْقُرْآنِ، فَحَدَّثَنِي بِهِ كَمَا كَانَ فِي الْكِتَابِ سَوَاءً."],"takhrij":"حسن: رواه عبدالرّزاق (20852)، وأحمد (6514، 6872، 19763)، كاملاً ومختصراً،، وابن أبي عاصم في السنة (700، 701، 702)، والحاكم (253)، والبيهقي في البعث (155) كلهم من طرقٍ عن عبد الله بن بريدة، عن أبي سبرة، عن عبدالله بن عمرو بن العاص قال: فذكره مطولا ومختصرًا.","grade":"حسن","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by ʿAbd al-Razzāq (20852), and through him by Aḥmad (19763, 6872).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["ʿAbdullāh ibn Buraydah reported: ʿUbaydullāh ibn Ziyād doubted the reality of the Basin, and there were some Ḥarūriyyah with him. He said: “What do you think of this Basin that is mentioned? I do not think it is anything!” Some of his companions said: “There are a number of the Companions of the Prophet ﷺ with you. Send for them and ask them.” So he sent for a man from Muzaynah and asked him about the Basin, and the man narrated to him concerning it. Then he said: “Send for Abū Barzah al-Aslamī.” Abū Barzah came wearing two striped garments, one wrapped around his waist and the other draped over his shoulders. He was a stocky man of somewhat short stature. When ʿUbaydullāh saw him, he laughed and said: “This Muḥammadan of yours is certainly a short, stocky man!” The elderly Companion understood what he meant and said: “How astonishing! I never thought I would live to see a time when my people would regard companionship with Muḥammad ﷺ as a disgrace!” Those sitting with ʿUbaydullāh said: “The governor only summoned you to ask you about the Basin. Did you hear anything concerning it from the Messenger of Allah ﷺ?” He replied: “Yes. I heard the Messenger of Allah ﷺ mention it. Whoever denies it—may Allah not give him a drink from it.” He then shook out his cloak and departed angrily. ʿUbaydullāh then sent for Zayd ibn Arqam and asked him about the Basin. Zayd related to him an impressive report that pleased him. He asked: “Did you personally hear this from the Messenger of Allah ﷺ?” Zayd replied: “No, but my brother narrated it to me.” He said: “Then we have no need for your brother’s narration.” Abū Sabrah—one of ʿUbaydullāh’s companions—then said: “When your father went as a delegate to Muʿāwiyah, I accompanied him. I met ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ, and he narrated directly to me a ḥadīth that he had heard from the Messenger of Allah ﷺ. He dictated it to me and I wrote it down.” ʿUbaydullāh said: “I adjure you to ride this horse hard until it sweats and bring me that written document.” Abū Sabrah said: So I mounted the horse and drove it until it sweated, then brought him the document. In it was written: “This is what ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ narrated to me, that he heard the Messenger of Allah ﷺ say: ‘Indeed, Allah hates obscenity and deliberate obscene conduct. By the One in whose Hand is the soul of Muḥammad, the Hour will not be established until obscenity and shameless conduct become widespread, bad treatment of neighbors and severing of family ties become widespread, the trustworthy person is betrayed, and the treacherous person is trusted. By the One in whose Hand is the soul of Muḥammad, among the best Muslims is the one from whose tongue and hand the Muslims are safe, and the best migration is that of one who abandons what Allah has forbidden. By the One in whose Hand is my soul, the example of the believer is like a piece of gold: its owner blows upon it, yet it neither changes nor diminishes. By the One in whose Hand is the soul of Muḥammad, the example of the believer is like the date-palm: it takes in what is good, produces what is good, and if it falls, it neither breaks nor spoils. Indeed, I have a Basin whose two sides are like the distance between Aylah and Makkah—or he said, between Ṣanʿāʾ and Madinah. Its pitchers are like the stars. Its water is whiter than milk and sweeter than honey. Whoever drinks from it will never thirst afterward.’” Abū Sabrah said: Then ʿUbaydullāh took the written document, and I became distressed over losing it.","Later I met Yaḥyā ibn Yaʿmar and complained to him about that. He said: “By Allah, I have memorized it more firmly than I have memorized a sūrah of the Qurʾān.” Then he narrated it to me exactly as it had been written in the document."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه عبد الرزاق (20852)، وعنه أحمد (19763، 6872)."},{"num":853,"demo":false,"sanad":"","matn":["عَنْ أَبِي حَمْزَةَ قَالَ: دَخَلَ أَبُو بَرْزَةَ عَلَى عَبْيدَالَلهِ بْنِ زِيَادٍ، فَقَالَ: إِنَّ مُحَدِّثَكُمْ هَذَا لَدَحْدَاحٌ، فَقَالَ: مَا كُنْتُ أَرَى أَعِيشُ فِي قَوْمٍ يَعُدُّونَ صُحْبَةَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهُ وَسَلَّمَ عَارًا. قَالُوا: إِنَّ الْأَمِيرَ إِنَّمَا دَعَاكَ لِيَسْأَلَكَ عَنِ الْحَوْضِ، عَنْ أَيِّ بَالِهِ، قَالَ: أَحَقٌّ هُوَ؟ قَالَ: نَعَمْ، فَمَنْ كَذَّبَ بِهِ فَلَا سَقَاهُ اللَّهُ مِنْهُ."],"takhrij":"حسن: رواه البيهقيّ في البعث (154) من طريق محمد بن يحيى الذّهليّ، ثنا عبدالرحمن بن مهدي، عن قرّة بن خالد، عن أبي حمزة، فذكره.","grade":"حسن","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Bayhaqī in al-Baʿth (154).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["Abū Ḥamzah reported: Abū Barzah entered upon ʿUbaydullāh ibn Ziyād, who said: “This Muḥammadan of yours is certainly a short, stocky man!” Abū Barzah replied: “I never thought I would live among people who regarded companionship with the Messenger of Allah ﷺ as a disgrace.” They said: “The governor only summoned you to ask you about the Basin and its reality.” He said: “Is it true?” He replied: “Yes. Whoever denies it—may Allah not give him a drink from it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البيهقي في البعث (154)."},{"num":854,"demo":false,"sanad":"","matn":["عَنْ أَبِي طَالُوتَ الْعَنَزِيِّ قَالَ: سَمِعْتُ أَبَا بَرْزَةَ وَخَرَجَ مِنْ عِنْدِ عُبَيْدِ اللَّهِ بْنِ زِيَادٍ وَهُوَ مُغْضَبٌ فَقَالَ: مَا كُنْتُ أَظُنُّ أَنِّي أَعِيشُ حَتَّى أُخَلَّفُ فِي قَوْمٍ يُعَيِّرُونِي بِصُحْبَةِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالُوا: إِنَّ مُحَمَّدِيَّكُمْ هَذَا الَدَّحْدَاحٌ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ فِي الْحَوْضِ: فَمَنْ كَذَّبَ فَلَا سَقَاهُ اللَّهُ مِنْهُ."],"takhrij":"حسن: رواه الإمام أحمد (19779) عن يزيد بن هارون، أخبرنا محمد بن مهزم العنزيّ، عن أبي طالوت العنزيّ، قال: فذكره.","grade":"حسن","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (19779).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["Abū Ṭālūt al-ʿAnazī reported: I heard Abū Barzah as he came out from the presence of ʿUbaydullāh ibn Ziyād, breathing heavily. He said: “I never thought I would live long enough to remain among a people who reproach me for having been a Companion of Muḥammad ﷺ!” They said: “This Muḥammadan of yours is the short, stocky man!” He said: “I heard the Messenger of Allah ﷺ speak concerning the Basin. Whoever denies it—may Allah not give him a drink from it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (19779)."},{"num":855,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ زِيَادًا أَوِ ابْنَ زِيَادٍ، ذُكِرَ عِنْدَهُ الْحَوْضُ، فَأَنْكَرَ ذَلِكَ، فَبَلَغَ ذَلِكَ أَنَسًا، فَقَالَ: أَمَا وَاللَّهِ لَأَسُوءَنَّهُ غَدًا. فَقَالَ: مَا أَنْكَرْتُمْ مِنَ الْحَوْضِ؟ قَالُوا: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَذْكُرُهُ؟ قَالَ: نَعَمْ، وَلَقَدْ أَدْرَكْتُ عَجَائِزَ بِالْمَدِينَةِ لَا يُصَلِّينَ صَلَاةً إِلَّا سَأَلْنَ اللَّهَ تَعَالَى أَنْ يُورِدَهُنَّ حَوْضَ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه ابن أبي عاصم في السنة (698) عن هدبة، ثنا حمّاد بن سلمة، عن ثابت، عن أنس، فذكره.","grade":"صحيح","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Ibn Abī ʿĀṣim in al-Sunnah (698) and Abū Yaʿlā (3355).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["Anas ibn Mālik, may Allah be pleased with him, reported: Ziyād—or Ibn Ziyād—was mentioned in connection with the Basin, and he denied it. When this reached Anas, he said: “By Allah, tomorrow I will certainly displease him.” He then asked: “What is it that you deny concerning the Basin?” They asked: “Did you hear the Prophet ﷺ mention it?” He replied: “Yes. I lived to see elderly women in Madinah who would not perform a single prayer without asking Allah Most High to bring them to the Basin of Muḥammad ﷺ.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن أبي عاصم في السنة (698)، وأبو يعلى (3355)."},{"num":856,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ أَرْقَمَ قَالَ: بَعَثَ إِلَيَّ عُبَيْدُ اللَّهِ بْنُ زِيَادٍ، فَأَتَيْتُهُ فَقَالَ: مَا أَحَادِيثُ تُحَدِّثُهَا وَتَرْوِيهَا عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَا نَجِدُهَا فِي كِتَابِ اللَّهِ عَزَّ وَجَلَّ؟ تُحَدِّثُ أَنَّ لَهُ حَوْضًا فِي الْجَنَّةِ! قَالَ: قَدْ حَدَّثَنَاهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَوَعَدَنَاهُ، قَالَ: كَذَبْتَ، وَلَكِنَّكَ شَيْخٌ قَدْ خَرِفْتَ، قَالَ: إِنِّي قَدْ سَمِعَتْهُ أُذُنَايَ، وَوَعَاهُ قَلْبِي مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ: مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا، فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنْ جَهَنَّمَ، وَمَا كَذَبْتُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه أحمد (19266)، والطبرانيّ في الكبير (5021)، والبزار - كشف الأستار (217)، كلّهم من طريق أبي حيان التّيميّ، حدّثني يزيد بن حيان التّيميّ، قال: حدّثنا زيد بن أرقم في مجلسه، قال: بعث إلى عبيدالله بن زياد، فذكره.","grade":"صحيح","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Aḥmad (19266), al-Ṭabarānī in al-Muʿjam al-Kabīr (5/203–204), and al-Bazzār in Kashf al-Astār (217).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["Zayd ibn Arqam, may Allah be pleased with him, said: ʿUbaydullāh ibn Ziyād sent for me, so I came to him. He said: “What are these narrations that you relate and transmit from the Messenger of Allah ﷺ which we do not find in the Book of Allah, Mighty and Majestic? You claim that he has a Basin in Paradise!” I replied: “The Messenger of Allah ﷺ certainly told us about it and promised it to us.” He said: “You have lied! Rather, you are an old man who has become senile.” I replied: “My own two ears heard it and my heart retained it from the Messenger of Allah ﷺ, who said: ‘Whoever deliberately lies about me, let him take his seat in Hell.’ And I have not lied about the Messenger of Allah ﷺ.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[1265],"tks":"صحيح: رواه أحمد (19266)، والطبراني في الكبير (5/203–204)، والبزار في كشف الأستار (217)."},{"num":857,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ أَرْقَمَ قَالَ: كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَنَزَلْنَا مَنْزِلًا فَقَالَ: مَا أَنْتُمْ جُزْءٌ مِنْ مِائَةِ أَلْفِ جُزْءٍ مِمَّنْ يَرِدُ عَلَيَّ الْحَوْضَ، قَالَ: قُلْتُ: كَمْ كُنْتُمْ يَوْمَئِذٍ؟ قَالَ: سَبْعُ مِائَةٍ، أَوْ ثَمَانِ مِائَةٍ."],"takhrij":"حسن: رواه أبو داود (4746) عن حفص بن عمر النّمريّ، حدّثنا شعبة، عن عمرو بن مرة، عن أبي حمزة، عن زيد بن أرقم، فذكر مثله.","grade":"حسن","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Abū Dāwūd (4746).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["Zayd ibn Arqam, may Allah be pleased with him, said: We were with the Messenger of Allah ﷺ and stopped at a place. He said: “You do not constitute even one part out of one hundred thousand parts of those who will come to me at the Basin.” It was asked: “How many of you were there that day?” He replied: “Seven hundred or eight hundred.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4746)."},{"num":858,"demo":false,"sanad":"","matn":["عَنْ كَعْبِ بْنِ عُجْرَةَ قَالَ: خَرَجَ إِلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَنَحْنُ تِسْعَةٌ: خَمْسَةٌ، وَأَرْبَعَةٌ، أَحَدُ الْعَدَدَيْنِ مِنَ الْعَرَبِ، وَالْآخَرُ مِنَ الْعَجَمِ، فَقَالَ: اسْمَعُوا، هَلْ سَمِعْتُمْ أَنَّهُ سَيَكُونُ بَعْدِي أُمَرَاءُ فَمَنْ دَخَلَ عَلَيْهِمْ فَصَدَّقَهُمْ بِكَذِبِهِمْ وَأَعَانَهُمْ عَلَى ظُلْمِهِمْ فَلَيْسَ مِنِّي وَلَسْتُ مِنْهُ، وَلَيْسَ بِوَارِدٍ عَلَيَّ الْحَوْضَ، وَمَنْ لَمْ يَدْخُلْ عَلَيْهِمْ وَلَمْ يُعِنْهُمْ عَلَى ظُلْمِهِمْ وَلَمْ يُصَدِّقْهُمْ بِكَذِبِهِمْ فَهُوَ مِنِّي وَأَنَا مِنْهُ وَهُوَ وَارِدٌ عَلَيَّ الْحَوْضَ."],"takhrij":"صحيح: رواه الترمذي (2259) عن هارون بن إسحاق الهمدانيّ، حدّثني محمد بن عبدالوهاب، عن مِسْعَر، عن أبي حصين، عن الشّعبيّ، عن عاصم العدويّ، عن كعب بن عُجرة، قال: فذكره.","grade":"صحيح","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Tirmidhī (2259), al-Nasāʾī (4208), and Aḥmad (18151). Al-Tirmidhī said: “A Ṣaḥīḥ Gharīb ḥadīth.”","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["Kaʿb ibn ʿUjrah, may Allah be pleased with him, reported: The Messenger of Allah ﷺ came out to us while we were nine—five and four—one of the two groups being Arabs and the other non-Arabs. He said: “Listen. Have you heard that after me there will be rulers? Whoever enters upon them, affirms their lies, and assists them in their oppression is not from me and I am not from him, and he will not come to me at the Basin. But whoever does not enter upon them, does not assist them in their oppression, and does not affirm their lies is from me and I am from him, and he will come to me at the Basin.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (2259)، والنسائي (4208)، وأحمد (18151). وقال الترمذي: «حديث صحيح غريب»."},{"num":859,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لِكَعْبِ بْنِ عُجْرَةَ: أَعَاذَكَ اللَّهُ مِنْ إِمَارَةِ السُّفَهَاءِ، قَالَ: وَمَا إِمَارَةُ السُّفَهَاءِ؟ قَالَ: أُمَرَاءُ يَكُونُونَ بَعْدِي لَا يَقْتَدُونَ بِهَدْيِي، وَلَا يَسْتَنُّونَ بِسُنَّتِي، فَمَنْ صَدَّقَهُمْ بِكَذِبِهِمْ، وَأَعَانَهُمْ عَلَى ظُلْمِهِمْ، فَأُولَئِكَ لَيْسُوا مِنِّي، وَلَسْتُ مِنْهُمْ، وَلَا يَرِدُوا عَلَيَّ حَوْضِي، وَمَنْ لَمْ يُصَدِّقْهُمْ بِكَذِبِهِمْ، وَلَمْ يُعِنْهُمْ عَلَى ظُلْمِهِمْ، فَأُولَئِكَ مِنِّي وَأَنَا مِنْهُمْ، وَسَيَرِدُوا عَلَيَّ حَوْضِي.","يَا كَعْبُ بْنَ عُجْرَةَ: الصَّوْمُ جُنَّةٌ، وَالصَّدَقَةُ تُطْفِئُ الْخَطِيئَةَ، وَالصَّلَاةُ قُرْبَانٌ أَوْ قَالَ: بُرْهَانٌ يَا كَعْبُ بْنَ عُجْرَةَ، إِنَّهُ لَا يَدْخُلُ الْجَنَّةَ لَحْمٌ نَبَتَ مِنْ سُحْتٍ، النَّارُ أَوْلَى بِهِ، يَا كَعْبُ بْنَ عُجْرَةَ، النَّاسُ غَادِيَانِ: فَمُبْتَاعٌ نَفْسَهُ فَمُعْتِقُهَا، وَبَائِعٌ نَفْسَهُ فَمُوبِقُهَا."],"takhrij":"حسن: رواه الإمام أحمد (14441) عن عبدالرزّاق وهو في مصنّفه abdrazzaq(20719)، ومن طريقه أخرجه ابنُ حبان في صحيحه (4514)، والحاكم (8302) عن معمر، عن ابن خُثيم، عن عبدالرحمن بن سابط، عن جابر، فذكره.","grade":"حسن","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: The core warning concerning foolish rulers is narrated by al-Tirmidhī (2259) and authenticated by Ibn Ḥibbān (279) and al-Ḥākim (265).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh, may Allah be pleased with them, reported: The Prophet ﷺ said to Kaʿb ibn ʿUjrah may Allah be pleased with him: “May Allah protect you from the rule of foolish leaders.” Kaʿb asked: “What is the rule of foolish leaders?” He replied: “Rulers who will come after me who do not follow my guidance and do not adhere to my Sunnah. Whoever affirms their lies and assists them in their oppression—such people are not from me and I am not from them, and they will not come to me at my Basin. But whoever does not affirm their lies and does not assist them in their oppression—such people are from me and I am from them, and they will come to me at my Basin.","O Kaʿb ibn ʿUjrah, fasting is a shield, charity extinguishes sin, and prayer is an offering of nearness—or he said: a proof. O Kaʿb ibn ʿUjrah, flesh that has grown from unlawful earnings will not enter Paradise; the Fire has a greater claim to it. O Kaʿb ibn ʿUjrah, people go out in two ways: one purchases his own soul and sets it free, while another sells his soul and destroys it.”"]},"buhuth":{"en":["Ḥasan: Narrated by Imām Aḥmad (14441), ʿAbd al-Razzāq (20719), Ibn Ḥibbān (4514), and al-Ḥākim (4/422)."]}},"tuhfa":{},"full":1,"dr":1,"rep":[7669],"tks":"حسن: رواه الإمام أحمد (14441)، وعبد الرزاق (20719)، وابن حبان (4514)، والحاكم (8302)."},{"num":860,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ، عَنِ النَّبيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّهَا سَتَكُونُ أُمَرَاءُ يَكْذِبونَ وَيَظْلِمُونَ، فَمَنْ صَدَّقَهُمْ بكَذِبهِمْ، وَأَعَانَهُمْ عَلَى ظُلْمِهِمْ، فَلَيْسَ مِنَّي وَلَسْتُ مِنْهُمْ، وَلَا يَرِدُ عَلَيَّ الْحَوْضَ، وَمَنْ لَمْ يُصَدِّقْهُمْ بكَذِبهِمْ وَلَمْ يُعِنْهُمْ عَلَى ظُلْمِهِمْ، فَهُوَ مِنِّي وَأَنَا مِنْهُ، وَسَيَرِدُ عَلَيَّ الْحَوْضَ."],"takhrij":"صحيح: رواه الإمام أحمد (23260)، والبزّار (2834) كلاهما من حديث إسماعيل بن علية، عن يونس بن عبيد، عن حُميد بن هلال، أو عن غيره، ، عن ربعي بن حراش، عن حذيفة، فذكر مثله.","grade":"صحيح","chapter_ar":"باب الإيمان بإثبات حوض النبي ﷺ وصفاته، ومن يرد عليه ومن يُذاد عنه من أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Imām Aḥmad (23260) and al-Bazzār (2832).","chapter_en":"Belief in the Prophet’s ﷺ Basin, Its Description, Those Who Will Come to It, and Those From His Ummah Who Will Be Driven Away From It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":24,"content":{"translation":{"en":["Ḥudhayfah may Allah be pleased with him reported that the Prophet ﷺ said: “There will indeed be rulers who lie and act unjustly. Whoever affirms their lies and assists them in their oppression is not from me and I am not from him, and he will not come to me at the Basin. But whoever does not affirm their lies and does not assist them in their oppression is from me and I am from him, and he will come to me at the Basin.”"]},"buhuth":{"en":["Among the Important Benefits","Al-Qurṭubī, may Allah have mercy on him, said:","“Among the matters that every legally responsible person must know and affirm as true is that Allah Most High has specifically honored His Prophet Muḥammad ﷺ with al-Kawthar, namely the Basin, whose name, description, drink, and vessels have been explicitly described in numerous famous and authentic ḥadīths.","Taken together, these reports produce definitive knowledge and certainty through mass transmission. More than thirty Companions narrated reports concerning it from the Prophet ﷺ. More than twenty of them are represented in the two Ṣaḥīḥ collections, while the remainder are found in other works through sound and well-known transmissions.","Then comparable numbers of the Tābiʿūn transmitted these reports from the Companions. These narrations continued through successive generations, with increasing numbers of transmitters throughout the various lands, whose efforts were devoted to narrating them, preserving them in the major compilations, and recording them, until they reached us and Allah’s proof through them was established against us.","It therefore became obligatory upon us to believe and affirm this, just as the Salaf unanimously affirmed it and the people of the Sunnah among later generations did likewise.","A group of innovators denied it, diverted it from its apparent meaning, and went to extremes in interpreting it, despite there being no rational or customary impossibility requiring departure from its apparent meaning, nor any textual or transmitted evidence calling for such interpretation.","Such interpretation is therefore a distortion arising from unsound reasoning, by which its proponents violated the consensus of the Salaf and departed from the way of the leading scholars of later generations.”","End quote.","Al-Mufhim limā Ashkala min Talkhīṣ Kitāb Muslim (6/90).","Note: The Meaning of “al-Kawthar” and “the Basin”","As for the statement:","“Al-Kawthar is the Basin,”","the correct view is that al-Kawthar is a river in Paradise that flows into the Basin, as established in the authentic narrations.","The Expressions “Uṣayḥāb” and “Aṣḥāb”","The expression:","“uṣayḥāb”","is the diminutive form, while:","“aṣḥāb”","is the regular form. They are divided in two categories:","The first are sinners who turned away from upright conduct, not from Islam itself. They replaced righteous deeds with sinful deeds. Such people will enter Paradise through the Prophet’s ﷺ intercession and will not remain eternally in the Fire.","The second are those who truly apostatized into disbelief. The intended meaning is the followers of Musaylimah the Liar who apostatized after the death of the Prophet ﷺ and were fought by Abū Bakr may Allah be pleased with him, along with some of the harsh Bedouin tribes.","These ḥadīths do not support the Shīʿī claim that all of the Companions apostatized except for a small number. It argues that historical events themselves refute that claim, and that those who apostatized were instead groups among the rough Bedouins and the followers of Musaylimah the Liar."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (23260)، والبزار (2834)."},{"num":861,"demo":false,"sanad":"","matn":["عَنْ أُسَيْدِ بْنِ حُضَيْرٍ، أَنَّ رَجُلًا مِنْ الْأَنْصَارِ خَلَا بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: أَلَا تَسْتَعْمِلُنِي كَمَا اسْتَعْمَلْتَ فُلَانًا؟ فَقَالَ: إِنَّكُمْ سَتَلْقَوْنَ بَعْدِي أَثَرَةً فَاصْبِرُوا حَتَّى تَلْقَوْنِي عَلَى الْحَوْضِ."],"takhrij":"متفق عليه: رواه البخاريّ في مناقب الأنصار (3792)، ومسلم في الإمارة (1845) كلاهما عن محمد بن بشار، حدّثنا محمد بن جعفر غندر، حدّثنا شعبة، سمعتُ قتادة، عن أنس بن مالك، عن أُسيد بن حُضير، فذكره.","grade":"متفق عليه","chapter_ar":"باب وعد النبي ﷺ الأنصار بلقائهم على الحوض","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3792) and Muslim (1845).","chapter_en":"The Prophet ﷺ Promising the Anṣār That They Would Meet Him at the Basin","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":25,"content":{"translation":{"en":["Usayd ibn Ḥuḍayr, may Allah be pleased with him, reported: A man from the Anṣār spoke privately with the Messenger of Allah ﷺ and said: “Will you not appoint me as you appointed so-and-so?” He replied: “Indeed, after me you will encounter others being preferred over you, so remain patient until you meet me at the Basin.”"]},"buhuth":{"en":["The word:","“atharah”","may be pronounced with two fatḥahs, and it may also be pronounced with a ḍammah on the first letter and a sukūn on the second. It is derived from al-istiʾthār, meaning that others are given preference over you.","Thus, the instruction is to remain patient when others are preferred over you.","It also contains an indication that authority would eventually pass to people other than the Anṣār, and events occurred just as the Prophet ﷺ described.","See: Fatḥ al-Bārī (11/118)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3792)، ومسلم (1845)."},{"num":862,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِلْأَنْصَارِ: إِنَّكُمْ سَتَلْقَوْنَ بَعْدِي أَثَرَةً فَاصْبِرُوا حَتَّى تَلْقَوْنِي، وَمَوْعِدُكُمُ الْحَوْضُ."],"takhrij":"صحيح: رواه البخاريّ في مناقب الأنصار (3793) عن محمد بن بشار، قال: حدّثنا غندر، حدّثنا شعبة، عن هشام، قال: سمعتُ أنس بن مالك، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب وعد النبي ﷺ الأنصار بلقائهم على الحوض","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (3793).","chapter_en":"The Prophet ﷺ Promising the Anṣār That They Would Meet Him at the Basin","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":25,"content":{"translation":{"en":["Anas ibn Mālik, may Allah be pleased with him, reported: The Prophet ﷺ said to the Anṣār: “Indeed, after me you will encounter others being preferred over you, so remain patient until you meet me. Your appointed meeting place is the Basin.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (3793)."},{"num":863,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ زَيْدِ بْنِ عَاصِمٍ الْمَازِنِيِّ قَالَ (فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ): قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِلْأَنْصَارِ: إِنَّكُمْ سَتَلْقَوْنَ بَعْدِي أُثْرَةً، فَاصْبِرُوا حَتَّى تَلْقَوْنِي عَلَى الْحَوْضِ."],"takhrij":"متفق عليه: رواه البخاريّ في المغازي (4330)، ومسلم في الزّكاة (1061) كلاهما من حديث عمرو بن يحيى بن عُمارة، عن عبّاد بن تميم، عن عبدالله بن زيد بن عاصم، فذكره في حديث طويل، وسيأتي في موضعه إن شاء الله.","grade":"متفق عليه","chapter_ar":"باب وعد النبي ﷺ الأنصار بلقائهم على الحوض","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4330) and Muslim (1061).","chapter_en":"The Prophet ﷺ Promising the Anṣār That They Would Meet Him at the Basin","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":25,"content":{"translation":{"en":["ʿAbdullāh ibn Zayd ibn ʿĀṣim al-Māzinī, may Allah be pleased with him, reported: The Prophet ﷺ said to the Anṣār: “Indeed, after me you will encounter others being preferred over you, so remain patient until you meet me at the Basin.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4330)، ومسلم (1061)."},{"num":864,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: يَا مَعْشَرَ الْأَنْصَارِ، مَوْعِدُكُمْ حَوْضِي، آنِيَتُهُ أَكْثَرُ مِنْ عَدَدِ نُجُومِ السَّمَاءِ، أَوْ مِثْلُ عَدَدِ نُجُومِ السَّمَاءِ، وَإِنَّ عَرْضَهُ كَمَا بَيْنِي وَبَيْنَ صَنْعَاءَ، أَوْ كَمَا بَيْنِي وَبَيْنَ عُمَانَ."],"takhrij":"حسن: رواه البزّار (6215) عن عبدالله بن سعيد، ثنا عقبة بن خالد، ثنا سعد بن سعيد، قال: سمعت أنس بن مالك، فذكره.","grade":"حسن","chapter_ar":"باب وعد النبي ﷺ الأنصار بلقائهم على الحوض","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Bazzār (6215).","chapter_en":"The Prophet ﷺ Promising the Anṣār That They Would Meet Him at the Basin","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":25,"content":{"translation":{"en":["Anas, may Allah be pleased with him, said: I heard the Messenger of Allah ﷺ say: “O assembly of the Anṣār, your appointed meeting place is my Basin. Its vessels are more numerous than the stars of the sky—or as numerous as the stars of the sky—and its width is like the distance between where I am and Ṣanʿāʾ, or like the distance between where I am and ʿAmmān.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10485],"tks":"حسن: رواه البزار (6215)."},{"num":865,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا بَيْنَ بَيْتِي وَمِنْبَرِي رَوْضَةٌ مِنْ رِيَاضِ الْجَنَّةِ، وَمِنْبَرِي عَلَى حَوْضِي."],"takhrij":"متفق عليه: رواه مالك في القبلة (10) عن خبيب بن عبدالرحمن، عن حفص بن عاصم، عن أبي هريرة، أو عن أبي سعيد الخدريّ، أنّ رسول الله صلى الله عليه وسلم قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب أن منبر النبي ﷺ على الحوض","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (10), al-Bukhārī (7335), and Muslim (1391).","chapter_en":"The Prophet’s ﷺ Pulpit Is Upon the Basin","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":26,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “What lies between my house and my pulpit is a garden from the gardens of Paradise, and my pulpit is upon my Basin.”"]},"buhuth":{"en":["Regarding his statement:","“My pulpit is upon my Basin,”","al-Zurqānī said:","“The pulpit upon which he made this statement will be moved on the Day of Resurrection and set up at his Basin.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10661],"tks":"متفق عليه: رواه مالك (10)، والبخاري (7335)، ومسلم (1391)."},{"num":866,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ بْنِ سَعْدٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ لِكُلِّ قَوْمٍ فَرَطًا، وَإِنِّي فَرَطُكُمْ عَلَى الْحَوْضِ، فَمَنْ وَرَدَ عَلَيَّ الْحَوْضَ فَشَرِبَ لَمْ يَظْمَأْ، وَمَنْ لَمْ يَظْمَأْ دَخَلَ الْجَنَّةَ."],"takhrij":"حسن: رواه الطبرانيّ في الكبير (5760) عن عبدان بن أحمد، ثنا دُحيم، ثنا ابن أبي فديك، عن موسى بن يعقوب، عن أبي حازم، عن سهل بن سعد، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء أن لكل نبي حوضًا","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Kabīr (6/168).","chapter_en":"What Has Been Reported That Every Prophet Has a Basin","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":27,"content":{"translation":{"en":["Sahl ibn Saʿd may Allah be pleased with him reported that the Prophet ﷺ said: “Every people has one who goes ahead of them, and I will be your forerunner at the Basin. Whoever reaches the Basin and drinks from it will not thirst, and whoever does not thirst will enter Paradise.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (5760)."},{"num":867,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَا أَوَّلُ النَّاسِ يَشْفَعُ فِي الْجَنَّةِ، وَأَنَا أَكْثَرُ الأَنْبِيَاءِ تَبَعًا.","وَفِي رِوَايَةِ: أَنَا أَكْثَرُ الأَنْبِيَاءِ تَبَعًا يَوْمَ الْقِيَامَةِ، وَأَنَا أَوَّلُ مَنْ يَقْرَعُ بَابَ الْجَنَّةِ.","وَفِي رِوَايَةِ: أَنَا أَوَّلُ شَفِيعٍ فِي الْجَنَّةِ، لَمْ يُصَدَّقْ نَبِيٌّ مِنَ الأَنْبِيَاءِ مَا صُدِّقْتُ، وَإِنَّ مِنَ الأَنْبِيَاءِ نَبِيًّا، مَا يُصَدِّقُهُ مِنْ أُمَّتِهِ، إِلَّا رَجُلٌ وَاحِدٌ."],"takhrij":"صحيح: رواه مسلم في الإيمان (196) عن قتيبة بن سعيد، قال: حدّثنا جرير، عن المختار بن فلفل، عن أنس، فذكره.","grade":"صحيح","chapter_ar":"باب في قول النبي ﷺ: «أنا أول من يشفع»","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (196).","chapter_en":"The Prophet’s ﷺ Statement: “I Am the First to Intercede”","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":1,"content":{"translation":{"en":["Anas may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “I will be the first of the people to intercede concerning Paradise, and I will have the greatest following among the prophets.” In another narration:","“I will have the greatest following among the prophets on the Day of Resurrection, and I will be the first to knock at the gate of Paradise.”","And in another narration: “I will be the first intercessor concerning Paradise. No prophet among the prophets was believed by as many people as believed me, and among the prophets was one whom only a single man from his nation believed.”"]},"intro_majmu":{"ar":["قال الله تعالى:","﴿وَكَمْ مِنْ مَلَكٍ فِي السَّمَاوَاتِ لَا تُغْنِي شَفَاعَتُهُمْ شَيْئًا إِلَّا مِنْ بَعْدِ أَنْ يَأْذَنَ اللهُ لِمَنْ يَشَاءُ وَيَرْضَى﴾","[النجم: ٢٦]","وقال تعالى:","﴿قُلْ لِلَّهِ الشَّفَاعَةُ جَمِيعًا﴾","[الزمر: ٤٤]","وقال تعالى:","﴿مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ﴾","[البقرة: ٢٥٥]","وقال تعالى:","﴿وَلَا يَشْفَعُونَ إِلَّا لِمَنِ ارْتَضَى﴾","[الأنبياء: ٢٨]","فدلت هذه الآيات الكريمة على أن الشفاعة لا تتحقق إلا بشرطين:","الشرط الأول: إذن الله للشافع أن يشفع.","والشرط الثاني: رضا الله عن المشفوع له.","وهي خاصة بأهل التوحيد، وأما المشركون فلا يملكون شفاعة، ولا تنفعهم شفاعة الشافعين.","وقال تعالى:","﴿لَا يَمْلِكُونَ الشَّفَاعَةَ إِلَّا مَنِ اتَّخَذَ عِنْدَ الرَّحْمَٰنِ عَهْدًا﴾","[مريم: ٨٧]","وقال تعالى:","﴿فَمَا تَنْفَعُهُمْ شَفَاعَةُ الشَّافِعِينَ﴾","[المدثر: ٤٨]","وقال تعالى:","﴿وَلَمْ يَكُنْ لَهُمْ مِنْ شُرَكَائِهِمْ شُفَعَاءُ وَكَانُوا بِشُرَكَائِهِمْ كَافِرِينَ﴾","[الروم: ١٣]","وقد خص الله تعالى نبينا ﷺ يوم القيامة بثلاث شفاعات:","الشفاعة الأولى: الشفاعة العظمى، وهي المقام المحمود، وهي أن يشفع في أهل الموقف حتى يُقضى بينهم بعد أن تتراجع الأنبياء: آدم، ونوح، وإبراهيم، وموسى، وعيسى ابن مريم عليهم السلام عن الشفاعة، حتى تنتهي إليه ﷺ.","الشفاعة الثانية: شفاعته ﷺ في أهل الجنة أن يدخلوا الجنة بعد الفراغ من الحساب.","الشفاعة الثالثة: شفاعته ﷺ في عمه أبي طالب أن يخفف عنه العذاب.","وأما شفاعته ﷺ فيمن استحق النار من عصاة الموحدين ألا يدخلها، وشفاعته فيمن دخل النار من عصاة الموحدين، وشفاعته في رفع درجات بعض أهل الجنة، فهذه يشاركه فيها غيره من الأنبياء والملائكة والصديقين والشهداء.","ينظر: العقيدة الواسطية، لشيخ الإسلام ابن تيمية، مع شرحها للشيخ صالح الفوزان (ص ١٥٦–١٥٩)."],"en":["Allah Most High said:","“How many angels are there in the heavens whose intercession avails nothing except after Allah gives permission to whomever He wills and is pleased with.”","[Sūrat al-Najm 53:26]","And He said:","“Say: To Allah belongs all intercession.”","[Sūrat al-Zumar 39:44]","And He said:","“Who is it that can intercede with Him except by His permission?”","[Sūrat al-Baqarah 2:255]","And He said:","“They do not intercede except for one with whom He is pleased.”","[Sūrat al-Anbiyāʾ 21:28]","These noble verses establish that intercession occurs only when two conditions are fulfilled:","The first condition: Allah gives the intercessor permission to intercede.","The second condition: Allah is pleased with the one for whom intercession is sought.","It is specifically for the people of Tawḥīd. As for the polytheists, they possess no intercession, nor will the intercession of the intercessors benefit them.","And He said:","“They possess no intercession except one who has taken a covenant with the Most Merciful.”","[Sūrat Maryam 19:87]","And Allah Most High said:","“So the intercession of the intercessors will not benefit them.”","[Sūrat al-Muddaththir 74:48]","And He said:","“They will have no intercessors from among those they associated as partners, and they will disbelieve in those partners.”","[Sūrat al-Rūm 30:13]","Allah Most High has specifically honored our Prophet ﷺ on the Day of Resurrection with three intercessions:","The first intercession is the Great Intercession, which is the Praised Station. He ﷺ will intercede for the people at the Standing so that judgment may begin among them, after the prophets Adam, Noah, Abraham, Moses, and Jesus son of Mary عليهم السلام each decline to undertake it, until it reaches him ﷺ.","The second intercession is his ﷺ intercession for the people of Paradise so that they may enter Paradise after the reckoning has been completed.","The third intercession is his ﷺ intercession for his uncle Abū Ṭālib so that his punishment may be reduced.","As for his ﷺ intercession for sinful monotheists who deserve the Fire so that they do not enter it, his intercession for sinful monotheists who have entered the Fire, and his intercession for some of the people of Paradise to be raised in rank, these forms of intercession are also shared by other prophets, angels, the truthful, and the martyrs.","See: al-ʿAqīdah al-Wāsiṭiyyah by Shaykh al-Islām Ibn Taymiyyah, with its explanation by Shaykh Ṣāliḥ al-Fawzān (pp. 156–159)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (196)."},{"num":868,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَا سَيِّدُ وَلَدِ آدَمَ يَوْمَ الْقِيَامَةِ، وَأَوَّلُ مَنْ يَنْشَقُّ عَنْهُ الْقَبْرُ، وَأَوَّلُ شَافِعٍ، وَأَوَّلُ مُشَفَّعٍ."],"takhrij":"صحيح: رواه مسلم في الفضائل (2278) عن الحكم بن موسى أبي صالح، حدّثنا هِقْل (يعني ابن زياد)، عن الأوزاعيّ، حدّثني أبو عمار، حدّثني عبدالله بن فرّوخ، حدّثني أبو هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب في قول النبي ﷺ: «أنا أول من يشفع»","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2278).","chapter_en":"The Prophet’s ﷺ Statement: “I Am the First to Intercede”","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “I am the leader of the children of Adam on the Day of Resurrection, the first for whom the grave will be split open, the first to intercede, and the first whose intercession will be accepted.”"]}},"tuhfa":{},"full":1,"rep":[13397],"tks":"صحيح: رواه مسلم (2278)."},{"num":869,"demo":false,"sanad":"","matn":["عَنْ أُبَيِّ بْنِ كَعْبٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا كَانَ يَوْمُ الْقِيَامَةِ كُنْتُ إِمَامَ النَّبِيِّينَ وَخَطِيبَهُمْ، وَصَاحِبَ شَفَاعَتِهِمْ غَيْرَ فَخْرٍ."],"takhrij":"حسن: رواه الترمذيّ تحت حديث ذي رقم (3613)، وابن ماجه (4314) كلاهما من حديث عبدالله بن محمد بن عقيل، عن الطّفيل بن أبي بن كعب، عن أبيه، فذكره.","grade":"حسن","chapter_ar":"باب في قول النبي ﷺ: «أنا أول من يشفع»","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Tirmidhī (3613), Ibn Mājah (4314), and Aḥmad (21247).","chapter_en":"The Prophet’s ﷺ Statement: “I Am the First to Intercede”","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":1,"content":{"translation":{"en":["Ubayy ibn Kaʿb may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “On the Day of Resurrection, I will be the leader of the prophets, their spokesman, and the possessor of their intercession—without boasting.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (3613)، وابن ماجه (4314)، وأحمد (21247)."},{"num":870,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لِكُلِّ نَبِيٍّ دَعْوَةٌ يَدْعُو بِهَا، فَأُرِيدُ أَنْ أَخْتَبِئَ دَعْوَتِي شَفَاعَةً لِأُمَّتِي فِي الْآخِرَةِ."],"takhrij":"متفق عليه: رواه مالك في القرآن (26) عن أبي الزّناد، عن الأعرج، عن أبي هريرة، فذكره. ومن هذا الطريق رواه القعنبيّ أيضاً عن الإمام مالك كما رواه الجوهري في مسند الموطأ (533).","grade":"متفق عليه","chapter_ar":"باب اختباء النبي ﷺ دعوته لشفاعة أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (26), al-Bukhārī (6304), and Muslim (198).","chapter_en":"The Prophet ﷺ Reserved His Supplication for the Intercession of His Ummah","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":2,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Prophet ﷺ said: “Every prophet has a supplication which he makes, and I wish to reserve my supplication as intercession for my Ummah in the Hereafter.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (26)، والبخاري (6304)، ومسلم (198)."},{"num":871,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لِكُلِّ نَبِيٍّ دَعْوَةٌ مُسْتَجَابَةٌ، فَتَعَجَّلَ كُلُّ نَبِيٍّ دَعْوَتَهُ، وَإِنِّي اخْتَبَأْتُ دَعْوَتِي شَفَاعَةً لِأُمَّتِي يَوْمَ الْقِيَامَةِ، فَهِيَ نَائِلَةٌ إِنْ شَاءَ اللَّهُ مَنْ مَاتَ مِنْ أُمَّتِي لَا يُشْرِكُ بِاللَّهِ شَيْئًا."],"takhrij":"صحيح: رواه مسلم في الإيمان (199) من طرق عن أبي معاوية، عن الأعمش، عن أبي صالح، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب اختباء النبي ﷺ دعوته لشفاعة أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (199).","chapter_en":"The Prophet ﷺ Reserved His Supplication for the Intercession of His Ummah","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":2,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Every prophet has an answered supplication. Each prophet hastened to use his supplication, whereas I have reserved my supplication as intercession for my Ummah on the Day of Resurrection. It will reach, if Allah wills, whoever from my Ummah dies without associating anything with Allah.”"]},"buhuth":{"en":["In another wording:","“Every prophet has an answered supplication which he makes and which is answered and granted to him. I have reserved my supplication as intercession for my Ummah on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (199)."},{"num":872,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّهُ قَالَ لِكَعْبِ الأَحْبَارِ: إِنَّ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لِكُلِّ نَبِيٍّ دَعْوَةٌ يَدْعُوهَا، فَأَنَا أُرِيدُ إِنْ شَاءَ اللَّهُ أَنْ أَخْتَبِئَ دَعْوَتِي شَفَاعَةً لِأُمَّتِي يَوْمَ الْقِيَامَةِ."],"takhrij":"صحيح: رواه مسلم في الإيمان (198) عن حرملة بن يحيى، أخبرنا ابن وهب، أخبرني يونس، عن ابن شهاب، أنّ عمرو بن أبي سفيان بن أَسيد بن جارية الثّقفيّ أخبره، أنّ أبا هريرة قال لكعب، فذكره.","grade":"صحيح","chapter_ar":"باب اختباء النبي ﷺ دعوته لشفاعة أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (199).","chapter_en":"The Prophet ﷺ Reserved His Supplication for the Intercession of His Ummah","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":2,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that he said to Kaʿb al-Aḥbār: The Prophet of Allah ﷺ said: “Every prophet has a supplication that he makes, and I intend, if Allah wills, to reserve my supplication as intercession for my Ummah on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (198)."},{"num":873,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لِكُلِّ نَبِيٍّ دَعْوَةٌ مُسْتَجَابَةٌ، وَإِنِّي اخْتَبَأْتُ دَعْوَتِي شَفَاعَةً لِأُمَّتِي يَوْمَ الْقِيَامَةِ."],"takhrij":"صحيح: رواه الإمام أحمد (7714) عن عبدالرزّاق، حدّثنا معمر، عن الزّهريّ، قال: أخبرني القاسم بن محمد، قال: اجتمع أبو هريرة وكعب، فجعل أبو هريرة يحدِّث كعباً عن النّبيّ صلى الله عليه وسلم، وكعب يحدِّث أبا هريرة عن الكتب. قال أبو هريرة: قال النبي صلى الله عليه وسلم ... الحديث.","grade":"صحيح","chapter_ar":"باب اختباء النبي ﷺ دعوته لشفاعة أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (199) and Aḥmad (7714).","chapter_en":"The Prophet ﷺ Reserved His Supplication for the Intercession of His Ummah","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":2,"content":{"translation":{"en":["Abū Hurayrah and Kaʿb met. Abū Hurayrah began narrating to Kaʿb from the Prophet ﷺ, while Kaʿb narrated to Abū Hurayrah from the earlier scriptures. Abū Hurayrah, may Allah be pleased with him, said: The Prophet ﷺ said: “Every prophet has an answered supplication, and I have reserved my supplication as intercession for my Ummah on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (199)، وأحمد (7714)."},{"num":874,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: كُلُّ نَبِيٍّ سَأَلَ سُؤْلًا أَوْ قَالَ: لِكُلِّ نَبِيٍّ دَعْوَةٌ قَدْ دَعَا بِهَا، فَاسْتُجِيبَ فَجَعَلْتُ دَعْوَتِي شَفَاعَةً لِأُمَّتِي يَوْمَ الْقِيَامَةِ."],"takhrij":"متفق عليه: رواه البخاريّ في الدعوات (6305)، ومسلم في الإيمان (200: 344) كلاهما من حديث المعتمر، عن أبيه، عن أنس فذكره.","grade":"متفق عليه","chapter_ar":"باب اختباء النبي ﷺ دعوته لشفاعة أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6305) and Muslim (200:344).","chapter_en":"The Prophet ﷺ Reserved His Supplication for the Intercession of His Ummah","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":2,"content":{"translation":{"en":["Anas may Allah be pleased with him reported that the Prophet ﷺ said: “Every prophet made a request—or he said: every prophet had a supplication which he made and which was answered—and I made my supplication an intercession for my Ummah on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6305)، ومسلم (200: 344)."},{"num":875,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ يَقُولُ: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لِكُلِّ نَبِيٍّ دَعْوَةٌ قَدْ دَعَا بِهَا فِي أُمَّتِهِ، وَخَبَأْتُ دَعْوَتِي شَفَاعَةً لِأُمَّتِي يَوْمَ الْقِيَامَةِ."],"takhrij":"صحيح: رواه مسلم في الإيمان (201) عن محمد بن أحمد بن أبي خلف، حدّثنا روح، حدّثنا ابن جريج، قال: أخبرني أبو الزبير، أنه سمع جابر بن عبدالله، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب اختباء النبي ﷺ دعوته لشفاعة أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (201).","chapter_en":"The Prophet ﷺ Reserved His Supplication for the Intercession of His Ummah","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":2,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh may Allah be pleased with them reported that the Prophet ﷺ said: “Every prophet had a supplication which he made concerning his nation, and I have reserved my supplication as intercession for my Ummah on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (201)."},{"num":876,"demo":false,"sanad":"","matn":["عَنْ أُبَيِّ بْنِ كَعْبٍ قَالَ: كُنْتُ فِي الْمَسْجِدِ، فَدَخَلَ رَجُلٌ يُصَلِّي فَقَرَأَ قِرَاءَةً أَنْكَرْتُهَا عَلَيْهِ ثُمَّ دَخَلَ آخَرُ، فَقَرَأَ قِرَاءَةً سِوَى قَرَاءَةِ صَاحِبِهِ، فَلَمَّا قَضَيْنَا الصَّلَاةَ دَخَلْنَا جَمِيعًا عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقُلْتُ: إِنَّ هَذَا قَرَأَ قِرَاءَةً أَنْكَرْتُهَا عَلَيْهِ وَدَخَلَ آخَرُ فَقَرَأَ سِوَى قِرَاءَةِ صَاحِبِهِ، فَأَمَرَهُمَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَرَءَا، فَحَسَّنَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَأْنَهُمَا فَسَقَطَ فِي نَفْسِي مِنَ التَّكْذِيبِ وَلَا إِذْ كُنْتُ فِي الْجَاهِلِيَّةِ، فَلَمَّا رَأَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا قَدْ غَشِيَنِي، ضَرَبَ فِي صَدْرِي، فَفِضْتُ عَرَقًا وَكَأَنَّمَا أَنْظُرُ إِلَى اللَّهِ عَزَّ وَجَلَّ فَرَقًا، فَقَالَ لِي: يَا أُبَيُّ، أُرْسِلَ إِلَيَّ أَنِ اقْرإِ الْقُرْآنَ عَلَى حَرْفٍ، فَرَدَدْتُ إِلَيْهِ أَنْ هَوِّنْ عَلَى أُمَّتِي، فَرَدَّ إِلَيَّ الثَّانِيَةَ اقْرَأْهُ عَلَى حَرْفَيْنِ، فَرَدَدْتُ إِلَيْهِ أَنْ هَوِّنْ عَلَى أُمَّتِي، فَرَدَّ إِلَيَّ الثَّالِثَةَ اقْرَأْهُ عَلَى سَبْعَةِ أَحْرُفٍ، فَلَكَ بِكُلِّ رَدَّةٍ رَدَدْتُكَهَا مَسْأَلَةٌ تَسْأَلُنِيهَا، فَقُلْتُ: اللَّهُمَّ اغْفِرْ لِأُمَّتِي، اللَّهُمَّ اغْفِرْ لِأُمَّتِي، وَأَخَّرْتُ الثَّالِثَةَ لِيَوْمٍ يَرْغَبُ إِلَيَّ الْخَلْقُ كُلُّهُمْ حَتَّى إِبْرَاهِيمُ عَلَيْهِ السَّلامُ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (820) عن محمد بن عبدالله بن نمير، حدّثنا أبي، حدّثنا إسماعيل بن أبي خالد، عن عبدالله بن عيسى بن عبدالرحمن بن أبي ليلى، عن جدّه، عن أُبي بن كعب، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب اختباء النبي ﷺ دعوته لشفاعة أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (820).","chapter_en":"The Prophet ﷺ Reserved His Supplication for the Intercession of His Ummah","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":2,"content":{"translation":{"en":["Ubayy ibn Kaʿb, may Allah be pleased with him, said: I was in the mosque when a man entered and prayed. He recited in a manner that I objected to. Then another man entered and recited differently from the first. When we finished the prayer, we all went to the Messenger of Allah ﷺ. I said: “This man recited in a manner that I objected to, and then another came and recited differently from him.” The Messenger of Allah ﷺ instructed both of them to recite, so they recited, and the Prophet ﷺ approved the recitation of both. Then there arose within me a degree of doubt such as had not occurred to me even during the Days of Ignorance. When the Messenger of Allah ﷺ saw what had overcome me, he struck me upon the chest. I broke into a sweat, and it was as though I were looking toward Allah, Mighty and Majestic, out of intense fear. He said to me: “O Ubayy, I was instructed to recite the Qurʾān in one ḥarf, so I replied: ‘Make it easier for my Ummah.’ Then I was instructed a second time: ‘Recite it in two aḥruf.’ I replied: ‘Make it easier for my Ummah.’ Then I was instructed a third time: ‘Recite it in seven aḥruf. For every time you have been sent back with a response, you have a request which you may ask of Me.’ So I said: ‘O Allah, forgive my Ummah. O Allah, forgive my Ummah.’ And I postponed the third request until a Day when all of creation will turn to me seeking it, even Abraham, peace be upon him.”"]},"buhuth":{"en":["The words:","“And I postponed the third”","refer to the intercession, as is explicitly stated in other narrations:","“I reserved the third as intercession for my Ummah on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (820)."},{"num":877,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي عُقَيْلٍ قَالَ: انْطَلَقْنَا فَأَتَيْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَنَخْنَا بِالْبَابِ، وَمَا فِي النَّاسِ أَبْغَضُ إِلَيْنَا مِنْ رَجُلٍ يَلِجُ عَلَيْهِ، فَمَا خَرَجْنَا حَتَّى مَا فِي النَّاسِ أَحَدٌ أَحَبَّ إِلَيْنَا مِنْ رَجُلٍ يَدْخُلُ عَلَيْهِ، قَالَ: فَقَالَ قَائِلٌ مِنَّا: يَا رَسُولَ اللَّهِ، أَلَا سَأَلْتَ رَبَّكَ مُلْكًا كَمُلْكِ سُلَيْمَانَ؟ فَضَحِكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ قَالَ: لَعَلَّ لِصَاحِبِكُمْ عِنْدَ اللَّهِ أَفْضَلَ مِنْ مُلْكِ سُلَيْمَانَ، إِنَّ اللَّهَ لَمْ يَبْعَثْ نَبِيًّا إِلَّا، أَعْطَاهُ دَعْوَةً، فَمِنْهُمْ مَنِ اتَّخَذَهَا دُنْيَا فَأُعْطِيهَا، وَمِنْهُمْ مَنْ دَعَا بِهَا عَلَى قَوْمِهِ إِذْ عَصَوْهُ فَأُهْلِكُوا بِهَا، وَإِنَّ اللَّهَ أَعْطَانِي دَعْوَةً، فَخَبَّيْتُهَا عِنْدَ رَبِّي شَفَاعَةً لِأُمَّتِي يَوْمَ الْقِيَامَةِ."],"takhrij":"حسن: رواه البزّار- كشف الأستار (2459)، وابن أبي عاصم في السنة (824) كلاهما من طريق زهير، ثنا أبو خالد الدّالاني، ثنا عون بن أبي جحيفة السوائيّ، عن عبدالرحمن بن علقمة الثقفيّ، عن عبدالرحمن بن أبي عقيل، قال: فذكره.","grade":"حسن","chapter_ar":"باب اختباء النبي ﷺ دعوته لشفاعة أمته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Bazzār in Kashf al-Astār (2459) and Ibn Abī ʿĀṣim in al-Sunnah (824).","chapter_en":"The Prophet ﷺ Reserved His Supplication for the Intercession of His Ummah","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":2,"content":{"translation":{"en":["ʿAbd al-Raḥmān ibn Abī ʿAqīl reported: We set out and came to the Messenger of Allah ﷺ and made our mounts kneel at his door. At first, there was no one more disliked by us than a person who entered upon him, yet by the time we left, there was no one more beloved to us than one who entered upon him. One of us asked: “O Messenger of Allah, why did you not ask your Lord for a kingdom like the kingdom of Solomon?” The Messenger of Allah ﷺ laughed and said: “Perhaps your companion possesses something with Allah better than the kingdom of Solomon. Allah never sent a prophet except that He gave him a supplication. Some of them used it for something of this world and were granted it, while others supplicated against their people when they disobeyed them and their people were destroyed through it. Allah has given me a supplication, and I have reserved it with my Lord as intercession for my Ummah on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار في كشف الأستار (2459)، وابن أبي عاصم في السنة (824)."},{"num":878,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: أُتِيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمًا بِلَحْمٍ، فَرُفِعَ إِلَيْهِ الذِّرَاعُ وَكَانَتْ تُعْجِبُهُ فَنَهَسَ مِنْهَا نَهْسَةً فَقَالَ: أَنَا سَيِّدُ النَّاسِ يَوْمَ الْقِيَامَةِ، وَهَلْ تَدْرُونَ بِمَ ذَاكَ يَجْمَعُ اللَّهُ يَوْمَ الْقِيَامَةِ الأَوَّلِينَ وَالآخِرِينَ فِي صَعِيدٍ وَاحِدٍ؟ فَيُسْمِعُهُمُ الدَّاعِي وَيَنْفُذُهُمُ الْبَصَرُ، وَتَدْنُو الشَّمْسُ، فَيَبْلُغُ النَّاسَ مِنَ الْغَمِّ وَالْكَرْبِ مَا لَا يُطِيقُونَ وَمَا لَا يَحْتَمِلُونَ، فَيَقُولُ بَعْضُ النَّاسِ لِبَعْضٍ: أَلَا تَرَوْنَ مَا أَنْتُمْ فِيهِ أَلَا تَرَوْنَ مَا قَدْ بَلَغَكُمْ أَلَا تَنْظُرُونَ مَنْ يَشْفَعُ لَكُمْ إِلَى رَبِّكُمْ؟ فَيَقُولُ بَعْضُ النَّاسِ لِبَعْضٍ: ائْتُوا آدَمَ، فَيَأْتُونَ آدَمَ فَيَقُولُونَ: يَا آدَمُ أَنْتَ أَبُو الْبَشَرِ خَلَقَكَ اللَّهُ بِيَدِهِ وَنَفَخَ فِيكَ مِنْ رُوحِهِ، وَأَمَرَ الْمَلَائِكَةَ فَسَجَدُوا لَكَ، اشْفَعْ لَنَا إِلَى رَبِّكَ، أَلَا تَرَى إِلَى مَا نَحْنُ فِيهِ، أَلَا تَرَى إِلَى مَا قَدْ بَلَغَنَا، فَيَقُولُ آدَمُ: إِنَّ رَبِّي غَضِبَ الْيَوْمَ غَضَبًا، لَمْ يَغْضَبْ قَبْلَهُ مِثْلَهُ، وَلَنْ يَغْضَبَ بَعْدَهُ مِثْلَهُ، وَإِنَّهُ نَهَانِي عَنِ الشَّجَرَةِ فَعَصَيْتُهُ نَفْسِي نَفْسِي، اذْهَبُوا إِلَى غَيْرِي، اذْهَبُوا إِلَى نُوحٍ فَيَأْتُونَ نُوحًا فَيَقُولُونَ: يَا نُوحُ أَنْتَ أَوَّلُ الرُّسُلِ إِلَى الأَرْضِ، وَسَمَّاكَ اللَّهُ عَبْدًا شَكُورًا، اشْفَعْ لَنَا إِلَى رَبِّكَ، أَلَا تَرَى مَا نَحْنُ فِيهِ، أَلَا تَرَى مَا قَدْ بَلَغَنَا، فَيَقُولُ لَهُمْ: إِنَّ رَبِّي قَدْ غَضِبَ الْيَوْمَ غَضَبًا، لَمْ يَغْضَبْ قَبْلَهُ مِثْلَهُ، وَلَنْ يَغْضَبَ بَعْدَهُ مِثْلَهُ، وَإِنَّهُ قَدْ كَانَتْ لِي دَعْوَةٌ، دَعَوْتُ بِهَا عَلَى قَوْمِي نَفْسِي نَفْسِي، اذْهَبُوا إِلَى إِبْرَاهِيمَ عَلَيْهِ السَّلامُ، فَيَأْتُونَ إِبْرَاهِيمَ، فَيَقُولُونَ: أَنْتَ نَبِيُّ اللَّهِ وَخَلِيلُهُ مِنْ أَهْلِ الأَرْضِ، اشْفَعْ لَنَا إِلَى رَبِّكَ، أَلَا تَرَى إِلَى مَا نَحْنُ فِيهِ، أَلَا تَرَى إِلَى مَا قَدْ بَلَغَنَا، فَيَقُولُ لَهُمْ إِبْرَاهِيمُ: إِنَّ رَبِّي قَدْ غَضِبَ الْيَوْمَ غَضَبًا، لَمْ يَغْضَبْ قَبْلَهُ مِثْلَهُ، وَلَا يَغْضَبُ بَعْدَهُ مِثْلَهُ، وَذَكَرَ كَذَبَاتِهِ نَفْسِي نَفْسِي، اذْهَبُوا إِلَى غَيْرِي، اذْهَبُوا إِلَى مُوسَى، فَيَأْتُونَ مُوسَى عَلَيْهِ السَّلامُ، فَيَقُولُونَ: يَا مُوسَى أَنْتَ رَسُولُ اللَّهِ، فَضَّلَكَ اللَّهُ بِرِسَالَاتِهِ وَبِتَكْلِيمِهِ عَلَى النَّاسِ اشْفَعْ لَنَا إِلَى رَبِّكَ، أَلَا تَرَى إِلَى مَا نَحْنُ فِيهِ، أَلَا تَرَى مَا قَدْ بَلَغَنَا، فَيَقُولُ لَهُمْ مُوسَى عَلَيْهِ السَّلامُ: إِنَّ رَبِّي قَدْ غَضِبَ الْيَوْمَ غَضَبًا، لَمْ يَغْضَبْ قَبْلَهُ مِثْلَهُ، وَلَنْ يَغْضَبَ بَعْدَهُ مِثْلَهُ، وَإِنِّي قَتَلْتُ: نَفْسًا لَمْ أُومَرْ بِقَتْلِهَا نَفْسِي نَفْسِي، اذْهَبُوا إِلَى عِيسَى عَلَيْهِ السَّلامُ، فَيَأْتُونَ عِيسَى، فَيَقُولُونَ: يَا عِيسَى أَنْتَ رَسُولُ اللَّهِ وَكَلَّمْتَ النَّاسَ فِي الْمَهْدِ، وَكَلِمَةٌ مِنْهُ أَلْقَاهَا إِلَى مَرْيَمَ وَرُوحٌ مِنْهُ، فَاشْفَعْ لَنَا إِلَى رَبِّكَ، أَلَا تَرَى مَا نَحْنُ فِيهِ، أَلَا تَرَى مَا قَدْ بَلَغَنَا، فَيَقُولُ لَهُمْ عِيسَى عَلَيْهِ السَّلامُ: إِنَّ رَبِّي قَدْ غَضِبَ الْيَوْمَ غَضَبًا، لَمْ يَغْضَبْ قَبْلَهُ مِثْلَهُ، وَلَنْ يَغْضَبَ بَعْدَهُ مِثْلَهُ، وَلَمْ يَذْكُرْ لَهُ ذَنْبًا نَفْسِي نَفْسِي، اذْهَبُوا إِلَى غَيْرِي، اذْهَبُوا إِلَى مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَيَأْتُونِّي فَيَقُولُونَ: يَا مُحَمَّدُ أَنْتَ رَسُولُ اللَّهِ وَخَاتَمُ الأَنْبِيَاءِ وَغَفَرَ اللَّهُ لَكَ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ، اشْفَعْ لَنَا إِلَى رَبِّكَ أَلَا تَرَى مَا نَحْنُ فِيه؟ِ أَلَا تَرَى مَا قَدْ بَلَغَنَا؟ فَأَنْطَلِقُ فَآتِي تَحْتَ الْعَرْشِ فَأَقَعُ سَاجِدًا لِرَبِّي ثُمَّ يَفْتَحُ اللَّهُ عَلَيَّ وَيُلْهِمُنِي مِنْ مَحَامِدِهِ وَحُسْنِ الثَّنَاءِ عَلَيْهِ شَيْئًا، لَمْ يَفْتَحْهُ لِأَحَدٍ قَبْلِي، ثُمَّ يُقَالُ: يَا مُحَمَّدُ ارْفَعْ رَأْسَكَ سَلْ تُعْطَهْ اشْفَعْ تُشَفَّعْ فَأَرْفَعُ رَأْسِي فَأَقُولُ: يَا رَبِّ أُمَّتِي أُمَّتِي فَيُقَالُ: يَا مُحَمَّدُ أَدْخِلِ الْجَنَّةَ مِنْ أُمَّتِكَ مَنْ لَا حِسَابَ عَلَيْهِ مِنَ البَابِ الأَيْمَنِ مِنَ أَبْوَابِ الْجَنَّةِ، وَهُمْ شُرَكَاءُ النَّاسِ فِيمَا سِوَى ذَلِكَ مِنَ الأَبْوَابِ، وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ إِنَّ مَا بَيْنَ الْمِصْرَاعَيْنِ مِنْ مَصَارِيعِ الْجَنَّةِ لَكَمَا بَيْنَ مَكَّةَ وَهَجَرٍ أَوْ كَمَا بَيْنَ مَكَّةَ وَبُصْرَى."],"takhrij":"متفق عليه: رواه البخاريّ في التفسير (4712)، ومسلم في الإيمان (194) كلاهما من حديث أبي حيان التّيميّ، عن أبي زرعة بن عمرو بن جرير، عن أبي هريرة، فذكره. واللّفظ لمسلم، ولفظ البخاريّ قريب منه غير أنه ذكر: نفسي نفسي نفسي ثلاث مرّات.","grade":"متفق عليه","chapter_ar":"باب شفاعة النبي ﷺ لأهل الموقف","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4712) and Muslim (194).","chapter_en":"The Prophet’s ﷺ Intercession for the People at the Standing","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":3,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported: One day meat was brought to the Messenger of Allah ﷺ. The foreleg was presented to him, and he liked it, so he took a bite from it and said: “I am the leader of mankind on the Day of Resurrection. Do you know why? Allah will gather the first and the last on the Day of Resurrection upon one level plain, so that the caller can be heard by all of them and the eye can encompass them. The sun will draw near, and the people will experience such grief and distress that they will be unable to bear or endure it. Some people will say to others: ‘Do you not see the state you are in? Do you not see what has befallen you? Will you not look for someone to intercede for you with your Lord?’ Some of them will say: ‘Go to Adam.’ They will come to Adam and say: ‘O Adam, you are the father of mankind. Allah created you with His Hand, breathed into you of His spirit, and commanded the angels to prostrate to you. Intercede for us with your Lord. Do you not see the state we are in? Do you not see what has befallen us?’ Adam will say: ‘Indeed, my Lord is angry today with an anger the like of which He has never been angry before, and the like of which He will never be angry afterward. He forbade me from the tree, but I disobeyed Him. Myself! Myself! Go to someone else. Go to Noah.’ They will come to Noah and say: ‘O Noah, you are the first messenger sent to the people of the earth, and Allah named you a grateful servant. Intercede for us with your Lord. Do you not see the state we are in? Do you not see what has befallen us?’ He will say: ‘Indeed, my Lord is angry today with an anger the like of which He has never been angry before, and the like of which He will never be angry afterward. I had a supplication which I used against my people. Myself! Myself! Go to Abraham.’ They will come to Abraham and say: ‘You are the Prophet of Allah and His close friend among the people of the earth. Intercede for us with your Lord. Do you not see the state we are in? Do you not see what has befallen us?’ Abraham will say: ‘Indeed, my Lord is angry today with an anger the like of which He has never been angry before, and the like of which He will never be angry afterward.’ He will mention the statements he made, then say: ‘Myself! Myself! Go to someone else. Go to Moses.’ They will come to Moses and say: ‘O Moses, you are the Messenger of Allah. Allah favored you above the people with His messages and by speaking directly to you. Intercede for us with your Lord. Do you not see the state we are in? Do you not see what has befallen us?’ Moses will say: ‘Indeed, my Lord is angry today with an anger the like of which He has never been angry before, and the like of which He will never be angry afterward. I killed a soul which I had not been commanded to kill. Myself! Myself! Go to Jesus.’ They will come to Jesus and say: ‘O Jesus, you are the Messenger of Allah. You spoke to the people in the cradle, you are His Word which He cast to Mary, and a spirit from Him. Intercede for us with your Lord. Do you not see the state we are in? Do you not see what has befallen us?’ Jesus will say: ‘Indeed, my Lord is angry today with an anger the like of which He has never been angry before, and the like of which He will never be angry afterward.’ He will not mention any sin for himself. ‘Myself! Myself! Go to someone else. Go to Muḥammad ﷺ.’ They will come to me and say: ‘O Muḥammad, you are the Messenger of Allah and the Seal of the Prophets. Allah has forgiven you what preceded of your sin and what followed. Intercede for us with your Lord. Do you not see the state we are in? Do you not see what has befallen us?’ So I will set out and come beneath the Throne, then fall in prostration before my Lord. Allah will then open for me and inspire me with praises of Him and beautiful commendation such as He had never opened for anyone before me. Then it will be said: ‘O Muḥammad, raise your head. Ask and you will be given. Intercede and your intercession will be accepted.’ I will raise my head and say: ‘My Lord, my Ummah! My Ummah!’ It will be said: ‘O Muḥammad, admit into Paradise from your Ummah those who will have no reckoning through the right-hand gate of Paradise. They will also share with the rest of the people in the other gates.’ By the One in whose Hand is the soul of Muḥammad, the distance between the two sides of a gate of Paradise is like the distance between Makkah and Hajar, or like the distance between Makkah and Buṣrā.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4712)، ومسلم (194)."},{"num":879,"demo":false,"sanad":"","matn":["عَنْ مَعْبَدِ بْنِ هِلَالٍ الْعَنَزِيِّ قَالَ: انْطَلَقْنَا إِلَى أَنَسِ بْنِ مَالِكٍ وَتَشَفَّعْنَا بِثَابِتٍ، فَانْتَهَيْنَا إِلَيْهِ وَهُوَ يُصَلِّي الضُّحَى، فَاسْتَأْذَنَ لَنَا ثَابِتٌ، فَدَخَلْنَا عَلَيْهِ وَأَجْلَسَ ثَابِتًا مَعَهُ عَلَى سَرِيرِهِ، فَقَالَ لَهُ: يَا أَبَا حَمْزَةَ إِنَّ إِخْوَانَكَ مِنْ أَهْلِ الْبَصْرَةِ يَسْأَلُونَكَ، أَنْ تُحَدِّثَهُمْ حَدِيثَ الشَّفَاعَةِ قَالَ: حَدَّثَنَا مُحَمَّدٌ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا كَانَ يَوْمُ الْقِيَامَةِ مَاجَ النَّاسُ بَعْضُهُمْ إِلَى بَعْضٍ، فَيَأْتُونَ آدَمَ فَيَقُولُونَ لَهُ: اشْفَعْ لِذُرِّيَّتِكَ فَيَقُولُ: لَسْتُ لَهَا، وَلَكِنْ عَلَيْكُمْ بِإِبْرَاهِيمَ عَلَيْهِ السَّلَام، فَإِنَّهُ خَلِيلُ اللَّهِ، فَيَأْتُونَ إِبْرَاهِيمَ فَيَقُولُ: لَسْتُ لَهَا وَلَكِنْ عَلَيْكُمْ بِمُوسَى عَلَيْهِ السَّلَام، فَإِنَّهُ كَلِيمُ اللَّهِ، فَيُؤْتَى مُوسَى فَيَقُولُ: لَسْتُ لَهَا وَلَكِنْ عَلَيْكُمْ بِعِيسَى عَلَيْهِ السَّلَام، فَإِنَّهُ رُوحُ اللَّهِ وَكَلِمَتُهُ، فَيُؤتَى عِيسَى فَيَقُولُ: لَسْتُ لَهَا، وَلَكِنْ عَلَيْكُمْ بِمُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأُوتَى فَأَقُولُ: أَنَا لَهَا فَأَنْطَلِقُ فَأَسْتَأْذِنُ عَلَى رَبِّي، فَيُؤْذَنُ لِي فَأَقُومُ بَيْنَ يَدَيْهِ، فَأَحْمَدُهُ بِمَحَامِدَ لَا أَقْدِرُ عَلَيْهِ الآنَ يُلْهِمُنِيهِ اللَّهُ، ثُمَّ أَخِرُّ لَهُ سَاجِدًا فَيُقَالُ لِي: يَا مُحَمَّدُ ارْفَعْ رَأْسَ وَقُلْ: يُسْمَعْ لَكَ وَسَلْ تُعْطَهْ وَاشْفَعْ تُشَفَّعْ فَأَقُولُ: رَبِّ أُمَّتِي أُمَّتِي فَيُقَالُ: انْطَلِقْ فَمَنْ كَانَ فِي قَلْبِهِ مِثْقَالُ حَبَّةٍ مِنْ بُرَّةٍ أَوْ شَعِيرَةٍ مِنَ إِيمَانٍ، فَأَخْرِجْهُ مِنْهَا، فَأَنْطَلِقُ، فَأَفْعَلُ، ثُمَّ أَرْجِعُ إِلَى رَبِّي، فَأَحْمَدُهُ بِتِلْكَ الْمَحَامِدِ ثُمَّ أَخِرُّ لَهُ سَاجِدًا فَيُقَالُ لِي: يَا مُحَمَّدُ ارْفَعْ رَأْسَكَ وَقُلْ: يُسْمَعْ لَكَ وَسَلْ تُعْطَهْ وَاشْفَعْ تُشَفَّعْ، فَأَقُولُ: أُمَّتِي أُمَّتِي فَيُقَالُ لِي: انْطَلِقْ فَمَنْ كَانَ فِي قَلْبِهِ مِثْقَالُ حَبَّةٍ مِنْ خَرْدَلٍ مِنَ إِيمَانٍ، فَأَخْرِجْهُ مِنْهَا فَأَنْطَلِقُ فَأَفْعَلُ ثُمَّ أَعُودُ إِلَى رَبِّي، فَأَحْمَدُهُ بِتِلْكَ الْمَحَامِدِ، ثُمَّ أَخِرُّ لَهُ سَاجِدًا فَيُقَالُ لِي: يَا مُحَمَّدُ ارْفَعْ رَأْسَكَ وَقُلْ: يُسْمَعْ لَكَ وَسَلْ تُعْطَهْ وَاشْفَعْ تُشَفَّعْ، فَأَقُولُ: يَا رَبِّ أُمَّتِي أُمَّتِي، فَيُقَالُ لِي: انْطَلِقْ فَمَنْ كَانَ فِي قَلْبِهِ أَدْنَى أَدْنَى أَدْنَى مِنْ مِثْقَالِ حَبَّةٍ مِنْ خَرْدَلٍ مِنَ إِيمَانٍ، فَأَخْرِجْهُ مِنَ النَّارِ فَأَنْطَلِقُ فَأَفْعَلُ.","هَذَا حَدِيثُ أَنَسٍ الَّذِي أَنْبَأَنَا بِهِ، فَخَرَجْنَا مِنْ عِنْدِهِ، فَلَمَّا كُنَّا بِظَهْرِ الْجَبَّانِ قُلْنَا: لَوْ مِلْنَا إِلَى الْحَسَنِ، فَسَلَّمْنَا عَلَيْهِ وَهُوَ مُسْتَخْفٍ فِي دَارِ أَبِي خَلِيفَةَ قَالَ: فَدَخَلْنَا عَلَيْهِ فَسَلَّمْنَا عَلَيْهِ، فَقُلْنَا: يَا أَبَا سَعِيدٍ جِئْنَا مِنْ عِنْدِ أَخِيكَ أَبِي حَمْزَةَ، فَلَمْ نَسْمَعْ مِثْلَ حَدِيثٍ حَدَّثَنَاهُ فِي الشَّفَاعَةِ، قَالَ: هِيَهِ فَحَدَّثْنَاهُ الْحَدِيثَ، فَقَالَ: هِيَهِ، قُلْنَا: مَا زَادَنَا؟ قَالَ: قَدْ حَدَّثَنَا بِهِ مُنْذُ عِشْرِينَ سَنَةً، وَهُوَ يَوْمَئِذٍ جَمِيعٌ، وَلَقَدْ تَرَكَ شَيْئًا مَا أَدْرِي أَنَسِيَ الشَّيْخُ أَوْ كَرِهَ، أَنْ يُحَدِّثَكُمْ فَتَتَّكِلُوا، قُلْنَا لَهُ حَدِّثْنَا فَضَحِكَ، وَقَالَ: ﴿خُلِقَ الْإِنْسَانُ مِنْ عَجَلٍ﴾ [سورة الأنبياء: 37]. مَا ذَكَرْتُ لَكُمْ هَذَا، إِلَّا وَأَنَا أُرِيدُ أَنْ أُحَدِّثَكُمُوهُ، ثُمَّ أَرْجِعُ إِلَى رَبِّي فِي الرَّابِعَةِ، فَأَحْمَدُهُ بِتِلْكَ الْمَحَامِدِ ثُمَّ أَخِرُّ لَهُ سَاجِدًا فَيُقَالُ لِي: يَا مُحَمَّدُ ارْفَعْ رَأْسَكَ وَقُلْ: يُسْمَعْ لَكَ وَسَلْ تُعْطَ وَاشْفَعْ تُشَفَّعْ، فَأَقُولُ: يَا رَبِّ ائْذَنْ لِي فِيمَنْ، قَالَ: لَا إِلَهَ إِلَّا اللَّهُ، قَالَ: لَيْسَ ذَاكَ لَكَ أَوَ قَالَ: لَيْسَ ذَاكَ إِلَيْكَ، وَلَكِنْ وَعِزَّتِي وَكِبْرِيَائِي وَعَظَمَتِي وَجِبْرِيَائِي لَأُخْرِجَنَّ مَنْ قَالَ: لَا إِلَهَ إِلَّا اللَّهُ."],"takhrij":"متفق عليه: رواه البخاريّ في التوحيد (7510)، ومسلم في الإيمان (193: 326) كلاهما من حديث حمّاد بن زيد، حدّثنا معبدبن هلال العنـزيّ، قال: فذكره. واللّفظ لمسلم، ولفظ البخاريّ نحوه.","grade":"متفق عليه","chapter_ar":"باب شفاعة النبي ﷺ لأهل الموقف","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7510) and Muslim (193:326).","chapter_en":"The Prophet’s ﷺ Intercession for the People at the Standing","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":3,"content":{"translation":{"en":["Maʿbad ibn Hilāl al-ʿAnazī reported: We set out to visit Anas ibn Mālik may Allah be pleased with him and asked Thābit to intercede for us with him. We reached him while he was praying Ḍuḥā. Thābit sought permission for us, so we entered, and Anas seated Thābit with him upon his bed. Thābit said: “O Abū Ḥamzah, your brothers from the people of Baṣrah ask you to narrate to them the ḥadīth of intercession.” Anas said: Muḥammad ﷺ narrated to us: “On the Day of Resurrection, the people will surge against one another. They will come to Adam and say: ‘Intercede for your descendants.’ He will reply: ‘I am not suited for it. Go instead to Abraham, peace be upon him,, for he is the close friend of Allah.’ They will come to Abraham, who will say: ‘I am not suited for it. Go instead to Moses, peace be upon him,, for he is the one to whom Allah spoke.’ Moses will be approached and will say: ‘I am not suited for it. Go instead to Jesus, peace be upon him,, for he is a spirit from Allah and His Word.’ Jesus will be approached and will say: ‘I am not suited for it. Go instead to Muḥammad ﷺ.’ Then I will be approached, and I will say: ‘I am for it.’ I will set out and seek permission to enter upon my Lord, and permission will be granted to me. I will stand before Him and praise Him with praises which I am unable to produce now; rather, Allah will inspire them to me. Then I will fall in prostration before Him. It will be said to me: ‘O Muḥammad, raise your head. Speak and you will be heard. Ask and you will be given. Intercede and your intercession will be accepted.’ I will say: ‘My Lord, my Ummah! My Ummah!’ It will be said: ‘Go. Whoever has in his heart the weight of a grain of wheat or barley of faith, bring him out from it.’ So I will go and do so. Then I will return to my Lord, praise Him with those praises, and fall in prostration before Him. It will be said to me: ‘O Muḥammad, raise your head. Speak and you will be heard. Ask and you will be given. Intercede and your intercession will be accepted.’ I will say: ‘My Ummah! My Ummah!’ It will be said to me: ‘Go. Whoever has in his heart the weight of a mustard seed of faith, bring him out from it.’ So I will go and do so. Then I will return to my Lord and praise Him with those praises, then fall in prostration before Him. It will be said to me: ‘O Muḥammad, raise your head. Speak and you will be heard. Ask and you will be given. Intercede and your intercession will be accepted.’ I will say: ‘My Lord, my Ummah! My Ummah!’ It will be said to me: ‘Go. Whoever has in his heart the slightest, the slightest, the slightest amount less than the weight of a mustard seed of faith, bring him out of the Fire.’ So I will go and do so.” Maʿbad said: This was the ḥadīth of Anas which he narrated to us. We left him, and when we reached the outskirts of the graveyard we said:","“If only we went to al-Ḥasan.” We greeted him while he was hiding in the house of Abū Khalīfah. We entered and greeted him, then said: “O Abū Saʿīd, we have just come from your brother Abū Ḥamzah, and we have never heard anything like the ḥadīth he narrated to us concerning intercession.” He said: “Continue!” So we narrated the ḥadīth to him. He said: “Continue!” We replied: “He did not add anything more.” He said: “He narrated this to us twenty years ago, when he was still fully strong in body and memory, and he certainly omitted something. I do not know whether the shaykh forgot it or disliked narrating it to you lest you become complacent.” We said: “Then narrate it to us.” He laughed and recited: “Man was created of haste.” [Sūrat al-Anbiyāʾ 21:37] He said: “I only mentioned this because I intended to narrate it to you.” Then he continued: “Then I will return to my Lord a fourth time, praise Him with those praises, and fall in prostration before Him. It will be said to me: ‘O Muḥammad, raise your head. Speak and you will be heard. Ask and you will be given. Intercede and your intercession will be accepted.’ I will say: ‘My Lord, give me permission regarding whoever said: There is no deity worthy of worship except Allah.’ He will say: ‘That is not for you,’ or He said, ‘That is not up to you. But by My Might, My Majesty, My Greatness, and My Supremacy, I will surely bring out whoever said: There is no deity worthy of worship except Allah.’”"]},"buhuth":{"en":["The word:","“jamīʿ”","here means fully gathered in strength and possessing strong memory."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (7510)، ومسلم (193: 326)."},{"num":880,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَجْتَمِعُ الْمُؤْمِنُونَ يَوْمَ الْقِيَامَةِ فَيَقُولُونَ: لَوِ اسْتَشْفَعْنَا إِلَى رَبِّنَا فَيَأْتُونَ آدَمَ فَيَقُولُونَ: أَنْتَ أَبُو النَّاسِ خَلَقَكَ اللَّهُ بِيَدِهِ وَأَسْجَدَ لَكَ مَلَائِكَتَهُ، وَعَلَّمَكَ أَسْمَاءَ كُلِّ شَيْءٍ، فَاشْفَعْ لَنَا عِنْدَ رَبِّكَ حَتَّى يُرِيحَنَا مِنْ مَكَانِنَا هَذَا، فَيَقُولُ: لَسْتُ هُنَاكُمْ وَيَذْكُرُ ذَنْبَهُ، فَيَسْتَحِي ائْتُوا نُوحًا، فَإِنَّهُ أَوَّلُ رَسُولٍ بَعَثَهُ اللَّهُ إِلَى أَهْلِ الْأَرْضِ، فَيَأْتُونَهُ، فَيَقُولُ: لَسْتُ هُنَاكُمْ وَيَذْكُرُ سُؤَالَهُ رَبَّهُ مَا لَيْسَ لَهُ بِهِ عِلْمٌ فَيَسْتَحِي، فَيَقُولُ: ائْتُوا خَلِيلَ الرَّحْمَنِ، فَيَأْتُونَهُ، فَيَقُولُ: لَسْتُ هُنَاكُمُ ائْتُوا مُوسَى عَبْدًا كَلَّمَهُ اللَّهُ، وَأَعْطَاهُ التَّوْرَاةَ، فَيَأْتُونَهُ، فَيَقُولُ: لَسْتُ هُنَاكُمْ، وَيَذْكُرُ قَتْلَ النَّفْسِ بِغَيْرِ نَفْسٍ فَيَسْتَحِي مِنْ رَبِّهِ، فَيَقُولُ: ائْتُوا عِيسَى عَبْدَ اللَّهِ وَرَسُولَهُ، وَكَلِمَةَ اللَّهِ وَرُوحَهُ، فَيَقُولُ: لَسْتُ هُنَاكُمُ ائْتُوا مُحَمَّدًا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَبْدًا غَفَرَ اللَّهُ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ وَمَا تَأَخَّرَ، فَيَأْتُونِي، فَأَنْطَلِقُ حَتَّى أَسْتَأْذِنَ عَلَى رَبِّي، فَيُؤْذَنَ لِي، فَإِذَا رَأَيْتُ رَبِّي وَقَعْتُ سَاجِدًا، فَيَدَعُنِي مَا شَاءَ اللَّهُ، ثُمَّ يُقَالُ: ارْفَعْ رَأْسَكَ وَسَلْ تُعْطَهْ، وَقُلْ يُسْمَعْ، وَاشْفَعْ تُشَفَّعْ، فَأَرْفَعُ رَأْسِي فَأَحْمَدُهُ بِتَحْمِيدٍ يُعَلِّمُنِيهِ، ثُمَّ أَشْفَعُ فَيَحُدُّ لِي حَدًّا، فَأُدْخِلُهُمُ الْجَنَّةَ، ثُمَّ أَعُودُ إِلَيْهِ فَإِذَا رَأَيْتُ رَبِّي مِثْلَهُ، ثُمَّ أَشْفَعُ فَيَحُدُّ لِي حَدًّا، فَأُدْخِلُهُمُ الْجَنَّةَ، ثُمَّ أَعُودُ الرَّابِعَةَ، فَأَقُولُ: مَا بَقِيَ فِي النَّارِ إِلَّا مَنْ حَبَسَهُ الْقُرْآنُ وَوَجَبَ عَلَيْهِ الْخُلُودُ.","قَالَ أَبُو عَبْد اللَّهِ: إِلَّا مَنْ حَبَسَهُ الْقُرْآنُ يَعْنِي قَوْلَ اللَّهِ تَعَالَى: ﴿خَالِدِينَ فِيهَا﴾ [ سورة البقرة: 162]."],"takhrij":"متفق عليه: رواه البخاريّ في التفسير (4476)، ومسلم في الإيمان (193) كلاهما من حديث هشام، عن قتادة، عن أنس، فذكره، واللّفظ للبخاريّ، ولفظ مسلم نحوه.","grade":"متفق عليه","chapter_ar":"باب شفاعة النبي ﷺ لأهل الموقف","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4476) and Muslim (193).","chapter_en":"The Prophet’s ﷺ Intercession for the People at the Standing","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":3,"content":{"translation":{"en":["Anas may Allah be pleased with him reported that the Prophet ﷺ said: “The believers will gather on the Day of Resurrection and say: ‘If only we sought someone to intercede for us with our Lord.’ They will come to Adam and say: ‘You are the father of mankind. Allah created you with His Hand, caused His angels to prostrate to you, and taught you the names of all things. Intercede for us with your Lord so that He may relieve us from this place of ours.’ He will say: ‘I am not suited for that.’ He will mention his sin and become ashamed, then say: ‘Go to Noah, for he was the first messenger Allah sent to the people of the earth.’ They will come to him, and he will say: ‘I am not suited for that.’ He will mention that he asked his Lord concerning that of which he had no knowledge, and he will become ashamed. He will say: ‘Go to the close friend of the Most Merciful.’ They will come to Abraham, and he will say: ‘I am not suited for that. Go to Moses, a servant to whom Allah spoke and to whom He gave the Torah.’ They will come to him, and he will say: ‘I am not suited for that.’ He will mention that he killed a person without that person having killed another, and he will become ashamed before his Lord. He will say: ‘Go to Jesus, the servant and Messenger of Allah, His Word and a spirit from Him.’ Jesus will say: ‘I am not suited for that. Go to Muḥammad ﷺ, a servant whose former and latter sins Allah has forgiven.’ They will come to me. I will set out until I seek permission from my Lord, and permission will be granted to me. When I see my Lord, I will fall in prostration, and He will leave me in that state for as long as Allah wills. Then it will be said: ‘Raise your head. Ask and you will be given. Speak and you will be heard. Intercede and your intercession will be accepted.’ I will raise my head and praise Him with a praise which He will teach me. Then I will intercede, and He will set a limit for me, and I will admit those people into Paradise. Then I will return to Him, and when I see my Lord, the same will occur. Then I will intercede again, and He will set a limit for me, and I will admit them into Paradise. Then I will return a fourth time and say: ‘None remains in the Fire except those whom the Qurʾān has confined therein and for whom everlasting punishment has become obligatory.’”","Abū ʿAbdullāh said: The words: “Except those whom the Qurʾān has confined” refer to the statement of Allah Most High: “Abiding therein forever.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4476)، ومسلم (193)."},{"num":881,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: يُطَوَّلُ يَوْمُ الْقِيَامَةِ عَلَى النَّاسِ، فَيَقُولُ بَعْضُهُمْ لِبَعْضٍ: انْطَلِقُوا بِنَا إِلَى آدَمَ أَبِي الْبَشَرِ، فَيَشْفَعُ لَنَا إِلَى رَبِّنَا، فَلْيَقْضِ بَيْنَنَا، فَيَأْتُونَ آدَمَ، فَيَقُولُونَ: يَا آدَمُ، أَنْتَ الَّذِي خَلَقَكَ اللهُ بِيَدِهِ وَأَسْكَنَكَ جَنَّتَهُ، فَاشْفَعْ لَنَا إِلَى رَبِّكَ فَلْيَقْضِ بَيْنَنَا، فَيَقُولُ: إِنِّي لَسْتُ هُنَاكُمْ، وَلَكِنْ ائْتُوا نُوحًا رَأْسَ النَّبِيِّينَ فَيَأْتُونَهُ، فَيَقُولُونَ: يَا نُوحُ، اشْفَعْ لَنَا إِلَى رَبِّكَ فَلْيَقْضِ بَيْنَنَا، فَيَقُولُ: إِنِّي لَسْتُ هُنَاكُمْ، وَلَكِنْ ائْتُوا إِبْرَاهِيمَ خَلِيلَ اللهِ فَيَأْتُونَهُ، فَيَقُولُونَ: يَا إِبْرَاهِيمُ، اشْفَعْ لَنَا إِلَى رَبِّكَ فَلْيَقْضِ بَيْنَنَا، فَيَقُولُ: إِنِّي لَسْتُ هُنَاكُمْ، وَلَكِنْ ائْتُوا مُوسَى الَّذِي اصْطَفَاهُ اللهُ بِرِسَالَاتِهِ وَبِكَلَامِهِ، قَالَ: فَيَأْتُونَهُ فَيَقُولُونَ: يَا مُوسَى اشْفَعْ لَنَا إِلَى رَبِّكَ فَلْيَقْضِ بَيْنَنَا، فَيَقُولُ: إِنِّي لَسْتُ هُنَاكُمْ، وَلَكِنْ ائْتُوا عِيسَى رُوحَ اللهِ وَكَلِمَتَهُ، فَيَأْتُونَ عِيسَى فَيَقُولُونَ: يَا عِيسَى، اشْفَعْ لَنَا إِلَى رَبِّكَ فَلْيَقْضِ بَيْنَنَا، فَيَقُولُ: إِنِّي لَسْتُ هُنَاكُمْ، وَلَكِنْ ائْتُوا مُحَمَّدًا صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَإِنَّهُ خَاتَمُ النَّبِيِّينَ، فَإِنَّهُ قَدْ حَضَرَ الْيَوْمَ وَقَدْ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ وَمَا تَأَخَّرَ، فَيَقُولُ عِيسَى أَرَأَيْتُمْ لَوْ كَانَ مَتَاعٌ فِي وِعَاءٍ قَدْ خُتِمَ عَلَيْهِ، هَلْ كَانَ يُقْدَرُ عَلَى مَا فِي الْوِعَاءِ حَتَّى يُفَضَّ الْخَاتَمُ؟ فَيَقُولُونَ: لَا، قَالَ: فَإِنَّ مُحَمَّدًا صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَاتَمُ النَّبِيِّينَ. قَالَ: فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: فَيَأْتُونِي فَيَقُولُونَ: يَا مُحَمَّدُ! اشْفَعْ لَنَا إِلَى رَبِّكَ فَلِيَقْضِ بَيْنَنَا قَالَ: فَأَقُولُ: نَعَمْ، فَآتِي بَابَ الْجَنَّةِ، فَآخُذُ بِحَلْقَةِ الْبَابِ، فَأَسْتَفْتِحُ، فَيُقَالُ: مَنْ أَنْتَ؟ فَأَقُولُ: مُحَمَّدُ، فَيُفْتَحُ لِي فَأَخِرُّ سَاجِدًا، فَأَحْمَدُ رَبِّي بِمَحَامِدَ لَمْ يَحْمَدْهُ بِهَا أَحَدٌ كَانَ قَبْلِي، وَلَا يَحْمَدُهُ بِهَا أَحَدٌ كَانَ بَعْدِي، فَيَقُولُ: ارْفَعْ رَأْسَكَ، وَقُلْ يُسْمَعْ مِنْكَ، وَسَلْ تُعْطَهْ، وَاشْفَعْ تُشَفَّعْ، فَيَقُولُ: أَيْ رَبِّ! أُمَّتِي أُمَّتِي، فَيُقَالُ: أَخْرِجْ مَنْ كَانَ فِي قَلْبِهِ مِثْقَالُ شَعِيرَةٍ مِنْ إِيمَانٍ، قَالَ: فَأُخْرِجُهُمْ ثُمَّ أَخِرُّ سَاجِدًا، فَأَحْمَدُهُ بِمَحَامِدَ لَمْ يَحْمَدْهُ بِهَا أَحَدٌ كَانَ قَبْلِي، وَلَا يَحْمَدُهُ بِهَا أَحَدٌ كَانَ بَعْدِي، فَيُقَالُ لِي: ارْفَعْ رَأْسَكَ، وَسَلْ تُعْطَهْ، وَاشْفَعْ تُشَفَّعْ، فَأَقُولُ: أَيْ رَبِّ! أُمَّتِي أُمَّتِي، فَيُقَالُ: أَخْرِجْ مَنْ كَانَ فِي قَلْبِهِ مِثْقَالُ بُرَّةٍ مِنْ إِيمَانٍ، قَالَ: فَأُخْرِجُهُمْ قَالَ: ثُمَّ أَخِرُّ سَاجِدًا، فَأَقُولُ مِثْلَ ذَلِكَ، فَيُقَالُ: أَخْرِجْ مَنْ كَانَ فِي قَلْبِهِ مِثْقَالُ ذَرَّةٍ مِنْ إِيمَانٍ، قَالَ: فَأُخْرِجُهُمْ."],"takhrij":"صحيح: رواه الإمام أحمد (13590) عن عفّان، حدّثنا حمّاد بن سلمة، حدّثنا ثابت، عن أنس، فذكره.","grade":"صحيح","chapter_ar":"باب شفاعة النبي ﷺ لأهل الموقف","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Imām Aḥmad (13590), and authenticated by Ibn Khuzaymah (486).","chapter_en":"The Prophet’s ﷺ Intercession for the People at the Standing","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":3,"content":{"translation":{"en":["Anas may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “The Day of Resurrection will be prolonged for the people, so some of them will say to others: ‘Come, let us go to Adam, the father of mankind, so that he may intercede for us with our Lord, Mighty and Majestic, and He may judge between us.’ They will come to Adam and say: ‘O Adam, you are the one whom Allah created with His Hand and settled in His Paradise. Intercede for us with your Lord so that He may judge between us.’ He will say: ‘I am not suited for that. Rather, go to Noah, the foremost of the prophets.’ They will come to him and say: ‘O Noah, intercede for us with your Lord so that He may judge between us.’ He will reply: ‘I am not suited for that. Rather, go to Abraham, the close friend of Allah, Mighty and Majestic.’ They will come to him and say: ‘O Abraham, intercede for us with your Lord so that He may judge between us.’ He will say: ‘I am not suited for that. Rather, go to Moses, whom Allah, Mighty and Majestic, chose with His messages and His speech.’ They will come to him and say: ‘O Moses, intercede for us with your Lord, Mighty and Majestic, so that He may judge between us.’ He will say: ‘I am not suited for that. Rather, go to Jesus, the Spirit of Allah and His Word.’ They will come to Jesus and say: ‘O Jesus, intercede for us with your Lord so that He may judge between us.’ He will say: ‘I am not suited for that. Rather, go to Muḥammad ﷺ, for he is the Seal of the Prophets, and he has been forgiven what preceded of his sin and what followed.’ Jesus will say: ‘Tell me: if some goods were inside a vessel that had been sealed, could anyone reach what was inside until the seal was broken?’ They will reply: ‘No.’ He will say: ‘Indeed, Muḥammad ﷺ is the Seal of the Prophets.’ The Messenger of Allah ﷺ said: “They will come to me and say: ‘O Muḥammad, intercede for us with your Lord so that He may judge between us.’ I will say: ‘Yes.’ I will come to the gate of Paradise, take hold of its ring, and ask for it to be opened. It will be asked: ‘Who are you?’ I will reply: ‘Muḥammad.’ It will be opened for me, and I will fall in prostration. I will praise my Lord, Mighty and Majestic, with praises with which no one before me praised Him and no one after me will praise Him. He will say: ‘Raise your head. Speak and you will be heard. Ask and you will be given. Intercede and your intercession will be accepted.’ I will say: ‘My Lord, my Ummah! My Ummah!’ It will be said: ‘Bring out whoever has in his heart the weight of a grain of barley of faith.’ So I will bring them out. Then I will fall in prostration again and praise Him with praises with which no one before me praised Him and no one after me will praise Him. It will be said to me: ‘Raise your head. Ask and you will be given. Intercede and your intercession will be accepted.’ I will say: ‘My Lord, my Ummah! My Ummah!’ It will be said: ‘Bring out whoever has in his heart the weight of a grain of wheat of faith.’ So I will bring them out. Then I will fall in prostration again and say likewise. It will be said: ‘Bring out whoever has in his heart the weight of an atom of faith.’ So I will bring them out.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (13590)، وصححه ابن خزيمة (486)."},{"num":882,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ: أَنَّ الْأَنْبِيَاءَ عَلَيْهِمُ الصَّلَاةُ وَالسَّلَامُ ذُكِرُوا عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: وَالَّذِي نَفْسِي بِيَدِهِ، إِنِّي لِسَيِّدُ النَّاسِ يَوْمَ الْقِيَامَةِ وَلَا فَخْرَ، وَإِنَّ بِيَدِي لِوَاءَ الْحَمْدِ، وَإِنَّ تَحْتَهُ آدَمُ عَلَيْهِ السَّلَامُ وَمَنْ دُونَهُ وَلَا فَخْرَ قَالَ: يُنَادِي اللَّهُ عَزَّ وَجَلَّ يَوْمَئِذٍ آدَمَ، فَيَقُولُ آدَمُ: لَبَّيْكَ رَبِّ وَسَعْدَيْكَ، فَيَقُولُ: أَخْرِجْ مِنْ ذُرِّيَّتِكَ بَعْثَ النَّارِ فَيَقُولُ: وَمَا بَعْثُ النَّارِ؟ فَيَقُولُ: مِنْ كُلِّ أَلْفِ تِسْعَمِائَةٍ وَتِسْعَةً وَتِسْعِينَ، فَيُخْرِجُ مَالًا يَعْلَمُ عَدَدَهُ إِلَّا اللَّهُ عَزَّ وَجَلَّ، فَيَأْتُونَ آدَمَ عَلَيْهِ السَّلَامُ فَيَقُولُونَ: أَنْتَ آدَمُ أَكْرَمَكَ اللَّهُ، وَخَلَقَكَ بِيَدِهِ، وَنَفَخَ فِيكَ مِنْ رُوحِهِ، وَأَسْكَنَكَ جَنَّتَهُ، وَأَمَرَ الْمَلَائِكَةَ فَسَجَدُوا لَكَ، فَاشْفَعْ لِذُرِّيَّتِكَ، لَا تُحْرَقِ الْيَوْمَ بِالنَّارِ، فَيَقُولُ: لَيْسَ ذَلِكَ إِلَيَّ الْيَوْمَ، وَلَكِنْ سَأُرْشِدُكُمْ، عَلَيْكُمْ بِعَبْدٍ اتَّخَذَهُ اللَّهُ خَلِيلًا وَأَنَا مَعَكُمْ، فَيَأْتُونَ إِبْرَاهِيمَ عَلَيْهِ السَّلَامُ، فَيَقُولُونَ: يَا إِبْرَاهِيمُ، أَنْتَ عَبْدٌ اتَّخَذَكَ اللَّهُ خَلِيلًا، فَاشْفَعْ لِذُرِّيَةِ آدَمَ، لَا تُحْرَقِ الْيَوْمَ بِالنَّارِ، فَيَقُولُ: لَيْسَ ذَلِكَ إِلَيَّ، وَلَكِنْ سَأُرْشِدُكُمْ، عَلَيْكُمْ بِعَبْدٍ اصْطَفَاهُ اللَّهُ عَزَّ وَجَلَّ بِكَلَامِهِ وَرِسَالَاتِهِ، وَأَلْقَى عَلَيْهِ مَحَبَّةً مِنْهُ: مُوسَى، وَأَنَا مَعَكُمْ، فَيَأْتُونَ مُوسَى، فَيَقُولُونَ: يَا مُوسَى أَنْتَ عَبْدٌ اصْطَفَاكَ اللَّهُ عَزَّ وَجَلَّ بِرِسَالَاتِهِ وَكَلَامِهِ، وَأَلْقَى عَلَيْكَ مَحَبَّةً مِنْهُ، اشْفَعْ لِذُرِّيَةِ آدَمَ، لَا تُحْرَقِ الْيَوْمَ بِالنَّارِ قَالَ: لَيْسَ ذَلِكَ الْيَوْمَ إِلَيَّ، وَلَكِنْ سَأُرْشِدُكُمْ، عَلَيْكُمْ بِرُوحِ اللَّهِ وَكَلِمَتِهِ: عِيسَى ابْنِ مَرْيَمَ، فَيَأْتُونَ عِيسَى ابْنَ مَرْيَمَ عَلَيْهِ السَّلَامُ، فَيَقُولُونَ يَا عِيسَى، أَنْتَ رُوحُ اللَّهِ وَكَلِمَتُهُ، اشْفَعْ لِذُرِّيَةِ آدَمَ، لَا تُحْرَقِ الْيَوْمَ بِالنَّارِ قَالَ: لَيْسَ ذَلِكَ الْيَوْمَ إِلَيَّ، عَلَيْكُمْ بِعَبْدٍ جَعَلَهُ اللَّهُ عَزَّ وَجَلَّ رَحْمَةً لِلْعَالَمِينَ: أَحْمَدَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَأَنَا مَعَكُمْ، فَيَأْتُونَ فَيَقُولُونَ: يَا أَحْمَدُ، جَعَلَكَ اللَّهُ رَحْمَةً لِلْعَالَمِينَ، فَاشْفَعْ لِذُرِّيَةِ آدَمَ، لَا تُحْرَقِ الْيَوْمَ بِالنَّارِ، فَيَقُولُ: نَعَمْ، أَنَا صَاحِبُهَا فَآتِي حَتَّى آخُذَ بِحَلْقَةِ بَابِ الْجَنَّةِ، فَيُقَالُ: مَنْ هَذَا؟ فَأَقُولُ: أَنَا أَحْمَدُ فَيُفْتَحُ لِي، فَإِذَا نَظَرْتُ إِلَى الْجَبَّارِ تَبَارَكَ وَتَعَالَى خَرَرْتُ سَاجِدًا، ثُمَّ يُفْتَحُ لِي مِنَ التَّحْمِيدِ وَالثَّنَاءِ عَلَى الرَّبِّ عَزَّ وَجَلَّ شَيْءٌ لَا يُحْسِنُ الْخَلْقُ ثُمَّ يُقَالُ: سَلْ تُعْطَهُ، وَاشْفَعْ تُشَفَّعْ، فَيَقُولُ: يَا رَبِّ، ذُرِّيَّةُ آدَمَ لَا تُحْرَقِ الْيَوْمَ فِي النَّارِ فَيَقُولُ: اذْهَبُوا فَمَنْ وَجَدْتُمْ فِي قَلْبِهِ مِثْقَالَ دِينَارٍ مِنْ إِيمَانٍ فَأَخْرِجُوهُ، ثُمَّ يَعُودُونَ إِلَيَّ فَيَقُولُونَ: ذُرِّيَّةُ آدَمَ لَا تُحْرَقِ الْيَوْمَ بِالنَّارِ قَالَ: فَآتِي حَتَّى آخُذَ بِحَلْقَةِ بَابِ الْجَنَّةِ، فَيُقَالُ: مَنْ هَذَا؟ فَأَقُولُ: أَحْمَدُ فَيُفْتَحُ لِي، فَإِذَا نَظَرْتُ إِلَى الْجَبَّارِ تَبَارَكَ وَتَعَالَى خَرَرْتُ سَاجِدًا فَأَسْجُدُ مِثْلَ سُجُودِي أَوَّلَ مَرَّةٍ وَمِثْلَهُ مَعِي، فَيُفْتَحُ لِي مِنَ الثَّنَاءِ عَلَى الرَّبِّ عَزَّ وَجَلَّ مِنَ التَّحْمِيدِ مِثْلُ مَا فُتِحَ لِي أَوَّلَ مَرَّةٍ فَيُقَالُ: ارْفَعْ رَأْسَكَ، وَسَلْ تُعْطَهُ، وَاشْفَعْ تُشَفَّعْ فَأَقُولُ: يَا رَبُّ، ذُرِّيَّةُ آدَمَ، لَا تُحْرَقِ الْيَوْمَ بِالنَّارِ فَيَقُولُ: أَخْرِجُوا لَهُ مَنْ كَانَ فِي قَلْبِهِ مِثْقَالُ قِيرَاطٍ مِنْ إِيمَانٍ ثُمَّ يَعُودُونَ إِلَيَّ، فَآتِي حَتَّى أَصْنَعَ كَمَا صَنَعْتُ، فَإِذَا نَظَرْتُ إِلَى الْجَبَّارِ عَزَّ وَجَلَّ خَرَرْتُ سَاجِدًا، فَأَسْجُدُ كَسُجُودِي أَوَّلَ مَرَّةٍ وَمِثْلَهُ مَعِي، وَيُفْتَحُ لِي مِنَ الثَّنَاءِ وَالتَّحْمِيدِ مِثْلُ ذَلِكَ، ثُمَّ يُقَالُ: سَلْ تُعْطَهْ، وَاشْفَعْ تُشَفَّعْ فَأَقُولُ: يَا رَبِّ، ذُرِّيَّةُ آدَمَ، لَا تُحْرَقِ الْيَوْمَ بِالنَّارِ، فَيَقُولُ: اذْهَبُوا فَمَنْ وَجَدْتُمْ فِي قَلْبِهِ مِثْقَالَ ذَرَّةٍ مِنْ إِيمَانٍ فَأَخْرِجُوهُ، فَيُخْرِجُونَ مَا لَا يَعْلَمُ عِدَّتَهُمْ إِلَّا اللَّهُ عَزَّ وَجَلَّ، وَيَبْقَى أَكْثَرُهُمْ، ثُمَّ يُؤْذَنُ لِآدَمَ بِالشَّفَاعَةِ، فَيَشْفَعُ لِعَشَرَةِ آلَافِ أَلْفٍ، ثُمَّ يُؤْذَنُ لِلْمَلَائِكَةِ وَالنَّبِيِّينَ، فَيَشْفَعُونَ، حَتَّى إِنَّ الْمُؤْمِنَ لَيَشْفَعُ لِأَكْثَرِ مِنْ رَبِيعَةَ وَمُضَرَ."],"takhrij":"حسن: رواه الآجرّي في الشّريعة (809) عن أبي بكر جعفر بن محمد الفريابيّ، قال: حدّثنا قتيبة بن سعيد، قال: حدّثنا اللّيث بن سعد، عن خالد بن يزيد، عن سعيد بن أبي هلال، عن أنس بن مالك، فذكره.","grade":"حسن","chapter_ar":"باب شفاعة النبي ﷺ لأهل الموقف","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Ājurrī in al-Sharīʿah (809).","chapter_en":"The Prophet’s ﷺ Intercession for the People at the Standing","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":3,"content":{"translation":{"en":["Anas ibn Mālik may Allah be pleased with him reported that the prophets, peace be upon them, were mentioned in the presence of the Messenger of Allah ﷺ, and he said: “By the One in whose Hand is my soul, I will indeed be the leader of mankind on the Day of Resurrection—without boasting. In my hand will be the Banner of Praise, beneath which will be Adam peace be upon him and all those after him—without boasting. On that Day Allah, Mighty and Majestic, will call: ‘Adam!’ He will reply: ‘Here I am, my Lord, and at Your service.’ He will say: ‘Bring forth from your descendants the contingent of the Fire.’ Adam will ask: ‘What is the contingent of the Fire?’ He will say: ‘From every thousand, nine hundred and ninety-nine.’ There will come forth a number known only to Allah, Mighty and Majestic. They will come to Adam peace be upon him and say: ‘You are Adam. Allah honored you, created you with His Hand, breathed into you from His spirit, settled you in His Paradise, and commanded the angels to prostrate to you. Intercede for your descendants so that they will not be burned in the Fire today.’ He will say: ‘That is not for me today, but I will direct you to a servant whom Allah took as a close friend. I will go with you.’ They will come to Abraham, peace be upon him, and say: ‘O Abraham, you are a servant whom Allah took as a close friend. Intercede for the descendants of Adam so that they will not be burned in the Fire today.’ He will say: ‘That is not for me, but I will direct you to a servant whom Allah, Mighty and Majestic, chose with His speech and His messages and upon whom He cast love from Himself: Moses. I will go with you.’ They will come to Moses and say: ‘O Moses, you are a servant whom Allah chose with His messages and His speech and upon whom He cast love from Himself. Intercede for the descendants of Adam so that they will not be burned in the Fire.’ He will say: ‘That is not for me today, but I will direct you to the Spirit of Allah and His Word: Jesus son of Mary.’ They will come to Jesus son of Mary peace be upon him and say: ‘O Jesus, you are the Spirit of Allah and His Word. Intercede for the descendants of Adam so that they will not be burned in the Fire today.’ He will say: ‘That is not for me today. Go to a servant whom Allah, Mighty and Majestic, made a mercy to the worlds: Aḥmad. I will go with you.’ They will come to me and say: ‘O Aḥmad, Allah made you a mercy to the worlds. Intercede for the descendants of Adam so that we will not be burned in the Fire today.’ I will say: ‘Yes, I am the one for it.’ I will come and take hold of the ring of the gate of Paradise. It will be asked: ‘Who is this?’ I will reply: ‘I am Aḥmad.’ It will be opened for me. When I look toward al-Jabbār, Blessed and Exalted, I will fall in prostration. Then there will be opened for me forms of praise and glorification of the Lord, Mighty and Majestic, which creation cannot adequately perform. Then it will be said: ‘Ask and you will be given. Intercede and your intercession will be accepted.’ I will say: ‘My Lord, let the descendants of Adam not be burned in the Fire today.’ He will say: ‘Go. Whoever you find with the weight of a dinar of faith in his heart, bring him out.’ Then they will return to me, saying: ‘The descendants of Adam—let them not be burned in the Fire today.’ I will again come and take hold of the ring of the gate of Paradise. It will be asked: ‘Who is this?’ I will reply: ‘Aḥmad.’ It will be opened for me. When I look toward al-Jabbār, Blessed and Exalted, I will fall in prostration, like my first prostration, and similar praise and glorification will be opened for me as was opened the first time. It will be said: ‘Raise your head. Ask and you will be given. Intercede and your intercession will be accepted.’ I will say: ‘My Lord, let the descendants of Adam not be burned in the Fire today.’ He will say: ‘Bring out for him whoever has in his heart the weight of a qīrāṭ of faith.’ Then they will return to me, and I will do as I did before. When I look toward al-Jabbār, Mighty and Majestic, I will fall in prostration, prostrating as I did the first time, and similar praise and glorification will be opened for me. Then it will be said: ‘Ask and you will be given. Intercede and your intercession will be accepted.’ I will say: ‘My Lord, let the descendants of Adam not be burned in the Fire today.’ He will say: ‘Go. Whoever you find with the weight of an atom of faith in his heart, bring him out.’ They will bring out a number known only to Allah, Mighty and Majestic, while most will remain. Then Adam will be given permission to intercede, and he will intercede for ten million. Then the angels and prophets will be permitted to intercede, and they will intercede, until even a believer will intercede for more people than Rabīʿah and Muḍar.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الآجري في الشريعة (809)."},{"num":883,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: حَدَّثَنِي نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنِّي لَقَائِمٌ أَنْتَظِرُ أُمَّتِي تَعْبُرُ عَلَى الصِّرَاطِ، إِذْ جَاءَنِي عِيسَى، فَقَالَ: هَذِهِ الْأَنْبِيَاءُ قَدْ جَاءَتْكَ يَا مُحَمَّدُ يَسْأَلُونَ أَوْ قَالَ: يَجْتَمِعُونَ إِلَيْكَ، وَيَدْعُونَ اللَّهَ عَزَّ وَجَلَّ أَنْ يُفَرِّقَ جَمْعَ الْأُمَمِ إِلَى حَيْثُ يَشَاءُ اللَّهُ لِغَمِّ مَا هُمْ فِيهِ، فالْخَلْقُ مُلْجَمُونَ فِي الْعَرَقِ، فأَمَّا الْمُؤْمِنُ فَهُوَ عَلَيْهِ كَالزَّكْمَةِ، وَأَمَّا الْكَافِرُ فَيَتَغَشَّاهُ الْمَوْتُ قَالَ: قَالَ عِيسَى، انْتَظِرْ حَتَّى أَرْجِعَ إِلَيْكَ قَالَ: فَذَهَبَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى قَامَ تَحْتَ الْعَرْشِ، فَلَقِيَ مَا لَمْ يَلْقَ مَلَكٌ مُصْطَفًى، وَلَا نَبِيٌّ مُرْسَلٌ، فَأَوْحَى اللَّهُ عَزَّ وَجَلَّ إِلَى جِبْرِيلَ: اذْهَبْ إِلَى مُحَمَّدٍ، فَقُلْ لَهُ ارْفَعْ رَأْسَكَ، سَلْ تُعْطَ، وَاشْفَعْ تُشَفَّعْ قَالَ:فَشُفِّعْتُ فِي أُمَّتِي أَنْ أُخْرِجَ مِنْ كُلِّ تِسْعَةٍ وَتِسْعِينَ إِنْسَانًا، وَاحِدًا قَالَ:فَمَا زِلْتُ أَتَرَدَّدُ عَلَى رَبِّي، فَلَا أَقُومُ مَقَامًا إِلَّا شُفِّعْتُ، حَتَّى أَعْطَانِي اللَّهُ عَزَّ وَجَلَّ مِنْ ذَلِكَ أَنْ قَالَ: يَا مُحَمَّدُ، أَدْخِلْ مِنْ أُمَّتِكَ مِنْ خَلْقِ اللَّهِ عَزَّ وَجَلَّ مَنْ شَهِدَ أَنَّهُ لَا إِلَهَ إِلَّا اللَّهُ يَوْمًا وَاحِدًا مُخْلِصًا، وَمَاتَ عَلَى ذَلِكَ."],"takhrij":"حسن: رواه الإمام أحمد (12824) عن يونس بن محمد، حدّثنا حرب بن ميمون أبو الخطّاب الأنصاريّ، عن النّضر بن أنس، عن أنس، فذكره.","grade":"حسن","chapter_ar":"باب شفاعة النبي ﷺ لأهل الموقف","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (12824) and Ibn Khuzaymah in Kitāb al-Tawḥīd (488).","chapter_en":"The Prophet’s ﷺ Intercession for the People at the Standing","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":3,"content":{"translation":{"en":["Anas, may Allah be pleased with him, said: The Prophet of Allah ﷺ told me: “I will be standing, waiting for my Ummah to cross the Ṣirāṭ, when Jesus will come to me and say: ‘These prophets have come to you, O Muḥammad, asking you—or he said: gathering around you—and supplicating to Allah, Mighty and Majestic, to separate the assembled nations as He wills because of the anguish they are experiencing. The creation will be bridled in sweat. As for the believer, it will affect him like a cold, while the disbeliever will be overwhelmed by death.’ I will say: ‘O Jesus, wait until I return to you.’ Then the Prophet of Allah ﷺ will go until he stands beneath the Throne, where he will encounter that which no chosen angel and no sent prophet has encountered. Allah, Mighty and Majestic, will reveal to Jibrīl: ‘Go to Muḥammad and tell him: Raise your head. Ask and you will be given. Intercede and your intercession will be accepted.’ I will intercede for my Ummah so that one person out of every ninety-nine is brought out. I will continue returning to my Lord, Mighty and Majestic, and will not stand at any station except that I intercede, until Allah, Mighty and Majestic, grants me such that He says: ‘O Muḥammad, admit from your Ummah, from among Allah’s creation, whoever sincerely testified for even one day that there is no deity worthy of worship except Allah and died upon that.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (12824)، وابن خزيمة في كتاب التوحيد (488)."},{"num":884,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ (فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ): قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أُعْطِيتُ خَمْسًا لَمْ يُعْطَهُنَّ أَحَدٌ مِنَ الْأَنْبِيَاءِ قَبْلِي. فَذَكَرَ مِنْهَا: وَأُعْطِيتُ الشَّفَاعَةَ."],"takhrij":"متفق عليه: رواه البخاريّ في الصّلاة (438)، ومسلم في المساجد (521) كلاهما من حديث هُشيم، عن سيار، وهو أبو الحكم، ، قال: حدّثنا يزيد الفقير، عن جابر بن عبدالله، فذكره.","grade":"متفق عليه","chapter_ar":"باب شفاعة النبي ﷺ لأهل الموقف","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (438) and Muslim (521).","chapter_en":"The Prophet’s ﷺ Intercession for the People at the Standing","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":3,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh may Allah be pleased with them reported that the Messenger of Allah ﷺ said: “I have been given five things which no prophet before me was given.” Among them he mentioned: “And I have been given intercession.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (438)، ومسلم (521)."},{"num":885,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ قَالَ (فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ): قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أُوتِيتُ خَمْسًا لَمْ يُؤْتَهُنَّ نَبِيٌّ كَانَ قَبْلِي. فَذَكَرَ مِنْهَا أَنَّهُ قِيلَ لَهُ: سَلْ تُعْطَهْ، فَاخْتَبَأْتُهَا شَفَاعَةً لِأُمَّتِي، وَهِيَ نَائِلَةٌ مِنْكُمْ إِنْ شَاءَ اللَّهُ، مَنْ لَقِيَ اللَّهَ لَا يُشْرِكُ بِهِ شَيْئًا."],"takhrij":"حسن: رواه أحمد (21299) عن يعقوب، حدّثنا أبي، عن ابن إسحاق، حدّثني سليمان الأعمش، عن مجاهد بن جبر أبي الحجّاج، عن عبيد بن عمير اللّيثيّ، عن أبي ذر، فذكره.","grade":"حسن","chapter_ar":"باب شفاعة النبي ﷺ لأهل الموقف","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Aḥmad (21299).","chapter_en":"The Prophet’s ﷺ Intercession for the People at the Standing","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":3,"content":{"translation":{"en":["Abū Dharr may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “I was given five things which no prophet before me was given.” Among them he mentioned that it was said to him: “Ask, and you will be given.” He said: “So I reserved it as intercession for my Ummah. It will reach—if Allah wills—whoever among you meets Allah without associating anything with Him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (21299)."},{"num":886,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ: أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَامَ غَزْوَةِ تَبُوكَ قَامَ مِنَ اللَّيْلِ يُصَلِّي، فَاجْتَمَعَ وَرَاءَهُ رِجَالٌ مِنْ أَصْحَابِهِ يَحْرُسُونَهُ، حَتَّى إِذَا صَلَّى وَانْصَرَفَ إِلَيْهِمْ، فَقَالَ لَهُمْ: لَقَدْ أُعْطِيتُ اللَّيْلَةَ خَمْسًا، مَا أُعْطِيَهُنَّ أَحَدٌ قَبْلِي. فَذَكَرَ الْحَدِيثَ بِطُولِهِ: وَالْخَامِسَةُ، هِيَ مَا هِيَ، قِيلَ لِي سَلْ، فَإِنَّ كُلَّ نَبِيٍّ قَدْ سَأَلَ، فَأَخَّرْتُ مَسْأَلَتِي إِلَى يَوْمِ الْقِيَامَةِ، فَهِيَ لَكُمْ وَلِمَنْ شَهِدَ أَنْ لَا إِلَهَ إِلَّا اللَّهُ."],"takhrij":"حسن: رواه الإمام أحمد (7068) عن قتيبة بن سعيد، حدّثنا بكر بن مُضر، عن ابن الهاد، عن عمرو بن شعيب، عن أبيه، عن جدّه، فذكره.","grade":"حسن","chapter_ar":"باب شفاعة النبي ﷺ لأهل الموقف","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (7068).","chapter_en":"The Prophet’s ﷺ Intercession for the People at the Standing","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":3,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr, may Allah be pleased with them, reported: During the year of the expedition of Tabūk, the Messenger of Allah ﷺ stood during the night in prayer, while men from among his Companions gathered behind him to guard him. When he had finished praying and turned toward them, he said: “Tonight I have been given five things which no one before me was given.” He mentioned the lengthy ḥadīth, including: “And the fifth is what it is: it was said to me: ‘Ask, for every prophet has asked.’ So I postponed my request until the Day of Resurrection. It is for you and for whoever testifies that there is no deity worthy of worship except Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (7068)."},{"num":887,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَكْرٍ الصِّدِّيقِ قَالَ: أَصْبَحَ رَسُولُ اللّَهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ فَصَلَّى الْغَدَاةَ، ثُمَّ جَلَسَ حَتَّى إِذَا كَانَ مِنَ الضُّحَى ضَحِكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ جَلَسَ مَكَانَهُ حَتَّى صَلَّى الْأُولَى وَالْعَصْرَ وَالْمَغْرِبَ كُلُّ ذَلِكَ لَا يَتَكَلَّمُ حَتَّى صَلَّى الْعِشَاءَ الْآخِرَةَ، ثُمَّ قَامَ إِلَى أَهْلِهِ، فَقَالَ النَّاسُ لِأَبِي بَكْرٍ: أَلَا تَسْأَلُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا شَأْنُهُ؟ صَنَعَ الْيَوْمَ شَيْئًا لَمْ يَصْنَعْهُ قَطُّ، قَالَ: فَسَأَلَهُ، فَقَالَ: نَعَمْ، عُرِضَ عَلَيَّ مَا هُوَ كَائِنٌ مِنْ أَمْرِ الدُّنْيَا، وَأَمْرِ الْآخِرَةِ، فَجُمِعَ الْأَوَّلُونَ وَالْآخِرُونَ بِصَعِيدٍ وَاحِدٍ، فَفَظِعَ النَّاسُ بِذَلِكَ، حَتَّى انْطَلَقُوا إِلَى آدَمَ عَلَيْهِ السَّلَام، وَالْعَرَقُ يَكَادُ يُلْجِمُهُمْ، فَقَالُوا: يَا آدَمُ، أَنْتَ أَبُو الْبَشَرِ، وَأَنْتَ اصْطَفَاكَ اللَّهُ عَزَّ وَجَلَّ، اشْفَعْ لَنَا إِلَى رَبِّكَ، قَالَ: لَقَدْ لَقِيتُ مِثْلَ الَّذِي لَقِيتُمْ، انْطَلِقُوا إِلَى أَبِيكُمْ بَعْدَ أَبِيكُمْ، إِلَى نُوحٍ: ﴿إِنَّ اللَّهَ اصْطَفَى آدَمَ وَنُوحًا وَآلَ إِبْرَاهِيمَ وَآلَ عِمْرَانَ عَلَى الْعَالَمِينَ﴾ [سورة آل عمران: 33]، قَالَ: فَيَنْطَلِقُونَ إِلَى نُوحٍ عَلَيْهِ السَّلَام، فَيَقُولُونَ: اشْفَعْ لَنَا إِلَى رَبِّكَ، فَأَنْتَ اصْطَفَاكَ اللَّهُ، وَاسْتَجَابَ لَكَ فِي دُعَائِكَ، وَلَمْ يَدَعْ عَلَى الْأَرْضِ مِنَ الْكَافِرِينَ دَيَّارًا، فَيَقُولُ: لَيْسَ ذَاكُمْ عِنْدِي، انْطَلِقُوا إِلَى إِبْرَاهِيمَ عَلَيْهِ السَّلَام، فَإِنَّ اللَّهَ عَزَّ وَجَلَّ اتَّخَذَهُ خَلِيلًا، فَيَنْطَلِقُونَ إِلَى إِبْرَاهِيمَ، فَيَقُولُ: لَيْسَ ذَاكُمْ عِنْدِي، وَلَكِنْ انْطَلِقُوا إِلَى مُوسَى عَلَيْهِ السَّلَام، فَإِنَّ اللَّهَ عَزَّ وَجَلَّ كَلَّمَهُ تَكْلِيمًا، فَيَقُولُ مُوسَى عَلَيْهِ السَّلَام: لَيْسَ ذَاكُمْ عِنْدِي، وَلَكِنْ انْطَلِقُوا إِلَى عِيسَى ابْنِ مَرْيَمَ، فَإِنَّهُ يُبْرِئُ الْأَكْمَهَ وَالْأَبْرَصَ وَيُحْيِي الْمَوْتَى، فَيَقُولُ عِيسَى عَلَيْهِ السَّلَام: لَيْسَ ذَاكُمْ عِنْدِي، وَلَكِنْ انْطَلِقُوا إِلَى سَيِّدِ وَلَدِ آدَمَ، فَإِنَّهُ أَوَّلُ مَنْ تَنْشَقُّ عَنْهُ الْأَرْضُ يَوْمَ الْقِيَامَةِ، انْطَلِقُوا إِلَى مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَيَشْفَعَ لَكُمْ إِلَى رَبِّكُمْ عَزَّ وَجَلَّ، قَالَ: فَيَنْطَلِقُ، فَيَأْتِي جِبْرِيلُ عَلَيْهِ السَّلَام رَبَّهُ، فَيَقُولُ اللَّهُ عَزَّ وَجَلَّ: ائْذَنْ لَهُ، وَبَشِّرْهُ بِالْجَنَّةِ، قَالَ: فَيَنْطَلِقُ بِهِ جِبْرِيلُ، فَيَخِرُّ سَاجِدًا قَدْرَ جُمُعَةٍ، وَيَقُولُ اللَّهُ عَزَّ وَجَلَّ: ارْفَعْ رَأْسَكَ يَا مُحَمَّدُ، وَقُلْ يُسْمَعْ، وَاشْفَعْ تُشَفَّعْ، قَالَ: فَيَرْفَعُ رَأْسَهُ، فَإِذَا نَظَرَ إِلَى رَبِّهِ عَزَّ وَجَلَّ، خَرَّ سَاجِدًا قَدْرَ جُمُعَةٍ أُخْرَى، فَيَقُولُ اللَّهُ عَزَّ وَجَلَّ، ارْفَعْ رَأْسَكَ، وَقُلْ يُسْمَعْ، وَاشْفَعْ تُشَفَّعْ، قَالَ: فَيَذْهَبُ لِيَقَعَ سَاجِدًا، فَيَأْخُذُ جِبْرِيلُ عَلَيْهِ السَّلَام بِضَبْعَيْهِ، فَيَفْتَحُ اللَّهُ عَزَّ وَجَلَّ عَلَيْهِ مِنَ الدُّعَاءِ شَيْئًا لَمْ يَفْتَحْهُ عَلَى بَشَرٍ قَطُّ، فَيَقُولُ: أَيْ رَبِّ خَلَقْتَنِي، سَيِّدَ وَلَدِ آدَمَ، وَلَا فَخْرَ، وَأَوَّلَ مَنْ تَنْشَقُّ عَنْهُ الْأَرْضُ يَوْمَ الْقِيَامَةِ، وَلَا فَخْرَ، حَتَّى إِنَّهُ لَيَرِدُ عَلَيَّ الْحَوْضَ أَكْثَرُ مِمَّا بَيْنَ صَنْعَاءَ، وَأَيْلَةَ، ثُمَّ يُقَالُ: ادْعُوا الصِّدِّيقِينَ فَيَشْفَعُونَ، ثُمَّ يُقَالُ: ادْعُوا الْأَنْبِيَاءَ، قَالَ: فَيَجِيءُ النَّبِيُّ وَمَعَهُ الْعِصَابَةُ، وَالنَّبِيُّ وَمَعَهُ الْخَمْسَةُ وَالسِّتَّةُ، وَالنَّبِيُّ وَلَيْسَ مَعَهُ أَحَدٌ، ثُمَّ يُقَالُ: ادْعُوا الشُّهَدَاءَ فَيَشْفَعُونَ لِمَنْ أَرَادُوا، وَقَالَ: فَإِذَا فَعَلَتْ الشُّهَدَاءُ ذَلِكَ، قَالَ: يَقُولُ اللَّهُ عَزَّ وَجَلَّ: أَنَا أَرْحَمُ الرَّاحِمِينَ، أَدْخِلُوا جَنَّتِي، مَنْ كَانَ لَا يُشْرِكُ بِي شَيْئًا، قَالَ: فَيَدْخُلُونَ الْجَنَّةَ، قَالَ: ثُمَّ يَقُولُ اللَّهُ عَزَّ وَجَلَّ: انْظُرُوا فِي النَّارِ، هَلْ تَلْقَوْنَ مِنْ أَحَدٍ عَمِلَ خَيْرًا قَطُّ؟ قَالَ: فَيَجِدُونَ فِي النَّارِ رَجُلًا، فَيَقُولُ لَهُ: هَلْ عَمِلْتَ خَيْرًا قَطُّ؟ فَيَقُولُ: لَا، غَيْرَ أَنِّي كُنْتُ أُسَامِحُ النَّاسَ فِي الْبَيْعِ وَالشِّرَاءِ، فَيَقُولُ اللَّهُ عَزَّ وَجَلَّ: أَسْمِحُوا لِعَبْدِي كَإِسْمَاحِهِ إِلَى عَبِيدِي.","ثُمَّ يُخْرِجُونَ مِنَ النَّارِ رَجُلًا، فَيَقُولُ لَهُ: هَلْ عَمِلْتَ خَيْرًا قَطُّ؟ فَيَقُولُ: لَا، غَيْرَ أَنِّي قَدْ أَمَرْتُ وَلَدِي إِذَا مِتُّ فَأَحْرِقُونِي بِالنَّارِ، ثُمَّ اطْحَنُونِي، حَتَّى إِذَا كُنْتُ مِثْلَ الْكُحْلِ، فَاذْهَبُوا بِي إِلَى الْبَحْرِ، فَاذْرُونِي فِي الرِّيحِ، فَوَاللَّهِ لَا يَقْدِرُ عَلَيَّ رَبُّ الْعَالَمِينَ أَبَدًا، فَقَالَ اللَّهُ عَزَّ وَجَلَّ: لِمَ فَعَلْتَ ذَلِكَ؟ قَالَ: مِنْ مَخَافَتِكَ، قَالَ: فَيَقُولُ اللَّهُ عَزَّ وَجَلَّ انْظُرْ إِلَى مُلْكِ أَعْظَمِ مَلِكٍ، فَإِنَّ لَكَ مِثْلَهُ وَعَشَرَةَ أَمْثَالِهِ، قَالَ: فَيَقُولُ: لِمَ تَسْخَرُ بِي وَأَنْتَ الْمَلِكُ؟ قَالَ: وَذَاكَ الَّذِي ضَحِكْتُ مِنْهُ مِنَ الضُّحَى."],"takhrij":"حسن: رواه الإمام أحمد (15)، وأبو يعلى (56)، والبزّار- كشف الأستار (3465)، كلّهم من طريق النّضر بن شُميل، قال: حدّثني أبو نَعامة، قال: حدّثني أبو هُنيد البراء بن نوفل، عن والان العدَويّ، عن حذيفة، عن أبي بكر الصّديق، فذكر مثله، واللّفظ لأحمد.","grade":"حسن","chapter_ar":"باب شفاعة النبي ﷺ لأهل الموقف","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Aḥmad (15), Abū Yaʿlā (56), and al-Bazzār (3465).","chapter_en":"The Prophet’s ﷺ Intercession for the People at the Standing","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":3,"content":{"translation":{"en":["Abū Bakr al-Ṣiddīq, may Allah be pleased with him, reported: One morning the Messenger of Allah ﷺ performed the Fajr prayer and then remained seated. When the forenoon came, the Messenger of Allah ﷺ laughed. He remained in his place until he prayed Ẓuhr, ʿAṣr, and Maghrib, without speaking throughout that time. Then he prayed the final ʿIshāʾ prayer and went to his family. The people said to Abū Bakr: “Will you not ask the Messenger of Allah ﷺ what happened to him? Today he did something he had never done before.” So he asked him, and the Prophet ﷺ said: “Yes. I was shown what will occur concerning the affairs of this world and the Hereafter. The first and the last were gathered on a single plain, and the people were terrified by that until they went to Adam peace be upon him, while sweat was nearly reaching their mouths. They said: ‘O Adam, you are the father of mankind, and Allah, Mighty and Majestic, chose you. Intercede for us with your Lord.’ He will say: ‘I have encountered what you have encountered. Go to your father after your father—to Noah: “Indeed, Allah chose Adam and Noah and the family of Abraham and the family of ʿImrān over the worlds.”’ [Āl ʿImrān 3:33] They will go to Noah, peace be upon him, and say: ‘Intercede for us with your Lord. Allah chose you and answered your supplication, and He did not leave upon the earth a single dwelling disbeliever.’ He will say: ‘That is not for me. Go to Abraham, peace be upon him,, for Allah, Mighty and Majestic, took him as a close friend.’ They will go to Abraham, and he will say: ‘That is not for me. Rather, go to Moses, peace be upon him,, for Allah, Mighty and Majestic, spoke directly to him.’ Moses peace be upon him will say: ‘That is not for me. Rather, go to Jesus son of Mary, for he cured the blind from birth and the leper and brought the dead to life.’ Jesus will say: ‘That is not for me. Rather, go to the leader of the children of Adam. He will be the first for whom the earth will split open on the Day of Resurrection. Go to Muḥammad ﷺ, and he will intercede for you with your Lord, Mighty and Majestic.’ Then he will proceed, and Jibrīl, peace be upon him, will come to his Lord. Allah, Mighty and Majestic, will say: ‘Admit him and give him glad tidings of Paradise.’ Jibrīl will take him, and he will fall prostrate for the duration of a week. Allah, Mighty and Majestic, will say: ‘Raise your head, O Muḥammad. Speak and you will be heard; intercede and your intercession will be accepted.’ He will raise his head, but when he looks toward his Lord, Mighty and Majestic, he will fall prostrate for another week. Allah, Mighty and Majestic, will say: ‘Raise your head. Speak and you will be heard; intercede and your intercession will be accepted.’ When he is about to fall prostrate again, Jibrīl, peace be upon him, will take him by his upper arms, and Allah, Mighty and Majestic, will open for him words of supplication which He had never opened for any human being before. He will say: ‘My Lord, You created me as the leader of the children of Adam—and there is no boasting—and the first for whom the earth will split open on the Day of Resurrection—and there is no boasting. Indeed, more people will come to my Basin than the distance between Ṣanʿāʾ and Aylah.’ Then it will be said: ‘Call the truthful ones.’ They will intercede. Then it will be said: ‘Call the prophets.’ A prophet will come accompanied by a group; another prophet will come with five or six people; and another prophet will come with no one. Then it will be said: ‘Call the martyrs.’ They will intercede for whomever they wish. When the martyrs have done that, Allah, Mighty and Majestic, will say: ‘I am the Most Merciful of those who show mercy. Admit into My Paradise everyone who did not associate anything with Me.’ So they will enter Paradise. Then Allah, Mighty and Majestic, will say: ‘Look into the Fire. Do you find anyone who ever performed any good deed?’ They will find a man in the Fire and ask him: ‘Did you ever perform any good deed?’ He will reply: ‘No, except that I used to be lenient with people in buying and selling.’ Allah, Mighty and Majestic, will say: ‘Show leniency to My servant just as he used to show leniency to My servants.’ Then they will bring another man out of the Fire and ask him:","‘Did you ever perform any good deed?’ He will reply: ‘No, except that I instructed my children: when I die, burn me with fire, then grind me until I become like kohl, then take me to the sea and scatter me in the wind. By Allah, the Lord of the worlds will never be able to overpower me.’ Allah, Mighty and Majestic, will say: ‘Why did you do that?’ He will reply: ‘Out of fear of You.’ Allah, Mighty and Majestic, will say: ‘Look at the kingdom of the greatest king. You shall have its like and ten times as much.’ He will say: ‘Why are You making fun of me when You are the King?’ The Prophet ﷺ said: ‘That is what I laughed about in the forenoon.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (15)، وأبو يعلى (56)، والبزار (3465)."},{"num":888,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: تَلَا قَوْلَ اللَّهِ عَزَّ وَجَلَّ فِي إِبْرَاهِيمَ: ﴿رَبِّ إِنَّهُنَّ أَضْلَلْنَ كَثِيرًا مِنَ النَّاسِ فَمَنْ تَبِعَنِي فَإِنَّهُ مِنِّي﴾ [سورة إبراهيم: 36]، فَرَفَعَ يَدَيْهِ وَقَالَ: اللَّهُمَّ أُمَّتِي أُمَّتِي وَبَكَى فَقَالَ اللَّهُ عَزَّ وَجَلَّ: يَا جِبْرِيلُ، اذْهَبْ إِلَى مُحَمَّدٍ وَرَبُّكَ أَعْلَمُ، فَسَلْهُ مَا يُبْكِيكَ؟ فَأَتَاهُ جِبْرِيلُ عَلَيْهِ السَّلَامُ، فَسَأَلَهُ، فَأَخْبَرَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمَا قَالَ، وَهُوَ أَعْلَمُ، فَقَالَ اللَّهُ: يَا جِبْرِيلُ، اذْهَبْ إِلَى مُحَمَّدٍ، فَقُلْ: إِنَّا سَنُرْضِيكَ فِي أُمَّتِكَ وَلَا نَسُوؤُكَ."],"takhrij":"صحيح: رواه مسلم في الإيمان (202) عن يونس بن عبدالأعلى الصّدفيّ، أخبرنا ابنُ وهب، قال: أخبرني عمرو بن الحارث، أن بكر بن سوادة حدَّثه عن عبدالرحمن بن جبير، عن عبدالله بن عمرو، فذكره.","grade":"صحيح","chapter_ar":"باب شفاعة النبي ﷺ لأهل الموقف","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (202).","chapter_en":"The Prophet’s ﷺ Intercession for the People at the Standing","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":3,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ, may Allah be pleased with them, reported: The Prophet ﷺ recited the statement of Allah, Mighty and Majestic, concerning Abraham, peace be upon him: “My Lord, indeed they have led many people astray. So whoever follows me is of me, and whoever disobeys me—then indeed You are Most Forgiving, Most Merciful.” [Sūrat Ibrāhīm 14:36] Then he raised his hands and said: “O Allah, my Ummah! My Ummah!” And he wept. Allah, Mighty and Majestic, said: “O Jibrīl, go to Muḥammad—and your Lord knows best—and ask him what makes him weep.” Jibrīl, peace be upon him, came to him and asked him, and the Messenger of Allah ﷺ informed him of what he had said—though Allah knows best. Then Allah said: “O Jibrīl, go to Muḥammad and say: ‘Indeed, We will please you concerning your Ummah and will not distress you.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (202)."},{"num":889,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا يَزَالُ الرَّجُلُ يَسْأَلُ النَّاسَ حَتَّى يَأْتِيَ يَوْمَ الْقِيَامَةِ لَيْسَ فِي وَجْهِهِ مُزْعَةُ لَحْمٍ.","وَقَالَ: إِنَّ الشَّمْسَ تَدْنُو يَوْمَ الْقِيَامَةِ حَتَّى يَبْلُغَ الْعَرَقُ نِصْفَ الْأُذُنِ فَبَيْنَا هُمْ كَذَلِكَ اسْتَغَاثُوا بِآدَمَ، ثُمَّ بِمُوسَى، ثُمَّ بِمُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ.","وَزَادَ فِي رِوَايَةِ: فَيَشْفَعُ لِيُقْضَى بَيْنَ الْخَلْقِ فَيَمْشِي حَتَّى يَأْخُذَ بِحَلْقَةِ الْبَابِ، فَيَوْمَئِذٍ يَبْعَثُهُ اللَّهُ مَقَامًا مَحْمُودًا يَحْمَدُهُ أَهْلُ الْجَمْعِ كُلُّهُمْ."],"takhrij":"صحيح: رواه البخاريّ في الزّكاة (1474، 1475) عن يحيى بن بكير، حدّثنا اللّيث، عن عبيد الله بن أبي جعفر، قال: سمعت حمزة بن عبدالله بن عمر، قال: سمعت عبد الله بن عمر، قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء أن المقام المحمود هو الشفاعة","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (1474, 1475).","chapter_en":"What Has Been Reported That the Praised Station Is the Intercession","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":4,"content":{"translation":{"en":["Ibn ʿUmar may Allah be pleased with them reported that the Prophet ﷺ said: “A man will continue asking people until he comes on the Day of Resurrection with no piece of flesh remaining on his face.” He also said:","“The sun will draw near on the Day of Resurrection until the sweat reaches halfway up the ear. While they are in that state, they will seek help from Adam, then Moses, then Muḥammad ﷺ. He will intercede so that judgment may be passed among creation.","He will proceed until he takes hold of the ring of the gate. On that Day Allah will raise him to the Praised Station, for which all the gathered people will praise him.”"]},"intro":{"ar":["إن الله تبارك وتعالى وعد نبيه ﷺ بهذا المقام في قوله عز وجل:","﴿عَسَىٰ أَنْ يَبْعَثَكَ رَبُّكَ مَقَامًا مَحْمُودًا﴾","[الإسراء: ٧٩]","قال أهل العلم:","«عسى من الله واجب»، لا على الشك والارتياب."],"en":["Allah, Blessed and Exalted, promised His Prophet ﷺ this station in His statement, Mighty and Majestic:","“It may be that your Lord will raise you to a Praised Station.”","[Sūrat al-Isrāʾ 17:79]","The people of knowledge said:","“ʿAsā—‘it may be’—when stated by Allah indicates certainty,” not doubt or uncertainty."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (1474، 1475)."},{"num":890,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ: إِنَّ النَّاسَ يَصِيرُونَ يَوْمَ الْقِيَامَةِ جُثًا كُلُّ أُمَّةٍ تَتْبَعُ نَبِيَّهَا يَقُولُونَ: يَا فُلَانُ، اشْفَعْ يَا فُلَانُ، اشْفَعْ حَتَّى تَنْتَهِيَ الشَّفَاعَةُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَذَلِكَ يَوْمَ يَبْعَثُهُ اللَّهُ الْمَقَامَ الْمَحْمُودَ."],"takhrij":"صحيح: رواه البخاريّ في التفسير (4718) عن إسماعيل بن أبان، حدّثنا أبو الأحوص، عن آدم بن علي، قال: سمعت ابن عمر يقول (فذكره).","grade":"صحيح","chapter_ar":"باب ما جاء أن المقام المحمود هو الشفاعة","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (4718).","chapter_en":"What Has Been Reported That the Praised Station Is the Intercession","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":4,"content":{"translation":{"en":["Ibn ʿUmar, may Allah be pleased with them, said: “On the Day of Resurrection, the people will become kneeling groups, every nation following its prophet and saying: ‘O so-and-so, intercede!’ Until the intercession reaches the Prophet ﷺ. That is the Day on which Allah will raise him to the Praised Station.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (4718)."},{"num":891,"demo":false,"sanad":"","matn":["عَنْ كَعْبِ بْنِ مَالِكٍ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يُبْعَثُ النَّاسُ يَوْمَ الْقِيَامَةِ، فَأَكُونُ أَنَا وَأُمَّتِي عَلَى تَلٍّ، وَيَكْسُونِي رَبِّي تَبَارَكَ وَتَعَالَى حُلَّةً خَضْرَاءَ، ثُمَّ يُؤْذَنُ لِي فَأَقُولُ مَا شَاءَ اللَّهُ أَنْ أَقُولَ، فَذَاكَ الْمَقَامُ الْمَحْمُودُ."],"takhrij":"صحيح: رواه الإمام أحمد (15783)، والطّبرانيّ في الكبير (19/ح 142)، وفي الأوسط (8797)، وابن جرير في تفسيره (4781).","grade":"صحيح","chapter_ar":"باب ما جاء أن المقام المحمود هو الشفاعة","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Aḥmad (15783), al-Ṭabarānī in al-Muʿjam al-Kabīr (19/72) and al-Muʿjam al-Awsaṭ (8797), and Ibn Jarīr in his Tafsīr (15/48); authenticated by Ibn Ḥibbān (6479) and al-Ḥākim (3383).","chapter_en":"What Has Been Reported That the Praised Station Is the Intercession","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":4,"content":{"translation":{"en":["Kaʿb ibn Mālik may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “The people will be resurrected on the Day of Resurrection, and I and my Ummah will be upon a hill. My Lord, Blessed and Exalted, will clothe me in a green garment. Then permission will be granted to me, and I will say whatever Allah wills me to say. That is the Praised Station.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (15783)، والطبراني في الكبير (19/ح 142)، وفي الأوسط (8797)، وابن جرير في تفسيره (4781)، وصححه ابن حبان (6479)، والحاكم (3383)."},{"num":892,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَآَلِهِ وَسَلَّمَ، قَالَ: تُمَدُّ الأَرْضُ يَوْمَ الْقِيَامَةِ مَدًّا لِعَظَمَةِ الرَّحْمَنِ، ثُمَّ لا يَكُونُ لِبَشَرٍ مَنْ بَنِي آدَمَ إِلا مَوْضِعَ قَدَمَيْهِ، ثُمَّ أُدْعَى أَوَّلَ النَّاسِ فَأَخِرُّ سَاجِدًا، ثُمَّ يُؤْذَنُ لِي فَأَقُومُ فَأَقُولُ: يَا رَبِّ أَخْبَرَنِي هَذَا لِجِبْرِيلَ وَهُوَ عَنْ يَمِينِ الرَّحْمَنِ، وَاللَّهِ مَا رَآهُ جِبْرِيلُ قَبْلَهَا قَطُّ أَنَّكَ أَرْسَلْتَهُ إِلَيَّ، قَالَ: وَجِبْرِيلُ سَاكِتٌ لا يَتَكَلَّمُ، حَتَّى يَقُولَ اللَّهُ: صَدَقَ، ثُمَّ يُؤْذَنُ لِي فِي الشَّفَاعَةِ، فَأَقُولُ: يَا رَبِّ عِبَادُكَ عَبَدُوكَ فِي أَطْرَافِ الأَرْضِ، فَذَلِكَ الْمَقَامُ الْمَحْمُودُ."],"takhrij":"صحيح: رواه الحاكم (8701) عن إسماعيل بن محمد بن الفضل الشعرانيّ، ثنا جدي، ثنا إبراهيم بن حمزة الزّبيديّ، ثنا إبراهيم بن سعد، عن ابن شهاب، عن علي بن حسين، عن جابر، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء أن المقام المحمود هو الشفاعة","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Ḥākim (8701).","chapter_en":"What Has Been Reported That the Praised Station Is the Intercession","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":4,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh may Allah be pleased with them reported that the Messenger of Allah ﷺ said: “The earth will be stretched out on the Day of Resurrection because of the greatness of al-Raḥmān. Then no human being from among the children of Adam will have more than the place occupied by his two feet. Then I will be the first of the people to be called, and I will fall in prostration. Then permission will be granted to me, and I will say: ‘My Lord, this one’—meaning Jibrīl, who will be on the right of al-Raḥmān, and by Allah, Jibrīl had never seen Him before that—‘informed me that You sent him to me.’ Jibrīl will remain silent and will not speak until Allah says: ‘He has spoken the truth.’ Then permission will be granted to me to intercede, and I will say: ‘My Lord, Your servants worshipped You throughout the farthest regions of the earth.’ That is the Praised Station.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الحاكم (8701)."},{"num":893,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّهُ قَالَ: قِيلَ يَا رَسُولَ اللَّهِ، مَنْ أَسْعَدُ النَّاسِ بِشَفَاعَتِكَ يَوْمَ الْقِيَامَةِ؟ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَقَدْ ظَنَنْتُ يَا أَبَا هُرَيْرَةَ أَنْ لَا يَسْأَلَنِي عَنْ هَذَا الْحَدِيثِ أَحَدٌ أَوَّلُ مِنْكَ لِمَا رَأَيْتُ مِنْ حِرْصِكَ عَلَى الْحَدِيثِ، أَسْعَدُ النَّاسِ بِشَفَاعَتِي يَوْمَ الْقِيَامَةِ، مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ خَالِصًا مِنْ قَلْبِهِ أَوْ نَفْسِهِ."],"takhrij":"صحيح: رواه البخاريّ في العلم (99) عن عبدالعزيز بن عبدالله، قال: حدّثني سليمان بن عمرو بن أبي عمرو، عن سعيد بن أبي سعيد المقبريّ، عن أبي هريرة، فذكر مثله.","grade":"صحيح","chapter_ar":"باب شفاعة النبي ﷺ لكل من قال لا إله إلا الله ولم يشرك بالله ولو عمل الكبائر واستحق النار","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (99).","chapter_en":"The Prophet’s ﷺ Intercession for Everyone Who Said “There Is No Deity Worthy of Worship Except Allah” and Did Not Associate Anything With Allah, Even if He Committed Major Sins and Deserved the Fire","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":5,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported: It was asked: “O Messenger of Allah, who will be the happiest of people to receive your intercession on the Day of Resurrection?” The Messenger of Allah ﷺ replied: “I thought, O Abū Hurayrah, that no one would ask me about this ḥadīth before you, because of what I have seen of your eagerness for ḥadīth. The happiest of people to receive my intercession on the Day of Resurrection will be the one who says: ‘There is no deity worthy of worship except Allah,’ sincerely from his heart or his soul.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (99)."},{"num":894,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ:إِذَا كَانَ يَوْمُ الْقِيَامَةِ شُفِّعْتُ، فَقُلْتُ: يَا رَبِّ أَدْخِلِ الْجَنَّةَ مَنْ كَانَ فِي قَلْبِهِ خَرْدَلَةٌ، فَيَدْخُلُونَ، ثُمَّ أَقُولُ: أَدْخِلِ الْجَنَّةَ مَنْ كَانَ فِي قَلْبِهِ أَدْنَى شَيْءٍ.","فَقَالَ أَنَسٌ: كَأَنِّي أَنْظُرُ إِلَى أَصَابِعِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه البخاريّ في التوحيد (7509) عن يوسف بن راشد، حدّثنا أحمد بن عبدالله، حدّثنا أبو بكر بن عياش، عن حُميد، قال: سمعت أنساً، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب شفاعة النبي ﷺ لكل من قال لا إله إلا الله ولم يشرك بالله ولو عمل الكبائر واستحق النار","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (7509).","chapter_en":"The Prophet’s ﷺ Intercession for Everyone Who Said “There Is No Deity Worthy of Worship Except Allah” and Did Not Associate Anything With Allah, Even if He Committed Major Sins and Deserved the Fire","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":5,"content":{"translation":{"en":["Anas, may Allah be pleased with him, said: I heard the Prophet ﷺ say: “On the Day of Resurrection, I will be granted intercession. I will say: ‘My Lord, admit into Paradise whoever has in his heart the weight of a mustard seed.’ So they will enter. Then I will say: ‘Admit into Paradise whoever has in his heart even the slightest amount.’”","Anas said: “It is as though I can see the fingers of the Messenger of Allah ﷺ.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (7509)."},{"num":895,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَخْرُجُ قَوْمٌ مِنَ النَّارِ بَعْدَ مَا مَسَّهُمْ مِنْهَا سَفْعٌ، فَيَدْخُلُونَ الْجَنَّةَ، فَيُسَمِّيهِمْ أَهْلُ الْجَنَّةِ: الْجَهَنَّمِيِّينَ.","وَفِي رِوَايَةِ: لَيُصِيبَنَّ أَقْوَامًا سَفْعٌ مِنَ النَّارِ بِذُنُوبٍ أَصَابُوهَا عُقُوبَةً، ثُمَّ يُدْخِلُهُمُ اللَّهُ الْجَنَّةَ بِفَضْلِ رَحْمَتِهِ، يُقَالُ لَهُمْ: الْجَهَنَّمِيُّونَ."],"takhrij":"صحيح: رواه البخاريّ في الرقاق (6559) عن هدبة بن خالد، حدّثنا همّام، عن قتادة، حدّثنا أنس بن مالك، فذكره.","grade":"صحيح","chapter_ar":"باب شفاعة النبي ﷺ لكل من قال لا إله إلا الله ولم يشرك بالله ولو عمل الكبائر واستحق النار","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (6559). The second wording is also narrated by al-Bukhārī (7450).","chapter_en":"The Prophet’s ﷺ Intercession for Everyone Who Said “There Is No Deity Worthy of Worship Except Allah” and Did Not Associate Anything With Allah, Even if He Committed Major Sins and Deserved the Fire","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":5,"content":{"translation":{"en":["Anas ibn Mālik may Allah be pleased with him reported that the Prophet ﷺ said: “Some people will emerge from the Fire after its scorching has touched them. They will then enter Paradise, and the people of Paradise will call them al-Jahannamiyyūn.” In another narration: “Some people will certainly be touched by the scorching of the Fire because of sins they committed, as punishment. Then Allah will admit them into Paradise by the favor of His mercy, and they will be called al-Jahannamiyyūn.”"]},"buhuth":{"en":["The word:","“safʿ”","comes from safaʿa–yasfaʿu–safʿan, meaning to seize and pull forcefully.","From this is the statement of Allah Most High:","“No! If he does not desist, We will surely seize him by the forelock.”","[Sūrat al-ʿAlaq 96:15]","It is also said:","“The Fire safʿat his face,”","meaning that it changed the color of his skin and blackened it.","These are people of Tawḥīd who committed sins and offenses and were therefore admitted into the Fire. Allah will then admit them into Paradise through His mercy, and these are among those reached by intercession.","As for the people of shirk, there is no intercession for them."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (6559)، والرواية الثانية عند البخاري أيضا (7450)."},{"num":896,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَمَّا أَهْلُ النَّارِ الَّذِينَ هُمْ أَهْلُهَا فَإِنَّهُمْ لَا يَمُوتُونَ فِيهَا وَلَا يَحْيَوْنَ، وَلَكِنْ نَاسٌ أَصَابَتْهُمُ النَّارُ بِذُنُوبِهِمْ، أَوَ قَالَ: بِخَطَايَاهُمْ فَأَمَاتَهُمْ إِمَاتَةً حَتَّى إِذَا كَانُوا فَحْمًا أُذِنَ بِالشَّفَاعَةِ، فَجِيءَ بِهِمْ ضَبَائِرَ ضَبَائِرَ فَبُثُّوا عَلَى أَنْهَارِ الْجَنَّةِ، ثُمَّ قِيلَ: يَا أَهْلَ الْجَنَّةِ، أَفِيضُوا عَلَيْهِمْ، فَيَنْبُتُونَ نَبَاتَ الْحِبَّةِ تَكُونُ فِي حَمِيلِ السَّيْلِ.","فَقَالَ رَجُلٌ مِنَ الْقَوْمِ: كَأَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَدْ كَانَ بِالْبَادِيَةِ."],"takhrij":"صحيح: رواه مسلم في الإيمان (185) من طرق عن أبي سلمة، عن أبي نضرة، عن أبي سعيد، فذكر مثله.","grade":"صحيح","chapter_ar":"باب شفاعة النبي ﷺ لكل من قال لا إله إلا الله ولم يشرك بالله ولو عمل الكبائر واستحق النار","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (185).","chapter_en":"The Prophet’s ﷺ Intercession for Everyone Who Said “There Is No Deity Worthy of Worship Except Allah” and Did Not Associate Anything With Allah, Even if He Committed Major Sins and Deserved the Fire","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":5,"content":{"translation":{"en":["Abū Saʿīd may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “As for the people of the Fire who are its true inhabitants, they will neither die therein nor live. But there will be people whom the Fire afflicts because of their sins—or he said: because of their offenses—and it will cause them to die completely. When they have become charcoal, permission will be granted for intercession. They will then be brought forth in groups upon groups and scattered along the rivers of Paradise. Then it will be said: ‘O people of Paradise, pour water over them.’ Thereupon they will grow as a seed grows in the sediment carried by a flood.”","A man among the people said: “It is as though the Messenger of Allah ﷺ had lived in the desert.”"]},"buhuth":{"en":["The word:","“ḍabāʾir”","is the plural of ḍabārah—with either a kasrah or a fatḥah on the letter ḍād—and means groups separated from one another.","The expression:","“fa-buththū”","means: they were dispersed."]}},"tuhfa":{},"full":1,"dr":1,"rep":[12728,13141,13708],"tks":"صحيح: رواه مسلم (185)."},{"num":897,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَخْرُجُ مِنَ النَّارِ بِالشَّفَاعَةِ كَأَنَّهُمُ الثَّعَارِيرُ، قُلْتُ: مَا الثَّعَارِيرُ؟ قَالَ: الضَّغَابِيسُ، وَكَانَ قَدْ سَقَطَ فَمُهُ، فَقُلْتُ لِعَمْرِو بْنِ دِينَارٍ أَبَا مُحَمَّدٍ: سَمِعْتَ جَابِرَ بْنَ عَبْدِ اللَّهِ، يَقُولُ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: يَخْرُجُ بِالشَّفَاعَةِ مِنَ النَّارِ؟ قَالَ: نَعَمْ."],"takhrij":"متفق عليه: رواه البخاريّ في الرّقاق (6558)، ومسلم في الإيمان (191: 318) كلاهما من حماد بن زيد، عن عمرو بن دينار، عن جابر فذكر مثله، واللفظ للبخاري، وليس عند مسلم: كأنّهم الثّعارير وتفسيره.","grade":"متفق عليه","chapter_ar":"باب شفاعة النبي ﷺ لكل من قال لا إله إلا الله ولم يشرك بالله ولو عمل الكبائر واستحق النار","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6558) and Muslim (191:318). The wording is that of al-Bukhārī.","chapter_en":"The Prophet’s ﷺ Intercession for Everyone Who Said “There Is No Deity Worthy of Worship Except Allah” and Did Not Associate Anything With Allah, Even if He Committed Major Sins and Deserved the Fire","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":5,"content":{"translation":{"en":["Jābir may Allah be pleased with him reported that the Prophet ﷺ said: “Through intercession, people will emerge from the Fire as though they were al-thaʿārīr.” I asked: “What are al-thaʿārīr?” He replied: “Al-ḍaghābīs.” His teeth had already fallen out. I said to ʿAmr ibn Dīnār: “O Abū Muḥammad, did you hear Jābir ibn ʿAbdullāh say: ‘I heard the Prophet ﷺ say: Through intercession, people will emerge from the Fire’?” He replied: “Yes.”"]},"buhuth":{"en":["“Al-ḍaghābīs” are small, tender cucumbers or similar plants. Its singular is ḍaghbūs, and other explanations have also been given."]}},"tuhfa":{},"full":1,"dr":1,"rep":[89,16185],"tks":"متفق عليه: رواه البخاري (6558)، ومسلم (191: 318)، واللفظ للبخاري."},{"num":898,"demo":false,"sanad":"","matn":["عَنْ يَزِيدَ الْفَقِيرِ قَالَ: كُنْتُ قَدْ شَغَفَنِي رَأْيٌ مِنْ رَأْيِ الْخَوَارِجِ فَخَرَجْنَا فِي عِصَابَةٍ ذَوِي عَدَدٍ نُرِيدُ أَنْ نَحُجَّ، ثُمَّ نَخْرُجَ عَلَى النَّاسِ، قَالَ: فَمَرَرْنَا عَلَى الْمَدِينَةِ، فَإِذَا جَابِرُ بْنُ عَبْدِ اللَّهِ يُحَدِّثُ الْقَوْمَ، جَالِسٌ إِلَى سَارِيَةٍ، عَنِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: فَإِذَا هُوَ قَدْ ذَكَرَ الْجَهَنَّمِيِّينَ، قَالَ: فَقُلْتُ لَهُ: يَا صَاحِبَ رَسُولِ اللَّهِ، مَا هَذَا الَّذِي تُحَدِّثُونَ؟ وَاللَّهُ يَقُولُ: ﴿إِنَّكَ مَنْ تُدْخِلِ النَّارَ فَقَدْ أَخْزَيْتَهُ﴾ [سورة آل عمران: 192]، وَ ﴿ كُلَّمَا أَرَادُوا أَنْ يَخْرُجُوا مِنْهَا أُعِيدُوا فِيهَا﴾ [سورة السجدة: 20]، فَمَا هَذَا الَّذِي تَقُولُونَ؟ قَالَ: فَقَالَ: أَتَقْرَأُ الْقُرْآنَ؟ قُلْتُ: نَعَمْ، قَالَ: فَهَلْ سَمِعْتَ بِمَقَامِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّم يَعْنِي الَّذِي يَبْعَثُهُ اللَّهُ فِيهِ؟ قُلْتُ: نَعَمْ، قَالَ: فَإِنَّهُ مَقَامُ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَحْمُودُ الَّذِي يُخْرِجُ اللَّهُ بِهِ مَنْ يُخْرِجُ، قَالَ: ثُمَّ نَعَتَ وَضْعَ الصِّرَاطِ، وَمَرَّ النَّاسِ عَلَيْهِ، قَالَ: وَأَخَافُ أَنْ لَا أَكُونَ أَحْفَظُ ذَاكَ، قَالَ: غَيْرَ أَنَّهُ قَدْ زَعَمَ، أَنَّ قَوْمًا يَخْرُجُونَ مِنَ النَّارِ، بَعْدَ أَنْ يَكُونُوا فِيهَا، قَالَ: يَعْنِي فَيَخْرُجُونَ كَأَنَّهُمْ عِيدَانُ السَّمَاسِمِ، قَالَ: فَيَدْخُلُونَ نَهَرًا مِنْ أَنْهَارِ الْجَنَّةِ، فَيَغْتَسِلُونَ فِيهِ فَيَخْرُجُونَ كَأَنَّهُمُ الْقَرَاطِيسُ.","فَرَجَعْنَا، قُلْنَا: وَيْحَكُمْ! أَتُرَوْنَ الشَّيْخَ يَكْذِبُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرَجَعْنَا، فَلَا وَاللَّهِ مَا خَرَجَ مِنَّا غَيْرُ رَجُلٍ وَاحِدٍ."],"takhrij":"صحيح: أخرجه مسلم في الإيمان (191: 320) عن الحجاج بن الشاعر، حدثنا الفضل بن دكين، حدثنا أبو عاصم (يعني محمد بن أبي أيوب) قال: حدثني يزيد الفقير، قال: فذكره.","grade":"صحيح","chapter_ar":"باب شفاعة النبي ﷺ لكل من قال لا إله إلا الله ولم يشرك بالله ولو عمل الكبائر واستحق النار","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (191:320).","chapter_en":"The Prophet’s ﷺ Intercession for Everyone Who Said “There Is No Deity Worthy of Worship Except Allah” and Did Not Associate Anything With Allah, Even if He Committed Major Sins and Deserved the Fire","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":5,"content":{"translation":{"en":["Yazīd al-Faqīr reported: I had become deeply attracted to one of the views of the Khawārij, so a sizeable group of us set out intending to perform Ḥajj and afterward rise against the people. We passed through Madinah and found Jābir ibn ʿAbdullāh may Allah be pleased with them sitting beside a pillar, narrating to the people from the Messenger of Allah ﷺ. He mentioned al-Jahannamiyyūn. I said to him: “O Companion of the Messenger of Allah, what is this that you narrate? Allah says: ‘Our Lord, indeed whoever You admit into the Fire, You have certainly disgraced him, and the wrongdoers will have no helpers.’ [Āl ʿImrān 3:192] And: ‘As for those who defiantly disobeyed, their refuge will be the Fire. Whenever they wish to emerge from it, they will be returned to it, and it will be said to them: Taste the punishment of the Fire which you used to deny.’ [Sūrat al-Sajdah 32:20] So what is this that you are saying?” He asked: “Do you recite the Qurʾān?” I replied: “Yes.” He asked: “Have you heard of the Station of Muḥammad ﷺ”—meaning the station to which Allah will raise him? I replied: “Yes.” He said: “That is the Praised Station of Muḥammad ﷺ, through which Allah will bring out whomever He brings out.” He then described the placing of the Ṣirāṭ and the people passing over it. Yazīd said: “I fear that I did not preserve that portion precisely.” He continued: “However, he stated that people will emerge from the Fire after having been in it. They will emerge as though they were sesame stalks. They will enter a river from among the rivers of Paradise and wash in it, then emerge looking like sheets of paper.” We left and said:","“Woe to you! Do you think this elderly Companion would lie about the Messenger of Allah ﷺ?” So we abandoned our former view. By Allah, none of us later went out in rebellion except one man—or as Abū Nuʿaym narrated."]},"buhuth":{"en":["“Al-Faqīr,” with fāʾ followed by qāf, is a personal nickname. He was given it because he suffered from pain in the vertebrae of his back, not because the word here means “poor.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (191: 320)."},{"num":899,"demo":false,"sanad":"","matn":["عَنْ عِمْرَانَ بْنِ حُصَيْنٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَخْرُجُ قَوْمٌ مِنَ النَّارِ بِشَفَاعَةِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَيَدْخُلُونَ الْجَنَّةَ يُسَمَّوْنَ: الْجَهَنَّمِيِّينَ."],"takhrij":"صحيح: رواه البخاريّ في الرّقاق (6566) عن مسدّد، حدّثنا يحيى، عن الحسن بن ذكوان، حدّثنا أبو رجاء، حدّثنا عمران بن حصين، فذكره.","grade":"صحيح","chapter_ar":"باب شفاعة النبي ﷺ لكل من قال لا إله إلا الله ولم يشرك بالله ولو عمل الكبائر واستحق النار","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (6566).","chapter_en":"The Prophet’s ﷺ Intercession for Everyone Who Said “There Is No Deity Worthy of Worship Except Allah” and Did Not Associate Anything With Allah, Even if He Committed Major Sins and Deserved the Fire","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":5,"content":{"translation":{"en":["ʿImrān ibn Ḥuṣayn may Allah be pleased with him reported that the Prophet ﷺ said: “People will emerge from the Fire through the intercession of Muḥammad ﷺ. They will then enter Paradise and will be called al-Jahannamiyyūn.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[16186,16401],"tks":"صحيح: رواه البخاري (6566)."},{"num":900,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:شَفَاعَتِي لِأَهْلِ الْكَبَائِرِ مِنْ أُمَّتِي."],"takhrij":"صحيح: رواه أبو داود (4739)، والترمذيّ (2435)، وأحمد (13222)، وابن خزيمة في التوحيد (527)، وابن حبان (6468)، والحاكم (228) كلّهم من طرق عن أنس بن مالك، فذكره.","grade":"صحيح","chapter_ar":"باب شفاعة النبي ﷺ لكل من قال لا إله إلا الله ولم يشرك بالله ولو عمل الكبائر واستحق النار","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (4739), al-Tirmidhī (2435), and Aḥmad (13222).","chapter_en":"The Prophet’s ﷺ Intercession for Everyone Who Said “There Is No Deity Worthy of Worship Except Allah” and Did Not Associate Anything With Allah, Even if He Committed Major Sins and Deserved the Fire","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":5,"content":{"translation":{"en":["Anas may Allah be pleased with him reported that the Prophet ﷺ said: “My intercession is for the people who committed major sins from my Ummah.”"]},"buhuth":{"en":["Also narrated by Ibn Khuzaymah in al-Tawḥīd (527), Ibn Ḥibbān (6468), and al-Ḥākim (1/69). Al-Tirmidhī said: “Ḥasan Ṣaḥīḥ Gharīb.” Al-Ḥākim said: “Ṣaḥīḥ according to the conditions of the two Shaykhs.”","The statement “My intercession is for the people of major sins” refers to intercession after the Great Intercession, for believers who entered the Fire because of their sins and offenses and are then brought out through his ﷺ intercession. See: Ibn Khuzaymah, al-Tawḥīd (2/577)."]}},"tuhfa":{},"full":1,"dr":1,"rep":[16183],"tks":"صحيح: رواه أبو داود (4739)، والترمذي (2435)، وأحمد (13222)."},{"num":901,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ شَفَاعَتِي يَوْمَ الْقِيَامَةِ لِأَهْلِ الْكَبَائِرِ مِنْ أُمَّتِي."],"takhrij":"صحيح: رواه ابن ماجه (4310) عن عبدالرحمن بن إبراهيم الدّمشقيّ، قال: حدّثنا الوليد بن مسلم، قال: حدّثنا زهير بن محمد، عن جعفر بن محمد، عن أبيه، عن جابر، قال: فذكره.","grade":"صحيح","chapter_ar":"باب شفاعة النبي ﷺ لكل من قال لا إله إلا الله ولم يشرك بالله ولو عمل الكبائر واستحق النار","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Ibn Mājah (4310), Ibn Khuzaymah in al-Tawḥīd (531), Ibn Ḥibbān (6467).","chapter_en":"The Prophet’s ﷺ Intercession for Everyone Who Said “There Is No Deity Worthy of Worship Except Allah” and Did Not Associate Anything With Allah, Even if He Committed Major Sins and Deserved the Fire","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":5,"content":{"translation":{"en":["Jābir, may Allah be pleased with him, said: I heard the Messenger of Allah ﷺ say: “Indeed, my intercession on the Day of Resurrection is for those from my Ummah who committed major sins.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[16184],"tks":"صحيح: رواه ابن ماجه (4310)، وابن خزيمة في التوحيد (531)، وابن حبان (6467)."},{"num":902,"demo":false,"sanad":"","matn":["عَنْ كَعْبِ بْنِ عُجْرَةَ قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، الشَّفَاعَةُ؟ قَالَ: الشَّفَاعَةُ لِأَهْلِ الْكَبَائِرِ مِنْ أُمَّتِي."],"takhrij":"حسن: رواه الآجريّ في الشّريعة (780)، والخطيب في تاريخ بغداد (1292) (في ترجمة محمد بن عمر بن عبدالعزيز الهمدانيّ) كلاهما من طريق محمد بن بكّار، حدّثنا عنبسة بن عبدالواحد، عن واصل، عن أُمَيّ أبي عبدالرحمن، عن الشّعبيّ، عن كعب بن عجرة، فذكره.","grade":"حسن","chapter_ar":"باب شفاعة النبي ﷺ لكل من قال لا إله إلا الله ولم يشرك بالله ولو عمل الكبائر واستحق النار","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Ājurrī in al-Sharīʿah (780) and al-Khaṭīb in Tārīkh Baghdād (3/40).","chapter_en":"The Prophet’s ﷺ Intercession for Everyone Who Said “There Is No Deity Worthy of Worship Except Allah” and Did Not Associate Anything With Allah, Even if He Committed Major Sins and Deserved the Fire","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":5,"content":{"translation":{"en":["Kaʿb ibn ʿUjrah, may Allah be pleased with him, said: I asked: “O Messenger of Allah, what about the intercession?” He replied: “The intercession is for those from my Ummah who committed major sins.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الآجري في الشريعة (780)، والخطيب في تاريخ بغداد (1292)."},{"num":903,"demo":false,"sanad":"","matn":["عَنْ عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ قَالَ: عَرَّسَ بِنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ لَيْلَةٍ، فَافْتَرَشَ كُلُّ رَجُلٍ مِنَّا ذِرَاعَ رَاحِلَتِهِ، قَالَ: فَانْتَهَيْتُ إِلَى بَعْضِ الْإِبِلِ فَإِذَا نَاقَةُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيْسَ قُدَّامَهَا أَحَدٌ، قَالَ: فَانْطَلَقْتُ أَطْلُبُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَإِذَا مُعَاذُ بْنُ جَبَلٍ وَعَبْدُ اللَّهِ بْنُ قَيْسٍ قَائِمَانِ، قُلْتُ: أَيْنَ رَسُولُ اللَّهِ؟ قَالَا: مَا نَدْرِي غَيْرَ أَنَّا سَمِعْنَا صَوْتًا بِأَعْلَى الْوَادِي، فَإِذَا مِثْلُ هَزِيزِ الرَّحْلِ قَالَ: امْكُثُوا يَسِيرًا، ثُمَّ جَاءَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنَّهُ أَتَانِي اللَّيْلَةَ آتٍ مِنْ رَبِّي، فَخَيَّرَنِي بَيْنَ أَنْ يَدْخُلَ نِصْفُ أُمَّتِي الْجَنَّةَ وَبَيْنَ الشَّفَاعَةِ، فَاخْتَرْتُ الشَّفَاعَةَ، فَقُلْنَا: نَنْشُدُكَ اللَّهَ وَالصُّحْبَةَ لَمَا جَعَلْتَنَا مِنْ أَهْلِ شَفَاعَتِكَ، قَالَ: فَإِنَّكُمْ مِنْ أَهْلِ شَفَاعَتِي، قَالَ: فَأَقْبَلْنَا مَعَانِيقَ إِلَى النَّاسِ، فَإِذَا هُمْ قَدْ فَزِعُوا وَفَقَدُوا نَبِيَّهُمْ، وَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّهُ أَتَانِي اللَّيْلَةَ مِنْ رَبِّي آتٍ فَخَيَّرَنِي بَيْنَ أَنْ يَدْخُلَ نِصْفُ أُمَّتِي الْجَنَّةَ وَبَيْنَ الشَّفَاعَةِ، وَإِنِّي اخْتَرْتُ الشَّفَاعَةَ، قَالُوا: يَا رَسُولَ اللَّهِ، نَنْشُدُكَ اللَّهَ وَالصُّحْبَةَ لَمَا جَعَلْتَنَا مِنْ أَهْلِ شَفَاعَتِكَ، قَالَ: فَلَمَّا أَضَبُّوا عَلَيْهِ، قَالَ: فَأَنَا أُشْهِدُكُمْ أَنَّ شَفَاعَتِي لِمَنْ لَا يُشْرِكُ بِاللَّهِ شَيْئًا مِنْ أُمَّتِي."],"takhrij":"صحيح: رواه الإمام أحمد (24002)، وابن خزيمة (516، 517)، وابن حبان (211، 6463)، والآجري في الشريعة (793)، والحاكم (223) كلّهم من طريق قتادة، عن أبي المليح، عن عوف بن مالك الأشجعيّ، فذكره. ولفظهم سواء.","grade":"صحيح","chapter_ar":"باب شفاعة النبي ﷺ لكل من قال لا إله إلا الله ولم يشرك بالله ولو عمل الكبائر واستحق النار","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Imām Aḥmad (24002), Ibn Khuzaymah (516, 517), Ibn Ḥibbān (211, 6463).","chapter_en":"The Prophet’s ﷺ Intercession for Everyone Who Said “There Is No Deity Worthy of Worship Except Allah” and Did Not Associate Anything With Allah, Even if He Committed Major Sins and Deserved the Fire","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":5,"content":{"translation":{"en":["ʿAwf ibn Mālik al-Ashjaʿī, may Allah be pleased with him, reported: The Messenger of Allah ﷺ stopped to rest one night, and every man among us used the foreleg of his mount as a pillow. Later in the night, I came to where the she-camel of the Messenger of Allah ﷺ was, but there was no one in front of her. So I went looking for the Messenger of Allah ﷺ and found Muʿādh ibn Jabal and ʿAbdullāh ibn Qays standing there. I asked: “Where is the Messenger of Allah ﷺ?” They replied: “We do not know, except that we heard a sound from the upper part of the valley, like the humming of saddle gear.” He said: “Remain here for a little while.” Then the Messenger of Allah ﷺ came to us and said: “Tonight a visitor from my Lord came to me and gave me a choice between half of my Ummah entering Paradise and intercession, so I chose intercession.” We said: “We implore you by Allah and by our companionship with you to make us among those who receive your intercession.” He said: “You are indeed among those who will receive my intercession.” We then hurried back toward the people and found that they had become alarmed because they had lost sight of their Prophet. The Messenger of Allah ﷺ said: “Tonight a visitor from my Lord came to me and gave me a choice between half of my Ummah entering Paradise and intercession, so I chose intercession.” They said: “O Messenger of Allah, we implore you by Allah and by our companionship with you to make us among those who receive your intercession.” When they crowded around him, he said: “I call you to witness that my intercession is for whoever does not associate anything with Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (24002)، وابن خزيمة (516، 517)، وابن حبان (211، 6463)."},{"num":904,"demo":false,"sanad":"","matn":["عَنْ عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ قَالَ: كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ فَنَزَلْنَا لَيْلَةً، فَقُمْتُ أَطْلُبُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَمْ أَجِدْهُ، وَوَجَدْتُ مُعَاذَ بْنَ جَبَلٍ، وَأَبَا مُوسَى الْأَشْعَرِيَّ فَقَالَا: مَا حَاجَتُكَ؟ فَقُلْتُ: أَيْنَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ فَقَالَا: لَا نَدْرِي، فَبَيْنَا نَحْنُ عَلَى ذَلِكَ إِذْ سَمِعْنَا فِي أَعْلَى الْوَادِي هَدِيرًا كَهَدِيرِ الرَّحَا، فَلَمْ نَلْبَثْ أَنْ جَاءَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقُلْنَا: يَا رَسُولَ اللَّهِ فَقَدْنَاكَ اللَّيْلَةَ، فَقَالَ: إِنَّهُ أَتَانِي آتٍ مِنْ رَبِّي فَخَيَّرَنِي بَيْنَ أَنْ تَكُونَ أُمَّتِي شَطْرَ أَهْلِ الْجَنَّةِ، وَبَيْنَ الشَّفَاعَةِ، فَاخْتَرْتُ الشَّفَاعَةَ، فَقُلْنَا: يَا نَبِيَّ اللَّهِ ادْعُ اللَّهَ أَنْ يَجْعَلَنَا مِنْ أَهْلِ الشَّفَاعَةِ، فَقَالَ: اللَّهُمَّ اجْعَلْهُمْ مِنْ أَهْلِهَا، ثُمَّ أَتَيْنَا الْقَوْمَ فَأَخْبَرْنَاهُمْ فَقَالُوا: يَا رَسُولَ اللَّهِ ادْعُ اللَّهَ أَنْ يَجْعَلَنَا مِنْ أَهْلِ شَفَاعَتِكَ، فَقَالَ: اللَّهُمَّ اجْعَلْهُمْ مِنْ أَهْلِهَا ثُمَّ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أُشْهِدُكُمْ أَنَّ شَفَاعَتِي لِكُلِّ مَنْ مَاتَ لَا يُشْرِكُ بِاللَّهِ شَيْئًا."],"takhrij":"صحيح: رواه عبدالرّزاق (21790)، وابنُ أبي عاصم (819)، وابن خزيمة (522) كلّهم من طريق أبي قلابة، عن عوف بن مالك، قال (فذكره).","grade":"صحيح","chapter_ar":"باب شفاعة النبي ﷺ لكل من قال لا إله إلا الله ولم يشرك بالله ولو عمل الكبائر واستحق النار","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by ʿAbd al-Razzāq (20865), Ibn Abī ʿĀṣim (819), and Ibn Khuzaymah (522).","chapter_en":"The Prophet’s ﷺ Intercession for Everyone Who Said “There Is No Deity Worthy of Worship Except Allah” and Did Not Associate Anything With Allah, Even if He Committed Major Sins and Deserved the Fire","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":5,"content":{"translation":{"en":["ʿAwf ibn Mālik al-Ashjaʿī, may Allah be pleased with him, reported: We were with the Messenger of Allah ﷺ on a journey and stopped for the night. I got up looking for the Prophet ﷺ but could not find him. I found Muʿādh ibn Jabal and Abū Mūsā al-Ashʿarī. They asked: “What do you need?” I said: “Where is the Messenger of Allah ﷺ?” They replied: “We do not know.” While we were in that state, we heard from the upper part of the valley a rumbling like the rumbling of a millstone. It was not long before the Prophet ﷺ came. We said: “O Messenger of Allah, we missed you tonight.” He replied: “A visitor from my Lord came to me and gave me a choice between my Ummah being half of the people of Paradise and intercession, so I chose intercession.” We said: “O Prophet of Allah, supplicate to Allah to make us among those who receive the intercession.” He said: “O Allah, make them among its people.” Then we went to the people and informed them. They said: “O Messenger of Allah, supplicate to Allah to make us among those who receive your intercession.” He said: “O Allah, make them among its people.” Then the Messenger of Allah ﷺ said: “I call you to witness that my intercession is for everyone who dies without associating anything with Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه عبد الرزاق (21790)، وابن أبي عاصم (819)، وابن خزيمة (522)."},{"num":905,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى قَالَ: كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ لَيْلَةٍ فَعَرَّسَ وَعَرَّسْنَا، فَقَالَ: أَتَى آتٍ بَعْدَكُمْ مِنْ رَبِّكُمْ فَخَيَّرَنِي بَيْنَ أَنْ يَدْخُلَ نِصْفُ أُمَّتِي الْجَنَّةَ، وَبَيْنَ الشَّفَاعَةِ، فَاخْتَرْتُ الشَّفَاعَةَ. فَقُلْنَا: يَا رَسُولَ اللَّهِ، اجْعَلْنَا مِمَّنْ تَشْفَعُ لَهُ. قَالَ: أَنْتُمْ مِنْهُمْ. قُلْنَا: أَفَلَا نُبَشِّرُ النَّاسَ بِهَا يَا رَسُولَ اللَّهِ؟ وَابْتَدَرْنَاهُ الرِّجَالَ، فَلَمَّا كَثُرُوا عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: هِيَ لِكُلِّ مَنْ مَاتَ لَا يُشْرِكُ بِاللَّهِ شَيْئًا."],"takhrij":"حسن: رواه ابن أبي عاصم في السنة (821) عن هشام بن عمار، ثنا الحكم ابن هشام، حدّثنا عبدالملك بن عمير، عن أبي بردة، وأبي بكر ابني أبي موسى، عن أبي موسى قال: فذكره.","grade":"حسن","chapter_ar":"باب شفاعة النبي ﷺ لكل من قال لا إله إلا الله ولم يشرك بالله ولو عمل الكبائر واستحق النار","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Ibn Abī ʿĀṣim in al-Sunnah (821).","chapter_en":"The Prophet’s ﷺ Intercession for Everyone Who Said “There Is No Deity Worthy of Worship Except Allah” and Did Not Associate Anything With Allah, Even if He Committed Major Sins and Deserved the Fire","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":5,"content":{"translation":{"en":["Abū Mūsā, may Allah be pleased with him, reported: We were with the Messenger of Allah ﷺ one night. He stopped to rest and we rested as well. He said: “A visitor came after you from your Lord and gave me a choice between half of my Ummah entering Paradise and intercession, so I chose intercession.” We said: “O Messenger of Allah, make us among those for whom you intercede.” He replied: “You are among them.” We asked: “Should we not give the people glad tidings of this, O Messenger of Allah?” The men rushed toward him, and when many had gathered around the Messenger of Allah ﷺ, he said: “It is for everyone who dies without associating anything with Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن أبي عاصم في السنة (821)."},{"num":906,"demo":false,"sanad":"","matn":["عَنِ ابْنِ دَارَّةَ مَوْلَى عُثْمَانَ قَالَ: إِنَّا لَبِالْبَقِيعِ مَعَ أَبِي هُرَيْرَةَ إِذْ سَمِعْنَاهُ يَقُولُ: أَنَا أَعْلَمُ النَّاسِ بِشَفَاعَةِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ الْقِيَامَةِ، قَالَ: فَتَدَاكَّ النَّاسُ عَلَيْهِ، فَقَالُوا: إِيهٍ يَرْحَمُكَ اللَّهُ! قَالَ: يَقُولُ: اللَّهُمَّ اغْفِرْ لِكُلِّ عَبْدٍ مُسْلِمٍ لَقِيَكَ يُؤْمِنُ بِي لَا يُشْرِكُ بِكَ."],"takhrij":"حسن: رواه أحمد (9852) عن حجاج، قال: حدثنا ابن جريج، قال: حدثني العلاء بن عبد الرحمن بن يعقوب، عن ابن دارة، مولى عثمان فذكره.","grade":"حسن","chapter_ar":"باب شفاعة النبي ﷺ لكل من قال لا إله إلا الله ولم يشرك بالله ولو عمل الكبائر واستحق النار","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Aḥmad (9852).","chapter_en":"The Prophet’s ﷺ Intercession for Everyone Who Said “There Is No Deity Worthy of Worship Except Allah” and Did Not Associate Anything With Allah, Even if He Committed Major Sins and Deserved the Fire","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":5,"content":{"translation":{"en":["Ibn Dārah, the freedman of ʿUthmān, reported: We were in al-Baqīʿ with Abū Hurayrah may Allah be pleased with him when we heard him say: “I am the most knowledgeable of people concerning the intercession of Muḥammad ﷺ on the Day of Resurrection.” The people gathered closely around him and said: “Continue—may Allah have mercy upon you!” He said that the Prophet ﷺ says: “O Allah, forgive every Muslim servant who meets You believing in me and not associating anything with You.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (9852)."},{"num":907,"demo":false,"sanad":"","matn":["عَن أَبِي مُوسَى، أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَحْرُسُهُ أَصْحَابُهُ، فَقُمْتُ ذَاتَ لَيْلَةٍ، فَلَمْ أَرَهُ فِي مَنَامِهِ، فَأَخَذَنِي مَا قَدُمَ وَمَا حَدَثَ، فَذَهَبْتُ أَنْظُرُ، فَإِذَا أَنَا بِمُعَاذٍ قَدْ لَقِيَ الَّذِي لَقِيتُ، فَسَمِعْنَا صَوْتًا مِثْلَ هَزِيزِ الرَّحَا، فَوَقَفَا عَلَى مَكَانِهِمَا، فَجَاءَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ قِبَلِ الصَّوْتِ، فَقَالَ: هَلْ تَدْرُونَ أَيْنَ كُنْتُ؟ وَفِيمَ كُنْتُ؟ أَتَانِي آتٍ مِنْ رَبِّي عَزَّ وَجَلَّ، فَخَيَّرَنِي بَيْنَ أَنْ يَدْخُلَ نِصْفُ أُمَّتِي الْجَنَّةَ وَبَيْنَ الشَّفَاعَةِ، فَاخْتَرْتُ الشَّفَاعَةَ، فَقَالَا: يَا رَسُولَ اللَّهِ، ادْعُ اللَّهَ عَزَّ وَجَلَّ أَنْ يَجْعَلَنَا فِي شَفَاعَتِكَ، فَقَالَ: أَنْتُمْ وَمَنْ مَاتَ، لَا يُشْرِكُ بِاللَّهِ شَيْئًا فِي شَفَاعَتِي."],"takhrij":"حسن: رواه أحمد (19618) عن عفّان، حدّثنا حمّاد، يعني ابن سلمة، ، أخبرنا عاصم، عن أبي بردة، عن أبي موسى، فذكره.","grade":"حسن","chapter_ar":"باب شفاعة النبي ﷺ لكل من قال لا إله إلا الله ولم يشرك بالله ولو عمل الكبائر واستحق النار","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Aḥmad (19618).","chapter_en":"The Prophet’s ﷺ Intercession for Everyone Who Said “There Is No Deity Worthy of Worship Except Allah” and Did Not Associate Anything With Allah, Even if He Committed Major Sins and Deserved the Fire","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":5,"content":{"translation":{"en":["Abū Mūsā, may Allah be pleased with him, reported: The Prophet ﷺ used to be guarded by his Companions. I got up one night and did not find him in his sleeping place, so I became deeply worried and went looking for him. I then encountered Muʿādh, who had experienced the same concern as I had. We heard a sound like the humming of a millstone, so we remained where we were. The Prophet ﷺ came from the direction of the sound and said: “Do you know where I was and what I was doing? A visitor from my Lord, Mighty and Majestic, came to me and gave me a choice between half of my Ummah entering Paradise and intercession, so I chose intercession.” They said: “O Messenger of Allah, supplicate to Allah, Mighty and Majestic, to include us in your intercession.” He said: “You, and whoever dies without associating anything with Allah, are included in my intercession.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (19618)."},{"num":908,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنِّي لَأَوَّلُ النَّاسِ تَنْشَقُّ الْأَرْضُ عَنْ جُمْجُمَتِي يَوْمَ الْقِيَامَةِ وَلَا فَخْرَ، وَأُعْطَى لِوَاءَ الْحَمْدِ وَلَا فَخْرَ، وَأَنَا سَيِّدُ النَّاسِ يَوْمَ الْقِيَامَةِ وَلَا فَخْرَ، وَأَنَا أَوَّلُ مَنْ يَدْخُلُ الْجَنَّةَ يَوْمَ الْقِيَامَةِ وَلَا فَخْرَ، وَإِنِّي آتِي بَابَ الْجَنَّةِ فَآخُذُ بِحَلْقَتِهَا فَيَقُولُونَ: مَنْ هَذَا؟ فَأقُولُ: أَنَا مُحَمَّدٌ، فَيَفْتَحُونَ لِي، فَأَدْخُلُ، فَإِذَا الْجَبَّارُ عَزَّ وَجَلَّ مُسْتَقْبِلِي، فَأَسْجُدُ لَهُ، فَيَقُولُ: ارْفَعْ رَأْسَكَ يَا مُحَمَّدُ، وَتَكَلَّمْ يُسْمَعْ مِنْكَ، وَقُلْ: يُقْبَلْ مِنْكَ، وَاشْفَعْ تُشَفَّعْ، فَأَرْفَعُ رَأْسِي، فَأَقُولُ: أُمَّتِي أُمَّتِي يَا رَبِّ، فَيَقُولُ: اذْهَبْ إِلَى أُمَّتِكَ، فَمَنْ وَجَدْتَ فِي قَلْبِهِ مِثْقَالَ حَبَّةٍ مِنْ شَعِيرٍ مِنَ الْإِيمَانِ، فَأَدْخِلْهُ الْجَنَّةَ، فَأُقْبِلُ، فَمَنْ وَجَدْتُ فِي قَلْبِهِ ذَلِكَ، فَأُدْخِلُهُ الْجَنَّةَ، فَإِذَا الْجَبَّارُ عَزَّ وَجَلَّ مُسْتَقْبِلِي، فَأَسْجُدُ لَهُ، فَيَقُولُ: ارْفَعْ رَأْسَكَ يَا مُحَمَّدُ، وَتَكَلَّمْ يُسْمَعْ مِنْكَ، وَقُلْ: يُقْبَلْ مِنْكَ، وَاشْفَعْ تُشَفَّعْ، فَأَرْفَعُ رَأْسِي، فَأَقُولُ: أُمَّتِي أُمَّتِي أَيْ رَبِّ، فَيَقُولُ: اذْهَبْ إِلَى أُمَّتِكَ، فَمَنْ وَجَدْتَ فِي قَلْبِهِ نِصْفَ حَبَّةٍ مِنْ شَعِيرٍ مِنَ الْإِيمَانِ، فَأَدْخِلْهُمْ الْجَنَّةَ، فَأَذْهَبُ، فَمَنْ وَجَدْتُ فِي قَلْبِهِ مِثْقَالَ ذَلِكَ، أَدْخِلْتُهُمْ الْجَنَّةَ، فَإِذَا الْجَبَّارُ عَزَّ وَجَلَّ مُسْتَقْبِلِي، فَأَسْجُدُ لَهُ، فَيَقُولُ: ارْفَعْ رَأْسَكَ يَا مُحَمَّدُ، وَتَكَلَّمْ يُسْمَعْ مِنْكَ، وَقُلْ: يُقْبَلْ مِنْكَ، وَاشْفَعْ تُشَفَّعْ، فَأَرْفَعُ رَأْسِي، فَأَقُولُ: أُمَّتِي، أُمَّتِي، فَيَقُولُ: اذْهَبْ إِلَى أُمَّتِكَ، فَمَنْ وَجَدْتَ فِي قَلْبِهِ مِثْقَالَ حَبَّةٍ مِنْ خَرْدَلٍ مِنَ الْإِيمَانِ، فَأَدْخِلْهُ الْجَنَّةَ، فَأَذْهَبُ فَمَنْ وَجَدْتُ فِي قَلْبِهِ مِثْقَالَ ذَلِكَ أَدْخَلْتُهُمْ الْجَنَّةَ، وَفَرَغَ اللَّهُ مِنْ حِسَابِ النَّاسِ وَأَدْخَلَ مَنْ بَقِيَ مِنْ أُمَّتِي النَّارَ مَعَ أَهْلِ النَّارِ، فَيَقُولُ أَهْلُ النَّارِ: مَا أَغْنَى عَنْكُمْ أَنَّكُمْ كُنْتُمْ تَعْبَدُونَ اللَّهَ عَزَّ وَجَلَّ لَا تُشْرِكُونَ بِهِ شَيْئًا؟! فَيَقُولُ الْجَبَّارُ عَزَّ وَجَلَّ: فَبِعِزَّتِي لَأُعْتِقَنَّهُمْ مِنَ النَّارِ فَيُرْسِلُ إِلَيْهِمْ فَيَخْرُجُونَ وَقَدْ امْتَحَشُوا فَيَدْخُلُونَ فِي نَهَرِ الْحَيَاةِ، فَيَنْبُتُونَ فِيهِ كَمَا تَنْبُتُ الْحِبَّةُ فِي غُثَاءِ السَّيْلِ، وَيُكْتَبُ بَيْنَ أَعْيُنِهِمْ هَؤُلَاءِ عُتَقَاءُ اللَّهِ عَزَّ وَجَلَّ، فَيُذْهَبُ بِهِمْ، فَيُدْخَلُونَ الْجَنَّةَ، فَيَقُولُ لَهُمْ أَهْلُ الْجَنَّةِ: هَؤُلَاءِ الْجَهَنَّمِيُّونَ، فَيَقُولُ الْجَبَّارُ: بَلْ هَؤُلَاءِ عُتَقَاءُ الْجَبَّارِ عَزَّ وَجَلَّ."],"takhrij":"حسن: رواه الإمام أحمد (12469)، وابن منده في الإيمان (877)، وابن خزيمة في التوحيد (601)، والضّياء في المختارة (2345)، والدّارميّ (53) كلّهم من طريق اللّيث، عن ابن الهاد، عن عمرو بن أبي عمرو، عن أنس بن مالك، فذكره، واللّفظ لأحمد.","grade":"حسن","chapter_ar":"باب شفاعة النبي ﷺ لكل من قال لا إله إلا الله ولم يشرك بالله ولو عمل الكبائر واستحق النار","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (12469), Ibn Mandah in al-Īmān (877), Ibn Khuzaymah in al-Tawḥīd (601), al-Ḍiyāʾ in al-Mukhtārah (2345), and al-Dārimī (53).","chapter_en":"The Prophet’s ﷺ Intercession for Everyone Who Said “There Is No Deity Worthy of Worship Except Allah” and Did Not Associate Anything With Allah, Even if He Committed Major Sins and Deserved the Fire","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":5,"content":{"translation":{"en":["Anas, may Allah be pleased with him, said: I heard the Messenger of Allah ﷺ say: “I will indeed be the first of the people for whom the earth is split open from my skull on the Day of Resurrection—without boasting. I will be given the Banner of Praise—without boasting. I will be the leader of mankind on the Day of Resurrection—without boasting. And I will be the first to enter Paradise on the Day of Resurrection—without boasting. I will come to the gate of Paradise and take hold of its ring. They will ask: ‘Who is this?’ I will reply: ‘I am Muḥammad.’ They will open it for me and I will enter. Then al-Jabbār will be before me, and I will prostrate before Him. He will say: ‘Raise your head, O Muḥammad. Speak and you will be heard. Say something and it will be accepted from you. Intercede and your intercession will be accepted.’ I will raise my head and say: ‘My Ummah! My Ummah, O Lord!’ He will say: ‘Go to your Ummah. Whoever you find with the weight of a grain of barley of faith in his heart, admit him into Paradise.’ So I will go forward, and whoever I find with that in his heart, I will admit him into Paradise. Then al-Jabbār will be before me, and I will prostrate before Him. He will say: ‘Raise your head, O Muḥammad. Speak and you will be heard. Say something and it will be accepted from you. Intercede and your intercession will be accepted.’ I will raise my head and say: ‘My Ummah! My Ummah, O my Lord!’ He will say: ‘Go to your Ummah. Whoever you find with half a grain of barley of faith in his heart, admit them into Paradise.’ So I will go, and whoever I find with that amount in his heart, I will admit them into Paradise. Then al-Jabbār will be before me, and I will prostrate before Him. He will say: ‘Raise your head, O Muḥammad. Speak and you will be heard. Say something and it will be accepted from you. Intercede and your intercession will be accepted.’ I will raise my head and say: ‘My Ummah! My Ummah!’ He will say: ‘Go to your Ummah. Whoever you find with the weight of a mustard seed of faith in his heart, admit him into Paradise.’ So I will go, and whoever I find with that amount in his heart, I will admit them into Paradise. Allah will then finish judging the people, and whoever remains from my Ummah will be admitted into the Fire with the people of the Fire. The people of the Fire will say: ‘What benefit did it bring you that you used to worship Allah, Mighty and Majestic, without associating anything with Him?’ Then al-Jabbār will say: ‘By My Might, I will surely free them from the Fire.’ So they will be brought out after having been burned. They will enter the River of Life and grow therein just as a seed grows in the debris carried by a flood. Between their eyes will be written: ‘These are the freed servants of Allah.’ Then they will be taken away and admitted into Paradise. The people of Paradise will say: ‘These are the Jahannamiyyūn.’ But al-Jabbār will say: ‘Rather, these are those whom al-Jabbār has freed.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (12469)، وابن منده في الإيمان (877)، وابن خزيمة في التوحيد (601)، والضياء في المختارة (2345)، والدارمي (53)."},{"num":909,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: سَأَلْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَشْفَعَ لِي يَوْمَ الْقِيَامَةِ، فَقَالَ: أَنَا فَاعِلٌ قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، فَأَيْنَ أَطْلُبُكَ؟ قَالَ: اطْلُبْنِي أَوَّلَ مَا تَطْلُبُنِي عَلَى الصِّرَاطِ، قَالَ: قُلْتُ: فَإِنْ لَمْ أَلْقَكَ عَلَى الصِّرَاطِ؟ قَالَ: فَاطْلُبْنِي عِنْدَ الْمِيزَانِ، قُلْتُ: فَإِنْ لَمْ أَلْقَكَ عِنْدَ الْمِيزَانِ؟ قَالَ: فَاطْلُبْنِي عِنْدَ الْحَوْضِ فَإِنِّي لَا أُخْطِئُ هَذِهِ الثَّلَاثَ الْمَوَاطِنَ."],"takhrij":"حسن: رواه الترمذيّ (2433) عن عبدالله بن الصّباح الهاشميّ، حدّثنا بدل بن المحبرَّ، حدّثنا حرب بن ميمون الأنصاريّ أبو الخطّاب، حدّثنا النّضر بن أنس، عن أبيه، فذكره.","grade":"حسن","chapter_ar":"باب شفاعة النبي ﷺ لكل من قال لا إله إلا الله ولم يشرك بالله ولو عمل الكبائر واستحق النار","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Tirmidhī (2433) and Aḥmad (12825).","chapter_en":"The Prophet’s ﷺ Intercession for Everyone Who Said “There Is No Deity Worthy of Worship Except Allah” and Did Not Associate Anything With Allah, Even if He Committed Major Sins and Deserved the Fire","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":5,"content":{"translation":{"en":["Anas, may Allah be pleased with him, said: I asked the Prophet ﷺ to intercede for me on the Day of Resurrection. He said: “I will do so.” I asked: “O Messenger of Allah, where should I look for you?” He said: “First look for me at the Ṣirāṭ.” I asked: “If I do not find you at the Ṣirāṭ?” He replied: “Then look for me at the Scale.” I asked: “If I do not find you at the Scale?” He replied: “Then look for me at the Basin, for I will not be absent from these three places.”"]},"buhuth":{"en":["Al-Tirmidhī said:","“A Ḥasan Gharīb ḥadīth.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (2433)، وأحمد (12825)."},{"num":910,"demo":false,"sanad":"","matn":["عَنْ أُمِّ حَبِيبَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أُرِيتُ مَا يَلْقَى أُمَّتِي بَعْدِي، وَسَفْكَ بَعْضِهِمْ دِمَاءَ بَعْضٍ، وَسَبَقَ ذَلِكَ مِنَ اللَّهِ كَمَا سَبَقَ فِي الأُمَمِ قَبْلَهُمْ، فَسَأَلْتُهُ أَنْ يُولِيَنِي شَفَاعَةً يَوْمَ الْقِيَامَةِ فِيهِمْ، فَفَعَلَ."],"takhrij":"صحيح: رواه ابن خزيمة في التوحيد (533)، وابن أبي عاصم في السنة (801)، والحاكم (227) كلّهم من طريق أبي اليمان، قال: حدّثنا شعيب، وهو ابن أبي حمزة، ، عن الزهريّ، عن أنس، عن أمِّ حبيبة، فذكرته.","grade":"صحيح","chapter_ar":"باب شفاعة النبي ﷺ لكل من قال لا إله إلا الله ولم يشرك بالله ولو عمل الكبائر واستحق النار","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Ibn Khuzaymah in al-Tawḥīd (533), Ibn Abī ʿĀṣim in al-Sunnah (801), and al-Ḥākim (227).","chapter_en":"The Prophet’s ﷺ Intercession for Everyone Who Said “There Is No Deity Worthy of Worship Except Allah” and Did Not Associate Anything With Allah, Even if He Committed Major Sins and Deserved the Fire","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":5,"content":{"translation":{"en":["Umm Ḥabībah may Allah be pleased with her reported that the Prophet ﷺ said: “I was shown what my Ummah will encounter after me, including some of them shedding the blood of others. That had already been decreed by Allah, just as it had been decreed for the nations before them. So I asked Him to grant me intercession concerning them on the Day of Resurrection, and He did so.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن خزيمة في التوحيد (533)، وابن أبي عاصم في السنة (801)، والحاكم (227)."},{"num":911,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ: مَا زِلْنَا نُمْسِكُ عَنِ الِاسْتِغْفَارِ لِأَهْلِ الْكَبَائِرِ حَتَّى سَمِعْنَا مِنْ فِي نَبِيِّنَا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى ﴿لَا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ﴾. [سورة النساء: 48]. قَالَ: فَإِنِّي أَخَّرْتُ شَفَاعَتِي لِأَهْلِ الْكَبَائِرِ مِنْ أُمَّتِي يَوْمَ الْقِيَامَةِ فَأَمْسَكْنَا عَنْ كَثِيرٍ مِمَّا كَانَ فِي أَنْفُسِنَا."],"takhrij":"حسن: رواه أبو يعلى (5813)، والطبراني في الأوسط (5942) - مجمع البحرين (4809)، وابن أبي عاصم في السنة (830) كلّهم من طريق شيبان بن فرّوخ الأيلي، ثنا حرب بن سُريج المنقريّ، ثنا أيوب السّختيانيّ، عن نافع، عن ابن عمر، فذكره.","grade":"حسن","chapter_ar":"باب شفاعة النبي ﷺ لكل من قال لا إله إلا الله ولم يشرك بالله ولو عمل الكبائر واستحق النار","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Abū Yaʿlā (5813), al-Ṭabarānī in al-Muʿjam al-Awsaṭ — Majmaʿ al-Baḥrayn (4809), and Ibn Abī ʿĀṣim in al-Sunnah (830).","chapter_en":"The Prophet’s ﷺ Intercession for Everyone Who Said “There Is No Deity Worthy of Worship Except Allah” and Did Not Associate Anything With Allah, Even if He Committed Major Sins and Deserved the Fire","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":5,"content":{"translation":{"en":["Ibn ʿUmar, may Allah be pleased with them, said: We continued refraining from seeking forgiveness for people who committed major sins until we heard our Prophet ﷺ say: “Indeed, Allah, Blessed and Exalted, does not forgive associating partners with Him, but He forgives whatever is less than that for whomever He wills.” He said: “I have postponed my intercession for those from my Ummah who committed major sins until the Day of Resurrection.” Thereafter, we restrained ourselves from much of what had previously been in our minds concerning them."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو يعلى (5813)، والطبراني في الأوسط — مجمع البحرين (4809)، وابن أبي عاصم في السنة (830)."},{"num":912,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، عَنْ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا زِلْتُ اشْفَعْ إِلَى رَبِّي وَيُشْفَعْنِي حَتَّى أَقُولَ: رَبّ شُفْعَنِي فِيمَنْ قَالَ: لَا إلَهَ إلَّا اللَّهُ. قَالَ: فَيَقُولُ: لَيْسَتْ هَذِهِ لَك يَا مُحَمَّدُ، إِنَّمَا هِيَ لِي، أَمَا وَعِزَّتِي وَحِلْمِي وَرَحْمَتِي لَا أَدَعَ فِي النَّارِ أَحَدًا أَوْ قَالَ: عَبْدًا قَالَ: لَا إلَهَ إلَّا اللَّهُ."],"takhrij":"حسن: رواه أبو يعلى (2786) عن هارون بن عبدالله، حدّثنا حماد بن مسعدة، عن عمران العمي، عن الحسن، عن أنس، فذكره.","grade":"حسن","chapter_ar":"باب شفاعة النبي ﷺ لكل من قال لا إله إلا الله ولم يشرك بالله ولو عمل الكبائر واستحق النار","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Abū Yaʿlā (2786).","chapter_en":"The Prophet’s ﷺ Intercession for Everyone Who Said “There Is No Deity Worthy of Worship Except Allah” and Did Not Associate Anything With Allah, Even if He Committed Major Sins and Deserved the Fire","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":5,"content":{"translation":{"en":["Anas may Allah be pleased with him reported that the Prophet ﷺ said: “I will continue interceding before my Lord, and He will continue accepting my intercession, until I say: ‘My Lord, allow me to intercede for whoever said: There is no deity worthy of worship except Allah.’ He will say: ‘This is not for you, O Muḥammad. Rather, this belongs to Me. By My Might, My Forbearance, and My Mercy, I will not leave in the Fire anyone—or he said: any servant—who said: There is no deity worthy of worship except Allah.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو يعلى (2786)."},{"num":913,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ قَالَ حِينَ يَسْمَعُ النِّدَاءَ: اللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ وَالصَّلَاةِ الْقَائِمَةِ آتِ مُحَمَّدًا الْوَسِيلَةَ وَالْفَضِيلَةَ وَابْعَثْهُ مَقَامًا مَحْمُودًا الَّذِي وَعَدْتَهُ، حَلَّتْ لَهُ شَفَاعَتِي يَوْمَ الْقِيَامَةِ."],"takhrij":"صحيح: رواه البخاريّ في الأذان (614) عن علي بن عياش، قال: حدّثنا شعيب بن أبي حمزة، عن محمد بن المنكدر، عن جابر بن عبدالله، فذكره.","grade":"صحيح","chapter_ar":"شفاعة النبي ﷺ لكل من دعا بالدعاء عند سماع النداء","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī in the Book of the Call to Prayer (614).","chapter_en":"The Prophet’s ﷺ Intercession for Everyone Who Recites the Supplication Upon Hearing the Call to Prayer","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":6,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh may Allah be pleased with them reported that the Messenger of Allah ﷺ said: “Whoever says when he hears the call to prayer: ‘O Allah, Lord of this complete call and the established prayer, grant Muḥammad al-Wasīlah and al-Faḍīlah, and raise him to the Praised Station which You have promised him,’ my intercession will become due for him on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[1904,10985],"tks":"صحيح: رواه البخاري (614)."},{"num":914,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنِ اسْتَطَاعَ أَنْ يَمُوتَ بِالْمَدِينَةِ فَلْيَمُتْ بِهَا، فَإِنِّي أَشْفَعُ لِمَنْ يَمُوتُ بِهَا."],"takhrij":"حسن: رواه الترمذيّ (3917)، وابن ماجه (3112) كلاهما من طريق معاذ بن هشام، قال: حدّثني أبي، عن أيوب، عن نافع، عن ابن عمر، فذكره.","grade":"حسن","chapter_ar":"باب شفاعة النبي ﷺ لمن مات في المدينة","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Tirmidhī (3917) and Ibn Mājah (3112).","chapter_en":"The Prophet’s ﷺ Intercession for Whoever Dies in Madinah","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":7,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar may Allah be pleased with them reported that the Prophet ﷺ said: “Whoever among you is able to die in Madinah, let him die there, for I will intercede for whoever dies there.”"]},"buhuth":{"en":["Al-Tirmidhī said:","“Ḥasan Gharīb.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (3917)، وابن ماجه (3112)."},{"num":915,"demo":false,"sanad":"","matn":["عَنِ الصُّمَيْتَةَ امْرَأَةٍ مِنْ بَنِي لَيْثِ بْنِ بَكْرٍ وَكَانَتْ يَتِيمَةً فِي حِجْرِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَسَمِعْتُهَا تُحَدِّثُ صَفِيَّةَ بِنْتَ أَبِي عُبَيْدٍ أَنَّهَا سَمِعَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ اسْتَطَاعَ مِنْكُمْ أَنْ يَمُوتَ بِالْمَدِينَةِ فَلْيَمُتْ بِهَا فَإِنَّهُ مَنْ يَمُوتُ بِهَا أَشْفَعُ لَهُ أَوْ أَشْهَدُ لَهُ."],"takhrij":"صحيح: رواه النّسائيّ في الكبرى(4271)، وابن أبي عاصم في الأحاد والمثاني (3382) من طريق عقيل، عن الزّهريّ، عن عبيد الله (ابن عبدالله بن عمر)، عن عبدالله بن عتبة، عن صميتة، فذكرته. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب شفاعة النبي ﷺ لمن مات في المدينة","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Nasāʾī in al-Sunan al-Kubrā (4271) and Ibn Abī ʿĀṣim in al-Āḥād wa al-Mathānī (3382).","chapter_en":"The Prophet’s ﷺ Intercession for Whoever Dies in Madinah","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":7,"content":{"translation":{"en":["Ṣumaytah—a woman from Banū Layth who was under the care of the Messenger of Allah ﷺ—said: I heard the Messenger of Allah ﷺ say: “Whoever among you is able to die in Madinah, let him die there, for whoever dies there, I will intercede for him on the Day of Resurrection and bear witness for him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي في الكبرى (4271)، وابن أبي عاصم في الآحاد والمثاني (3382)."},{"num":916,"demo":false,"sanad":"","matn":["عَنْ سُبَيْعَةَ بِنْتِ الْحَارِثِ الْأَسْلَمِيَّةِ، أَنَّ رَسُولَ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنِ اسْتَطَاعَ مِنْكُمْ أَنْ يَمُوتَ بِالْمَدِينَةِ فَلْيَمُتْ، فَإِنَّهُ لَا يَمُوتُ بِهَا أَحَدٌ إِلَّا كُنْتُ لَهُ شَفِيعًا أَوْ شَهِيدًا يَوْمَ الْقِيَامَةِ."],"takhrij":"حسن: رواه الطبرانيّ في الكبير (24/ح 747)، وأبو يعلى كما في المطالب العالية (2/67)، وأبو نعيم في الصحابة (7668) كلّهم من طريق عبدالعزيز بن محمد الدّراورديّ، عن أسامة بن زيد، عن عبدالله بن عكرمة، عن عبدالله بن عبدالله بن عمر بن الخطّاب، عن أبيه، عن سُبيعة الأسلميّة، فذكرته.","grade":"حسن","chapter_ar":"باب شفاعة النبي ﷺ لمن مات في المدينة","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Kabīr (24/294), Abū Yaʿlā, as cited in al-Maṭālib al-ʿĀliyah (2/67), and Abū Nuʿaym in Maʿrifat al-Ṣaḥābah (6/3349).","chapter_en":"The Prophet’s ﷺ Intercession for Whoever Dies in Madinah","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":7,"content":{"translation":{"en":["Subayʿah bint al-Ḥārith al-Aslamiyyah may Allah be pleased with her reported that the Messenger of Allah ﷺ said: “Whoever among you is able to die in Madinah, let him die there, because no one dies there except that I will be an intercessor for him or a witness for him on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (24/ح 747)، وأبو يعلى كما في المطالب العالية (2/67)، وأبو نعيم في معرفة الصحابة (7668)."},{"num":917,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لَا يَصْبِرُ عَلَى لَأْوَائِهَا وَشِدَّتِهَا أَحَدٌ، إِلَّا كُنْتُ لَهُ شَفِيعًا أَوْ شَهِيدًا يَوْمَ الْقِيَامَةِ."],"takhrij":"صحيح: رواه مالك في كتاب الجامع (3) عن قطن بن وهب بن عُمير بن الأجدع، أن يُحَنَّس مولى الزّبير بن العوّام أخبره، أنّه كان جالساً عند عبدالله بن عمر في الفتنة، فأتَتْه مولاةً له تُسلم عليه، فقالت: إنّي أردت الخروجَ يا أبا عبدالرحمن اشتدّ علينا الزّمان. فقال لها عبدالله بن عمر: اقعدي لَكاعِ فإنّي سمعتُ رسول الله صلى الله عليه وسلم يقول (فذكر الحديث).","grade":"صحيح","chapter_ar":"باب شفاعة النبي ﷺ لمن صبر على لأواء المدينة","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Mālik in Kitāb al-Jāmiʿ (3).","chapter_en":"The Prophet’s ﷺ Intercession for Whoever Patiently Endures the Hardships of Madinah","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":8,"content":{"translation":{"en":["Ibn ʿUmar, may Allah be pleased with them, said: I heard the Messenger of Allah ﷺ say: “No one patiently endures its hardships and severity except that I will be an intercessor for him or a witness for him on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (3)."},{"num":918,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيَّ يَقُولُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لَا يَصْبِرُ أَحَدٌ عَلَى لَأْوَائِهَا فَيَمُوتَ، إِلَّا كُنْتُ لَهُ شَفِيعًا، أَوْ شَهِيدًا يَوْمَ الْقِيَامَةِ إِذَا كَانَ مُسْلِمًا."],"takhrij":"صحيح: رواه مسلم في الحجّ (1374: 477) عن قتيبة بن سعيد، حدّثنا ليث، عن سعيد بن أبي سعيد، عن أبي سعيد مولى المهْريّ أنّه جاء أبا سعيد الخدريّ ليالي الحرّة فاستشاره في الجلاء من المدينة، وشكا إليه أسعارَها وكثرةَ عياله، وأخبره أن لا صَبْرَ له على جَهْد المدينة ولأَوائها. فقال له: ويحك لا آمرُك بذلك، إنّي سمعتُ رسول الله صلى الله عليه وسلم يقول (فذكر الحديث).","grade":"صحيح","chapter_ar":"باب شفاعة النبي ﷺ لمن صبر على لأواء المدينة","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (1374).","chapter_en":"The Prophet’s ﷺ Intercession for Whoever Patiently Endures the Hardships of Madinah","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":8,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī, may Allah be pleased with him, said: I heard the Messenger of Allah ﷺ say: “No one patiently endures its hardships and then dies except that I will be an intercessor for him or a witness for him on the Day of Resurrection, provided that he was a Muslim.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1374)."},{"num":919,"demo":false,"sanad":"","matn":["عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ قَالَ (فَذَكَرَ الْحَدِيثَ): قَالَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْمَدِينَةُ خَيْرٌ لَهُمْ لَوْ كَانُوا يَعْلَمُونَ، لَا يَدَعُهَا أَحَدٌ رَغْبَةً عَنْهَا، إِلَّا أَبْدَلَ اللَّهُ فِيهَا مَنْ هُوَ خَيْرٌ مِنْهُ، وَلَا يَثْبُتُ أَحَدٌ عَلَى لَأْوَائِهَا وَجَهْدِهَا، إِلَّا كُنْتُ لَهُ شَفِيعًا، أَوْ شَهِيدًا يَوْمَ الْقِيَامَةِ."],"takhrij":"صحيح: رواه مسلم في الحج (1363) من طريق عثمان بن حكيم، حدّثني عامر بن سعد، عن أبيه (سعد بن أبي وقاص) قال (فذكر الحديث).","grade":"صحيح","chapter_ar":"باب شفاعة النبي ﷺ لمن صبر على لأواء المدينة","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (1363).","chapter_en":"The Prophet’s ﷺ Intercession for Whoever Patiently Endures the Hardships of Madinah","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":8,"content":{"translation":{"en":["Saʿd ibn Abī Waqqāṣ may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Madinah is better for them, if only they knew. No one leaves it out of aversion to it except that Allah replaces him in it with someone better than him. And no one remains steadfast through its hardships and difficulties except that I will be an intercessor for him or a witness for him on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1363)."},{"num":920,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا يَصْبِرُ عَلَى لَأْوَاءِ الْمَدِينَةِ، وَشِدَّتِهَا أَحَدٌ مِنْ أُمَّتِي، إِلَّا كُنْتُ لَهُ شَفِيعًا يَوْمَ الْقِيَامَةِ، أَوْ شَهِيدًا."],"takhrij":"صحيح: رواه مسلم في الحجّ (1378) من طرق عن إسماعيل بن جعفر، عن العلاء بن عبدالرحمن، عن أبيه، عن أبي هريرة، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب شفاعة النبي ﷺ لمن صبر على لأواء المدينة","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (1378).","chapter_en":"The Prophet’s ﷺ Intercession for Whoever Patiently Endures the Hardships of Madinah","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":8,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “No one from my Ummah patiently endures the hardships and severity of Madinah except that I will be an intercessor for him on the Day of Resurrection or a witness for him.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10633],"tks":"صحيح: رواه مسلم (1378)."},{"num":921,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَذُكِرَ عِنْدَهُ عَمُّهُ، فَقَالَ: لَعَلَّهُ تَنْفَعُهُ شَفَاعَتِي يَوْمَ الْقِيَامَةِ، فَيُجْعَلُ فِي ضَحْضَاحٍ مِنَ النَّارِ يَبْلُغُ كَعْبَيْهِ يَغْلِي مِنْهُ دِمَاغُهُ."],"takhrij":"متفق عليه: رواه البخاريّ في المناقب (3885)، ومسلم في الإيمان (210) من حديث اللّيث بن سعد، حدّثنا ابن الهاد، عن عبدالله بن خبّاب، عن أبي سعيد الخدريّ فذكره.","grade":"متفق عليه","chapter_ar":"باب شفاعة النبي ﷺ لأبي طالب لتخفيف العذاب عنه","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3885) and Muslim (210).","chapter_en":"The Prophet’s ﷺ Intercession for Abū Ṭālib So That His Punishment May Be Lessened","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":9,"content":{"translation":{"en":["Abū Saʿīd may Allah be pleased with him reported that he heard the Prophet ﷺ, when his uncle was mentioned in his presence, say: “Perhaps my intercession will benefit him on the Day of Resurrection, so he will be placed in a shallow part of the Fire reaching his ankles, because of which his brain will boil.”"]},"buhuth":{"en":["The word:","“ḍaḥḍāḥ”","refers to shallow water spread over the surface of the ground, reaching approximately to the ankles. The expression is used figuratively here for the Fire."]}},"tuhfa":{},"full":1,"dr":1,"rep":[8604,16182],"tks":"متفق عليه: رواه البخاري (3885)، ومسلم (210)."},{"num":922,"demo":false,"sanad":"","matn":["عَنْ الْعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ، أَنَّهُ قَالَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا أَغْنَيْتَ عَنْ عَمِّكَ فَإِنَّهُ كَانَ يَحُوطُكَ وَيَغْضَبُ لَكَ، قَالَ: هُوَ فِي ضَحْضَاحٍ مِنْ نَارٍ، وَلَوْلَا أَنَا لَكَانَ فِي الدَّرَكِ الْأَسْفَلِ مِنَ النَّارِ."],"takhrij":"متفق عليه: رواه البخاريّ في المناقب (3883)، ومسلم في الإيمان (209) كلاهما من حديث يحيى بن سعيد، عن سفيان، حدّثنا عبدالملك بن عمير، حدّثنا عبدالله بن الحارث، حدّثنا عباس بن عبدالمطلب، فذكره.","grade":"متفق عليه","chapter_ar":"باب شفاعة النبي ﷺ لأبي طالب لتخفيف العذاب عنه","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3883) and Muslim (209).","chapter_en":"The Prophet’s ﷺ Intercession for Abū Ṭālib So That His Punishment May Be Lessened","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":9,"content":{"translation":{"en":["Al-ʿAbbās ibn ʿAbd al-Muṭṭalib may Allah be pleased with him said to the Prophet ﷺ: “What benefit have you brought to your uncle? He used to protect you and become angry on your behalf.” He replied: “He is in a shallow part of the Fire. Were it not for me, he would have been in the lowest depth of the Fire.”"]},"buhuth":{"en":["In a wording narrated by Muslim:","I said:","“O Messenger of Allah, Abū Ṭālib used to protect you and support you. Did that benefit him?”","He replied:","“Yes. I found him in the depths of the Fire, and I brought him out to a shallow part of it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3883)، ومسلم (209)."},{"num":923,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أُعْطِيتُ خَمْسًا لَمْ يُعْطَهُنَّ أَحَدٌ مِنَ الْأَنْبِيَاءِ قَبْلِي نُصِرْتُ بِالرُّعْبِ مَسِيرَةَ شَهْرٍ، وَجُعِلَتْ لِي الْأَرْضُ مَسْجِدًا وَطَهُورًا، وَأَيُّمَا رَجُلٍ مِنْ أُمَّتِي أَدْرَكَتْهُ الصَّلَاةُ فَلْيُصَلِّ وَأُحِلَّتْ لِي الْغَنَائِمُ، وَكَانَ النَّبِيُّ يُبْعَثُ إِلَى قَوْمِهِ خَاصَّةً، وَبُعِثْتُ إِلَى النَّاسِ كَافَّةً، وَأُعْطِيتُ الشَّفَاعَةَ."],"takhrij":"متفق عليه: رواه البخاريّ في الصّلاة (438)، ومسلم في المساجد (521) كلاهما من حديث هُشيم، عن سيار، عن يزيد الفقير، عن جابر بن عبدالله، فذكره.","grade":"متفق عليه","chapter_ar":"باب ما فُضِّل به النبي ﷺ على غيره من الأنبياء، ومنها الشفاعة","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (438) and Muslim (521).","chapter_en":"What the Prophet ﷺ Was Favored With Over the Other Prophets, Including Intercession","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":10,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh may Allah be pleased with them reported that the Messenger of Allah ﷺ said: “I have been given five things which were not given to any prophet before me: I have been aided by fear cast into the enemy from the distance of a month’s journey; the earth has been made for me a place of prayer and a means of purification, so wherever a man from my Ummah is when the time for prayer reaches him, let him pray; the spoils of war have been made lawful for me; a prophet used to be sent specifically to his own people, whereas I have been sent to all mankind; and I have been granted intercession.”"]}},"tuhfa":{},"full":1,"rep":[730,795],"tks":"متفق عليه: رواه البخاري (438)، ومسلم (521)."},{"num":924,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أُوتِيتُ خَمْسًا لَمْ يُؤْتَهُنَّ نَبِيٌّ كَانَ قَبْلِي نُصِرْتُ بِالرُّعْبِ، فَيُرْعَبُ مِنِّي الْعَدُوُّ عَنْ مَسِيرَةِ شَهْرٍ، وَجُعِلَتْ لِي الْأَرْضُ مَسْجِدًا وَطَهُورًا، وَأُحِلَّتْ لِي الْغَنَائِمُ وَلَمْ تَحِلَّ لِأَحَدٍ كَانَ قَبْلِي، وَبُعِثْتُ إِلَى الْأَحْمَرِ وَالْأَسْوَدِ، وَقِيلَ لِي: سَلْ تُعْطَهْ، فَاخْتَبَأْتُهَا شَفَاعَةً لِأُمَّتِي، وَهِيَ نَائِلَةٌ مِنْكُمْ إِنْ شَاءَ اللَّهُ، مَنْ لَقِيَ اللَّهَ لَا يُشْرِكُ بِهِ شَيْئًا."],"takhrij":"حسن: رواه الإمام أحمد (21299) عن يعقوب، حدّثنا أبي، عن ابن إسحاق، حدّثني سليمان الأعمش، عن مجاهد بن جبر أبي الحجّاج، عن عبيد بن عمير اللّيثيّ، عن أبي ذر، قال: فذكره.","grade":"حسن","chapter_ar":"باب ما فُضِّل به النبي ﷺ على غيره من الأنبياء، ومنها الشفاعة","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (21299).","chapter_en":"What the Prophet ﷺ Was Favored With Over the Other Prophets, Including Intercession","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":10,"content":{"translation":{"en":["Abū Dharr may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “I was given five things which no prophet before me was given: I was aided by fear, so that the enemy fears me from the distance of a month’s journey; the earth was made for me a place of prayer and a means of purification; the spoils of war were made lawful for me, though they had not been made lawful for anyone before me; I was sent to the red and the black; and it was said to me: ‘Ask, and you will be given.’ So I reserved it as intercession for my Ummah. It will reach — if Allah wills — whoever among you meets Allah without associating anything with Him.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[732,797],"tks":"حسن: رواه الإمام أحمد (21299)."},{"num":925,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَامَ غَزْوَةِ تَبُوكَ قَامَ مِنَ اللَّيْلِ يُصَلِّي، فَاجْتَمَعَ وَرَاءَهُ رِجَالٌ مِنْ أَصْحَابِهِ يَحْرُسُونَهُ، حَتَّى إِذَا صَلَّى وَانْصَرَفَ إِلَيْهِمْ، فَقَالَ لَهُمْ: لَقَدْ أُعْطِيتُ اللَّيْلَةَ خَمْسًا، مَا أُعْطِيَهُنَّ أَحَدٌ قَبْلِي: أَمَّا أَنَا فَأُرْسِلْتُ إِلَى النَّاسِ كُلِّهِمْ عَامَّةً، وَكَانَ مَنْ قَبْلِي إِنَّمَا يُرْسَلُ إِلَى قَوْمِهِ، وَنُصِرْتُ عَلَى الْعَدُوِّ بِالرُّعْبِ، وَلَوْ كَانَ بَيْنِي وَبَيْنَهُمْ مَسِيرَةُ شَهْرٍ لَمُلِئَ مِنْهُ رُعْبًا، وَأُحِلَّتْ لِي الْغَنَائِمُ آكُلُهَا، وَكَانَ مَنْ قَبْلِي يُعَظِّمُونَ أَكْلَهَا، كَانُوا يُحْرِقُونَهَا، وَجُعِلَتْ لِي الْأَرْضُ مَسَاجِدَ وَطَهُورًا، أَيْنَمَا أَدْرَكَتْنِي الصَّلَاةُ تَمَسَّحْتُ وَصَلَّيْتُ، وَكَانَ مَنْ قَبْلِي يُعَظِّمُونَ ذَلِكَ، إِنَّمَا كَانُوا يُصَلُّونَ فِي كَنَائِسِهِمْ وَبِيَعِهِمْ، وَالْخَامِسَةُ، هِيَ مَا هِيَ، قِيلَ لِي سَلْ، فَإِنَّ كُلَّ نَبِيٍّ قَدْ سَأَلَ، فَأَخَّرْتُ مَسْأَلَتِي إِلَى يَوْمِ الْقِيَامَةِ، فَهِيَ لَكُمْ وَلِمَنْ شَهِدَ أَنْ لَا إِلَهَ إِلَّا اللَّهُ."],"takhrij":"حسن: رواه الإمام أحمد (7068) عن قتيبة بن سعيد، حدّثنا بكر بن مُضر، عن ابن الهاد، عن عمرو بن شعيب، عن أبيه، عن جدّه، فذكره.","grade":"حسن","chapter_ar":"باب ما فُضِّل به النبي ﷺ على غيره من الأنبياء، ومنها الشفاعة","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (7068).","chapter_en":"What the Prophet ﷺ Was Favored With Over the Other Prophets, Including Intercession","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":10,"content":{"translation":{"en":["ʿAmr ibn Shuʿayb narrated from his father, from his grandfather: During the year of the expedition of Tabūk, the Messenger of Allah ﷺ stood in prayer during the night. Men from among his Companions gathered behind him to guard him. When he finished praying and turned toward them, he said: “Tonight I have been given five things which no one before me was given: As for me, I have been sent universally to all people, whereas those before me were sent only to their own peoples; I have been granted victory over the enemy through fear, and even if there were a month’s journey between me and them, they would be filled with fear of me; the spoils of war have been made lawful for me to consume, whereas those before me regarded consuming them as a grave matter and would burn them; the earth has been made for me a place of prayer and a means of purification. Wherever prayer reaches me, I perform tayammum and pray, whereas those before me regarded this as a grave matter and would pray only in their churches and places of worship; and as for the fifth — it is what it is: it was said to me: ‘Ask, for every prophet has asked.’ So I postponed my request until the Day of Resurrection. It is for you and for whoever testifies that there is no deity worthy of worship except Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[799,8012,9634],"tks":"حسن: رواه الإمام أحمد (7068)."},{"num":926,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أُعْطِيتُ خَمْسًا لَمْ يُعْطَهُنَّ نَبِيٌّ قَبْلِي، وَلَا أَقُولُهُنَّ فَخْرًا: بُعِثْتُ إِلَى النَّاسِ كَافَّةً، الْأَحْمَرِ وَالْأَسْوَدِ، وَنُصِرْتُ بِالرُّعْبِ مَسِيرَةَ شَهْرٍ، وَأُحِلَّتْ لِي الْغَنَائِمُ، وَلَمْ تَحِلَّ لِأَحَدٍ قَبْلِي، وَجُعِلَتْ لِي الْأَرْضُ مَسْجِدًا وَطَهُورًا، وَأُعْطِيتُ الشَّفَاعَةَ، فَأَخَّرْتُهَا لِأُمَّتِي، فَهِيَ لِمَنْ لَا يُشْرِكُ بِاللَّهِ شَيْئًا."],"takhrij":"حسن: رواه الإمام أحمد (2742)، والبزّار- كشف الأستار (3460)، وابن أبي عاصم في السنة (803) كلّهم من طريق يزيد بن أبي زياد، عن مجاهد، عن ابن عباس، فذكره، ولفظهم سواء.","grade":"حسن","chapter_ar":"باب ما فُضِّل به النبي ﷺ على غيره من الأنبياء، ومنها الشفاعة","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Aḥmad (2742), al-Bazzār in Kashf al-Astār (3460), and Ibn Abī ʿĀṣim in al-Sunnah (803).","chapter_en":"What the Prophet ﷺ Was Favored With Over the Other Prophets, Including Intercession","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":10,"content":{"translation":{"en":["Ibn ʿAbbās may Allah be pleased with them reported that the Messenger of Allah ﷺ said: “I have been given five things which no prophet before me was given, and I do not say this boastfully: I was sent to all mankind, the red and the black; I was aided by fear cast into the enemy from the distance of a month’s journey; the spoils of war were made lawful for me, though they had not been lawful for anyone before me; the earth was made for me a place of prayer and a means of purification; and I was given intercession. I postponed it for my Ummah, and it is for whoever does not associate anything with Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (2742)، والبزار في كشف الأستار (3460)، وابن أبي عاصم في السنة (803)."},{"num":927,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: صِنْفَانِ مِنْ أُمَّتِي لَنْ تَنَالَهُمَا شَفَاعَتِي: إِمَامٌ ظَلُومٌ، وَكُلُّ غَالٍ مَارِقٍ."],"takhrij":"حسن: رواه الطبرانيّ في الكبير (8079) عن معاذ بن المثنى ومحمد بن التمار البصريّ، قالا: ثنا مسدّد، ثنا جعفر بن سليمان، عن المعلى بن زياد الفردوسيّ، عن أبي غالب، عن أبي أمامة، فذكره.","grade":"حسن","chapter_ar":"باب من لا تناله شفاعة النبي ﷺ","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Kabīr (8/337).","chapter_en":"Those Whom the Prophet’s ﷺ Intercession Will Not Reach","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":11,"content":{"translation":{"en":["Abū Umāmah al-Bāhilī may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Two categories from my Ummah will not be reached by my intercession: a tyrannical ruler, and every extremist who departs from the proper path.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (8079)."},{"num":928,"demo":false,"sanad":"","matn":["عَنْ مَعْقِلِ بْنِ يَسَارٍ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: رَجُلَانِ مِنْ أُمَّتِي لَا يَنَالُهُمَا شَفَاعَتِي: سُلْطَانٌ ظَلُومٌ غَشُومٌ، وَآخَرُ غَالٍ فِي الدِّينِ مَارِقٌ مِنْهُ."],"takhrij":"حسن: رواه الطبراني في الكبير (20/ح 496)، وابن أبي عاصم في السنة (41) كلاهما من حديث ابن المبارك، قال: أخبرني منيع، حدّثني معاوية بن قرّة، عن معقل بن يسار، فذكره.","grade":"حسن","chapter_ar":"باب من لا تناله شفاعة النبي ﷺ","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Kabīr (20/214) and Ibn Abī ʿĀṣim in al-Sunnah (41).","chapter_en":"Those Whom the Prophet’s ﷺ Intercession Will Not Reach","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":11,"content":{"translation":{"en":["Maʿqil ibn Yasār may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Two men will not be reached by my intercession: a tyrannical and hostile ruler, and another who goes to extremes in religion and departs from it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (20/ح 496)، وابن أبي عاصم في السنة (41)."},{"num":929,"demo":false,"sanad":"","matn":["عَنْ أَبِي الدَّرْدَاءِ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ اللَّعَّانِينَ لَا يَكُونُونَ شُهَدَاءَ وَلَا شُفَعَاءَ يَوْمَ الْقِيَامَةِ."],"takhrij":"صحيح: رواه مسلم في البر والصلة (2598) عن أبي بكر بن أبي شيبة، حدّثنا معاوية بن هشام، عن هشام بن سعد، عن زيد بن أسلم وأبي حازم، عن أمِّ الدّرداء، عن أبي الدّرداء، فذكره.","grade":"صحيح","chapter_ar":"باب من لا تكون له الشفاعة","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2598).","chapter_en":"Those Who Will Not Have Intercession","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":12,"content":{"translation":{"en":["Abū al-Dardāʾ, may Allah be pleased with him, said: I heard the Messenger of Allah ﷺ say: “Those who frequently curse others will not be witnesses or intercessors on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2598)."},{"num":930,"demo":false,"sanad":"","matn":["عَنْ رَبِيعَةَ بْنِ كَعْبٍ الْأَسْلَمِيِّ قَالَ: كُنْتُ أَبِيتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَتَيْتُهُ بِوَضُوئِهِ وَحَاجَتِهِ، فَقَالَ لِي: سَلْ، فَقُلْتُ: أَسْأَلُكَ مُرَافَقَتَكَ فِي الْجَنَّةِ؟ قَالَ: أَوَغَيْرَ ذَلِك؟ قُلْتُ: هُوَ ذَاكَ، قَالَ: فَأَعِنِّي عَلَى نَفْسِكَ، بِكَثْرَةِ السُّجُودِ."],"takhrij":"صحيح: رواه مسلم في الصلاة (489) عن الحكم بن موسى أبي صالح، حدثنا حِقْل بن زياد قال: سمعت الأوزاعي قال: حدثني يحي بن أبي كثير، حدثني أبو سلمة، حدثني ربيعة بن كعب فذكره","grade":"صحيح","chapter_ar":"باب طلب الشفاعة من النبي ﷺ","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (489).","chapter_en":"Seeking Intercession From the Prophet ﷺ","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":13,"content":{"translation":{"en":["Rabīʿah ibn Kaʿb al-Aslamī, may Allah be pleased with him, said: I used to spend the night with the Messenger of Allah ﷺ and would bring him water for his ablution and whatever else he needed. He said to me: “Ask.” I said: “I ask you for your companionship in Paradise.” He asked: “Or anything other than that?” I replied: “That is what I want.” He said: “Then help me concerning yourself by making abundant prostrations.”"]}},"tuhfa":{},"full":1,"rep":[2114],"tks":"صحيح: رواه مسلم (489)."},{"num":931,"demo":false,"sanad":"","matn":["عَنْ خَادِمٍ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلٍ أَوْ امْرَأَةٍ، قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِمَّا يَقُولُ لِلْخَادِمِ: أَلَكَ حَاجَةٌ؟ قَالَ: حَتَّى كَانَ ذَاتَ يَوْمٍ، فَقَالَ: يَا رَسُولَ اللَّهِ حَاجَتِي، قَالَ: وَمَا حَاجَتُكَ؟ قَالَ: حَاجَتِي أَنْ تَشْفَعَ لِي يَوْمَ الْقِيَامَةِ، قَالَ: وَمَنْ دَلَّكَ عَلَى هَذَا؟ قَالَ: رَبِّي، قَالَ: إِمَّا لَا فَأَعِنِّي بِكَثْرَةِ السُّجُودِ."],"takhrij":"صحيح: رواه أحمد (16076) عن عفّان، حدّثنا خالد، يعني الواسطيّ، قال: حدّثنا عمرو بن يحيى الأنصاريّ، عن زياد بن أبي زياد مولى بني مخزوم، عن خادم، فذكره.","grade":"صحيح","chapter_ar":"باب طلب الشفاعة من النبي ﷺ","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Aḥmad (16076).","chapter_en":"Seeking Intercession From the Prophet ﷺ","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":13,"content":{"translation":{"en":["A servant of the Prophet ﷺ, either a man or a woman, reported: Among the things the Prophet ﷺ would say to the servant was: “Do you have any need?” Then one day the servant said: “O Messenger of Allah, I have a need.” He asked: “What is your need?” The servant replied: “My need is that you intercede for me on the Day of Resurrection.” He asked: “Who directed you to this?” The servant replied: “My Lord.” He said: “Then, if that is what you seek, help me through abundant prostration.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2115],"tks":"صحيح: رواه أحمد (16076)."},{"num":932,"demo":false,"sanad":"","matn":["عَنْ رَبِيعَةَ بْنِ كَعْبٍ قَالَ: قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: سَلْنِي أُعْطِكَ، قُلْتُ: يَا رَسُولَ اللَّهِ، أَنْظِرْنِي أَنْظُرْ فِي أَمْرِي، قَالَ: فَانْظُرْ فِي أَمْرِكَ، قَالَ: فَنَظَرْتُ، فَقُلْتُ: إِنَّ أَمْرَ الدُّنْيَا يَنْقَطِعُ، فَلَا أَرَى شَيْئًا خَيْرًا مِنْ شَيْءٍ آخُذُهُ لِنَفْسِي لِآخِرَتِي، فَدَخَلْتُ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: مَا حَاجَتُكَ، فَقُلْتُ: يَا رَسُولَ اللَّهِ، اشْفَعْ لِي إِلَى رَبِّكَ عَزَّ وَجَلَّ، فَلْيُعْتِقْنِي مِنَ النَّارِ، فَقَالَ: مَنْ أَمَرَكَ بِهَذَا؟، فَقُلْتُ: لَا وَاللَّهِ يَا رَسُولَ اللَّهِ، مَا أَمَرَنِي بِهِ أَحَدٌ، وَلَكِنِّي نَظَرْتُ فِي أَمْرِي، فَرَأَيْتُ أَنَّ الدُّنْيَا زَائِلَةٌ مِنْ أَهْلِهَا، فَأَحْبَبْتُ أَنْ آخُذَ لِآخِرَتِي، قَالَ: فَأَعِنِّي عَلَى نَفْسِكَ بِكَثْرَةِ السُّجُودِ."],"takhrij":"حسن: رواه الإمام أحمد (16578) عن أبي اليمان، قال: حدثنا إسماعيل بن عياش، عن محمد بن إسحاق، عن محمد بن عمرو بن عطاء، عن نعيم بن مجمرة، عن ربيعة وفيه إسماعيل بن عياش وهو ضعيف في روايته عن غير أهل بلده، وهذا منها، ولكنه تابع.","grade":"حسن","chapter_ar":"باب طلب الشفاعة من النبي ﷺ","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (16578, 16579).","chapter_en":"Seeking Intercession From the Prophet ﷺ","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":13,"content":{"translation":{"en":["Rabīʿah ibn Kaʿb, may Allah be pleased with him, said: The Messenger of Allah ﷺ said to me: “Ask me, and I will give you.” I said: “O Messenger of Allah, give me time to consider my matter.” He said: “Then consider your matter.” I reflected and said: “The affair of this world will come to an end, so I see nothing better than something I can take for myself for my Hereafter.” I then entered upon the Prophet ﷺ, and he asked: “What is your need?” I replied: “O Messenger of Allah, intercede for me with your Lord, Mighty and Majestic, so that He may free me from the Fire.” He asked: “Who instructed you to ask for this?” I replied: “No, by Allah, O Messenger of Allah, no one instructed me. But I considered my situation and saw that this world is passing away from its people, so I wished to obtain something for my Hereafter.” He said: “Then help me concerning yourself by making abundant prostrations.”"]},"buhuth":{"en":["In the wording of the second narration, he said:","I used to serve the Messenger of Allah ﷺ and attend to his needs throughout the entire day until the Messenger of Allah ﷺ performed the final ʿIshāʾ prayer.","Then I would sit at his door after he entered his house, saying to myself:","“Perhaps the Messenger of Allah ﷺ may have some need.”","I would continue hearing him say:","“Glory be to Allah, glory be to Allah, glory be to Allah and praise be to Him.”","Eventually I would become weary and return, or sleep would overcome me and I would fall asleep.","One day, after seeing how prompt and attentive I was in serving him, he said:","“Ask me, O Rabīʿah, and I will give you.”","I said:","“Let me consider my matter, O Messenger of Allah, then I will tell you.”","I reflected within myself and realized that this world is temporary and passing away, and that whatever provision has been allotted to me in it will suffice me and will come to me.","So I said:","“I will ask the Messenger of Allah ﷺ for something concerning my Hereafter, for he has with Allah, Mighty and Majestic, the rank that he has.”","I then came to him, and he asked:","“What have you decided, O Rabīʿah?”","I replied:","“Yes, O Messenger of Allah. I ask you to intercede for me with your Lord so that He may free me from the Fire.”","He asked:","“Who instructed you to ask for this, O Rabīʿah?”","I replied:","“No, by the One who sent you with the truth, no one instructed me. But when you said:","‘Ask me and I will give you,’","and knowing the rank you have with Allah, I considered my situation and realized that this world is temporary and passing away, while the provision allotted to me in it will come to me. So I said:","‘I will ask the Messenger of Allah ﷺ for something concerning my Hereafter.’”","The Messenger of Allah ﷺ remained silent for a long time, then said to me:","“I will do so. Therefore, help me concerning yourself by making abundant prostrations.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (16578، 16579)."},{"num":933,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا مِنْ مَيِّتٍ يُصَلِّي عَلَيْهِ أُمَّةٌ مِنَ الْمُسْلِمِينَ يَبْلُغُونَ مِائَةً كُلُّهُمْ يَشْفَعُونَ لَهُ إِلَّا شُفِّعُوا فِيهِ."],"takhrij":"صحيح: رواه مسلم في الجنائز (947) عن الحسن بن عيسى، حدّثنا ابن المبارك، أخبرنا سلاّم بن أبي مُطيع، عن أيوب، عن أبي قلابة، عن عبدالله بن يزيد رضيع عائشة، عن عائشة، فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء في شفاعة المصلين للميت","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (947).","chapter_en":"What Has Been Reported Concerning the Intercession of Those Who Pray Over the Deceased","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":14,"content":{"translation":{"en":["ʿĀʾishah may Allah be pleased with her reported that the Prophet ﷺ said: “There is no deceased person over whom a group of one hundred Muslims perform the funeral prayer, all of them interceding for him, except that their intercession for him will be accepted.”"]},"buhuth":{"en":["He said: “I then narrated it to Shuʿayb ibn al-Ḥabḥāb, and he said: Anas ibn Mālik narrated it to me from the Prophet ﷺ.” The speaker in “I then narrated it to Shuʿayb” is Sallām ibn Abī Muṭīʿ; he narrates it by two routes: one from Ayyūb, from Abū Qilābah, from ʿAbdullāh ibn Yazīd, from ʿĀʾishah, and the second through Shuʿayb ibn al-Ḥabḥāb, from Anas ibn Mālik, from the Prophet ﷺ."]}},"tuhfa":{},"full":1,"dr":1,"rep":[3725],"tks":"صحيح: رواه مسلم (947)."},{"num":934,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّهُ مَاتَ ابْنٌ لَهُ بِقُدَيْدٍ أَوْ بِعُسْفَانَ، فَقَالَ: يَا كُرَيْبُ انْظُرْ مَا اجْتَمَعَ لَهُ مِنَ النَّاسِ، قَالَ: فَخَرَجْتُ فَإِذَا نَاسٌ قَدِ اجْتَمَعُوا لَهُ، فَأَخْبَرْتُهُ فَقَالَ: تَقُولُ هُمْ أَرْبَعُونَ، قَالَ: نَعَمْ، قَالَ: أَخْرِجُوهُ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ: مَا مِنْ رَجُلٍ مُسْلِمٍ يَمُوتُ، فَيَقُومُ عَلَى جَنَازَتِهِ أَرْبَعُونَ رَجُلًا لَا يُشْرِكُونَ بِاللَّهِ شَيْئًا، إِلَّا شَفَّعَهُمُ اللَّهُ فِيهِ."],"takhrij":"صحيح: رواه مسلم في الجنائز (948) من طرق عن أبي صخر، عن شريك ابن عبدالله بن أبي نمير، عن كريب مولى ابن عباس، عن عبدالله بن عباس، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في شفاعة المصلين للميت","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (948).","chapter_en":"What Has Been Reported Concerning the Intercession of Those Who Pray Over the Deceased","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":14,"content":{"translation":{"en":["Ibn ʿAbbās may Allah be pleased with them had a son who died at Qudayd or ʿUsfān. He said: “O Kurayb, see how many people have gathered for him.” Kurayb said: I went out and found that a number of people had gathered, so I informed him. He asked: “Would you say that they are forty?” I replied: “Yes.” He said: “Bring him out, for I heard the Messenger of Allah ﷺ say: ‘No Muslim man dies and forty men who associate nothing with Allah stand to perform his funeral prayer except that Allah accepts their intercession for him.’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (948)."},{"num":935,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ (فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ): قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: حَتَّى إِذَا خَلَصَ الْمُؤْمِنُونَ مِنَ النَّارِ، فَوَالَّذِي نَفْسِي بِيَدِهِ، مَا مِنْكُمْ مِنْ أَحَدٍ بِأَشَدَّ مُنَاشَدَةً لِلَّهِ فِي اسْتِقْصَاءِ الْحَقِّ مِنَ الْمُؤْمِنِينَ، لِلَّهِ يَوْمَ الْقِيَامَةِ لِإِخْوَانِهِمُ الَّذِينَ فِي النَّارِ، يَقُولُونَ: رَبَّنَا كَانُوا يَصُومُونَ مَعَنَا، وَيُصَلُّونَ، وَيَحُجُّونَ، فَيُقَالُ لَهُمْ: أَخْرِجُوا مَنْ عَرَفْتُمْ، فَتُحَرَّمُ صُوَرُهُمْ عَلَى النَّار، فَيُخْرِجُونَ خَلْقًا كَثِيرًا قَدْ أَخَذَتِ النَّارُ إِلَى نِصْفِ سَاقَيْهِ وَإِلَى رُكْبَتَيْهِ، ثُمَّ يَقُولُونَ: رَبَّنَا مَا بَقِيَ فِيهَا أَحَدٌ مِمَّنْ أَمَرْتَنَا بِهِ، فَيَقُولُ: ارْجِعُوا، فَمَنْ وَجَدْتُمْ فِي قَلْبِهِ مِثْقَالَ دِينَارٍ مِنْ خَيْرٍ، فَأَخْرِجُوهُ فَيُخْرِجُونَ خَلْقًا كَثِيرًا، ثُمَّ يَقُولُونَ: رَبَّنَا لَمْ نَذَرْ فِيهَا أَحَدًا مِمَّنْ أَمَرْتَنَا، ثُمَّ يَقُولُ: ارْجِعُوا فَمَنْ وَجَدْتُمْ فِي قَلْبِهِ مِثْقَالَ نِصْفِ دِينَارٍ مِنَ خَيْرٍ فَأَخْرِجُوهُ، فَيُخْرِجُونَ خَلْقًا كَثِيرًا، ثُمَّ يَقُولُونَ: رَبَّنَا لَمْ نَذَرْ فِيهَا مِمَّنْ أَمَرْتَنَا أَحَدًا، ثُمَّ يَقُولُ: ارْجِعُوا فَمَنْ وَجَدْتُمْ فِي قَلْبِهِ مِثْقَالَ ذَرَّةٍ مِنْ خَيْر، فَأَخْرِجُوهُ فَيُخْرِجُونَ خَلْقًا كَثِيرًا، ثُمَّ يَقُولُونَ: رَبَّنَا لَمْ نَذَرْ فِيهَا خَيْرًا.","وَكَانَ أَبُو سَعِيدٍ الْخُدْرِيُّ، يَقُولُ: إِنْ لَمْ تُصَدِّقُونِي بِهَذَا الْحَدِيثِ، فَاقْرَءُوا إِنْ شِئْتُمْ: ﴿إِنَّ اللَّهَ لَا يَظْلِمُ مِثْقَالَ ذَرَّةٍ وَإِنْ تَكُ حَسَنَةً يُضَاعِفْهَا وَيُؤْتِ مِنْ لَدُنْهُ أَجْرًا عَظِيمًا﴾ [سورة النساء: 40]. فَيَقُولُ اللَّهُ عَزَّ وَجَلَّ: شَفَعَتِ الْمَلَائِكَةُ، وَشَفَعَ النَّبِيُّونَ، وَشَفَعَ الْمُؤْمِنُونَ، وَلَمْ يَبْقَ إِلَّا أَرْحَمُ الرَّاحِمِينَ، فَيَقْبِضُ قَبْضَةً مِنَ النَّارِ، فَيُخْرِجُ مِنْهَا قَوْمًا لَمْ يَعْمَلُوا خَيْرًا قَطُّ، قَدْ عَادُوا حُمَمًا، فَيُلْقِيهِمْ فِي نَهَرٍ فِي أَفْوَاهِ الْجَنَّةِ، يُقَالُ لَهُ: نَهَرُ الْحَيَاةِ، فَيَخْرُجُونَ كَمَا تَخْرُجُ الْحِبَّةُ فِي حَمِيلِ السَّيْلِ أَلَا تَرَوْنَهَا تَكُونُ إِلَى الْحَجَرِ أَوْ إِلَى الشَّجَرِ، مَا يَكُونُ إِلَى الشَّمْسِ، أُصَيْفِرُ، وَأُخَيْضِرُ، وَمَا يَكُونُ مِنْهَا إِلَى الظِّلِّ يَكُونُ أَبْيَضَ، فَقَالُوا: يَا رَسُولَ اللَّهِ، كَأَنَّكَ كُنْتَ تَرْعَى بِالْبَادِيَةِ؟ قَالَ: فَيَخْرُجُونَ كَاللُّؤْلُؤِ فِي رِقَابِهِمُ الْخَوَاتِمُ، يَعْرِفُهُمْ أَهْلُ الْجَنَّةِ هَؤُلَاءِ عُتَقَاءُ اللَّهِ الَّذِينَ أَدْخَلَهُمُ اللَّهُ الْجَنَّةَ بِغَيْرِ عَمَلٍ عَمِلُوهُ، وَلَا خَيْرٍ قَدَّمُوهُ، ثُمَّ يَقُولُ: ادْخُلُوا الْجَنَّةَ، فَمَا رَأَيْتُمُوهُ فَهُوَ لَكُمْ، فَيَقُولُونَ: رَبَّنَا أَعْطَيْتَنَا مَا لَمْ تُعْطِ أَحَدًا مِنَ الْعَالَمِينَ؟ فَيَقُولُ: لَكُمْ عِنْدِي أَفْضَلُ مِنْ هَذَا، فَيَقُولُونَ: يَا رَبَّنَا، أَيُّ شَيْءٍ أَفْضَلُ مِنْ هَذَا؟ فَيَقُولُ: رِضَايَ، فَلَا أَسْخَطُ عَلَيْكُمْ بَعْدَهُ أَبَدًا."],"takhrij":"متفق عليه: رواه البخاريّ في التوحيد (7439)، ومسلم في الإيمان (183) من طريق زيد بن أسلم، عن عطاء بن يسار، عن أبي سعيد الخدريّ، فذكره في حديث طويل، انظره في رؤية المؤمنين ربَّهم يوم القيامة.","grade":"متفق عليه","chapter_ar":"باب في شفاعة الملائكة والنبيين والمؤمنين","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī in al-Tawḥīd (7439) and Muslim in al-Īmān (183).","chapter_en":"The Intercession of the Angels, the Prophets, and the Believers","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":15,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “When the believers have been delivered from the Fire, then by the One in whose Hand is my soul, none of you will plead with Allah more insistently in seeking the full restoration of his right than the believers will plead with Allah on the Day of Resurrection concerning their brothers who are in the Fire. They will say: ‘Our Lord, they used to fast with us, pray with us, and perform Ḥajj with us.’ It will be said to them: ‘Bring out those whom you recognize.’ Their forms will then be made forbidden to the Fire. They will bring out a great number of people, some of whom the Fire had reached halfway up their shins and others up to their knees. Then they will say: ‘Our Lord, none remains therein of those whom You commanded us to bring out.’ He will say: ‘Return, and whoever you find with the weight of a dinar of goodness in his heart, bring him out.’ They will bring out a great number. Then they will say: ‘Our Lord, we have left no one therein from among those whom You commanded us to bring out.’ Then He will say: ‘Return, and whoever you find with the weight of half a dinar of goodness in his heart, bring him out.’ They will bring out a great number. Then they will say: ‘Our Lord, we have left no one therein from among those whom You commanded us to bring out.’ Then He will say: ‘Return, and whoever you find with the weight of an atom of goodness in his heart, bring him out.’","They will bring out a great number. Then they will say: ‘Our Lord, we have left no one therein.’” Abū Saʿīd may Allah be pleased with him used to say: “If you do not believe me concerning this ḥadīth, then recite, if you wish: ‘Indeed, Allah does not wrong even by the weight of an atom.’” [Sūrat al-Nisāʾ 4:40] Then Allah, Mighty and Majestic, will say: “The angels have interceded, the prophets have interceded, and the believers have interceded. None remains except the Most Merciful of those who show mercy.” He will take a handful from the Fire and bring out from it people who never did any good; they will have become charred. He will cast them into a river at the entrances of Paradise called the River of Life, and they will emerge as a seed grows in the silt carried by a flood. Have you not seen how what faces the sun becomes yellowish and greenish, while what is in the shade is white? They said: “O Messenger of Allah, it is as though you used to tend livestock in the desert!” He said: “They will emerge like pearls, with marks on their necks by which the people of Paradise will recognize them: these are those whom Allah has freed, whom Allah admitted into Paradise without any deed they performed or any good they sent ahead. Then He will say: Enter Paradise; whatever you see is yours.” They will say: “Our Lord, You have given us what You have not given anyone among the worlds.” He will say: “You have with Me something better than this.” They will say: “Our Lord, what could be better than this?” He will say: “My pleasure; I will never be angry with you after this.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (7439)، ومسلم (183)."},{"num":936,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: قَدْ أَعْطَى اللَّهُ كُلَّ نَبِيٍّ عَطِيَّةً، فَكُلٌّ قَدْ تَعَجَّلَهَا، وَإِنِّي أَخَّرْتُ عَطِيَّتِي شَفَاعَةً لِأُمَّتِي، وَإِنَّ الرَّجُلَ مِنْ أُمَّتِي لَيَشْفَعُ لِلْفِئَامِ مِنَ النَّاسِ، فَيَدْخُلُونَ الْجَنَّةَ، وَإِنَّ الرَّجُلَ لَيَشْفَعُ لِلْقَبِيلَةِ، وَإِنَّ الرَّجُلَ لَيَشْفَعُ لِلْعُصْبَةِ، وَإِنَّ الرَّجُلَ لَيَشْفَعُ لِلثَّلَاثَةِ وَلِلرَّجُلَيْنِ وَلِلرَّجُلِ."],"takhrij":"حسن: رواه الإمام أحمد (11148)، وأبو يعلى (1014)، والبزّار- كشف الأستار (3458)، كلّهم من طريق زكريا بن أبي زائدة، عن عطيّة العوفيّ.","grade":"حسن","chapter_ar":"باب في شفاعة الملائكة والنبيين والمؤمنين","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Aḥmad (11148), Abū Yaʿlā (1014), and al-Bazzār in Kashf al-Astār (3458).","chapter_en":"The Intercession of the Angels, the Prophets, and the Believers","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":15,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī may Allah be pleased with him reported that the Prophet ﷺ said: “Every prophet was given a special gift, and each one hastened to use his gift. But I have postponed my gift as intercession for my Ummah. A man from my Ummah will intercede for a great multitude of people and they will enter Paradise. A man will intercede for an entire tribe. A man will intercede for a clan. A man will intercede for three people, for two people, and even for one person.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (11148)، وأبو يعلى (1014)، والبزار في كشف الأستار (3458)."},{"num":937,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَكْرٍ الصِّدِّيقِ فِي حَدِيثِ الشَّفَاعَةِ فِي الْمَوْقِفِ وَفِيه: ثُمَّ يُقَالُ: ادْعُوا الصِّدِّيقِينَ فَيَشْفَعُونَ، ثُمَّ يُقَالُ: ادْعُوا الْأَنْبِيَاءَ، قَالَ: فَيَجِيءُ النَّبِيُّ وَمَعَهُ الْعِصَابَةُ، وَالنَّبِيُّ وَمَعَهُ الْخَمْسَةُ وَالسِّتَّةُ، وَالنَّبِيُّ وَلَيْسَ مَعَهُ أَحَدٌ، ثُمَّ يُقَالُ: ادْعُوا الشُّهَدَاءَ فَيَشْفَعُونَ لِمَنْ أَرَادُوا، وَقَالَ: فَإِذَا فَعَلَتْ الشُّهَدَاءُ ذَلِكَ، قَالَ: يَقُولُ اللَّهُ عَزَّ وَجَلَّ: أَنَا أَرْحَمُ الرَّاحِمِينَ، أَدْخِلُوا جَنَّتِي، مَنْ كَانَ لَا يُشْرِكُ بِي شَيْئًا، قَالَ: فَيَدْخُلُونَ الْجَنَّةَ."],"takhrij":"حسن: رواه الإمام أحمد (15)، وأبو يعلى (56)، والبزّار- كشف الأستار (3465)، كلّهم من طريق النّضر بن شُميل، قال: حدّثني أبو نَعامة، قال: حدّثني أبو هُنيد البراء بن نوفل، عن والان العدَويّ، عن حذيفة، عن أبي بكر الصّديق، فذكره في حديث طويل سبق ذكره والنكارة فيه:تقديم الصديقين على الأنبياء.","grade":"حسن","chapter_ar":"باب في شفاعة الملائكة والنبيين والمؤمنين","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (15), Abū Yaʿlā (56), and al-Bazzār in Kashf al-Astār (3465).","chapter_en":"The Intercession of the Angels, the Prophets, and the Believers","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":15,"content":{"translation":{"en":["Abū Bakr al-Ṣiddīq may Allah be pleased with him reported in the ḥadīth concerning intercession at the Standing: “Then it will be said: ‘Call the truthful ones.’ They will intercede. Then it will be said: ‘Call the prophets.’ A prophet will come accompanied by a group; another prophet will come accompanied by five or six people; and another prophet will come with no one. Then it will be said: ‘Call the martyrs.’ They will intercede for whomever they wish. When the martyrs have done that, Allah, Mighty and Majestic, will say: ‘I am the Most Merciful of those who show mercy. Admit into My Paradise whoever did not associate anything with Me.’ Then they will enter Paradise.”"]},"buhuth":{"ar":["والنكارة فيه: تقديم الصديقين على الأنبياء."],"en":["The anomalous point in it is the placing of the truthful ones before the prophets."]}},"tuhfa":{},"full":1,"tks":"حسن: رواه الإمام أحمد (15)، وأبو يعلى (56)، والبزار في كشف الأستار (3465)."},{"num":938,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ الرَّجُلَ يَشْفَعُ لِلرَّجُلَيْنِ وَالثَّلَاثَةِ، وَالرَّجُلُ لِلرَّجُلِ."],"takhrij":"صحيح: رواه البزار - كشف الأستار (3473)، ، وابن خزيمة في التوحيد (624) من طرق عن عبدالرزّاق، أنبأ معمر، عن ثابت، أنه سمع أنس بن مالك يقول (فذكره).","grade":"صحيح","chapter_ar":"باب في شفاعة الملائكة والنبيين والمؤمنين","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bazzār in Kashf al-Astār (3473) and Ibn Khuzaymah in al-Tawḥīd (624).","chapter_en":"The Intercession of the Angels, the Prophets, and the Believers","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":15,"content":{"translation":{"en":["Anas may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “A man will indeed intercede for two or three people, and a man will intercede for one person.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البزار في كشف الأستار (3473)، وابن خزيمة في التوحيد (624)."},{"num":939,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ أَبِي الْجَدْعَاءِ، أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لَيَدْخُلَنَّ الْجَنَّةَ بِشَفَاعَةِ رَجُلٍ مِنْ أُمَّتِي أَكْثَرُ مِنْ بَنِي تَمِيمٍ، قَالُوا: يَا رَسُولَ اللَّهِ سِوَاكَ؟ قَالَ: سِوَايَ."],"takhrij":"صحيح: رواه الترمذيّ (2438)، وابن ماجه (4316)، والسياق له، كلاهما من طريق خالد الحذّاء، عن عبدالله بن شقيق، عن عبدالله بن أبي الجدعاء، فذكره،","grade":"صحيح","chapter_ar":"باب في شفاعة الملائكة والنبيين والمؤمنين","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Tirmidhī (2438) and Ibn Mājah (4316), with the wording of Ibn Mājah.","chapter_en":"The Intercession of the Angels, the Prophets, and the Believers","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":15,"content":{"translation":{"en":["ʿAbdullāh ibn Abī al-Jadʿāʾ may Allah be pleased with him reported that he heard the Prophet ﷺ say: “More people than the number of Banū Tamīm will certainly enter Paradise through the intercession of a man from my Ummah.” They asked: “O Messenger of Allah, someone other than you?” He replied: “Someone other than me.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (2438)، وابن ماجه (4316)، والسياق له."},{"num":940,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَكْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يُحْمَلُ النَّاسُ عَلَى الصِّرَاطِ يَوْمَ الْقِيَامَةِ، فَتَقَادَعُ بِهِمْ جَنَبَتَا الصِّرَاطِ تَقَادُعَ الْفَرَاشِ فِي النَّارِ، قَالَ: فَيُنْجِي اللَّهُ بِرَحْمَتِهِ مَنْ يَشَاءُ، قَالَ: ثُمَّ يُؤْذَنُ لِلْمَلَائِكَةِ وَالنَّبِيِّينَ وَالشُّهَدَاءِ أَنْ يَشْفَعُوا، فَيَشْفَعُونَ وَيُخْرِجُونَ، وَيَشْفَعُونَ وَيُخْرِجُونَ، وَيَشْفَعُونَ وَيُخْرِجُونَ، وَزَادَ عَفَّانُ مَرَّةً، فَقَالَ أَيْضًا: وَيَشْفَعُونَ وَيُخْرِجُونَ مَنْ كَانَ فِي قَلْبِهِ مَا يَزِنُ ذَرَّةً مِنْ إِيمَانٍ."],"takhrij":"حسن: رواه الإمام أحمد (20440)، والبزّار- البحر الزخار (3671)، والطبرانيّ في الصغير (929)، وابن أبي عاصم في السنة (838) كلّهم من حديث عفّان بن مسلم، حدّثنا سعيد بن زيد، قال: سمعت أبا سليمان العصريّ، حدّثنا عقبة بن صُهبان، عن أبي بكرة، عن النبيّ صلى الله عليه وسلم، فذكره.","grade":"حسن","chapter_ar":"باب في شفاعة الملائكة والنبيين والمؤمنين","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (20440), al-Bazzār in al-Baḥr al-Zakhkhār (3671), al-Ṭabarānī in al-Muʿjam al-Ṣaghīr (929), and Ibn Abī ʿĀṣim in al-Sunnah (838).","chapter_en":"The Intercession of the Angels, the Prophets, and the Believers","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":15,"content":{"translation":{"en":["Abū Bakrah may Allah be pleased with him reported that the Prophet ﷺ said: “People will be carried onto the Ṣirāṭ on the Day of Resurrection, and the two sides of the Ṣirāṭ will cause them to fall from it like moths falling into a fire.” He said: “Then Allah will save by His mercy whomever He wills.” He said: “Then the angels, the prophets, and the martyrs will be given permission to intercede. They will intercede and bring people out; they will intercede and bring people out; and they will intercede and bring people out.” ʿAffān added on one occasion: “And they will intercede and bring out whoever has in his heart the weight of an atom of faith.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[16188],"tks":"حسن: رواه الإمام أحمد (20440)، والبزار في البحر الزخار (3671)، والطبراني في الصغير (929)، وابن أبي عاصم في السنة (838)."},{"num":941,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ (فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ) عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: خَرَرْتُ سَاجِدًا، فَأَسْجُدُ كَسُجُودِي أَوَّلَ مَرَّةٍ وَمِثْلَهُ مَعَهُ، وَيُفْتَحُ لِي مِنَ الثَّنَاءِ وَالتَّحْمِيدِ مِثْلُ ذَلِكَ، ثُمَّ يُقَالُ: سَلْ تُعْطَهْ، وَاشْفَعْ تُشَفَّعْ فَأَقُولُ: يَا رَبِّ، ذُرِّيَّةُ آدَمَ، لَا تُحْرَقِ الْيَوْمَ بِالنَّارِ، فَيَقُولُ: اذْهَبُوا فَمَنْ وَجَدْتُمْ فِي قَلْبِهِ مِثْقَالَ ذَرَّةٍ مِنْ إِيمَانٍ فَأَخْرِجُوهُ، فَيُخْرِجُونَ مَا لَا يَعْلَمُ عِدَّتَهُمْ إِلَّا اللَّهُ عَزَّ وَجَلَّ، وَيَبْقَى أَكْثَرُهُمْ، ثُمَّ يُؤْذَنُ لِآدَمَ بِالشَّفَاعَةِ، فَيَشْفَعُ لِعَشَرَةِ آلَافِ أَلْفٍ، ثُمَّ يُؤْذَنُ لِلْمَلَائِكَةِ وَالنَّبِيِّينَ، فَيَشْفَعُونَ، حَتَّى إِنَّ الْمُؤْمِنَ لَيَشْفَعُ لِأَكْثَرِ مِنْ رَبِيعَةَ وَمُضَرَ."],"takhrij":"حسن: رواه الآجرّي في الشّريعة (809) عن أبي بكر جعفر بن محمد الفريابيّ، قال: حدّثنا قتيبة بن سعيد، قال: حدّثنا اللّيث بن سعد، عن خالد بن يزيد، عن سعيد بن أبي هلال، عن أنس بن مالك، فذكر الحديث بطوله، وسبق كاملا في الشّفاعة لأهل الموقف.","grade":"حسن","chapter_ar":"باب في شفاعة الملائكة والنبيين والمؤمنين","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Ājurrī in al-Sharīʿah (809).","chapter_en":"The Intercession of the Angels, the Prophets, and the Believers","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":15,"content":{"translation":{"en":["Anas ibn Mālik may Allah be pleased with him reported that the Prophet ﷺ said: “I will fall down in prostration and prostrate as I did the first time, and similarly again. Then there will be opened for me praises and glorifications like those before. Then it will be said: ‘Ask and you will be given; intercede and your intercession will be accepted.’ I will say: ‘My Lord, let the descendants of Adam not be burned in the Fire today.’ He will say: ‘Go, and whoever you find with the weight of an atom of faith in his heart, bring him out.’ They will bring out a number whose count none knows except Allah, Mighty and Majestic, while most will remain. Then Adam will be permitted to intercede, and he will intercede for ten million. Then the angels and the prophets will be permitted to intercede, and they will intercede, until even a believer will intercede for more people than Rabīʿah and Muḍar.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الآجري في الشريعة (809)."},{"num":942,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ بْنِ الْيَمَانِ، أَنَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يُخْرِجُ اللَّهُ قَوْمًا مُنْتِنِينَ قَدْ مَحَشَتْهُمْ النَّارُ بشَفَاعَةِ الشَّافِعِينَ، فَيُدْخِلُهُمْ الْجَنَّةَ، فَيُسَمَّوْنَ الْجَهَنَّمِيُّونَ."],"takhrij":"حسن: رواه الإمام أحمد (23423)، وأبو داود الطيالسيّ في مسنده (420) ومن طريقه ابنُ خزيمة (545)، والآجريّ في الشّريعة (805) كلّهم من طريق شعبة، عن حمّاد، عن ربعي بن حراش، عن حذيفة، فذكره.","grade":"حسن","chapter_ar":"باب في شفاعة الملائكة والنبيين والمؤمنين","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Aḥmad (23423), Abū Dāwūd al-Ṭayālisī (420), and Ibn Khuzaymah (545).","chapter_en":"The Intercession of the Angels, the Prophets, and the Believers","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":15,"content":{"translation":{"en":["Ḥudhayfah ibn al-Yamān may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Allah will bring out people who have become foul-smelling, whom the Fire has scorched through the intercession of those who intercede. He will admit them into Paradise, and they will be called al-Jahannamiyyūn.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (23423)، وأبو داود الطيالسي (420)، وابن خزيمة (545)."},{"num":943,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَخْرُجُ مِنَ النَّارِ بِشَفَاعَةِ رَجُلٍ مِنْ أُمَّتِي أَكْثَرُ مِنْ رَبِيعَةَ وَمُضَرَ."],"takhrij":"حسن: رواه الطّبرانيّ في الكبير (8058) عن أحمد بن داود المكيّ، ثنا مسلم بن إبراهيم، ثنا مبارك بن فضالة، عن أبي غالب، عن أبي أمامة، فذكره.","grade":"حسن","chapter_ar":"باب في شفاعة الملائكة والنبيين والمؤمنين","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Kabīr (8/330).","chapter_en":"The Intercession of the Angels, the Prophets, and the Believers","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":15,"content":{"translation":{"en":["Abū Umāmah may Allah be pleased with him reported that the Prophet ﷺ said: “More people than the number of Rabīʿah and Muḍar will be brought out of the Fire through the intercession of a man from my Ummah.”"]},"buhuth":{"en":["Aḥmad (22215) and al-Ājurrī in al-Sharīʿah (817) also narrated it with the wording:","“Through the intercession of a man who is not a prophet, a number like the two great tribes—or like one of the two great tribes—Rabīʿah and Muḍar will certainly enter Paradise.”","A man asked:","“O Messenger of Allah, is Rabīʿah not from Muḍar?”","He replied:","“I only say what I am made to say.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (8058)."},{"num":944,"demo":false,"sanad":"","matn":["عَنْ عُتْبَةَ بْنِ عَبْدٍ السُّلَمِيِّ قَالَ: جَاءَ أَعْرَابِيٌّ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ـ فَقَالَ: مَا حَوْضُكَ الَّذِي تُحَدِّثُ عَنْهُ؟ قَالَ: كَمَا بَيْنَ الْبَيْضَاءِ إِلَى بُصْرَى، يَمُدُّنِي اللَّهُ فِيهِ بِكُرَاعٍ لَا يَدْرِي إِنْسَانٌ مِمَّنْ خُلِقَ أَيْنَ طَرَفَيْهِ، فَكَبَّرَ عُمَرُ بْنُ الْخَطَّابِ، فَقَالَ: أَمَّا الْحَوْضُ فَيَرِدُ عَلَيْهِ فُقَرَاءُ الْمُهَاجِرِينَ، الَّذِينَ يُقَاتِلُونَ فِي سَبِيلِ اللَّهِ، ويَمُوتُونَ فِي سَبِيلِ اللَّهِ. فَأَرْجُو أَنْ يُورِثَنِي الْكُرَاعَ فَأَشْرَبَ مِنْهُ وَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ رَبِّي وَعَدَنِي أَنْ يُدْخِلَ الْجَنَّةَ مِنْ أُمَّتِي سَبْعِينَ أَلْفًا بِغَيْرِ حِسَابٍ ثُمَّ يَشْفَعُ كُلُّ أَلْفٍ لِسَبْعِينَ أَلْفًا، ثُمَّ يَحْثِي رَبِّي تَبَارَكَ وَتَعَالَى بِكَفَّيْهِ ثَلَاثَ حَثَيَاتٍ. فَكَبَّرَ عُمَرُ، وَقَالَ: إِنَّ السَّبْعِينَ الْأُولَى لَيُشَفِّعُهُمُ اللَّهُ فِي آبَائِهِمْ، وَأَبْنَائِهِمْ، وَعَشَائِرِهِمْ، وَأَرْجُو أَنْ يَجْعَلَنِي اللَّهُ فِي إِحْدَى الْحَثَيَاتِ الْأَوَاخِرِ . فَقَالَ الْأَعْرَابِيُّ: يَا رَسُولَ اللَّهِ، فِيهَا فَاكِهَةٌ؟ قَالَ: نَعَمْ، وَفِيهَا شَجَرَةٌ تُدْعَى طُوبَى هِيَ تُطَابِقُ الْفِرْدَوْسَ. فَقَالَ: أَيُّ شَجَرِ أَرْضِنَا تُشْبِهُ؟ قَالَ: لَيْسَ تُشْبِهُ مِنْ شَجَرِ أَرْضِكَ، وَلَكِنْ أَتَيْتَ الشَّامَ؟ قَالَ: لَا، يَا رَسُولَ اللَّهِ قَالَ: فَإِنَّهَا تُشْبِهُ شَجَرَةً فِي الشَّامِ تُدْعَى الْجَوْزَةَ، تَنْبُتُ عَلَى سَاقٍ وَاحِدٍ، ثُمَّ يَنْتَشِرُ أَعْلَاهَا. قَالَ: فَمَا عِظَمُ أَصْلِهَا؟ قَالَ: لَوِ ارْتَحَلَتْ جَذَعَةٌ مِنْ إِبِلِ أَهْلِكَ لَمَا قَطَعَتْهَا حَتَّى تَنْكَسِرَ تَرْقُوَتُهَا هَرَمًا. قَالَ: فِيهَا عِنَبٌ؟ قَالَ: نَعَمْ. قَالَ: مَا عِظَمُ الْعُنْقُودِ مِنْهَا؟ قَالَ: مَسِيرَةُ شَهْرِ لِلْغُرَابِ الْأَبْقَعِ، لَا يَنْثَنِي وَلَا يَفْتُرُ . قَالَ: فَمَا عِظَمُ الْحِبَّةِ مِنْهُ؟ قَالَ: هَلْ ذَبَحَ أَبُوكَ مِنْ غَنَمِهِ تيسا عَظِيمًا؟ قَالَ: نَعَمْ . قَالَ: فَسَلَخَ إِهَابَهَا فَأَعْطَاهُ أُمَّكَ، فَقَالَ: ادْبَغِي هَذَا، ثُمَّ افْرِي لَنَا مِنْهُ ذَنُوبًا نَرْوي بِهِ ماشِيَتَنَا؟ قَالَ: نَعَمْ قَالَ: فَإِنَّ تِلْكَ الْحِبَّةَ تُشْبِعُنِي وَأَهْلَ بَيْتِي؟ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: وَعَامَّةَ عَشِيرَتِكَ."],"takhrij":"حسن: رواه الطّبراني في الأوسط (404) واللّفظ له، وفي الكبير (17/ح 312)، وأحمد (17642) مختصراً كلّهم من طريق عامر بن زيد البكالي، أنه سمع عتبة بن عبدالسّلميّ، فذكره. وصحّحه ابن حبان (6450).","grade":"حسن","chapter_ar":"باب في شفاعة الملائكة والنبيين والمؤمنين","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Awsaṭ (404), with this wording, in al-Muʿjam al-Kabīr (17/126–127), and by Aḥmad (17642) in abbreviated form. Ibn Ḥibbān authenticated it (6450).","chapter_en":"The Intercession of the Angels, the Prophets, and the Believers","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":15,"content":{"translation":{"en":["ʿUtbah ibn ʿAbd al-Sulamī, may Allah be pleased with him, reported: A Bedouin came to the Messenger of Allah ﷺ and asked: “What is this Basin of yours that you speak about?” He replied: “It is like the distance from al-Bayḍāʾ to Buṣrā. Allah will supply me in it with a channel from Paradise whose two ends no human being among creation knows.” ʿUmar ibn al-Khaṭṭāb, may Allah be pleased with him, said: “Allāhu Akbar!” ʿUmar ibn al-Khaṭṭāb, may Allah be pleased with him, said: “As for the Basin, the poor among the Muhājirūn will come to it—those who fight in the path of Allah and die in the path of Allah. I hope that Allah will grant me that channel so that I may drink from it.” The Messenger of Allah ﷺ also said: “My Lord has promised me that He will admit seventy thousand from my Ummah into Paradise without reckoning. Then every thousand will intercede for seventy thousand, and then my Lord, Blessed and Exalted, will scoop three handfuls with His two Hands.” ʿUmar again said: “Allāhu Akbar!” Then he said: “As for the first seventy thousand, Allah will permit them to intercede for their fathers, their sons, and their clans. I hope that Allah will place me among one of the final three handfuls.” The Bedouin asked: “O Messenger of Allah, is there fruit in it?” He replied: “Yes. In it is a tree called Ṭūbā, and it spans al-Firdaws.” He asked: “Which tree from our land does it resemble?” He replied: “It resembles none of the trees of your land. But have you ever been to al-Shām?” He said: “No, O Messenger of Allah.” He said: “It resembles a tree in al-Shām called al-Jawzah. It grows upon a single trunk, and then its upper part spreads out.” He asked: “How large is its base?” He replied: “If a mature she-camel from the camels of your family were to travel around it, she would not complete the distance before her collarbone broke from old age.” He asked: “Are there grapes upon it?” He replied: “Yes.” He asked: “How large is one of its clusters?” He replied: “The distance of a month’s journey for a speckled crow that neither turns aside nor tires.” He asked: “How large is one grape from it?” He replied: “Did your father ever slaughter a large billy goat from his flock?” He said: “Yes.” He said: “Did he skin its hide and give it to your mother, saying: ‘Tan this, then make for us from it a large bucket with which we can water our livestock’?” He replied: “Yes.” He said: “One of those grapes would satisfy me and the people of my household.” The Prophet ﷺ said: “And most of your clan as well.”"]},"buhuth":{"en":["The expression:","“with a kurāʿ”","means: with a channel or extension from the water of Paradise."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الأوسط (404)، واللفظ له، وفي الكبير (17/126–127)، وأحمد (17642) مختصرا، وصححه ابن حبان (6450)."},{"num":945,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ بْنِ الْيَمَانِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: يَقُولُ إِبْرَاهِيمُ يَوْمَ الْقِيَامَةِ: يَا رَبَّاهُ، فَيَقُولُ الرَّبُّ جَلَّ وَعَلا: يَا لَبَّيْكَاهُ، فَيَقُولُ إِبْرَاهِيمُ: يَا رَبِّ حَرَّقْتَ بَنِيَّ، فَيَقُولُ: أَخْرِجُوا مِنَ النَّارِ مَنْ كَانَ فِي قَلْبِهِ ذَرَّةٌ أَوْ شَعِيرَةٌ مِنْ إِيمَانٍ."],"takhrij":"صحيح: رواه ابنُ حبان (7378) عن محمد بن الحسن بن مكرم، قال: حدّثنا سُريج بن يونس، قال: حدّثنا مروان بن معاوية، قال: حدّثنا أبو مالك الأشجعيّ، عن حذيفة، فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في شفاعة إبراهيم عليه السلام للمسلمين من ولده","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Ibn Ḥibbān (7378).","chapter_en":"What Has Been Reported Concerning the Intercession of Abraham, peace be upon him, for the Muslims Among His Descendants","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":16,"content":{"translation":{"en":["Ḥudhayfah may Allah be pleased with him reported that the Prophet ﷺ said: “Abraham will say on the Day of Resurrection: ‘My Lord!’ The Lord, Majestic and Exalted, will say: ‘Here I am.’ Abraham will say: ‘My Lord, You have burned my children.’ He will say: ‘Bring out of the Fire whoever had in his heart the weight of an atom—or a grain—of faith.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن حبان (7378)."},{"num":946,"demo":false,"sanad":"","matn":["عَنْ الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لِلشَّهِيدِ عِنْدَ اللَّهِ سِتُّ خِصَالٍ: يُغْفَرُ لَهُ فِي أَوَّلِ دَفْعَةٍ، وَيَرَى مَقْعَدَهُ مِنَ الْجَنَّةِ، وَيُجَارُ مِنْ عَذَابِ الْقَبْرِ، وَيَأْمَنُ مِنَ الْفَزَعِ الْأَكْبَرِ، وَيُوضَعُ عَلَى رَأْسِهِ تَاجُ الْوَقَارِ الْيَاقُوتَةُ مِنْهَا خَيْرٌ مِنَ الدُّنْيَا وَمَا فِيهَا، وَيُزَوَّجُ اثْنَتَيْنِ وَسَبْعِينَ زَوْجَةً مِنَ الْحُورِ الْعِينِ، وَيُشَفَّعُ فِي سَبْعِينَ مِنْ أَقَارِبِهِ."],"takhrij":"حسن: رواه الترمذيّ (1661) عن عبدالله بن عبدالرحمن، حدّثنا نُعيم بن حمّاد، حدّثنا بقية بن الوليد، عن بحير بن سعد، عن خالد بن معدان، عن المقدام بن معديكرب، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في شفاعة الشهيد","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Tirmidhī (1663).","chapter_en":"What Has Been Reported Concerning the Intercession of the Martyr","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":17,"content":{"translation":{"en":["Al-Miqdām ibn Maʿdīkarib may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “The martyr has six qualities: he is forgiven at the first outpouring of his blood; he is shown his place in Paradise; he is protected from the punishment of the grave; he is safe from the Greatest Terror; a crown of dignity is placed upon his head, one ruby of which is better than the world and everything in it; he is married to seventy-two wives from the ḥūr al-ʿayn; and he is permitted to intercede for seventy of his relatives.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (1661)."},{"num":947,"demo":false,"sanad":"","matn":["عَنْ أَبِي الدَّرْدَاءِ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يُشَفَّعُ الشَّهِيدُ فِي سَبْعِينَ مِنْ أَهْلِ بَيْتِهِ."],"takhrij":"حسن: رواه أبو داود (2522) ومن طريقه البيهقيّ (18527) عن أحمد بن صالح، حدّثنا يحيى بن حسان، حدّثنا الوليد بن رباح الذَّماريّ، حدّثني عمّي نمران بن عتبة الذّماريّ، قال: دخلنا على أمّ الدّرداء ونحن أيتام، فقالت: أبشروا فإنّي سمعتُ أبا الدّرداء يقول: قال رسول الله صلى الله عليه وسلم  (فذكره).","grade":"حسن","chapter_ar":"باب ما جاء في شفاعة الشهيد","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Abū Dāwūd (2522), through his route by al-Bayhaqī (9/164), and by Ibn Ḥibbān (4660).","chapter_en":"What Has Been Reported Concerning the Intercession of the Martyr","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":17,"content":{"translation":{"en":["Abū al-Dardāʾ, may Allah be pleased with him, said: I heard the Messenger of Allah ﷺ say: “The martyr will be permitted to intercede for seventy members of his household.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (2522)، ومن طريقه البيهقي (18527)، وابن حبان (4660)."},{"num":948,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ الْبَاهِلِيِّ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: اقْرَءُوا الْقُرْآنَ، فَإِنَّهُ يَأْتِي يَوْمَ الْقِيَامَةِ شَفِيعًا لِأَصْحَابِهِ، اقْرَءُوا الزَّهْرَاوَيْنِ الْبَقَرَةَ وَسُورَةَ آلِ عِمْرَانَ فَإِنَّهُمَا تَأْتِيَانِ يَوْمَ الْقِيَامَةِ، كَأَنَّهُمَا غَمَامَتَانِ، أَوْ كَأَنَّهُمَا غَيَايَتَانِ، أَوْ كَأَنَّهُمَا فِرْقَانِ مِنْ طَيْرٍ صَوَافَّ تُحَاجَّانِ عَنْ أَصْحَابِهِمَا، اقْرَءُوا سُورَةَ الْبَقَرَةِ فَإِنَّ أَخْذَهَا بَرَكَةٌ، وَتَرْكَهَا حَسْرَةٌ، وَلَا تَسْتَطِيعُهَا الْبَطَلَةُ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (804) عن الحسن بن علي الحلواني، حدّثنا أبو توبة (وهو الربيع بن نافع)، حدّثنا معاوية (يعني ابن سلام)، عن زيد، أنه سمع أبا سلاّم يقول: حدّثني أبو أمامة، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في شفاعة القرآن لأهله","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (804).","chapter_en":"What Has Been Reported Concerning the Intercession of the Qurʾān for Its People","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":18,"content":{"translation":{"en":["Abū Umāmah al-Bāhilī, may Allah be pleased with him, said: I heard the Messenger of Allah ﷺ say: “Recite the Qurʾān, for it will come on the Day of Resurrection as an intercessor for its companions. Recite the two radiant ones: al-Baqarah and Sūrat Āl ʿImrān, for they will come on the Day of Resurrection as though they were two clouds, or two canopies, or two flocks of birds in ranks, pleading on behalf of their companions. Recite Sūrat al-Baqarah, for taking hold of it is a blessing, abandoning it is a cause of regret, and the sorcerers cannot withstand it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (804)."},{"num":949,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ مَرْفُوعًا: إِنَّ سُورَةً مِنَ الْقُرْآنِ ثَلَاثُونَ آيَةً شَفَعَتْ لِرَجُلٍ حَتَّى غُفِرَ لَهُ وَهِيَ: ﴿تَبَارَكَ الَّذِي بِيَدِهِ الْمُلْكُ﴾."],"takhrij":"حسن: رواه أبو داود (1400)، والترمذيّ (2891)، وابن ماجه (3786)، وصحّحه ابن حبان (787)، والحاكم (2075) كلّهم من طريق شعبة، عن قتادة، عن عباس الجشميّ، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في شفاعة القرآن لأهله","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Abū Dāwūd (1400), al-Tirmidhī (2891), and Ibn Mājah (3786). Ibn Ḥibbān authenticated it (787).","chapter_en":"What Has Been Reported Concerning the Intercession of the Qurʾān for Its People","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بشفاعة النبي ﷺ وغيره","group_en":"Collection of Chapters Concerning Belief in the Intercession of the Prophet ﷺ and Others","part_no":2,"group_no":10,"chapter_no":18,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported from the Prophet ﷺ: “A sūrah of the Qurʾān consisting of thirty verses interceded for a man until he was forgiven. It is: ‘Blessed is He in whose Hand is all dominion.’” [Sūrat al-Mulk 67:1]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13594],"tks":"حسن: رواه أبو داود (1400)، والترمذي (2891)، وابن ماجه (3786)، وصححه ابن حبان (787)."},{"num":950,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا تُفَضِّلُوا بَيْنَ أَنْبِيَاءِ اللَّهِ فَإِنَّهُ ﴿يُنْفَخُ فِي الصُّورِ فَيَصْعَقُ مَنْ فِي السَّمَوَاتِ وَمَنْ فِي الْأَرْضِ إِلَّا مَنْ شَاءَ اللَّهُ ثُمَّ يُنْفَخُ فِيهِ أُخْرَى﴾ [سورة الزمر: 68] فَأَكُونُ أَوَّلَ مَنْ بُعِثَ فَإِذَا مُوسَى آخِذٌ بِالْعَرْشِ فَلَا أَدْرِي أَحُوسِبَ بِصَعْقَتِهِ يَوْمَ الطُّورِ أَمْ بُعِثَ قَبْلِي... (فَذَكَرَ الْحَدِيثَ)."],"takhrij":"متفق عليه: رواه البخاريّ في أحاديث الأنبياء (3414)، ومسلم في كتاب الفضائل (2373) كلاهما عن عبدالعزيز بن عبدالله بن أبي سلمة، عن عبدالله بن الفضل الهاشميّ، عن عبدالرحمن الأعرج، عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في النفخ في الصور","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3414) and Muslim (2373).","chapter_en":"What Has Been Reported Concerning the Blowing of the Trumpet","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان باليوم الآخر","group_en":"Collection of Chapters Concerning Faith in the Last Day","part_no":2,"group_no":11,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Do not give preference among the Prophets of Allah, for the Trumpet will be blown and whoever is in the heavens and whoever is on the earth will fall unconscious, except whom Allah wills. Then it will be blown again, and I will be the first to be raised. Yet there will be Moses holding onto the Throne. I do not know whether his swooning at Mount Ṭūr will have been counted for him, or whether he will have been raised before me.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3414)، ومسلم (2373)."},{"num":951,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَذَكَرَ خُرُوجِ الدَّجَّالِ، ثُمَّ قَالَ: فَيَبْقَى شِرَارُ النَّاسِ فِي خِفَّةِ الطَّيْرِ وَأَحْلَامِ السِّبَاعِ، لَا يَعْرِفُونَ مَعْرُوفًا، وَلَا يُنْكِرُونَ مُنْكَرًا، فَيَتَمَثَّلُ لَهُمُ الشَّيْطَانُ، فَيَقُولُ: أَلَا تَسْتَجِيبُونَ، فَيَقُولُونَ: فَمَا تَأْمُرُنَا فَيَأْمُرُهُمْ بِعِبَادَةِ الْأَوْثَانِ، وَهُمْ فِي ذَلِكَ دَارٌّ رِزْقُهُمْ حَسَنٌ عَيْشُهُمْ، ثُمَّ يُنْفَخُ فِي الصُّورِ، فَلَا يَسْمَعُهُ أَحَدٌ إِلَّا أَصْغَى لِيتًا وَرَفَعَ لِيتًا، قَالَ وَأَوَّلُ مَنْ يَسْمَعُهُ: رَجُلٌ يَلُوطُ حَوْضَ إِبِلِهِ، قَالَ: فَيَصْعَقُ وَيَصْعَقُ النَّاسُ، ثُمَّ يُرْسِلُ اللَّهُ، أَوَ قَالَ يُنْزِلُ اللَّهُ مَطَرًا كَأَنَّهُ الطَّلُّ أَوِ الظِّلُّ نُعْمَانُ الشَّاكُّ، فَتَنْبُتُ مِنْهُ أَجْسَادُ النَّاسِ ثُمَّ يُنْفَخُ فِيهِ أُخْرَى، فَإِذَا هُمْ قِيَامٌ يَنْظُرُونَ.... (الْحَدِيثَ)."],"takhrij":"صحيح: رواه مسلم في الفتن وأشراط الساعة (2940) عن عبدالله بن معاذ العنبريّ، حدّثنا أبي، حدّثنا شعبة، عن النعمان بن سالم، قال: سمعت يعقوب بن عاصم بن عروة بن مسعود الثّقفيّ. يقول: سمعت عبدالله بن عمرو، فذكره بطوله في قصة خروج الدّجال.","grade":"صحيح","chapter_ar":"باب ما جاء في النفخ في الصور","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2940).","chapter_en":"What Has Been Reported Concerning the Blowing of the Trumpet","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان باليوم الآخر","group_en":"Collection of Chapters Concerning Faith in the Last Day","part_no":2,"group_no":11,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr may Allah be pleased with them reported that the Messenger of Allah ﷺ, after mentioning the emergence of the Dajjāl, said: “Then the worst of people will remain, light as birds and with the minds of beasts. They will neither recognize what is good nor denounce what is evil. Satan will appear before them and say: ‘Will you not respond?’ They will ask: ‘What do you command us to do?’ He will command them to worship idols. Yet during that time their provisions will be abundant and their lives pleasant. Then the Trumpet will be blown. No one will hear it except that he will lower one side of his neck and raise the other to listen. The first person to hear it will be a man plastering the watering trough of his camels. He will fall unconscious, and the people will fall unconscious. Then Allah will send—or he said: Allah will send down—rain like fine drizzle or shade; Nuʿmān was uncertain concerning the wording. From it the bodies of the people will grow. Then the Trumpet will be blown again, and suddenly they will be standing, looking on…”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2940)."},{"num":952,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كَيْفَ أَنْعَمُ وَصَاحِبُ الصُّوَرِ قَدِ الْتَقَمَ وَحَنَا جَبْهَتَهُ يَنْتَظِرُ مَتَى يُؤْمَرُ أَنْ يَنْفُخَ؟ قِيلَ: قُلْنَا: يَا رَسُولَ اللَّهِ، مَا نَقُولُ يَوْمَئِذٍ؟ قَالَ: قُولُوا: حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ، عَلَى اللَّهِ تَوَكَّلْنَا."],"takhrij":"صحيح: رواه أبو يعلى (1084- تحقيق حسين أسد) عن عثمان، حدّثنا جرير، عن الأعمش، عن أبي صالح، عن أبي سعيد، فذكر الحديث. وإسناده صحيح.وصحّحه ابن حبّان (823).","grade":"صحيح","chapter_ar":"باب ما جاء في النفخ في الصور","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Yaʿlā (1084) and authenticated by Ibn Ḥibbān (823).","chapter_en":"What Has Been Reported Concerning the Blowing of the Trumpet","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان باليوم الآخر","group_en":"Collection of Chapters Concerning Faith in the Last Day","part_no":2,"group_no":11,"chapter_no":1,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “How can I feel at ease when the one entrusted with the Trumpet has already placed the horn to his mouth, lowered his forehead, and is waiting for the command to blow?” We asked: “O Messenger of Allah, what should we say at that time?” He replied: “Say: ‘Allah is sufficient for us, and He is the best Disposer of affairs. Upon Allah we place our trust.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو يعلى (1084)، وصححه ابن حبان (823)."},{"num":953,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ طَرْفَ صَاحِبِ الصُّوَرِ مُذْ وُكِّلَ بِهِ مُسْتَعِدٌّ، يَنْظُرُ نَحْوَ الْعَرْشِ، مَخَافَةَ أَنْ يُؤْمَرَ قَبْلَ أَنْ يَرْتَدَّ إِلَيْهِ طَرْفُهُ، كَأَنَّ عَيْنَيْهِ كَوْكَبَانِ دُرِّيَّانِ."],"takhrij":"حسن: رواه الحاكم (8676) من طريق محمد بن هشام بن ملاس النّمريّ، عن مروان بن معاوية الفزاريّ، عن عبيد الله بن عبدالله بن الأصمّ، ثنا يزيد بن الأصمّ، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في النفخ في الصور","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Ḥākim (8676).","chapter_en":"What Has Been Reported Concerning the Blowing of the Trumpet","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان باليوم الآخر","group_en":"Collection of Chapters Concerning Faith in the Last Day","part_no":2,"group_no":11,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Ever since the one entrusted with the Trumpet was assigned to it, his gaze has remained fixed and ready, looking toward the Throne for fear that he may be commanded before his glance can return to him. His two eyes are like two brilliant stars.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[296,13641],"tks":"حسن: رواه الحاكم (8676)."},{"num":954,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ قَالَ: جَاءَ أَعْرَابِيٌّ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: مَا الصُّورُ؟ قَالَ: قَرْنٌ يُنْفَخُ فِيهِ."],"takhrij":"صحيح: رواه أبو داود (4742)، والترمذيّ (2430، 3244) كلاهما من طريق سليمان التّيميّ، عن أسلم العجليّ، عن بشر بن شفاف، عن عبدالله بن عمرو بن العاص، فذكر الحديث، واللّفظ للترمذيّ. ولفظ أبي داود: الصور قرنٌ يُنفخ فيه.","grade":"صحيح","chapter_ar":"باب ما جاء أن الصور هو القرن","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (4742), al-Tirmidhī (2430, 3244), Ibn Ḥibbān (7312), and al-Ḥākim (3640).","chapter_en":"What Has Been Reported That the Trumpet Is a Horn","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان باليوم الآخر","group_en":"Collection of Chapters Concerning Faith in the Last Day","part_no":2,"group_no":11,"chapter_no":2,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ, may Allah be pleased with them, reported: A Bedouin came to the Prophet ﷺ and asked: “What is the Trumpet?” He replied: “A horn into which it will be blown.”"]},"buhuth":{"en":["The wording above is that of al-Tirmidhī. Abū Dāwūd’s wording is:","“The Trumpet is a horn into which it will be blown.”","Al-Tirmidhī said in the first location:","“Ḥasan.”","And in the second:","“Ḥasan Ṣaḥīḥ.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (4742)، والترمذي (2430، 3244)، وابن حبان (7312)، والحاكم (3640)."},{"num":955,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّكُمْ مَحْشُورُونَ حُفَاةً عُرَاةً غُرْلًا ثُمَّ قَرَأَ: ﴿كَمَا بَدَأْنَا أَوَّلَ خَلْقٍ نُعِيدُهُ وَعْدًا عَلَيْنَا إِنَّا كُنَّا فَاعِلِينَ﴾ [سورة الأنبياء: 104]، وَأَوَّلُ مَنْ يُكْسَى يَوْمَ الْقِيَامَةِ إِبْرَاهِيمُ، وَإِنَّ أُنَاسًا مِنْ أَصْحَابِي يُؤْخَذُ بِهِمْ ذَاتَ الشِّمَالِ فَأَقُولُ: أَصْحَابِي أَصْحَابِي فَيَقُولُ: إِنَّهُمْ لَمْ يَزَالُوا مُرْتَدِّينَ عَلَى أَعْقَابِهِمْ مُنْذُ فَارَقْتَهُمْ فَأَقُولُ كَمَا قَالَ: الْعَبْدُ الصَّالِحُ: ﴿وَكُنْتُ عَلَيْهِمْ شَهِيدًا مَا دُمْتُ فِيهِمْ فَلَمَّا تَوَفَّيْتَنِي كُنْتَ أَنْتَ الرَّقِيبَ عَلَيْهِمْ وَأَنْتَ عَلَى كُلِّ شَيْءٍ شَهِيدٌ (117) إِنْ تُعَذِّبْهُمْ فَإِنَّهُمْ عِبَادُكَ وَإِنْ تَغْفِرْ لَهُمْ فَإِنَّكَ أَنْتَ الْعَزِيزُ الْحَكِيمُ (118)﴾ [سورة المائدة: 117، 118]."],"takhrij":"متفق عليه: رواه البخاريّ في أحاديث الأنبياء (3349)، ومسلم في كتاب الجنة (2860) كلاهما من حديث المغيرة بن النّعمان، قال: حدّثني سعيد بن جبير، عن ابن عباس، فذكر الحديث، واللّفظ للبخاريّ.","grade":"متفق عليه","chapter_ar":"باب كيف يُحشر الناس يوم القيامة","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3349) and Muslim (2860). The wording above is that of al-Bukhārī.","chapter_en":"How the People Will Be Gathered on the Day of Resurrection","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان باليوم الآخر","group_en":"Collection of Chapters Concerning Faith in the Last Day","part_no":2,"group_no":11,"chapter_no":3,"content":{"translation":{"en":["Ibn ʿAbbās may Allah be pleased with them reported that the Prophet ﷺ said: “You will be gathered barefoot, naked, and uncircumcised.” Then he recited: “Just as We began the first creation, We will repeat it—a promise binding upon Us. Indeed, We will do it.” [Sūrat al-Anbiyāʾ 21:104] “And the first person to be clothed on the Day of Resurrection will be Abraham. Some men from my Companions will be taken toward the left, and I will say: ‘My Companions! My Companions!’ It will be said: ‘They never ceased turning back upon their heels from the time you left them.’ Then I will say as the righteous servant said: ‘I was a witness over them as long as I remained among them, but when You took me, You were the Watcher over them, and You are Witness over all things. If You punish them, they are Your servants; and if You forgive them, then indeed You alone are the Almighty, the All-Wise.’” [Sūrat al-Māʾidah 5:117–118]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3349)، ومسلم (2860)، واللفظ للبخاري."},{"num":956,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: تُحْشَرُونَ حُفَاةً عُرَاةً غُرْلًا، قَالَتْ عَائِشَةُ: فَقُلْتُ يَا رَسُولَ اللَّهِ: الرِّجَالُ وَالنِّسَاءُ يَنْظُرُ بَعْضُهُمْ إِلَى بَعْضٍ، فَقَالَ: الْأَمْرُ أَشَدُّ مِنْ أَنْ يُهِمَّهُمْ ذَاكِ."],"takhrij":"متفق عليه: رواه البخاريّ في الرقاق (6527)، ومسلم في كتاب الجنة (2859) كلاهما من طريق حاتم بن أبي صغيرة، عن عبدالله بن أبي مليكة، قال: حدّثني القاسم بن محمد بن أبي بكر، أنّ عائشة، فذكرت الحديث.","grade":"متفق عليه","chapter_ar":"باب كيف يُحشر الناس يوم القيامة","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6527) and Muslim (2859).","chapter_en":"How the People Will Be Gathered on the Day of Resurrection","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان باليوم الآخر","group_en":"Collection of Chapters Concerning Faith in the Last Day","part_no":2,"group_no":11,"chapter_no":3,"content":{"translation":{"en":["ʿĀʾishah may Allah be pleased with her reported that the Messenger of Allah ﷺ said: “You will be gathered barefoot, naked, and uncircumcised.” ʿĀʾishah asked: “O Messenger of Allah, will the men and women look at one another?” He replied: “The matter will be too overwhelming for them to be concerned with that.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6527)، ومسلم (2859)."},{"num":957,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يُحْشَرُ النَّاسُ عَلَى ثَلَاثِ طَرَائِقَ رَاغِبِينَ رَاهِبِينَ، وَاثْنَانِ عَلَى بَعِيرٍ، وَثَلَاثَةٌ عَلَى بَعِيرٍ، وَأَرْبَعَةٌ عَلَى بَعِيرٍ، وَعَشَرَةٌ عَلَى بَعِيرٍ، وَيَحْشُرُ بَقِيَّتَهُمُ النَّارُ، تَقِيلُ مَعَهُمْ حَيْثُ قَالُوا، وَتَبِيتُ مَعَهُمْ حَيْثُ بَاتُوا، وَتُصْبِحُ مَعَهُمْ حَيْثُ أَصْبَحُوا، وَتُمْسِي مَعَهُمْ حَيْثُ أَمْسَوْا."],"takhrij":"متفق عليه: رواه البخاريّ في الرّقاق (6522)، ومسلم في صفة الجنة (2861) كلاهما من حديث وُهيب، عن ابن طاوُس، عن أبيه، عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب كيف يُحشر الناس يوم القيامة","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6522) and Muslim (2861).","chapter_en":"How the People Will Be Gathered on the Day of Resurrection","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان باليوم الآخر","group_en":"Collection of Chapters Concerning Faith in the Last Day","part_no":2,"group_no":11,"chapter_no":3,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Prophet ﷺ said: “The people will be gathered in three ways: desiring and fearing; two upon one camel, three upon one camel, four upon one camel, and ten upon one camel. The remainder of them will be gathered by the Fire. It will rest with them wherever they rest, spend the night with them wherever they spend the night, be with them in the morning wherever morning reaches them, and be with them in the evening wherever evening reaches them.”"]},"buhuth":{"en":["Al-Khaṭṭābī said:","“The gathering mentioned in this ḥadīth will take place before the establishment of the Hour. The people will be gathered alive toward al-Shām.","As for the gathering that will occur after resurrection from the graves, it will be different from this description of riding camels and taking turns riding them. Rather, it will be as stated in the report that they will be resurrected on the Day of Resurrection barefoot, naked, empty-handed, and uncircumcised.","It has also been said that this resurrection occurs before the gathering. Thus, there is no contradiction or conflict between the two ḥadīths.”","Aʿlām al-Ḥadīth (3/2269).","Al-Baghawī also mentioned it in Sharḥ al-Sunnah (15/125)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6522)، ومسلم (2861)."},{"num":958,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ أُنَيْسٍ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: يُحْشَرُ النَّاسُ يَوْمَ الْقِيَامَةِ أَوْ قَالَ: الْعِبَادُ عُرَاةً غُرْلًا بُهْمًا، قَالَ: قُلْنَا: وَمَا بُهْمًا؟ قَالَ: لَيْسَ مَعَهُمْ شَيْءٌ، ثُمَّ يُنَادِيهِمْ بِصَوْتٍ يَسْمَعُهُ مَنْ بَعُدَ كَمَا يَسْمَعُهُ مَنْ قُرْبٍ، أَنَا الْمَلِكُ، أَنَا الدَّيَّانُ، وَلَا يَنْبَغِي لِأَحَدٍ مِنْ أَهْلِ النَّارِ أَنْ يَدْخُلَ النَّارَ، وَلَهُ عِنْدَ أَحَدٍ مِنْ أَهْلِ الْجَنَّةِ حَقٌّ حَتَّى أَقُصَّهُ مِنْهُ، وَلَا يَنْبَغِي لِأَحَدٍ مِنْ أَهْلِ الْجَنَّةِ أَنْ يَدْخُلَ الْجَنَّةَ وَلِأَحَدٍ مِنْ أَهْلِ النَّارِ عِنْدَهُ حَقٌّ حَتَّى أَقُصَّهُ مِنْهُ حَتَّى اللَّطْمَةُ، قَالَ: قُلْنَا: كَيْفَ وَإِنَّا إِنَّمَا نَأْتِي اللَّهَ عَزَّ وَجَلَّ عُرَاةً غُرْلًا بُهْمًا؟ قَالَ: بِالْحَسنَاتِ وَالسَّيِّئَاتِ."],"takhrij":"حسن: رواه الإمام أحمد (16042) واللّفظ له، والحارث بن أبي أسامة (45) زوائده، والبخاريّ في الأدب المفرد (970)، وخلق أفعال العباد (ص92)، وابن أبي عاصم في السنة (514)، والحاكم (3638)، وصحّحه، كلّهم من طرق عن همّام بن يحيى، عن القاسم بن عبدالواحد المكيّ، عن عبدالله بن محمد بن عقيل، أنه سمع جابر بن عبدالله يقول: بلغني حديثٌ عن رجل سمعه من رسول الله صلى الله عليه وسلم، فاشتريتُ بعيراً، ثم شددتُ عليه رحلي، فسرتُ إليه شهراً حتى قدمتُ عليه الشام، فإذا عبدالله بن أنيس، فقال للبوّاب: قل له جابر على الباب. قال: ابن عبدالله؟ قلت: نعم. فخرج يطأ ثوبه، فاعتنقني واعتنقته. فقلتُ: حديثاً بلغني عنك أنّك سمعتَه من رسول الله صلى الله عليه وسلم في القصاص، فخشيتُ أن تموتَ أو أموتَ قبل أن أسمعه. قال: سمعتُ رسول الله صلى الله عليه وسلم يقول (فذكر الحديث).","grade":"حسن","chapter_ar":"باب كيف يُحشر الناس يوم القيامة","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (16042), with this wording, al-Ḥārith ibn Abī Usāmah (45) in his additional narrations, al-Bukhārī in al-Adab al-Mufrad (970) and Khalq Afʿāl al-ʿIbād (p. 92), Ibn Abī ʿĀṣim in al-Sunnah (514), and al-Ḥākim (3638), who authenticated it.","chapter_en":"How the People Will Be Gathered on the Day of Resurrection","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان باليوم الآخر","group_en":"Collection of Chapters Concerning Faith in the Last Day","part_no":2,"group_no":11,"chapter_no":3,"content":{"translation":{"en":["ʿAbdullāh ibn Unays, may Allah be pleased with him, said: I heard the Messenger of Allah ﷺ say: “The people—or he said: the servants—will be gathered on the Day of Resurrection naked, uncircumcised, and empty-handed.” We asked: “What does ‘empty-handed’ mean?” He replied: “They will have nothing with them. Then He will call them with a voice heard by the one who is far away just as it is heard by the one who is near: ‘I am the King. I am the Judge. It is not fitting for anyone from the people of the Fire to enter the Fire while he has a right due from someone among the people of Paradise until I exact it for him. Nor is it fitting for anyone from the people of Paradise to enter Paradise while someone among the people of the Fire has a right due from him until I exact it from him—even a slap.’” We asked: “How, when we will come to Allah, Mighty and Majestic, naked, uncircumcised, and empty-handed?” He replied: “By means of good deeds and bad deeds.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[406,1116,16152,16222],"tks":"حسن: رواه الإمام أحمد (16042)، واللفظ له، والحارث بن أبي أسامة (45) في زوائده، والبخاري في الأدب المفرد (970)، وخلق أفعال العباد (ص 92)، وابن أبي عاصم في السنة (514)، والحاكم (3638) وصححه."},{"num":959,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ رَجُلًا قَالَ: يَا رَسُولَ اللَّهِ، كَيْفَ يُحْشَرُ الْكَافِرُ عَلَى وَجْهِهِ يَوْمَ الْقِيَامَةِ؟ قَالَ: أَلَيْسَ الَّذِي أَمْشَاهُ عَلَى رِجْلَيْهِ فِي الدُّنْيَا، قَادِرًا عَلَى أَنْ يُمْشِيَهُ عَلَى وَجْهِهِ يَوْمَ الْقِيَامَةِ."],"takhrij":"متفق عليه: رواه البخاريّ في التفسير (4760)، ومسلم في صفات المنافقين (2806) كلاهما من حديث يونس بن محمد البغداديّ، حدّثنا شيبان، عن قتادة، حدّثنا أنس بن مالك، فذكره. قال قتادة: بلى وعِزَّة ربِّنا.","grade":"متفق عليه","chapter_ar":"باب أن الكافر يُحشر على وجهه","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4760) and Muslim (2806).","chapter_en":"The Disbeliever Will Be Gathered Upon His Face","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان باليوم الآخر","group_en":"Collection of Chapters Concerning Faith in the Last Day","part_no":2,"group_no":11,"chapter_no":4,"content":{"translation":{"en":["Anas ibn Mālik, may Allah be pleased with him, reported: A man asked: “O Messenger of Allah, how will the disbeliever be gathered upon his face on the Day of Resurrection?” He replied: “Is not the One who made him walk upon two legs in this world able to make him walk upon his face on the Day of Resurrection?”"]},"intro":{"ar":["قال الله تعالى:","﴿وَنَحْشُرُهُمْ يَوْمَ الْقِيَامَةِ عَلَى وُجُوهِهِمْ عُمْيًا وَبُكْمًا وَصُمًّا مَأْوَاهُمْ جَهَنَّمُ كُلَّمَا خَبَتْ زِدْنَاهُمْ سَعِيرًا﴾","[الإسراء: ٩٧]","وقال تعالى:","﴿الَّذِينَ يُحْشَرُونَ عَلَى وُجُوهِهِمْ إِلَى جَهَنَّمَ أُولَئِكَ شَرٌّ مَكَانًا وَأَضَلُّ سَبِيلًا﴾","[الفرقان: ٣٤]"],"en":["Allah Most High said:","“We will gather them on the Day of Resurrection upon their faces—blind, mute, and deaf. Their refuge will be Hell. Whenever it subsides, We will increase for them the blazing Fire.”","[Sūrat al-Isrāʾ 17:97]","And He said:","“Those who will be gathered upon their faces toward Hell—those are the worst in position and the farthest astray from the path.”","[Sūrat al-Furqān 25:34]"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4760)، ومسلم (2806)."},{"num":960,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ بْنِ سَعْدٍ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: يُحْشَرُ النَّاسُ يَوْمَ الْقِيَامَةِ عَلَى أَرْضٍ بَيْضَاءَ عَفْرَاءَ كَقُرْصَةِ نَقِيٍّ.","قَالَ سَهْلٌ أَوْ غَيْرُهُ: لَيْسَ فِيهَا مَعْلَمٌ لِأَحَدٍ."],"takhrij":"متفق عليه: رواه البخاريّ في الرّقاق (6521)، ومسلم في صفات المنافقين (2790) كلاهما من حديث محمد بن جعفر بن أبي كثير، حدّثني أبو حازم بن دينار، عن سهل بن سعد، فذكره.","grade":"متفق عليه","chapter_ar":"باب وصف الأرض التي يُحشر الناس عليها","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6521) and Muslim (2790).","chapter_en":"Description of the Land Upon Which the People Will Be Gathered","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان باليوم الآخر","group_en":"Collection of Chapters Concerning Faith in the Last Day","part_no":2,"group_no":11,"chapter_no":5,"content":{"translation":{"en":["Sahl ibn Saʿd, may Allah be pleased with him, said: I heard the Prophet ﷺ say: “The people will be gathered on the Day of Resurrection upon a whitish, pale land, like a round loaf made from pure refined flour.”"]},"buhuth":{"en":["Al-Khaṭṭābī said:","“Al-ʿufrah is a whiteness that is not intensely bright. Al-naqī refers to fine white flour that has been purified of its husk and bran.”","Aʿlām al-Ḥadīth (3/2268).","Suhayl—or someone else—said: “There will be no landmark there for anyone.”","Regarding the phrase “There will be no landmark there for anyone,” it means that the land will be level, with no elevation to obstruct sight and no building to conceal what lies beyond it. A landmark is one of the signs of the land by which roads are recognized."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6521)، ومسلم (2790)."},{"num":961,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَوَّلُ مَنْ يُدْعَى يَوْمَ الْقِيَامَةِ آدَمُ فَتَرَاءَى ذُرِّيَّتُهُ، فَيُقَالُ: هَذَا أَبُوكُمْ آدَمُ، فَيَقُولُ: لَبَّيْكَ وَسَعْدَيْكَ، فَيَقُولُ: أَخْرِجْ بَعْثَ جَهَنَّمَ مِنْ ذُرِّيَّتِكَ، فَيَقُولُ: يَا رَبِّ كَمْ أُخْرِجُ، فَيَقُولُ: أَخْرِجْ مِنْ كُلِّ مِائَةٍ تِسْعَةً وَتِسْعِينَ، فَقَالُوا: يَا رَسُولَ اللَّهِ: إِذَا أُخِذَ مِنَّا مِنْ كُلِّ مِائَةٍ تِسْعَةٌ وَتِسْعُونَ فَمَاذَا يَبْقَى مِنَّا؟ قَالَ: إِنَّ أُمَّتِي فِي الْأُمَمِ كَالشَّعَرَةِ الْبَيْضَاءِ فِي الثَّوْرِ الْأَسْوَدِ."],"takhrij":"صحيح: رواه البخاريّ في الرّقاق (6529) عن إسماعيل، حدّثني أخي، عن سليمان، عن ثور، عن أبي الغيث، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب أول من يُدعى يوم القيامة آدم عليه السلام","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (6529).","chapter_en":"The First to Be Called on the Day of Resurrection Will Be Adam peace be upon him","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان باليوم الآخر","group_en":"Collection of Chapters Concerning Faith in the Last Day","part_no":2,"group_no":11,"chapter_no":6,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Prophet ﷺ said: “The first to be called on the Day of Resurrection will be Adam. His descendants will be shown before him, and it will be said: ‘This is your father Adam.’ He will say: ‘Here I am, my Lord, at Your service.’ It will be said: ‘Bring forth from your descendants the contingent for Hell.’ He will ask: ‘My Lord, how many should I bring forth?’ He will say: ‘Bring forth ninety-nine out of every hundred.’” They asked: “O Messenger of Allah, if ninety-nine out of every hundred of us are taken, then what will remain of us?” He replied: “My Ummah among the other nations is like a white hair on a black bull.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (6529)."},{"num":962,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ زَوْجَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَتْ لَا تَسْمَعُ شَيْئًا لَا تَعْرِفُهُ إِلَّا رَاجَعَتْ فِيهِ حَتَّى تَعْرِفَهُ، وَأَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ حُوسِبَ عُذِّبَ، قَالَتْ عَائِشَةُ: فَقُلْتُ أَوَلَيْسَ يَقُولُ اللَّهُ تَعَالَى: ﴿فَسَوْفَ يُحَاسَبُ حِسَابًا يَسِيرًا﴾ [سورة الانشقاق: 8] قَالَتْ، فَقَالَ: إِنَّمَا ذَلِكِ الْعَرْضُ، وَلَكِنْ مَنْ نُوقِشَ الْحِسَابَ يَهْلِكْ."],"takhrij":"متفق عليه: رواه البخاريّ في العلم (103) عن سعيد بن أبي مريم، قال: أخبرنا نافع بن عمر، قال: حدّثني ابنُ أبي مليكة، أنّ عائشة زوج النبيّ صلى الله عليه وسلم، فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في العرض والحساب","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (103) and Muslim (2876).","chapter_en":"What Has Been Reported Concerning Presentation Before Allah and the Reckoning","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان باليوم الآخر","group_en":"Collection of Chapters Concerning Faith in the Last Day","part_no":2,"group_no":11,"chapter_no":7,"content":{"translation":{"en":["ʿĀʾishah, the wife of the Prophet ﷺ, may Allah be pleased with her would never hear something she did not understand without asking about it until she understood it. The Prophet ﷺ said: “Whoever is called to account will be punished.” ʿĀʾishah said: I asked: “Does Allah Most High not say: ‘Then he will be called to account with an easy reckoning’?” [Sūrat al-Inshiqāq 84:8] He replied: “That is only the presentation. But whoever is subjected to a detailed examination in the reckoning will be ruined.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (103)، ومسلم (2876)."},{"num":963,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ نُوقِشَ الْحِسَابَ بِعَمَلِهِ هَلَكَ."],"takhrij":"حسن: رواه ابن أبي عاصم في السنة (886) عن محمد بن مهدي، ثنا أبو عامر عبدالملك بن عمرو، عن محمد بن مسلم، عن عمرو بن دينار، عن ابن الزبير، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في العرض والحساب","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Ibn Abī ʿĀṣim in al-Sunnah (886).","chapter_en":"What Has Been Reported Concerning Presentation Before Allah and the Reckoning","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان باليوم الآخر","group_en":"Collection of Chapters Concerning Faith in the Last Day","part_no":2,"group_no":11,"chapter_no":7,"content":{"translation":{"en":["ʿAbdullāh ibn al-Zubayr may Allah be pleased with them reported that the Prophet ﷺ said: “Whoever is subjected to a detailed examination of his deeds in the reckoning will be ruined.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن أبي عاصم في السنة (886)."},{"num":964,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ نَاسًا قَالُوا لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا رَسُولَ اللَّهِ، هَلْ نَرَى رَبَّنَا يَوْمَ الْقِيَامَةِ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هَلْ تُضَارُّونَ فِي رُؤْيَةِ الْقَمَرِ لَيْلَةَ الْبَدْرِ؟ قَالُوا: لَا يَا رَسُولَ اللَّهِ، قَالَ: هَلْ تُضَارُّونَ فِي الشَّمْسِ لَيْسَ دُونَهَا سَحَابٌ؟ قَالُوا: لَا يَا رَسُولَ اللَّهِ، قَالَ: فَإِنَّكُمْ تَرَوْنَهُ كَذَلِكَ، يَجْمَعُ اللَّهُ النَّاسَ يَوْمَ الْقِيَامَةِ، فَيَقُولُ: مَنْ كَانَ يَعْبُدُ شَيْئًا فَلْيَتَّبِعْهُ، فَيَتَّبِعُ مَنْ كَانَ يَعْبُدُ الشَّمْسَ الشَّمْسَ، وَيَتَّبِعُ مَنْ كَانَ يَعْبُدُ الْقَمَرَ الْقَمَرَ، وَيَتَّبِعُ مَنْ كَانَ يَعْبُدُ الطَّوَاغِيتَ الطَّوَاغِيتَ، وَتَبْقَى هَذِهِ الأُمَّةُ فِيهَا مُنَافِقُوهَا، فَيَأْتِيهِمُ اللَّهُ تَبَارَكَ وَتَعَالَى فِي صُورَةٍ غَيْرِ صُورَتِهِ الَّتِي يَعْرِفُونَ، فَيَقُولُ: أَنَا رَبُّكُمْ، فَيَقُولُونَ: نَعُوذُ بِاللَّهِ مِنْكَ، هَذَا مَكَانُنَا حَتَّى يَأْتِيَنَا رَبُّنَا، فَإِذَا جَاءَ رَبُّنَا عَرَفْنَاهُ، فَيَأْتِيهِمُ اللَّهُ تَعَالَى فِي صُورَتِهِ الَّتِي يَعْرِفُونَ، فَيَقُولُ: أَنَا رَبُّكُمْ، فَيَقُولُونَ: أَنْتَ رَبُّنَا، فَيَتَّبِعُونَهُ وَيُضْرَبُ الصِّرَاطُ بَيْنَ ظَهْرَيْ جَهَنَّمَ، فَأَكُونُ أَنَا، وَأُمَّتِي أَوَّلَ مَنْ يُجِيزُ، وَلَا يَتَكَلَّمُ يَوْمَئِذٍ إِلَّا الرُّسُلُ وَدَعْوَى الرُّسُلِ يَوْمَئِذٍ: اللَّهُمَّ سَلِّمْ سَلِّمْ، وَفِي جَهَنَّمَ كَلَالِيبُ مِثْلُ شَوْكِ السَّعْدَانِ، هَلْ رَأَيْتُمُ السَّعْدَانَ؟ قَالُوا: نَعَمْ يَا رَسُولَ اللَّهِ، قَالَ: فَإِنَّهَا مِثْلُ شَوْكِ السَّعْدَانِ، غَيْرَ أَنَّهُ لَا يَعْلَمُ مَا قَدْرُ عِظَمِهَا إِلَّا اللَّهُ، تَخْطَفُ النَّاسَ بِأَعْمَالِهِمْ، فَمِنْهُمُ الْمُؤْمِنُ بَقِيَ بِعَمَلِهِ، وَمِنْهُمُ الْمُجَازَى حَتَّى يُنَجَّى، حَتَّى إِذَا فَرَغَ اللَّهُ مِنَ الْقَضَاءِ بَيْنَ الْعِبَادِ، وَأَرَادَ أَنْ يُخْرِجَ بِرَحْمَتِهِ مَنْ أَرَادَ مِنْ أَهْلِ النَّارِ، أَمَرَ الْمَلَائِكَةَ أَنْ يُخْرِجُوا مِنَ النَّارِ، مَنْ كَانَ لَا يُشْرِكُ بِاللَّهِ شَيْئًا، مِمَّنْ أَرَادَ اللَّهُ تَعَالَى أَنْ يَرْحَمَهُ مِمَّنْ يَقُولُ: لَا إِلَهَ إِلَّا اللَّهُ، فَيَعْرِفُونَهُمْ فِي النَّارِ يَعْرِفُونَهُمْ بِأَثَرِ السُّجُودِ تَأْكُلُ النَّارُ مِنَ ابْنِ آدَمَ، إِلَّا أَثَرَ السُّجُودِ حَرَّمَ اللَّهُ عَلَى النَّارِ أَنْ تَأْكُلَ أَثَرَ السُّجُودِ، فَيُخْرَجُونَ مِنَ النَّارِ وَقَدِ امْتَحَشُوا فَيُصَبُّ عَلَيْهِمْ مَاءُ الْحَيَاةِ، فَيَنْبُتُونَ مِنْهُ كَمَا تَنْبُتُ الْحِبَّةُ فِي حَمِيلِ السَّيْلِ، ثُمَّ يَفْرُغُ اللَّهُ تَعَالَى مِنَ الْقَضَاءِ بَيْنَ الْعِبَادِ، وَيَبْقَى رَجُلٌ مُقْبِلٌ بِوَجْهِهِ عَلَى النَّارِ وَهُوَ آخِرُ أَهْلِ الْجَنَّةِ دُخُولًا الْجَنَّةَ، فَيَقُولُ: أَيْ رَبِّ اصْرِفْ وَجْهِي عَنِ النَّارِ، فَإِنَّهُ قَدْ قَشَبَنِي رِيحُهَا، وَأَحْرَقَنِي ذَكَاؤُهَا، فَيَدْعُو اللَّهَ مَا شَاءَ اللَّهُ أَنْ يَدْعُوَهُ، ثُمَّ يَقُولُ اللَّهُ تَبَارَكَ وَتَعَالَى: هَلْ عَسَيْتَ إِنْ فَعَلْتُ ذَلِكَ بِكَ أَنْ تَسْأَلَ غَيْرَهُ؟ فَيَقُولُ: لَا أَسْأَلُكَ غَيْرَهُ، وَيُعْطِي رَبَّهُ مِنْ عُهُودٍ، وَمَوَاثِيقَ مَا شَاءَ اللَّهُ، فَيَصْرِفُ اللَّهُ وَجْهَهُ عَنِ النَّارِ، فَإِذَا أَقْبَلَ عَلَى الْجَنَّةِ وَرَآهَا، سَكَتَ مَا شَاءَ اللَّهُ، أَنْ يَسْكُتَ ثُمَّ يَقُولُ: أَيْ رَبِّ قَدِّمْنِي إِلَى بَابِ الْجَنَّةِ، فَيَقُولُ اللَّهُ لَهُ: أَلَيْسَ قَدْ أَعْطَيْتَ عُهُودَكَ، وَمَوَاثِيقَكَ، لَا تَسْأَلُنِي غَيْرَ الَّذِي أَعْطَيْتُكَ، وَيْلَكَ يَا ابْنَ آدَمَ، مَا أَغْدَرَكَ، فَيَقُولُ: أَيْ رَبِّ، وَيَدْعُو اللَّهَ حَتَّى يَقُولَ لَهُ: فَهَلْ عَسَيْتَ إِنْ أَعْطَيْتُكَ ذَلِكَ، أَنْ تَسْأَلَ غَيْرَهُ؟ فَيَقُولُ: لَا وَعِزَّتِكَ، فَيُعْطِي رَبَّهُ مَا شَاءَ اللَّهُ مِنْ عُهُودٍ، وَمَوَاثِيقَ، فَيُقَدِّمُهُ إِلَى بَابِ الْجَنَّةِ، فَإِذَا قَامَ عَلَى بَابِ الْجَنَّةِ، انْفَهَقَتْ لَهُ الْجَنَّةُ، فَرَأَى مَا فِيهَا مِنَ الْخَيْرِ وَالسُّرُورِ، فَيَسْكُتُ مَا شَاءَ اللَّهُ أَنْ يَسْكُتَ، ثُمَّ يَقُولُ: أَيْ رَبِّ أَدْخِلْنِي الْجَنَّةَ؟ فَيَقُولُ اللَّهُ تَبَارَكَ وَتَعَالَى لَهُ: أَلَيْسَ قَدْ أَعْطَيْتَ عُهُودَكَ، وَمَوَاثِيقَكَ، أَنْ لَا تَسْأَلَ غَيْرَ مَا أُعْطِيتَ، وَيْلَكَ يَا ابْنَ آدَمَ، مَا أَغْدَرَكَ، فَيَقُولُ: أَيْ رَبِّ لَا أَكُونُ أَشْقَى خَلْقِكَ، فَلَا يَزَالُ يَدْعُو اللَّهَ، حَتَّى يَضْحَكَ اللَّهُ تَبَارَكَ وَتَعَالَى مِنْهُ، فَإِذَا ضَحِكَ اللَّهُ مِنْهُ، قَالَ: ادْخُلِ الْجَنَّةَ، فَإِذَا دَخَلَهَا، قَالَ اللَّهُ لَهُ: تَمَنَّهْ، فَيَسْأَلُ رَبَّهُ وَيَتَمَنَّى، حَتَّى إِنَّ اللَّهَ لَيُذَكِّرُهُ مِنْ كَذَا وَكَذَا، حَتَّى إِذَا انْقَطَعَتْ بِهِ الأَمَانِيُّ، قَالَ اللَّهُ تَعَالَى: ذَلِكَ لَكَ وَمِثْلُهُ مَعَهُ."],"takhrij":"متفق عليه: رواه البخاريّ في التوحيد (7437)، ومسلم في الإيمان (182) كلاهما من حديث إبراهيم بن سعد، عن ابن شهاب، عن عطاء بن يزيد اللّيثيّ، أنّ أبا هريرة أخبره أنّ ناساً قالوا (فذكر الحديث)، ولفظهما سواء.","grade":"متفق عليه","chapter_ar":"باب الصراط جسر جهنم","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7437) and Muslim (182).","chapter_en":"The Ṣirāṭ Is the Bridge Over Hell","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان باليوم الآخر","group_en":"Collection of Chapters Concerning Faith in the Last Day","part_no":2,"group_no":11,"chapter_no":8,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported: Some people asked the Messenger of Allah ﷺ: “O Messenger of Allah, will we see our Lord on the Day of Resurrection?” The Messenger of Allah ﷺ asked: “Do you experience any difficulty in seeing the full moon on a clear night?” They replied: “No, O Messenger of Allah.” He asked: “Do you experience any difficulty in seeing the sun when there are no clouds before it?” They replied: “No, O Messenger of Allah.” He said: “Then you will see Him in that manner. Allah will gather the people on the Day of Resurrection and say: ‘Whoever used to worship something, let him follow it.’ Whoever used to worship the sun will follow the sun; whoever used to worship the moon will follow the moon; and whoever used to worship false deities will follow those false deities. This Ummah will remain, with its hypocrites among it. Allah, Blessed and Exalted, will come to them in a form other than the form they recognize and say: ‘I am your Lord.’ They will say: ‘We seek refuge in Allah from you! We will remain here until our Lord comes to us. When our Lord comes, we will recognize Him.’ Then Allah Most High will come to them in the form they recognize and say: ‘I am your Lord.’ They will say: ‘You are our Lord.’ Then they will follow Him. The Ṣirāṭ will be placed across Hell. I and my Ummah will be the first to cross it. No one will speak on that Day except the messengers, and the supplication of the messengers on that Day will be: ‘O Allah, grant safety! Grant safety!’ In Hell there will be hooks like the thorns of al-Saʿdān. Have you seen al-Saʿdān?” They replied: “Yes, O Messenger of Allah.” He said: “They are like the thorns of al-Saʿdān, except that no one knows how enormous they are except Allah. They will seize the people according to their deeds. Among them will be the believer who is saved by his deeds, and among them will be one who is ruined. When Allah has finished judging between the servants and wishes, by His mercy, to bring out whomever He wills from the people of the Fire, He will command the angels to bring out from the Fire those who did not associate anything with Allah, from among those upon whom Allah Most High wishes to have mercy—those who used to say: ‘There is no deity worthy of worship except Allah.’ The angels will recognize them in the Fire by the marks of prostration. The Fire consumes every part of the son of Adam except the marks of prostration. Allah has forbidden the Fire from consuming the marks of prostration. They will be brought out of the Fire after having been severely burned and charred, and the Water of Life will be poured over them. They will grow from it just as a seed grows in the sediment carried by a flood. Then Allah Most High will finish judging between the servants. One man will remain facing the Fire—and he will be the last of the people of Paradise to enter Paradise. He will say: ‘My Lord, turn my face away from the Fire. Its odor has harmed me and its heat has burned me.’ He will supplicate to Allah for as long as Allah wills. Then Allah, Blessed and Exalted, will say: ‘If I do that for you, will you perhaps ask Me for something else?’ He will reply: ‘I will not ask You for anything else.’ He will give his Lord whatever covenants and pledges Allah wills, so Allah will turn his face away from the Fire. When he faces Paradise and sees it, he will remain silent for as long as Allah wills. Then he will say: ‘My Lord, bring me near the gate of Paradise.’ Allah will say to him: ‘Did you not give your pledges that you would ask for nothing beyond what I had already given you? Woe to you, O son of Adam! How treacherous you are!’ He will say: ‘My Lord…’ and continue supplicating until Allah says: ‘If I grant you that, will you then ask Me for something else?’ He will reply: ‘No, by Your Might!’ He will give his Lord whatever pledges and covenants Allah wills, and Allah will bring him near the gate of Paradise. When he stands at the gate of Paradise, Paradise will open wide before him and he will see the goodness and joy within it. He will remain silent for as long as Allah wills, then say: ‘My Lord, admit me into Paradise.’ Allah, Blessed and Exalted, will say: ‘Did you not give your pledges and covenants that you would ask for nothing beyond what I had already given you? Woe to you, O son of Adam! How treacherous you are!’ He will say: ‘My Lord, do not make me the most miserable of Your creation.’ He will continue supplicating to Allah until Allah, Blessed and Exalted, laughs at him. When Allah laughs at him, He will say: ‘Enter Paradise.’ When he enters it, Allah will say to him: ‘Wish.’ So he will ask his Lord and make wishes, until Allah Himself reminds him of this and that. When his wishes are exhausted, Allah Most High will say: ‘All of that is yours, and the like of it besides.’”"]},"buhuth":{"en":["The word:","“kalālīb”","is the plural of kallūb, meaning an iron hook with a curved head used to catch or seize something.","The expression:","“like the thorns of al-Saʿdān”","refers to a plant known for its large, sharp thorns.","The word:","“imtaḥashū”","means that they were burned and severely charred.","The word:","“infahaqat”","means that it opened widely and expanded."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (7437)، ومسلم (182)."},{"num":965,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، أَنَّ نَاسًا فِي زَمَنِ ِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالُوا: يَا رَسُولَ اللَّهِ، هَلْ نَرَى رَبَّنَا يَوْمَ الْقِيَامَةِ؟ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: نَعَمْ، قَالَ: هَلْ تُضَارُّونَ فِي رُؤْيَةِ الشَّمْسِ بِالظَّهِيرَةِ، صَحْوًا لَيْسَ مَعَهَا سَحَابٌ؟ وَهَلْ تُضَارُّونَ فِي رُؤْيَةِ الْقَمَرِ لَيْلَةَ الْبَدْرِ، صَحْوًا لَيْسَ فِيهَا سَحَابٌ؟ قَالُوا: لَا يَا رَسُولَ اللَّهِ، قَالَ: مَا تُضَارُّونَ فِي رُؤْيَةِ اللَّهِ تَبَارَكَ وَتَعَالَى يَوْمَ الْقِيَامَةِ، إِلَّا كَمَا تُضَارُّونَ فِي رُؤْيَةِ أَحَدِهِمَا، إِذَا كَانَ يَوْمُ الْقِيَامَةِ أَذَّنَ مُؤَذِّنٌ لِيَتَّبِعْ كُلُّ أُمَّةٍ مَا كَانَتْ تَعْبُدُ، فَلَا يَبْقَى أَحَدٌ كَانَ يَعْبُدُ غَيْرَ اللَّهِ سُبْحَانَهُ مِنَ الأَصْنَامِ، وَالأَنْصَابِ، إِلَّا يَتَسَاقَطُونَ فِي النَّارِ حَتَّى إِذَا لَمْ يَبْقَ إِلَّا مَنْ كَانَ يَعْبُدُ اللَّهَ مِنْ بَرٍّ، وَفَاجِرٍ، وَغُبَّرِ أَهْلِ الْكِتَابِ، فَيُدْعَى الْيَهُودُ، فَيُقَالُ لَهُمْ: مَا كُنْتُمْ تَعْبُدُونَ؟ قَالُوا: كُنَّا نَعْبُدُ عُزَيْرَ ابْنَ اللَّهِ، فَيُقَالُ: كَذَبْتُمْ، مَا اتَّخَذَ اللَّهُ مِنْ صَاحِبَةٍ، وَلَا وَلَدٍ، فَمَاذَا تَبْغُونَ؟ قَالُوا: عَطِشْنَا يَا رَبَّنَا فَاسْقِنَا، فَيُشَارُ إِلَيْهِمْ أَلَا تَرِدُونَ، فَيُحْشَرُونَ إِلَى النَّارِ، كَأَنَّهَا سَرَابٌ يَحْطِمُ بَعْضُهَا بَعْضًا، فَيَتَسَاقَطُونَ فِي النَّارِ، ثُمَّ يُدْعَى النَّصَارَى، فَيُقَالُ لَهُمْ: مَا كُنْتُمْ تَعْبُدُونَ؟ قَالُوا: كُنَّا نَعْبُدُ الْمَسِيحَ ابْنَ اللَّهِ، فَيُقَالُ لَهُمْ: كَذَبْتُمْ، مَا اتَّخَذَ اللَّهُ مِنْ صَاحِبَةٍ، وَلَا وَلَدٍ، فَيُقَالُ لَهُمْ: مَاذَا تَبْغُونَ؟ فَيَقُولُونَ: عَطِشْنَا يَا رَبَّنَا فَاسْقِنَا، قَالَ: فَيُشَارُ إِلَيْهِمْ، أَلَا تَرِدُونَ، فَيُحْشَرُونَ إِلَى جَهَنَّمَ، كَأَنَّهَا سَرَابٌ يَحْطِمُ بَعْضُهَا بَعْضًا، فَيَتَسَاقَطُونَ فِي النَّارِ، حَتَّى إِذَا لَمْ يَبْقَ إِلَّا مَنْ كَانَ يَعْبُدُ اللَّهَ تَعَالَى مِنْ بَرٍّ، وَفَاجِرٍ، أَتَاهُمْ رَبُّ الْعَالَمِينَ سُبْحَانَهُ وَتَعَالَى فِي أَدْنَى صُورَةٍ مِنَ الَّتِي رَأَوْهُ فِيهَا، قَالَ: فَمَا تَنْتَظِرُونَ، تَتْبَعُ كُلُّ أُمَّةٍ مَا كَانَتْ تَعْبُدُ، قَالُوا: يَا رَبَّنَا، فَارَقْنَا النَّاسَ فِي الدُّنْيَا، أَفْقَرَ مَا كُنَّا إِلَيْهِمْ وَلَمْ نُصَاحِبْهُمْ، فَيَقُولُ: أَنَا رَبُّكُمْ، فَيَقُولُونَ: نَعُوذُ بِاللَّهِ مِنْكَ، لَا نُشْرِكُ بِاللَّهِ شَيْئًا، مَرَّتَيْنِ أَوْ ثَلَاثًا، حَتَّى إِنَّ بَعْضَهُمْ لَيَكَادُ أَنْ يَنْقَلِبَ، فَيَقُولُ: هَلْ بَيْنَكُمْ وَبَيْنَهُ آيَةٌ فَتَعْرِفُونَهُ بِهَا؟ فَيَقُولُونَ: نَعَمْ، فَيُكْشَفُ عَنْ سَاقٍ، فَلَا يَبْقَى مَنْ كَانَ يَسْجُدُ لِلَّهِ مِنْ تِلْقَاءِ نَفْسِهِ، إِلَّا أَذِنَ اللَّهُ لَهُ بِالسُّجُودِ، وَلَا يَبْقَى مَنْ كَانَ يَسْجُدُ اتِّقَاءً وَرِيَاءً، إِلَّا جَعَلَ اللَّهُ ظَهْرَهُ طَبَقَةً وَاحِدَةً، كُلَّمَا أَرَادَ أَنْ يَسْجُدَ، خَرَّ عَلَى قَفَاهُ، ثُمَّ يَرْفَعُونَ رُءُوسَهُمْ وَقَدْ تَحَوَّلَ فِي صُورَتِهِ الَّتِي رَأَوْهُ فِيهَا أَوَّلَ مَرَّةٍ، فَقَالَ: أَنَا رَبُّكُمْ، فَيَقُولُونَ: أَنْتَ رَبُّنَا، ثُمَّ يُضْرَبُ الْجِسْرُ عَلَى جَهَنَّمَ، وَتَحِلُّ الشَّفَاعَةُ، وَيَقُولُونَ: اللَّهُمَّ سَلِّمْ سَلِّمْ، قِيلَ: يَا رَسُولَ اللَّهِ، وَمَا الْجِسْرُ؟ قَالَ: دَحْضٌ مَزِلَّةٌ فِيهِ خَطَاطِيفُ، وَكَلَالِيبُ، وَحَسَكٌ تَكُونُ بِنَجْدٍ فِيهَا شُوَيْكَةٌ، يُقَالُ لَهَا: السَّعْدَانُ، فَيَمُرُّ الْمُؤْمِنُونَ كَطَرْفِ الْعَيْنِ، وَكَالْبَرْقِ، وَكَالرِّيحِ، وَكَالطَّيْرِ، وَكَأَجَاوِيدِ الْخَيْلِ وَالرِّكَابِ، فَنَاجٍ مُسَلَّمٌ، وَمَخْدُوشٌ مُرْسَلٌ، وَمَكْدُوسٌ فِي نَارِ جَهَنَّمَ، حَتَّى إِذَا خَلَصَ الْمُؤْمِنُونَ مِنَ النَّارِ، فَوَالَّذِي نَفْسِي بِيَدِهِ، مَا مِنْكُمْ مِنْ أَحَدٍ بِأَشَدَّ مُنَاشَدَةً لِلَّهِ فِي اسْتِقْصَاءِ الْحَقِّ مِنَ الْمُؤْمِنِينَ، لِلَّهِ يَوْمَ الْقِيَامَةِ لِإِخْوَانِهِمُ الَّذِينَ فِي النَّارِ، يَقُولُونَ: رَبَّنَا كَانُوا يَصُومُونَ مَعَنَا، وَيُصَلُّونَ، وَيَحُجُّونَ، فَيُقَالُ لَهُمْ: أَخْرِجُوا مَنْ عَرَفْتُمْ، فَتُحَرَّمُ صُوَرُهُمْ عَلَى النَّار، فَيُخْرِجُونَ خَلْقًا كَثِيرًا قَدْ أَخَذَتِ النَّارُ إِلَى نِصْفِ سَاقَيْهِ وَإِلَى رُكْبَتَيْهِ، ثُمَّ يَقُولُونَ: رَبَّنَا مَا بَقِيَ فِيهَا أَحَدٌ مِمَّنْ أَمَرْتَنَا بِهِ، فَيَقُولُ: ارْجِعُوا، فَمَنْ وَجَدْتُمْ فِي قَلْبِهِ مِثْقَالَ دِينَارٍ مِنْ خَيْرٍ، فَأَخْرِجُوهُ فَيُخْرِجُونَ خَلْقًا كَثِيرًا، ثُمَّ يَقُولُونَ: رَبَّنَا لَمْ نَذَرْ فِيهَا أَحَدًا مِمَّنْ أَمَرْتَنَا، ثُمَّ يَقُولُ: ارْجِعُوا فَمَنْ وَجَدْتُمْ فِي قَلْبِهِ مِثْقَالَ نِصْفِ دِينَارٍ مِنَ خَيْرٍ فَأَخْرِجُوهُ، فَيُخْرِجُونَ خَلْقًا كَثِيرًا، ثُمَّ يَقُولُونَ: رَبَّنَا لَمْ نَذَرْ فِيهَا مِمَّنْ أَمَرْتَنَا أَحَدًا، ثُمَّ يَقُولُ: ارْجِعُوا فَمَنْ وَجَدْتُمْ فِي قَلْبِهِ مِثْقَالَ ذَرَّةٍ مِنْ خَيْر، فَأَخْرِجُوهُ فَيُخْرِجُونَ خَلْقًا كَثِيرًا، ثُمَّ يَقُولُونَ: رَبَّنَا لَمْ نَذَرْ فِيهَا خَيْرًا.","وَكَانَ أَبُو سَعِيدٍ الْخُدْرِيُّ يَقُولُ: إِنْ لَمْ تُصَدِّقُونِي بِهَذَا الْحَدِيثِ، فَاقْرَءُوا إِنْ شِئْتُمْ: ﴿إِنَّ اللَّهَ لَا يَظْلِمُ مِثْقَالَ ذَرَّةٍ وَإِنْ تَكُ حَسَنَةً يُضَاعِفْهَا وَيُؤْتِ مِنْ لَدُنْهُ أَجْرًا عَظِيمًا﴾ [سورة النساء: 40]. فَيَقُولُ اللَّهُ عَزَّ وَجَلَّ: شَفَعَتِ الْمَلَائِكَةُ، وَشَفَعَ النَّبِيُّونَ، وَشَفَعَ الْمُؤْمِنُونَ، وَلَمْ يَبْقَ إِلَّا أَرْحَمُ الرَّاحِمِينَ، فَيَقْبِضُ قَبْضَةً مِنَ النَّارِ، فَيُخْرِجُ مِنْهَا قَوْمًا لَمْ يَعْمَلُوا خَيْرًا قَطُّ، قَدْ عَادُوا حُمَمًا، فَيُلْقِيهِمْ فِي نَهَرٍ فِي أَفْوَاهِ الْجَنَّةِ، يُقَالُ لَهُ: نَهَرُ الْحَيَاةِ، فَيَخْرُجُونَ كَمَا تَخْرُجُ الْحِبَّةُ فِي حَمِيلِ السَّيْلِ أَلَا تَرَوْنَهَا تَكُونُ إِلَى الْحَجَرِ أَوْ إِلَى الشَّجَرِ، مَا يَكُونُ إِلَى الشَّمْسِ، أُصَيْفِرُ، وَأُخَيْضِرُ، وَمَا يَكُونُ مِنْهَا إِلَى الظِّلِّ يَكُونُ أَبْيَضَ، فَقَالُوا: يَا رَسُولَ اللَّهِ، كَأَنَّكَ كُنْتَ تَرْعَى بِالْبَادِيَةِ؟ قَالَ: فَيَخْرُجُونَ كَاللُّؤْلُؤِ فِي رِقَابِهِمُ الْخَوَاتِمُ، يَعْرِفُهُمْ أَهْلُ الْجَنَّةِ هَؤُلَاءِ عُتَقَاءُ اللَّهِ الَّذِينَ أَدْخَلَهُمُ اللَّهُ الْجَنَّةَ بِغَيْرِ عَمَلٍ عَمِلُوهُ، وَلَا خَيْرٍ قَدَّمُوهُ، ثُمَّ يَقُولُ: ادْخُلُوا الْجَنَّةَ، فَمَا رَأَيْتُمُوهُ فَهُوَ لَكُمْ، فَيَقُولُونَ: رَبَّنَا أَعْطَيْتَنَا مَا لَمْ تُعْطِ أَحَدًا مِنَ الْعَالَمِينَ؟ فَيَقُولُ: لَكُمْ عِنْدِي أَفْضَلُ مِنْ هَذَا، فَيَقُولُونَ: يَا رَبَّنَا، أَيُّ شَيْءٍ أَفْضَلُ مِنْ هَذَا؟ فَيَقُولُ: رِضَايَ، فَلَا أَسْخَطُ عَلَيْكُمْ بَعْدَهُ أَبَدًا."],"takhrij":"متفق عليه: رواه البخاريّ في التفسير (4581)، ومسلم في الإيمان (183) كلاهما من حديث حفص بن ميسرة، عن زيد بن أسلم، عن عطاء بن يسار، عن أبي سعيد الخدريّ، فذكر الحديث، واللّفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب الصراط جسر جهنم","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4581) and Muslim (183). The wording is that of Muslim.","chapter_en":"The Ṣirāṭ Is the Bridge Over Hell","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان باليوم الآخر","group_en":"Collection of Chapters Concerning Faith in the Last Day","part_no":2,"group_no":11,"chapter_no":8,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī, may Allah be pleased with him, reported: Some people during the lifetime of the Messenger of Allah ﷺ asked: “O Messenger of Allah, will we see our Lord on the Day of Resurrection?” The Messenger of Allah ﷺ replied: “Yes.” He asked: “Do you experience any difficulty in seeing the sun at midday on a clear day when there are no clouds? And do you experience any difficulty in seeing the full moon on a clear night when there are no clouds?” They replied: “No, O Messenger of Allah.” He said: “You will experience no difficulty in seeing Allah, Blessed and Exalted, on the Day of Resurrection, just as you experience no difficulty in seeing either of those two. When the Day of Resurrection comes, a caller will proclaim: ‘Let every nation follow what it used to worship.’ No one who worshipped anything besides Allah, Glorified is He, from among idols and stone altars will remain except that they will fall into the Fire. When none remain except those who worshipped Allah, whether righteous or sinful, together with remnants of the People of the Scripture, the Jews will be called and asked: ‘What did you worship?’ They will reply: ‘We used to worship ʿUzayr, the son of Allah.’ It will be said: ‘You have lied. Allah has taken neither a consort nor a child. What do you seek?’ They will say: ‘Our Lord, we are thirsty, so give us drink.’ It will be indicated to them: ‘Will you not go to drink?’ They will then be driven toward the Fire as though it were a mirage, one part crashing into another, and they will fall into the Fire. Then the Christians will be called and asked: ‘What did you worship?’ They will reply: ‘We used to worship the Messiah, the son of Allah.’ It will be said to them: ‘You have lied. Allah has taken neither a consort nor a child.’ They will be asked: ‘What do you seek?’ They will say: ‘Our Lord, we are thirsty, so give us drink.’ It will be indicated to them: ‘Will you not go to drink?’ They will be driven toward Hell as though it were a mirage, one part crashing into another, and they will fall into the Fire. When none remain except those who worshipped Allah Most High, whether righteous or sinful, the Lord of the worlds, Glorified and Exalted, will come to them in a form different from the form in which they first recognized Him. It will be said: ‘What are you waiting for? Every nation has followed what it used to worship.’ They will say: ‘Our Lord, we separated ourselves from the people in the world when we were most in need of them, and we did not accompany them.’ He will say: ‘I am your Lord.’ They will say: ‘We seek refuge in Allah from you. We associate nothing with Allah.’ They will repeat this two or three times, until some of them nearly turn back. He will ask: ‘Is there a sign between you and Him by which you will recognize Him?’ They will reply: ‘Yes.’ Then the Shin will be uncovered. No one who used to prostrate to Allah willingly and sincerely will remain except that Allah will permit him to prostrate. But no one who used to prostrate merely out of fear or showing off will remain except that Allah will make his back one rigid plate; whenever he attempts to prostrate, he will fall backward. Then they will raise their heads, and He will have returned to the form in which they recognized Him the first time. He will say: ‘I am your Lord.’ They will say: ‘You are our Lord.’ Then the bridge will be placed across Hell, intercession will be permitted, and they will say: ‘O Allah, grant safety! Grant safety!’ It was asked: “O Messenger of Allah, what is the bridge?” He replied: “It is slippery and causes feet to slip. Upon it are grappling hooks, hooks, and thorny spikes like the thorns of a plant found in Najd called al-Saʿdān. The believers will pass over it like the blink of an eye, like lightning, like the wind, like birds, and like the finest horses and riding animals. Some will be saved completely unharmed, some will be scratched and then released, and some will be thrown into the Fire of Hell. When the believers have been delivered from the Fire, then by the One in whose Hand is my soul, none of you will plead with Allah more insistently for the restoration of his rights than the believers will plead with Allah on the Day of Resurrection concerning their brothers who are in the Fire. They will say: ‘Our Lord, they used to fast with us, pray with us, and perform Ḥajj with us.’ It will be said to them: ‘Bring out those whom you recognize.’ Their forms will be made forbidden to the Fire. They will bring out a great many people, some of whom the Fire had reached halfway up their shins and others up to their knees. They will then say: ‘Our Lord, none remains therein of those whom You commanded us to bring out.’ He will say: ‘Return, and whoever you find with the weight of a dinar of goodness in his heart, bring him out.’ They will bring out a great many people. Then they will say: ‘Our Lord, we have left no one therein whom You commanded us to bring out.’ He will say: ‘Return, and whoever you find with the weight of half a dinar of goodness in his heart, bring him out.’ They will bring out a great many people. Then they will say: ‘Our Lord, we have left no one therein whom You commanded us to bring out.’ He will say: ‘Return, and whoever you find with the weight of an atom of goodness in his heart, bring him out.’ They will bring out a great many people. Then they will say: ‘Our Lord, we have left no goodness therein.’”","Abū Saʿīd al-Khudrī may Allah be pleased with him used to say: “If you do not believe me regarding this ḥadīth, then recite, if you wish: ‘Indeed, Allah does not wrong even by the weight of an atom. If there is a good deed, He multiplies it and gives from Himself a tremendous reward.’” [Sūrat al-Nisāʾ 4:40] Then Allah, Mighty and Majestic, will say: “The angels have interceded, the prophets have interceded, and the believers have interceded, and none remains except the Most Merciful of those who show mercy. He will take a handful from the Fire and bring out from it people who never performed any good deed at all and who have become charcoal. He will cast them into a river at the entrances of Paradise called the River of Life. They will emerge from it just as a seed emerges from the sediment carried by a flood. Do you not see that what grows beside a stone or tree, when exposed to the sun, becomes yellowish or greenish, while what grows in the shade becomes white?” They said: “O Messenger of Allah, it is as though you used to herd animals in the desert!” He continued: “They will emerge like pearls, with marks upon their necks. The people of Paradise will recognize them: ‘These are those whom Allah freed, whom Allah admitted into Paradise without any deed they performed and without any good they sent ahead.’ Then He will say: ‘Enter Paradise. Whatever you see therein is yours.’ They will say: ‘Our Lord, You have given us what You have not given anyone among all the worlds.’ He will say: ‘I have something with Me for you that is even better than this.’ They will ask: ‘Our Lord, what could be better than this?’ He will say: ‘My pleasure. I will never be displeased with you after this, ever.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (4581)، ومسلم (183)، واللفظ لمسلم."},{"num":966,"demo":false,"sanad":"","matn":["عَنِ ابْنِ مَسْعُودٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: آخِرُ مَنْ يَدْخُلُ الْجَنَّةَ رَجُلٌ، فَهْوَ يَمْشِي مَرَّةً، وَيَكْبُو مَرَّةً، وَتَسْفَعُهُ النَّارُ مَرَّةً، فَإِذَا مَا جَاوَزَهَا الْتَفَتَ إِلَيْهَا، فَقَالَ: تَبَارَكَ الَّذِي نَجَّانِي مِنْكِ، لَقَدْ أَعْطَانِي اللَّهُ شَيْئًا مَا أَعْطَاهُ أَحَدًا مِنَ الأَوَّلِينَ وَالآخِرِينَ، فَتُرْفَعُ لَهُ شَجَرَةٌ، فَيَقُولُ: أَيْ رَبِّ، أَدْنِنِي مِنْ هَذِهِ الشَّجَرَةِ، فَلِأَسْتَظِلَّ بِظِلِّهَا، وَأَشْرَبَ مِنْ مَائِهَا، فَيَقُولُ اللَّهُ عَزَّ وَجَلَّ: يَا ابْنَ آدَمَ، لَعَلِّي إِنَّ أَعْطَيْتُكَهَا سَأَلْتَنِي غَيْرَهَا؟ فَيَقُولُ: لَا يَا رَبِّ، وَيُعَاهِدُهُ أَنْ لَا يَسْأَلَهُ غَيْرَهَا، وَرَبُّهُ يَعْذِرُهُ، لِأَنَّهُ يَرَى مَا لَا صَبْرَ لَهُ عَلَيْهِ، فَيُدْنِيهِ مِنْهَا، فَيَسْتَظِلُّ بِظِلِّهَا، وَيَشْرَبُ مِنْ مَائِهَا، ثُمَّ تُرْفَعُ لَهُ شَجَرَةٌ هِيَ أَحْسَنُ مِنَ الأُولَى، فَيَقُولُ: أَيْ رَبِّ، أَدْنِنِي مِنْ هَذِهِ لِأَشْرَبَ مِنْ مَائِهَا، وَأَسْتَظِلَّ بِظِلِّهَا، لَا أَسْأَلُكَ غَيْرَهَا، فَيَقُولُ: يَا ابْنَ آدَمَ، أَلَمْ تُعَاهِدْنِي أَنْ لَا تَسْأَلَنِي غَيْرَهَا؟ فَيَقُولُ: لَعَلِّي إِنْ أَدْنَيْتُكَ مِنْهَا تَسْأَلُنِي غَيْرَهَا، فَيُعَاهِدُهُ أَنْ لَا يَسْأَلَهُ غَيْرَهَا، وَرَبُّهُ يَعْذِرُهُ، لِأَنَّهُ يَرَى مَا لَا صَبْرَ لَهُ عَلَيْه، فَيُدْنِيهِ مِنْهَا، فَيَسْتَظِلُّ بِظِلِّهَا، وَيَشْرَبُ مِنْ مَائِهَا، ثُمَّ تُرْفَعُ لَهُ شَجَرَةٌ عِنْدَ بَابِ الْجَنَّةِ هِيَ أَحْسَنُ مِنَ الأُولَيَيْنِ، فَيَقُولُ: أَيْ رَبِّ، أَدْنِنِي مِنْ هَذِهِ لِأَسْتَظِلَّ بِظِلِّهَا وَأَشْرَبَ مِنْ مَائِهَا، لَا أَسْأَلُكَ غَيْرَهَا، فَيَقُولُ: يَا ابْنَ آدَمَ، أَلَمْ تُعَاهِدْنِي أَنْ لَا تَسْأَلَنِي غَيْرَهَا؟ قَالَ: بَلَى يَا رَبِّ، هَذِهِ لَا أَسْأَلُكَ غَيْرَهَا، وَرَبُّهُ يَعْذِرُهُ، لِأَنَّهُ يَرَى مَا لَا صَبْرَ لَهُ عَلَيْهَا، فَيُدْنِيهِ مِنْهَا، فَإِذَا أَدْنَاهُ مِنْهَا فَيَسْمَعُ أَصْوَاتَ أَهْلِ الْجَنَّةِ، فَيَقُولُ: أَيْ رَبِّ أَدْخِلْنِيهَا؟ فَيَقُولُ: يَا ابْنَ آدَمَ، مَا يَصْرِينِي مِنْكَ، أَيُرْضِيكَ أَنْ أُعْطِيَكَ الدُّنْيَا وَمِثْلَهَا مَعَهَا؟ قَالَ: يَا رَبِّ، أَتَسْتَهْزِئُ مِنِّي وَأَنْتَ رَبُّ الْعَالَمِينَ؟.","فَضَحِكَ ابْنُ مَسْعُودٍ فَقَالَ: أَلَا تَسْأَلُونِي مِمَّ أَضْحَكُ؟ فَقَالُوا: مِمَّ تَضْحَكُ؟ قَالَ: هَكَذَا ضَحِكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالُوا: مِمَّ تَضْحَكُ يَا رَسُولَ اللَّهِ؟ قَالَ: مِنْ ضِحْكِ رَبِّ الْعَالَمِينَ، حِينَ قَالَ: أَتَسْتَهْزِئُ مِنِّي وَأَنْتَ رَبُّ الْعَالَمِينَ ؟، فَيَقُولُ: إِنِّي لَا أَسْتَهْزِئُ مِنْكَ، وَلَكِنِّي عَلَى مَا أَشَاءُ قَادِرٌ."],"takhrij":"صحيح: رواه مسلم في الإيمان (187) عن أبي بكر بن أبي شيبة، حدّثنا عفّان بن مسلم، حدّثنا حمّاد بن سلمة، حدّثنا ثابت، عن أنس بن مالك، عن ابن مسعود، فذكره. إلاّ أنّ مسلماً لم يذكر لفظ الصّراط وهو ثابت عند غيره، وإنّما اكتفى بقوله: يمشي مرة، ويكبو مرة، وتسعفه النار مرة.","grade":"صحيح","chapter_ar":"باب الصراط جسر جهنم","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (187).","chapter_en":"The Ṣirāṭ Is the Bridge Over Hell","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان باليوم الآخر","group_en":"Collection of Chapters Concerning Faith in the Last Day","part_no":2,"group_no":11,"chapter_no":8,"content":{"translation":{"en":["Ibn Masʿūd may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “The last person to enter Paradise will be a man who sometimes walks, sometimes stumbles, and sometimes is scorched by the Fire. When he has passed beyond it, he will turn toward it and say: ‘Blessed is the One who saved me from you! Allah has given me something that He did not give anyone among the first or the last.’ Then a tree will be raised before him. He will say: ‘My Lord, bring me near this tree so that I may take shade beneath it and drink from its water.’ Allah, Mighty and Majestic, will say: ‘O son of Adam, perhaps if I give you this, you will ask Me for something else?’ He will reply: ‘No, my Lord.’ He will promise not to ask Him for anything else. His Lord will excuse him because He sees that which the man cannot bear to resist. So He will bring him near it, and he will take shade beneath it and drink from its water. Then another tree, more beautiful than the first, will be raised before him. He will say: ‘My Lord, bring me near this one so that I may drink from its water and take shade beneath it. I will ask You for nothing else.’ Allah will say: ‘O son of Adam, did you not promise Me that you would ask Me for nothing else? Perhaps if I bring you near it, you will ask Me for something else?’ He will again promise that he will ask for nothing else. His Lord will excuse him because He sees that which the man cannot bear to resist. So He will bring him near it, and he will take shade beneath it and drink from its water. Then another tree will be raised before him at the gate of Paradise, more beautiful than the previous two. He will say: ‘My Lord, bring me near this one so that I may take shade beneath it and drink from its water. I will ask You for nothing else.’ Allah will say: ‘O son of Adam, did you not promise Me that you would ask Me for nothing else?’ He will reply: ‘Yes, my Lord. This one—and I will ask You for nothing else.’ His Lord will excuse him because He sees that which the man cannot bear to resist. So He will bring him near it. When He brings him near it, he will hear the voices of the people of Paradise and say: ‘My Lord, admit me into it.’ Allah will say: ‘O son of Adam, what will bring your requests to an end? Would it please you if I gave you the entire world and another like it with it?’ He will say: ‘My Lord, are You making fun of me while You are the Lord of the worlds?’” Ibn Masʿūd laughed and said:","“Will you not ask me why I am laughing?” They asked: “Why are you laughing?” He replied: “This is how the Messenger of Allah ﷺ laughed.” They asked: “Why did you laugh, O Messenger of Allah?” He replied: “Because of the laughter of the Lord of the worlds when the man says: ‘Are You making fun of me while You are the Lord of the worlds?’ Allah will say: ‘I am not making fun of you. Rather, I am capable of whatever I will.’” Then He will admit him into Paradise."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (187)."},{"num":967,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ وَ حُذَيْفَةَ قَالَا: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَجْمَعُ اللَّهُ تَبَارَكَ وَتَعَالَى النَّاسَ، فَيَقُومُ الْمُؤْمِنُونَ، حَتَّى تُزْلَفَ لَهُمُ الْجَنَّةُ، فَيَأْتُونَ آدَمَ، فَيَقُولُونَ: يَا أَبَانَا، اسْتَفْتِحْ لَنَا الْجَنَّةَ، فَيَقُولُ: وَهَلْ أَخْرَجَكُمْ مِنَ الْجَنَّةِ، إِلَّا خَطِيئَةُ أَبِيكُمْ آدَمَ، لَسْتُ بِصَاحِبِ ذَلِكَ، اذْهَبُوا إِلَى ابْنِي إِبْرَاهِيمَ خَلِيلِ اللَّهِ، قَالَ: فَيَقُولُ إِبْرَاهِيمُ: لَسْتُ بِصَاحِبِ ذَلِكَ، إِنَّمَا كُنْتُ خَلِيلًا مِنْ وَرَاءَ، وَرَاءَ، اعْمِدُوا إِلَى مُوسَى عَلَيْهِ السَّلامُ، الَّذِي كَلَّمَهُ اللَّهُ تَكْلِيمًا، فَيَأْتُونَ مُوسَى عَلَيْهِ السَّلامُ، فَيَقُولُ: لَسْتُ بِصَاحِبِ ذَلِكَ، اذْهَبُوا إِلَى عِيسَى، كَلِمَةِ اللَّهِ وَرُوحِهِ، فَيَقُولُ عِيسَى عَلَيْهِ السَّلامُ: لَسْتُ بِصَاحِبِ ذَلِكَ، فَيَأْتُونَ مُحَمَّدًا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَيَقُومُ فَيُؤْذَنُ لَهُ، وَتُرْسَلُ الأَمَانَةُ وَالرَّحِمُ، فَتَقُومَانِ جَنَبَتَيِ الصِّرَاطِ يَمِينًا وَشِمَالًا، فَيَمُرُّ أَوَّلُكُمْ كَالْبَرْقِ، قَالَ: قُلْتُ: بِأَبِي أَنْتَ وَأُمِّي، أَيُّ شَيْءٍ كَمَرِّ الْبَرْقِ؟ قَالَ: أَلَمْ تَرَوْا إِلَى الْبَرْقِ كَيْفَ يَمُرُّ وَيَرْجِعُ فِي طَرْفَةِ عَيْنٍ، ثُمَّ كَمَرِّ الرِّيحِ، ثُمَّ كَمَرِّ الطَّيْرِ وَشَدِّ الرِّجَالِ تَجْرِي بِهِمْ أَعْمَالُهُمْ، وَنَبِيُّكُمْ قَائِمٌ عَلَى الصِّرَاطِ؟ يَقُولُ: رَبِّ سَلِّمْ، سَلِّمْ، حَتَّى تَعْجِزَ أَعْمَالُ الْعِبَادِ، حَتَّى يَجِيءَ الرَّجُلُ، فَلَا يَسْتَطِيعُ السَّيْرَ إِلَّا زَحْفًا، قَالَ: وَفِي حَافَتَيِ الصِّرَاطِ كَلَالِيبُ مُعَلَّقَةٌ مَأْمُورَةٌ بِأَخْذِ مَنْ أُمِرَتْ بِهِ، فَمَخْدُوشٌ نَاجٍ، وَمَكْدُوسٌ فِي النَّارِ، وَالَّذِي نَفْسُ أَبِي هُرَيْرَةَ بِيَدِهِ، إِنَّ قَعْرَ جَهَنَّمَ لَسَبْعُونَ خَرِيفًا."],"takhrij":"صحيح: رواه مسلم في الإيمان (195) عن محمد بن خليفة البجليّ، حدّثنا محمد بن فضيل، حدّثنا أبو مالك الأشجعيّ، عن أبي حازم، عن أبي هريرة.","grade":"صحيح","chapter_ar":"باب الصراط جسر جهنم","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim in al-Īmān (195).","chapter_en":"The Ṣirāṭ Is the Bridge Over Hell","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان باليوم الآخر","group_en":"Collection of Chapters Concerning Faith in the Last Day","part_no":2,"group_no":11,"chapter_no":8,"content":{"translation":{"en":["Abū Hurayrah and Ḥudhayfah may Allah be pleased with them reported that the Messenger of Allah ﷺ said: “Allah, Blessed and Exalted, will gather the people. The believers will stand until Paradise is brought near to them. They will come to Adam and say: ‘Our father, ask that Paradise be opened for us.’ He will say: ‘Was it not the sin of your father Adam that caused you to be expelled from Paradise? I am not the one for this. Go to my son Abraham, the close friend of Allah.’ Abraham will say: ‘I am not the one for this. I was only a close friend from far, far away. Go to Moses ﷺ, the one to whom Allah spoke directly.’ They will come to Moses ﷺ, and he will say: ‘I am not the one for this. Go to Jesus, the Word of Allah and His Spirit.’ Jesus ﷺ will say: ‘I am not the one for this.’ Then they will come to Muḥammad ﷺ. He will stand, and permission will be granted to him. Trustworthiness and the ties of kinship will be sent forth, and they will stand on the two sides of the Ṣirāṭ, on the right and on the left. The first of you will pass like lightning.” I asked: “May my father and mother be sacrificed for you! What is passing like lightning?” He replied: “Have you not seen how lightning passes and returns in the blink of an eye? Then some will pass like the wind, then like birds, and then like men running swiftly. Their deeds will carry them along. Your Prophet will be standing upon the Ṣirāṭ saying: ‘My Lord, save! Save!’ Until the deeds of the servants become insufficient, and a man will come who cannot move except by crawling. On the two sides of the Ṣirāṭ are hooks hanging there, commanded to seize those whom they are commanded to seize. Some will be scratched but saved, while others will be piled into the Fire.” By the One in whose Hand is the soul of Abū Hurayrah, the depth of Hell is seventy years."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (195)."},{"num":968,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، أَنَّهُ سُئِلَ عَنِ الْوُرُودِ، قَالَ: نَحْنُ يَوْمَ الْقِيَامَةِ عَلَى كَذَا وَكَذَا، انْظُرْ أَيْ ذَلِكَ فَوْقَ النَّاسِ، قَالَ: فَتُدْعَى الْأُمَمُ بِأَوْثَانِهَا وَمَا كَانَتْ تَعْبُدُ، الْأَوَّلَ فَالْأَوَّلَ، ثُمَّ يَأْتِينَا رَبُّنَا بَعْدَ ذَلِكَ، فَيَقُولُ: مَنْ تَنْتَظِرُونَ؟ فَيَقُولُونَ: نَنْتَظِرُ رَبَّنَا عَزَّ وَجَلَّ، فَيَقُولُ: أَنَا رَبُّكُمْ، فَيَقُولُونَ: حَتَّى نَنْظُرَ إِلَيْكَ، فَيَتَجَلَّى لَهُمْ يَضْحَكُ.","قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: فَيَنْطَلِقُ بِهِمْ وَيَتَّبِعُونَهُ، وَيُعْطَى كُلُّ إِنْسَانٍ مُنَافِقٍ أَوْ مُؤْمِنٍ نُورًا، ثُمَّ يَتَّبِعُونَهُ، عَلَى جِسْرِ جَهَنَّمَ كَلَالِيبُ، وَحَسَكٌ تَأْخُذُ مَنْ شَاءَ اللَّهُ، ثُمَّ يُطْفَأُ نُورُ الْمُنَافِقِ، ثُمَّ يَنْجُو الْمُؤْمِنُونَ فَتَنْجُو أَوَّلُ زُمْرَةٍ، وُجُوهُهُمْ كَالْقَمَرِ لَيْلَةَ الْبَدْرِ، سَبْعُونَ أَلْفًا لَا يُحَاسَبُونَ، ثُمَّ الَّذِينَ يَلُونَهُمْ كَأَضْوَإِ نَجْمٍ فِي السَّمَاءِ، ثُمَّ كَذَلِكَ، ثُمَّ تَحِلُّ الشَّفَاعَةُ، حَتَّى يَخْرُجَ مِنَ النَّارِ مَنْ قَالَ: لَا إِلَهَ إِلَّا اللَّهُ، وَكَانَ فِي قَلْبِهِ مِنَ الْخَيْرِ مَا يَزِنُ شَعِيرَةً، فَيُجْعَلُونَ بِفِنَاءِ أَهْلِ الْجَنَّةِ، وَيَجْعَلُ أَهْلُ الْجَنَّةِ يَرُشُّونَ عَلَيْهِمِ الْمَاءَ، حَتَّى يَنْبُتُونَ نَبَاتَ الشَّيْءِ فِي السَّيْلِ، ثُمَّ يَسْأَلُ حَتَّى يُجْعَلَ لَهُ الدُّنْيَا وَعَشَرَةُ أَمْثَالِهَا مَعَهَا."],"takhrij":"صحيح: رواه مسلم في الإيمان (191) من طرق عن روح بن عبادة، حدثنا ابن جريج، قال: أخبرني أبو الزبير، أنه سمع جابر بن عبدالله يسأل عن الورود، فذكره.","grade":"صحيح","chapter_ar":"باب الصراط جسر جهنم","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim in al-Īmān (191).","chapter_en":"The Ṣirāṭ Is the Bridge Over Hell","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان باليوم الآخر","group_en":"Collection of Chapters Concerning Faith in the Last Day","part_no":2,"group_no":11,"chapter_no":8,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh may Allah be pleased with them was asked about the coming to the Fire, and he said: “On the Day of Resurrection we will be at such-and-such a place”—meaning above the people. “The nations will then be called with their idols and whatever they used to worship, one after another. Then our Lord will come to us afterward and say: ‘Whom are you waiting for?’ They will reply: ‘We are waiting for our Lord.’ He will say: ‘I am your Lord.’ They will say: ‘Not until we look at You.’ Then He will reveal Himself to them, laughing.” Jābir said: I heard the Prophet ﷺ say:","“Then He will proceed with them and they will follow Him. Every person, whether hypocrite or believer, will be given a light, and they will follow. Upon the bridge over Hell there will be hooks and thorns which seize whomever Allah wills. Then the hypocrite’s light will be extinguished; the believers will be saved. The first group to be saved will consist of seventy thousand whose faces are like the moon on the night of the full moon. They will not be brought to account. Those who follow them will be like the brightest star in the sky, and so on. Then intercession will take place until whoever said: ‘There is no deity worthy of worship except Allah,’ and had in his heart goodness equal to the weight of a grain of barley, will be brought out of the Fire. They will be placed in the open area before the people of Paradise, and the people of Paradise will sprinkle water over them until they grow as vegetation grows in floodwater. Then the man will continue asking until he is granted the world and ten times its like along with it.”"]},"buhuth":{"en":["From this same route, Imām Aḥmad (15115) also narrated it, and the wording is his."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (191)."},{"num":969,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: سَأَلْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ قَوْلِهِ عَزَّ وَجَلَّ: ﴿يَوْمَ تُبَدَّلُ الْأَرْضُ غَيْرَ الْأَرْضِ وَالسَّمَاوَاتُ وَبَرَزُوا لِلَّهِ الْوَاحِدِ الْقَهَّارِ﴾ [إبراهيم: 48] فَأَيْنَ يَكُونُ النَّاسُ يَوْمَئِذٍ يَا رَسُولَ اللَّهِ ؟، فَقَالَ: عَلَى الصِّرَاطِ."],"takhrij":"صحيح: رواه مسلم في صفات المنافقين (2791) عن أبي بكر بن أبي شيبة، حدّثنا علي بن مسهر، عن داود، عن الشعبي، عن مسروق، عن عائشة، فذكرته.","grade":"صحيح","chapter_ar":"باب الصراط جسر جهنم","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2791).","chapter_en":"The Ṣirāṭ Is the Bridge Over Hell","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان باليوم الآخر","group_en":"Collection of Chapters Concerning Faith in the Last Day","part_no":2,"group_no":11,"chapter_no":8,"content":{"translation":{"en":["ʿĀʾishah may Allah be pleased with her said: I asked the Messenger of Allah ﷺ about the statement of Allah, Mighty and Majestic: “On the Day the earth will be changed to another earth, and the heavens as well, and all will appear before Allah, the One, the Overpowering.” [Sūrat Ibrāhīm 14:48] I asked: “Where will the people be on that Day, O Messenger of Allah?” He replied: “Upon the Ṣirāṭ.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2791)."},{"num":970,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ يَقُولُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: يُوضَعُ الصِّرَاطُ بَيْنَ ظَهْرَيْ جَهَنَّمَ، عَلَيْهِ حَسَكٌ كَحَسَكِ السَّعْدَانِ، ثُمَّ يَسْتَجِيزُ النَّاسُ، فَنَاجٍ مُسَلَّمٌ، وَمَجْروحٌ بِهِ، ثُمَّ نَاجٍ وَمُحْتَبِسٌ بِهِ، مَنْكُوسٌ فِيهَا، فَإِذَا فَرَغَ اللَّهُ عَزَّ وَجَلَّ مِنَ الْقَضَاءِ بَيْنَ الْعِبَادِ يَفْقِدُ الْمُؤْمِنُونَ رِجَالًا كَانُوا مَعَهُمْ فِي الدُّنْيَا يُصَلُّونَ بِصَلَاتِهِمْ، وَيُزَكُّونَ بِزَكَاتِهِمْ، وَيَصُومُونَ صِيَامَهُمْ، وَيَحُجُّونَ حَجَّهُمْ، وَيَغْزُونَ غَزْوَهُمْ، فَيَقُولُونَ: أَيْ رَبَّنَا عِبَادٌ مِنْ عِبَادِكَ كَانُوا مَعَنَا فِي الدُّنْيَا، يُصَلُّونَ صَلَاتَنَا، وَيُزَكُّونَ زَكَاتَنَا، وَيَصُومُونَ صِيَامَنَا، وَيَحُجُّونَ حَجَّنَا، وَيَغْزُونَ غَزْوَنَا، لَا نَرَاهُمْ، فَيَقُولُ: اذْهَبُوا إِلَى النَّارِ، فَمَنْ وَجَدْتُمْ فِيهَا مِنْهُمْ فَأَخْرِجُوهُ، قَالَ: فَيَجِدُونَهُمْ قَدْ أَخَذَتْهُمْ النَّارُ عَلَى قَدْرِ أَعْمَالِهِمْ، فَمِنْهُمْ مَنْ أَخَذَتْهُ إِلَى قَدَمَيْهِ، وَمِنْهُمْ مَنْ أَخَذَتْهُ إِلَى نِصْفِ سَاقَيْهِ، وَمِنْهُمْ مَنْ أَخَذَتْهُ إِلَى رُكْبَتَيْهِ، وَمِنْهُمْ مَنْ أَزِرَتْهُ، وَمِنْهُمْ مَنْ أَخَذَتْهُ إِلَى ثَدْيَيْهِ، وَمِنْهُمْ مَنْ أَخَذَتْهُ إِلَى عُنُقِهِ، وَلَمْ تَغْشَ الْوُجُوهَ مِنْهَا، فَيُطْرَحُونَ فِي مَاءِ الْحَيَاةِ \"، قِيلَ: يَا رَسُولَ اللَّهِ، وَمَا مَاءُ الْحَيَاةِ ؟، قَالَ: غُسْلُ أَهْلِ الْجَنَّةِ، فَيَنْبُتُونَ نَبَاتَ الزَّرْعَةِ، وَقَالَ مَرَّةً فِيهِ: كَمَا تَنْبُتُ الزَّرْعَةُ فِي غُثَاءِ السَّيْلِ، ثُمَّ يَشْفَعُ الْأَنْبِيَاءُ فِي كُلِّ مَنْ كَانَ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ مُخْلِصًا، فَيُخْرِجُونَهُمْ مِنْهَا، قَالَ: ثُمَّ يَتَحَنَّنُ اللَّهُ بِرَحْمَتِهِ عَلَى مَنْ فِيهَا، فَمَا يَتْرُكُ فِيهَا عَبْدًا فِي قَلْبِهِ مِثْقَالُ حَبَّةٍ مِنْ إِيمَانٍ إِلَّا أَخْرَجَهُ مِنْهَا."],"takhrij":"حسن: رواه أحمد (11081) واللّفظ له، وابن خزيمة في التوحيد (648)، وابن ماجه (4280) مختصراً، والحاكم (8737) كلّهم من طريق محمد بن إسحاق، قال: حدّثني عبيد الله بن المغيرة بن مُعيقيب، عن سليمان بن عمرو بن عبد العُتْواريّ، أحد بني ليث، وكان يتيماً في حجر أبي سعيد، قال: سمعت أبا سعيد يقول فذكره.","grade":"حسن","chapter_ar":"باب الصراط جسر جهنم","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Aḥmad (11081), whose wording is given here, Ibn Khuzaymah in al-Tawḥīd (648), Ibn Mājah (4280) in abridged form, and al-Ḥākim (8738).","chapter_en":"The Ṣirāṭ Is the Bridge Over Hell","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان باليوم الآخر","group_en":"Collection of Chapters Concerning Faith in the Last Day","part_no":2,"group_no":11,"chapter_no":8,"content":{"translation":{"en":["Abū Saʿīd, may Allah be pleased with him, said: I heard the Messenger of Allah ﷺ say: “The Ṣirāṭ will be placed across Hell. Upon it are thorns like the thorns of al-Saʿdān. Then the people will cross. Some will be saved completely; some will be wounded by it and then saved; while others will be seized by it and thrown upside down into the Fire. When Allah, Mighty and Majestic, has finished judging between the servants, the believers will notice that certain men who had been with them in this world are missing—men who prayed as they prayed, gave Zakāh as they gave Zakāh, fasted as they fasted, performed Ḥajj as they performed Ḥajj, and fought as they fought. They will say: ‘Our Lord, servants from among Your servants were with us in the world. They prayed our prayer, gave our Zakāh, fasted our fasting, performed our Ḥajj, and fought our fighting, but we do not see them!’ He will say: ‘Go to the Fire, and whoever you find among them, bring him out.’ They will find them affected by the Fire according to their deeds. Among them will be those whom it reached only to their feet; among them those whom it reached halfway up their shins; among them those whom it reached to their knees; among them those whom it reached to the waist; among them those whom it reached to the chest; and among them those whom it reached to the neck. But it will not cover their faces. They will bring them out and cast them into the Water of Life.” It was asked: “O Messenger of Allah, what is the Water of Life?” He replied: “The washing-water of the people of Paradise. They will grow like crops.” On another occasion he said: “Just as vegetation grows in the debris carried by a flood.” “Then the prophets will intercede for everyone who sincerely testified that there is no deity worthy of worship except Allah, and they will bring them out of it.” He continued: “Then Allah will show compassion, through His mercy, toward those remaining in it. He will not leave therein any servant who has in his heart the weight of a grain of faith except that He will bring him out.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (11081)، واللفظ له، وابن خزيمة في التوحيد (648)، وابن ماجه (4280) مختصرا، والحاكم (8738)."},{"num":971,"demo":false,"sanad":"","matn":["عَنْ ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: كُنْتُ قَائِمًا عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَجَاءَ حِبْرٌ مِنْ أَحْبَارِ الْيَهُودِ، فَقَالَ: السَّلَامُ عَلَيْكَ يَا مُحَمَّدُ، فَدَفَعْتُهُ دَفْعَةً كَادَ يُصْرَعُ مِنْهَا، فَقَالَ: لِمَ تَدْفَعُنِي؟ فَقُلْتُ: أَلَا تَقُولُ يَا رَسُولَ اللَّهِ؟ فَقَالَ الْيَهُودِيُّ: إِنَّمَا نَدْعُوهُ بِاسْمِهِ الَّذِي سَمَّاهُ بِهِ أَهْلُهُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ اسْمِي مُحَمَّدٌ الَّذِي سَمَّانِي بِهِ أَهْلِي، فَقَالَ الْيَهُودِيُّ: جِئْتُ أَسْأَلُكَ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَيَنْفَعُكَ شَيْءٌ إِنْ حَدَّثْتُكَ؟ قَالَ: أَسْمَعُ بِأُذُنَيَّ، فَنَكَتَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِعُودٍ مَعَهُ، فَقَالَ: سَلْ، فَقَالَ الْيَهُودِيُّ: أَيْنَ يَكُونُ النَّاسُ يَوْمَ تُبَدَّلُ الأَرْضُ غَيْرَ الأَرْضِ وَالسَّمَوَاتُ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هُمْ فِي الظُّلْمَةِ دُونَ الْجِسْرِ، قَالَ: فَمَنْ أَوَّلُ النَّاسِ إِجَازَةً؟ قَالَ: فُقَرَاءُ الْمُهَاجِرِينَ، قَالَ الْيَهُودِيُّ: فَمَا تُحْفَتُهُمْ حِينَ يَدْخُلُونَ الْجَنَّةَ؟ قَالَ: زِيَادَةُ كَبِدِ النُّونِ، قَالَ: فَمَا غِذَاؤُهُمْ عَلَى إِثْرِهَا؟ قَالَ: يُنْحَرُ لَهُمْ ثَوْرُ الْجَنَّةِ الَّذِي كَانَ يَأْكُلُ مِنْ أَطْرَافِهَا، قَالَ: فَمَا شَرَابُهُمْ عَلَيْهِ؟ قَالَ: مِنْ عَيْنٍ فِيهَا، تُسَمَّى سَلْسَبِيلًا، قَالَ: صَدَقْتَ..... (فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ)."],"takhrij":"صحيح: رواه مسلم في الحيض (315) من حديث أبي سلاّم قال: حدّثني أبو أسماء الرّحبي، أنّ ثوبان مولى رسول الله صلى الله عليه وسلم قال (فذكر الحديث) في سياق أطول.","grade":"صحيح","chapter_ar":"باب أول من يتجاوز الصراط هم فقراء المهاجرين","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (315).","chapter_en":"The First to Cross the Ṣirāṭ Will Be the Poor Among the Muhājirūn","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان باليوم الآخر","group_en":"Collection of Chapters Concerning Faith in the Last Day","part_no":2,"group_no":11,"chapter_no":9,"content":{"translation":{"en":["Thawbān, the freed servant of the Messenger of Allah ﷺ, said: I was standing with the Messenger of Allah ﷺ when a learned Jewish scholar came and said: “Peace be upon you, O Muḥammad!” I pushed him so forcefully that he nearly fell. He asked: “Why do you push me?” I replied: “Why do you not say: ‘O Messenger of Allah’?” The Jewish man said: “We only call him by the name his family gave him.” The Messenger of Allah ﷺ said: “Indeed, my name is Muḥammad, the name my family gave me.” The Jewish man said: “I came to ask you.” The Messenger of Allah ﷺ asked him: “Will it benefit you if I answer you?” He replied: “I will listen with my ear.” The Messenger of Allah ﷺ tapped the ground with a stick he had and said: “Ask.” The Jewish man asked: “Where will the people be on the Day when the earth is changed to another earth and the heavens as well?” The Messenger of Allah ﷺ replied: “They will be in darkness beneath the bridge.” He asked: “Who will be the first people to cross?” He replied: “The poor among the Muhājirūn.” The Jewish man asked: “What will be their welcoming gift when they enter Paradise?” He replied: “An extra portion from the liver of the nūn.” He asked: “What will their food be after that?” He replied: “A bull of Paradise which used to graze at its edges will be slaughtered for them.” He asked: “What will their drink be with it?” He replied: “From a spring in Paradise called Salsabīl.” He said: “You have spoken the truth.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (315)."},{"num":972,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ اللَّهَ يَبْعَثُ رِيحًا مِنْ الْيَمَنِ، أَلْيَنَ مِنَ الْحَرِيرِ، فَلَا تَدَعُ أَحَدًا فِي قَلْبِهِ، قَالَ أَبُو عَلْقَمَةَ: مِثْقَالُ حَبَّةٍ، وقَالَ عَبْدُ الْعَزِيزِ: مِثْقَالُ ذَرَّةٍ مِنَ إِيمَانٍ إِلَّا قَبَضَتْهُ."],"takhrij":"صحيح: رواه مسلم في الإيمان (117) من طرق عن صفوان بن سُليم، عن عبدالله بن سلمان، عن أبيه، عن أبي هريرة، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب لا تقوم الساعة إلا على شرار الناس وذهاب الإيمان قبل قيام الساعة","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (117).","chapter_en":"The Hour Will Be Established Only Upon the Worst of People, and Faith Will Disappear Before the Hour","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان باليوم الآخر","group_en":"Collection of Chapters Concerning Faith in the Last Day","part_no":2,"group_no":11,"chapter_no":10,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Indeed, Allah will send a wind from Yemen softer than silk. It will not leave anyone who has in his heart the weight of a grain—and in another narration, the weight of an atom—of faith except that it will take his soul.”"]},"buhuth":{"en":["Al-Qurṭubī said:","“This wind will only be sent after the descent of Jesus son of Mary and his killing of the Dajjāl, as stated in the ḥadīth of ʿAbdullāh ibn ʿAmr.","Although that narration states that it comes from the direction of al-Shām, it is possible that its origin will be from Yemen, after which it will pass through al-Shām and blow from there upon those nearby.","The removal of faith mentioned in this ḥadīth occurs through the taking of the souls of the people who possess faith, as stated in the ḥadīth of ʿAbdullāh ibn ʿAmr.”","That narration follows."]}},"tuhfa":{},"full":1,"dr":1,"rep":[16013],"tks":"صحيح: رواه مسلم (117)."},{"num":973,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو قَالَ (فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ): قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ثُمَّ يُرْسِلُ اللَّهُ رِيحًا بَارِدَةً مِنْ قِبَلِ الشَّأْمِ، فَلَا يَبْقَى عَلَى وَجْهِ الْأَرْضِ أَحَدٌ فِي قَلْبِهِ مِثْقَالُ ذَرَّةٍ مِنْ خَيْرٍ أَوْ إِيمَانٍ، إِلَّا قَبَضَتْهُ حَتَّى لَوْ أَنَّ أَحَدَكُمْ دَخَلَ فِي كَبِدِ جَبَلٍ لَدَخَلَتْهُ عَلَيْهِ حَتَّى تَقْبِضَهُ، قَالَ: سَمِعْتُهَا مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: فَيَبْقَى شِرَارُ النَّاسِ فِي خِفَّةِ الطَّيْرِ وَأَحْلَامِ السِّبَاعِ، لَا يَعْرِفُونَ مَعْرُوفًا، وَلَا يُنْكِرُونَ مُنْكَرًا، فَيَتَمَثَّلُ لَهُمُ الشَّيْطَانُ، فَيَقُولُ: أَلَا تَسْتَجِيبُونَ، فَيَقُولُونَ: فَمَا تَأْمُرُنَا فَيَأْمُرُهُمْ بِعِبَادَةِ الْأَوْثَانِ."],"takhrij":"صحيح: رواه مسلم في الفتن وأشراط الساعة (2940) عن عبدالله بن معاذ العنبري، حدثنا أبي، حدثنا شعبة، عن النعمان بن سالم، قال: سمعت يعقوب بن عاصم بن عروة بن مسعود الثقفي، يقول سمعت عبدالله بن عمرو في حديث طويل سبق ذكر بعضه في باب النفخ في الصور.","grade":"صحيح","chapter_ar":"باب لا تقوم الساعة إلا على شرار الناس وذهاب الإيمان قبل قيام الساعة","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2940).","chapter_en":"The Hour Will Be Established Only Upon the Worst of People, and Faith Will Disappear Before the Hour","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان باليوم الآخر","group_en":"Collection of Chapters Concerning Faith in the Last Day","part_no":2,"group_no":11,"chapter_no":10,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr may Allah be pleased with them reported that the Messenger of Allah ﷺ said: “Then Allah will send a cold wind from the direction of al-Shām. No one will remain upon the face of the earth who has in his heart the weight of an atom of goodness or faith except that it will take his soul. Even if one of you were to enter the very heart of a mountain, it would enter upon him there until it took his soul.” He said: And I heard the Messenger of Allah ﷺ say: “Then the worst of people will remain. They will be light like birds and possess the minds of beasts. They will neither recognize what is good nor condemn what is evil. Satan will appear before them and say: ‘Will you not respond?’ They will ask: ‘What do you command us to do?’ He will command them to worship idols.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2940)."},{"num":974,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لا تَقُومُ السَّاعَةُ حَتَّى لَا يُقَالَ فِي الأَرْضِ: اللَّهُ اللَّهُ.","وَفِي رِوَايَةِ: لَا تَقُومُ السَّاعَةُ عَلَى أَحَدٍ، يَقُولُ: اللَّهُ اللَّهُ."],"takhrij":"صحيح: رواه مسلم في الإيمان (148) من طرق عن ثابت، عن أنس، فذكره.","grade":"صحيح","chapter_ar":"باب لا تقوم الساعة إلا على شرار الناس وذهاب الإيمان قبل قيام الساعة","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (148).","chapter_en":"The Hour Will Be Established Only Upon the Worst of People, and Faith Will Disappear Before the Hour","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان باليوم الآخر","group_en":"Collection of Chapters Concerning Faith in the Last Day","part_no":2,"group_no":11,"chapter_no":10,"content":{"translation":{"en":["Anas may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “The Hour will not be established until it is no longer said upon the earth: ‘Allah, Allah.’” In another narration:","“The Hour will not be established while anyone remains who says: ‘Allah, Allah.’”"]},"buhuth":{"en":["This does not contradict the Prophet’s ﷺ statement:","“A group from my Ummah will continue to remain manifest upon the truth until the Day of Resurrection,”","as narrated by Muslim (156) from Jābir ibn ʿAbdullāh.","This is because that group will fight the Dajjāl and gather with Jesus, peace be upon him. They will continue upon that until Allah takes their souls by means of the Yemeni wind, which will not leave any believer alive.","After them, only the worst of creation will remain. Among them there will be no one who says:","“Allah, Allah.”","They will engage in intercourse openly like donkeys, and upon them the Hour will be established.","Al-Qurṭubī explained this in al-Mufhim (1/365)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (148)."},{"num":975,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ قَبْلَ أَنْ يَمُوتَ بِشَهْرٍ: تَسْأَلُونِي عَنِ السَّاعَةِ؟ وَإِنَّمَا عِلْمُهَا عِنْدَ اللَّهِ، وَأُقْسِمُ بِاللَّهِ مَا عَلَى الْأَرْضِ مِنْ نَفْسٍ مَنْفُوسَةٍ تَأْتِي عَلَيْهَا مِائَةُ سَنَةٍ."],"takhrij":"صحيح: رواه مسلم في الفضائل (2538) من طريق حجاج بن محمد، قال: قال ابن جريج: أخبرني أبو الزبير، أنه سمع جابر بن عبدالله، يقول (فذكره).","grade":"صحيح","chapter_ar":"باب لا يعلم أحد متى تقوم الساعة إلا الله سبحانه وحده","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2538).","chapter_en":"No One Knows When the Hour Will Be Established Except Allah Alone, Glorified is He","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان باليوم الآخر","group_en":"Collection of Chapters Concerning Faith in the Last Day","part_no":2,"group_no":11,"chapter_no":11,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh, may Allah be pleased with them, said: I heard the Prophet ﷺ say one month before his death: “You ask me about the Hour? Its knowledge is only with Allah. By Allah, there is no living soul upon the earth today upon which one hundred years will pass.”"]},"buhuth":{"en":["Muslim (2538) also narrated the wording:","“No living soul will reach one hundred years.”","Sālim said:","“We discussed this in his presence. It refers to every soul that was alive on that day.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2538)."},{"num":976,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ قَالَ: لَمَّا رَجَعَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ تَبُوكَ، سَأَلُوهُ عَنِ السَّاعَةِ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا تَأْتِي مِائَةُ سَنَةٍ وَعَلَى الْأَرْضِ نَفْسٌ مَنْفُوسَةٌ الْيَوْمَ."],"takhrij":"صحيح: رواه مسلم في الفضائل (2539) من طريقين عن داود، عن أبي نضرة، عن أبي سعيد، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب لا يعلم أحد متى تقوم الساعة إلا الله سبحانه وحده","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2539).","chapter_en":"No One Knows When the Hour Will Be Established Except Allah Alone, Glorified is He","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان باليوم الآخر","group_en":"Collection of Chapters Concerning Faith in the Last Day","part_no":2,"group_no":11,"chapter_no":11,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī, may Allah be pleased with him, said: When the Prophet ﷺ returned from Tabūk, they asked him about the Hour. The Messenger of Allah ﷺ said: “One hundred years will not pass while there remains upon the earth any living soul that is alive today.”"]}},"tuhfa":{},"full":1,"rep":[8292,15890],"tks":"صحيح: رواه مسلم (2539)."},{"num":977,"demo":false,"sanad":"","matn":["عَنْ نُعَيْمِ بْنِ دِجَاجَةَ، أَنَّهُ قَالَ: دَخَلَ أَبُو مَسْعُودٍ عُقْبَةُ بْنُ عَمْرٍو الْأَنْصَارِيُّ عَلَى عَلِيِّ بْنِ أَبِي طَالِبٍ، فَقَالَ لَهُ عَلِيٌّ: أَنْتَ الَّذِي تَقُولُ: لَا يَأْتِي عَلَى النَّاسِ مِائَةُ سَنَةٍ وَعَلَى الْأَرْضِ عَيْنٌ تَطْرِفُ؟ إِنَّمَا قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا يَأْتِي عَلَى النَّاسِ مِائَةُ سَنَةٍ وَعَلَى الْأَرْضِ عَيْنٌ تَطْرِفُ مِمَّنْ هُوَ حَيٌّ الْيَوْمَ، وَاللَّهِ إِنَّ رَخَاءَ هَذِهِ الْأُمَّةِ بَعْدَ مِائَةِ عَامٍ."],"takhrij":"حسن: رواه الإمام أحمد (714) من طريق نُعيم بن دجاجة أنه قال: فذكره.","grade":"حسن","chapter_ar":"باب لا يعلم أحد متى تقوم الساعة إلا الله سبحانه وحده","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (714).","chapter_en":"No One Knows When the Hour Will Be Established Except Allah Alone, Glorified is He","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان باليوم الآخر","group_en":"Collection of Chapters Concerning Faith in the Last Day","part_no":2,"group_no":11,"chapter_no":11,"content":{"translation":{"en":["Abū Masʿūd ʿUqbah ibn ʿAmr al-Anṣārī may Allah be pleased with him entered upon ʿAlī ibn Abī Ṭālib may Allah be pleased with him. ʿAlī said to him: “Are you the one who says: ‘One hundred years will not pass while there remains upon the earth an eye that blinks’?” Rather, the Messenger of Allah ﷺ said: “One hundred years will not pass over the people while there remains upon the earth an eye that blinks from among those who are alive today. By Allah, the ease and prosperity of this Ummah will come after one hundred years.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (714)."},{"num":978,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا أَنْزَلَ اللَّهُ بِقَوْمٍ عَذَابًا أَصَابَ الْعَذَابُ مَنْ كَانَ فِيهِمْ، ثُمَّ بُعِثُوا عَلَى أَعْمَالِهِمْ."],"takhrij":"متفق عليه: رواه البخاريّ في الفتن (7108)، ومسلم في صفة الجنة والنار (2879) كلاهما من حديث يونس، عن الزهري، أخبرني حمزة بن عبدالله بن عمر، أنه سمع ابن عمر، فذكره، ولفظهما سواء.","grade":"متفق عليه","chapter_ar":"باب أن العبد يُبعث على ما مات عليه","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7108) and Muslim (2879).","chapter_en":"The Servant Will Be Resurrected Upon the State in Which He Died","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان باليوم الآخر","group_en":"Collection of Chapters Concerning Faith in the Last Day","part_no":2,"group_no":11,"chapter_no":12,"content":{"translation":{"en":["Ibn ʿUmar may Allah be pleased with them reported that the Messenger of Allah ﷺ said: “When Allah sends a punishment upon a people, the punishment afflicts everyone among them, and then they will be resurrected according to their deeds.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (7108)، ومسلم (2879)."},{"num":979,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ الأَنْصَارِيَّ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَبْلَ وَفَاتِهِ بِثَلَاثٍ، يَقُولُ: لَا يَمُوتَنَّ أَحَدُكُمْ إِلَّا وَهُوَ يُحْسِنُ بِاللَّهِ الظَّنَّ."],"takhrij":"صحيح: رواه مسلم في كتاب صفة الجنة والنار (2877) عن يحيى بن يحيى، أخبرنا يحيى بن زكريا، عن الأعمش، عن أبي سفيان، عن جابر، فذكره.","grade":"صحيح","chapter_ar":"باب أن العبد يُبعث على ما مات عليه","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2877).","chapter_en":"The Servant Will Be Resurrected Upon the State in Which He Died","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان باليوم الآخر","group_en":"Collection of Chapters Concerning Faith in the Last Day","part_no":2,"group_no":11,"chapter_no":12,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh al-Anṣārī, may Allah be pleased with them, said: I heard the Messenger of Allah ﷺ, three days before his death, say: “Let none of you die except while having a good expectation of Allah.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2877)."},{"num":980,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: يُبْعَثُ كُلُّ عَبْدٍ عَلَى مَا مَاتَ عَلَيْهِ."],"takhrij":"صحيح: رواه مسلم في صفة الجنة والنار (2878) من طرق عن جرير، عن الأعمش، عن أبي سفيان، عن جابر، فذكره.","grade":"صحيح","chapter_ar":"باب أن العبد يُبعث على ما مات عليه","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2878).","chapter_en":"The Servant Will Be Resurrected Upon the State in Which He Died","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان باليوم الآخر","group_en":"Collection of Chapters Concerning Faith in the Last Day","part_no":2,"group_no":11,"chapter_no":12,"content":{"translation":{"en":["Jābir, may Allah be pleased with him, said: I heard the Messenger of Allah ﷺ say: “Every servant will be resurrected upon the state in which he died.”"]}},"tuhfa":{},"full":1,"rep":[16144],"tks":"صحيح: رواه مسلم (2878)."},{"num":981,"demo":false,"sanad":"","matn":["عَنْ فَضَالَةَ بْنِ عُبَيْدٍ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ مَاتَ عَلَى مَرْتَبَةٍ مِنْ هَذِهِ الْمَرَاتِبِ، بُعِثَ عَلَيْهَا، قَالَ حَيْوَةُ: يَقُولُ: رِبَاطٌ، حَجٌّ أَوْ نَحْوُ ذَلِكَ."],"takhrij":"صحيح: رواه الإمام أحمد (23941) عن إبراهيم بن إسحاق، حدّثنا ابن المبارك (والحديث في كتاب الجهاد له: 173) عن حيوة بن شريح، قال: أخبرني أبو هانئ الخولانيّ، أنّ عمرو بن مالك الجَنْبيّ (بفتح الجيم وسكون النون) أخبره أنه سمع فضالة بن عبيد يحدِّث عن رسول الله صلى الله عليه وسلم، فذكره.","grade":"صحيح","chapter_ar":"باب أن العبد يُبعث على ما مات عليه","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Imām Aḥmad (23941, 23945), Ibn al-Mubārak in al-Jihād (173), and al-Ṭabarānī in al-Muʿjam al-Kabīr (18/305).","chapter_en":"The Servant Will Be Resurrected Upon the State in Which He Died","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان باليوم الآخر","group_en":"Collection of Chapters Concerning Faith in the Last Day","part_no":2,"group_no":11,"chapter_no":12,"content":{"translation":{"en":["Faḍālah ibn ʿUbayd may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Whoever dies while engaged in one of these stations of obedience will be resurrected upon it.” Ḥaywah said: “He meant such things as guarding the Muslim frontier, performing Ḥajj, or similar acts.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (23941، 23945)، وابن المبارك في الجهاد (173)، والطبراني في الكبير (18/305)."},{"num":982,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: يُبْعَثُ كُلُّ عَبْدٍ عَلَى مَا مَاتَ عَلَيْهِ، الْمُؤْمِنُ عَلَى إِيمَانِهِ، وَالْمُنَافِقُ عَلَى نِفَاقِهِ."],"takhrij":"حسن: رواه ابن حبان في صحيحه (7313) عن الحسن بن سفيان، قال: حدّثنا الحسن بن الصّبّاح البزّار، حدّثنا إسماعيل بن عبدالكريم، قال: أخبرني إبراهيم بن عقيل بن معقل، عن أبيه، عن وهب بن منبّه، عن جابر، فذكره.","grade":"حسن","chapter_ar":"باب أن العبد يُبعث على ما مات عليه","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Ibn Ḥibbān in his Ṣaḥīḥ (7313).","chapter_en":"The Servant Will Be Resurrected Upon the State in Which He Died","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان باليوم الآخر","group_en":"Collection of Chapters Concerning Faith in the Last Day","part_no":2,"group_no":11,"chapter_no":12,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh, may Allah be pleased with them, said: I heard the Prophet ﷺ say: “Every servant will be resurrected upon the state in which he died: the believer upon his faith, and the hypocrite upon his hypocrisy.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن حبان في صحيحه (7313)."},{"num":983,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: سَلُونِي؟ فَهَابُوهُ أَنْ يَسْأَلُوهُ، فَجَاءَ رَجُلٌ فَجَلَسَ عِنْدَ رُكْبَتَيْهِ، فَقَالَ: يَا رَسُولَ اللَّهِ، مَا الإِسْلَامُ؟ قَالَ: لَا تُشْرِكُ بِاللَّهِ شَيْئًا، وَتُقِيمُ الصَّلَاةَ، وَتُؤْتِي الزَّكَاةَ، وَتَصُومُ رَمَضَانَ، قَالَ: صَدَقْتَ، قَالَ: يَا رَسُولَ اللَّهِ، مَا الإِيمَانُ؟ قَالَ: أَنْ تُؤْمِنَ بِاللَّهِ، وَمَلَائِكَتِهِ، وَكِتَابِهِ، وَلِقَائِهِ، وَرُسُلِهِ، وَتُؤْمِنَ بِالْبَعْثِ، وَتُؤْمِنَ بِالْقَدَرِ كُلِّهِ، قَالَ: صَدَقْتَ. فَذَكَرَ الْحَدِيثَ بِطُولِهِ."],"takhrij":"متفق عليه: رواه مسلم في الإيمان (10) عن زهير بن حرب، حدّثنا جرير، عن عمارة (وهو ابن القعقاع)، عن أبي زرعة، عن أبي هريرة، فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الإيمان بالقدر","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim in al-Īmān (10).","chapter_en":"What Has Been Reported Concerning Belief in Divine Decree","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالقضاء والقدر","group_en":"Collection of Chapters Concerning Faith in Divine Decree and Predestination","part_no":2,"group_no":12,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported: The Messenger of Allah ﷺ said: “Ask me.” They were hesitant to question him. Then a man came and sat near his knees and asked: “O Messenger of Allah, what is Islam?” He replied: “That you associate nothing with Allah, establish the prayer, give Zakāh, and fast Ramaḍān.” He said: “You have spoken the truth.” Then he asked: “O Messenger of Allah, what is faith?” He replied: “That you believe in Allah, His angels, His Book, meeting Him, His messengers, the Resurrection, and that you believe in Divine Decree in its entirety.” He said: “You have spoken the truth.” Then the lengthy ḥadīth continues."]},"intro_majmu":{"ar":["الإيمان بالقدر يتضمن الإيمان بأمور أربعة دلت عليها النصوص من الكتاب الحكيم والسنة الصحيحة، وقررها أهل العلم، وهي:","الأمر الأول: الإيمان بأن الله سبحانه وتعالى قد علم ما كان وما يكون، وعلم أحوال عباده، وعلم أرزاقهم وآجالهم وأعمالهم وغير ذلك من شؤونهم قبل خلقهم، كما يدل على ذلك قوله تعالى:","﴿لِتَعْلَمُوا أَنَّ اللهَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ وَأَنَّ اللهَ قَدْ أَحَاطَ بِكُلِّ شَيْءٍ عِلْمًا﴾","[الطلاق: ١٢]","الأمر الثاني: الإيمان بأن الله تعالى كتب كل شيء مما هو كائن إلى قيام الساعة في اللوح المحفوظ، كما قال سبحانه وتعالى:","﴿وَكُلَّ شَيْءٍ أَحْصَيْنَاهُ فِي إِمَامٍ مُبِينٍ﴾","[يس: ١٢]","الأمر الثالث: الإيمان بأن مشيئة الله نافذة؛ فما شاء كان، وما لم يشأ لم يكن، كما قال سبحانه وتعالى:","﴿إِنَّمَا أَمْرُهُ إِذَا أَرَادَ شَيْئًا أَنْ يَقُولَ لَهُ كُنْ فَيَكُونُ﴾","[يس: ٨٢]","وقال تعالى:","﴿وَمَا تَشَاءُونَ إِلَّا أَنْ يَشَاءَ اللهُ رَبُّ الْعَالَمِينَ﴾","[التكوير: ٢٩]","الأمر الرابع: الإيمان بأن الله خلق كل عامل وعمله، وكل متحرك وحركته، وكل ساكن وسكونه، كما قال سبحانه وتعالى:","﴿وَاللهُ خَلَقَكُمْ وَمَا تَعْمَلُونَ﴾","[الصافات: ٩٦]","فالإيمان بالقدر يشمل الإيمان بهذه الأمور الأربعة عند أهل السنة والجماعة، وأدلتها من نصوص الكتاب والسنة مذكورة في الأبواب الآتية."],"en":["Belief in Divine Decree includes belief in four matters established by the texts of the Wise Qurʾān and the authentic Sunnah and affirmed by the scholars:","First: Belief that Allah, Glorified and Exalted, knew everything that has occurred and everything that will occur. He knew the conditions of His servants, their provisions, their lifespans, their deeds, and all their other affairs before creating them, as indicated by His statement:","“So that you may know that Allah is Most Capable of all things and that Allah has encompassed all things in knowledge.”","[Sūrat al-Ṭalāq 65:12]","Second: Belief that Allah Most High wrote everything that will occur until the establishment of the Hour in the Preserved Tablet, as He, Glorified is He, said:","“And We have enumerated everything in a clear Record.”","[Sūrat Yā Sīn 36:12]","Third: Belief that Allah’s will is always carried out: whatever He wills occurs, and whatever He does not will does not occur, as He, Glorified and Exalted, said:","“His command, when He wills a thing, is only that He says to it, ‘Be,’ and it is.”","[Sūrat Yā Sīn 36:82]","And Allah Most High said:","“And you do not will unless Allah wills—the Lord of all worlds.”","[Sūrat al-Takwīr 81:29]","Fourth: Belief that Allah created every doer and his deed, every moving being and its movement, and every still being and its stillness, as He, Glorified is He, said:","“Allah created you and what you do.”","[Sūrat al-Ṣāffāt 37:96]","Thus, according to Ahl al-Sunnah wa al-Jamāʿah, belief in Divine Decree encompasses belief in these four matters. Their proofs from the Qurʾān and Sunnah are presented in the chapters that follow."]},"intro":{"ar":["قال الله تعالى:","﴿مَا أَصَابَ مِنْ مُصِيبَةٍ فِي الْأَرْضِ وَلَا فِي أَنْفُسِكُمْ إِلَّا فِي كِتَابٍ مِنْ قَبْلِ أَنْ نَبْرَأَهَا إِنَّ ذَٰلِكَ عَلَى اللهِ يَسِيرٌ﴾","[الحديد: ٢٢]","وقال تعالى:","﴿سُنَّةَ اللهِ فِي الَّذِينَ خَلَوْا مِنْ قَبْلُ وَكَانَ أَمْرُ اللهِ قَدَرًا مَقْدُورًا﴾","[الأحزاب: ٣٨]","قال مالك بن أنس رحمه الله:","«ما أضل من كذب بالقدر! لو لم يكن عليهم فيه حجة إلا قوله تعالى:","﴿هُوَ الَّذِي خَلَقَكُمْ فَمِنْكُمْ كَافِرٌ وَمِنْكُمْ مُؤْمِنٌ﴾","[التغابن: ٢]","لكفى بها حجة»."],"en":["Allah Most High said:","“No calamity befalls the earth or yourselves except that it is written in a Record before We bring it into existence. Indeed, that is easy for Allah.”","[Sūrat al-Ḥadīd 57:22]","And Allah Most High said:","“This is the established way of Allah concerning those who passed away before, and the command of Allah is a decree already determined.”","[Sūrat al-Aḥzāb 33:38]","Mālik ibn Anas, may Allah have mercy on him, said:","“No one is more astray than one who denies Divine Decree. Even if there were no proof against them concerning it other than the statement of Allah Most High:","‘He is the One who created you; yet some of you are disbelievers and some of you are believers,’","[Sūrat al-Taghābun 64:2]","that alone would be sufficient as proof.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مسلم (10)."},{"num":984,"demo":false,"sanad":"","matn":["عَنِ ابْنِ الدَّيْلَمِيِّ قَالَ: أَتَيْتُ أُبَيَّ بْنَ كَعْبٍ فَقُلْتُ لَهُ: وَقَعَ فِي نَفْسِي شَيْءٌ مِنَ الْقَدَرِ فَحَدِّثْنِي بِشَيْءٍ لَعَلَّ اللَّهَ أَنْ يُذْهِبَهُ مِنْ قَلْبِي، قَالَ: لَوْ أَنَّ اللَّهَ عَذَّبَ أَهْلَ سَمَاوَاتِهِ وَأَهْلَ أَرْضِهِ عَذَّبَهُمْ وَهُوَ غَيْرُ ظَالِمٍ لَهُمْ، وَلَوْ رَحِمَهُمْ كَانَتْ رَحْمَتُهُ خَيْرًا لَهُمْ مِنْ أَعْمَالِهِمْ وَلَوْ أَنْفَقْتَ مِثْلَ أُحُدٍ ذَهَبًا فِي سَبِيلِ اللَّهِ مَا قَبِلَهُ اللَّهُ مِنْكَ حَتَّى تُؤْمِنَ بِالْقَدَرِ، وَتَعْلَمَ أَنَّ مَا أَصَابَكَ لَمْ يَكُنْ لِيُخْطِئَكَ، وَأَنَّ مَا أَخْطَأَكَ لَمْ يَكُنْ لِيُصِيبَكَ، وَلَوْ مُتَّ عَلَى غَيْرِ هَذَا لَدَخَلْتَ النَّارَ، قَالَ: ثُمَّ أَتَيْتُ عَبْدَ اللَّهِ بْنَ مَسْعُودٍ، فَقَالَ مِثْلَ ذَلِكَ، قَالَ: ثُمَّ أَتَيْتُ حُذَيْفَةَ بْنَ الْيَمَانِ، فَقَالَ مِثْلَ ذَلِكَ، قَال: ثُمَّ أَتَيْتُ زَيْدَ بْنَ ثَابِتٍ فَحَدَّثَنِي عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِثْلَ ذَلِكَ."],"takhrij":"حسن: رواه أبو داود (4699)، وابن ماجه (77) كلاهما من طريق أبي سنان، عن وهب بن خالد الحمصيّ، عن ابن الدّيلميّ، فذكر مثله.","grade":"حسن","chapter_ar":"باب ما جاء في الإيمان بالقدر","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Abū Dāwūd (4699) and Ibn Mājah (77).","chapter_en":"What Has Been Reported Concerning Belief in Divine Decree","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالقضاء والقدر","group_en":"Collection of Chapters Concerning Faith in Divine Decree and Predestination","part_no":2,"group_no":12,"chapter_no":1,"content":{"translation":{"en":["Ibn al-Daylamī said: I came to Ubayy ibn Kaʿb may Allah be pleased with him and said: “Something concerning Divine Decree has entered my heart. Tell me something by which Allah may remove it from my heart.” He replied: “If Allah were to punish the inhabitants of His heavens and the inhabitants of His earth, He would punish them without being unjust to them. And if He were to show them mercy, His mercy would be better for them than their deeds. If you were to spend the equivalent of Mount Uḥud in gold in the path of Allah, Allah would not accept it from you until you believed in Divine Decree and knew that whatever struck you could never have missed you, and whatever missed you could never have struck you. If you died upon anything other than this, you would enter the Fire.” He said: Then I went to ʿAbdullāh ibn Masʿūd may Allah be pleased with him, and he said the same. Then I went to Ḥudhayfah ibn al-Yamān may Allah be pleased with him, and he said the same. Then I went to Zayd ibn Thābit may Allah be pleased with him, and he narrated the same to me from the Prophet ﷺ."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4699)، وابن ماجه (77)."},{"num":985,"demo":false,"sanad":"","matn":["عَنْ أَبِي الدَّرْدَاءِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا يَدْخُلُ الْجَنَّةَ عَاقٌّ، وَلَا مُدْمِنُ خَمْرٍ، وَلَا مُكَذِّبٌ بِقَدَرٍ."],"takhrij":"حسن: رواه الإمام أحمد (27484)، والبزّار- كشف الأستار (2182)، كلاهما من طريق سليمان بن عتبة أبي الرّبيع الدِّمشقيّ، قال: سمعتُ يونس بن ميسرة، عن أبي إدريس عائذ الله، عن أبي الدّرداء، فذكر مثله.","grade":"حسن","chapter_ar":"باب ما جاء في الإيمان بالقدر","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Aḥmad (27484), al-Bazzār in Kashf al-Astār (2182).","chapter_en":"What Has Been Reported Concerning Belief in Divine Decree","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالقضاء والقدر","group_en":"Collection of Chapters Concerning Faith in Divine Decree and Predestination","part_no":2,"group_no":12,"chapter_no":1,"content":{"translation":{"en":["Abū al-Dardāʾ may Allah be pleased with him reported that the Prophet ﷺ said: “An undutiful child will not enter Paradise, nor one addicted to intoxicants, nor one who denies Divine Decree.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (27484)، والبزار في كشف الأستار (2182)."},{"num":986,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ثَلَاثَةٌ لَا يَقْبَلُ اللَّهُ لَهُمْ صَرْفًا وَلَا عَدْلًا: عَاقٌّ وَمَنَّانٌ وَمُكَذِّبٌ بِالْقَدَرِ."],"takhrij":"حسن: رواه ابن أبي عاصم في السنة (323)، والبيهقيّ في القضاء والقدر (432)، والطبراني في الكبير (7547) كلّهم من طريق عمر بن يزيد البصريّ، أو النّصريّ، ، عن أبي سلام، عن أبي أمامة، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الإيمان بالقدر","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Ibn Abī ʿĀṣim in al-Sunnah (323), al-Bayhaqī in al-Qaḍāʾ wa al-Qadar (2/699), and al-Ṭabarānī in al-Muʿjam al-Kabīr (8/140).","chapter_en":"What Has Been Reported Concerning Belief in Divine Decree","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالقضاء والقدر","group_en":"Collection of Chapters Concerning Faith in Divine Decree and Predestination","part_no":2,"group_no":12,"chapter_no":1,"content":{"translation":{"en":["Abū Umāmah may Allah be pleased with him reported from the Prophet ﷺ: “There are three from whom Allah will accept neither obligatory nor voluntary deeds: one who is undutiful to his parents, one who reminds others of his favors, and one who denies Divine Decree.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن أبي عاصم في السنة (323)، والبيهقي في القضاء والقدر (432)، والطبراني في الكبير (7547)."},{"num":987,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا يُؤْمِنُ عَبْدٌ حَتَّى يُؤْمِنَ بِأَرْبَعٍ: يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنِّي مُحَمَّدٌ رَسُولُ اللَّهِ بَعَثَنِي بِالْحَقِّ، وَيُؤْمِنُ بِالْمَوْتِ، وَبِالْبَعْثِ بَعْدَ الْمَوْتِ، وَيُؤْمِنُ بِالْقَدَرِ."],"takhrij":"صحيح: رواه الترمذيّ (2145) عن محمود بن غيلان، حدثنا أبو داود، أنبأنا شعبة، عن منصور، عن ربعي بن حراش، عن علي، فذكر مثله.","grade":"صحيح","chapter_ar":"باب ما جاء في الإيمان بالقدر","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Tirmidhī (2145).","chapter_en":"What Has Been Reported Concerning Belief in Divine Decree","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالقضاء والقدر","group_en":"Collection of Chapters Concerning Faith in Divine Decree and Predestination","part_no":2,"group_no":12,"chapter_no":1,"content":{"translation":{"en":["ʿAlī ibn Abī Ṭālib may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “A servant does not believe until he believes in four things: he testifies that there is no deity worthy of worship except Allah and that I am the Messenger of Allah whom He sent with the truth; he believes in death; he believes in resurrection after death; and he believes in Divine Decree.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (2145)."},{"num":988,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا يُؤْمِنُ الْمَرْءُ حَتَّى يُؤْمِنَ بِالْقَدَرِ خَيْرِهِ وَشَرِّهِ."],"takhrij":"حسن: رواه الإمام أحمد (6703) عن أنس بن عياض، حدّثنا أبو حازم، عن عمرو بن شعيب، عن أبيه، عن جدّه، فذكر مثله.","grade":"حسن","chapter_ar":"باب ما جاء في الإيمان بالقدر","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (6703).","chapter_en":"What Has Been Reported Concerning Belief in Divine Decree","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالقضاء والقدر","group_en":"Collection of Chapters Concerning Faith in Divine Decree and Predestination","part_no":2,"group_no":12,"chapter_no":1,"content":{"translation":{"en":["ʿAmr ibn Shuʿayb narrated from his father, from his grandfather, that the Messenger of Allah ﷺ said: “A person does not believe until he believes in Divine Decree—its good and its evil.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (6703)."},{"num":989,"demo":false,"sanad":"","matn":["عَنْ أَبِي الدَّرْدَاءِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لِكُلِّ شَيْءٍ حَقِيقَةٌ، وَمَا بَلَغَ عَبْدٌ حَقِيقَةَ الْإِيمَانِ حَتَّى يَعْلَمَ أَنَّ مَا أَصَابَهُ لَمْ يَكُنْ لِيُخْطِئَهُ، وَمَا أَخْطَأَهُ لَمْ يَكُنْ لِيُصِيبَهُ."],"takhrij":"حسن: رواه الإمام أحمد (27490) عن هشيم، قال: حدّثنا أبو الرّبيع، عن يونس، عن أبي إدريس، عن أبي الدرداء، فذكر مثله.","grade":"حسن","chapter_ar":"باب ما أصاب العبد لم يكن ليخطئه، وما أخطأه لم يكن ليصيبه","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (27490).","chapter_en":"Whatever Befell the Servant Could Never Have Missed Him, and Whatever Missed Him Could Never Have Befallen Him","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالقضاء والقدر","group_en":"Collection of Chapters Concerning Faith in Divine Decree and Predestination","part_no":2,"group_no":12,"chapter_no":2,"content":{"translation":{"en":["Abū al-Dardāʾ may Allah be pleased with him reported that the Prophet ﷺ said: “Everything has a true reality, and a servant does not attain the true reality of faith until he knows that whatever befell him could never have missed him, and whatever missed him could never have befallen him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (27490)."},{"num":990,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، عن النبي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الْعَيْنُ حَقٌّ وَلَوْ كَانَ شَيْءٌ سَابَقَ الْقَدَرَ سَبَقَتْهُ الْعَيْنُ، وَإِذَا اسْتُغْسِلْتُمْ فَاغْسِلُوا."],"takhrij":"صحيح: رواه مسلم في كتاب السلام (2188) من طرق عن مسلم بن إبراهيم، قال: حدّثنا وُهيب، عن ابن طاوس، عن أبيه، عن ابن عباس، فذكر مثله.","grade":"صحيح","chapter_ar":"باب لا شيء يسبق القدر","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2188).","chapter_en":"Nothing Can Precede Divine Decree","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالقضاء والقدر","group_en":"Collection of Chapters Concerning Faith in Divine Decree and Predestination","part_no":2,"group_no":12,"chapter_no":3,"content":{"translation":{"en":["Ibn ʿAbbās may Allah be pleased with them reported that the Prophet ﷺ said: “The evil eye is real. If anything could precede Divine Decree, the evil eye would have preceded it. And when you are asked to wash for its treatment, then wash.”"]}},"tuhfa":{},"full":1,"rep":[11491,11499],"tks":"صحيح: رواه مسلم (2188)."},{"num":991,"demo":false,"sanad":"","matn":["عَنْ أَسْمَاءَ بِنْتِ عُمَيْسٍ قَالَتْ: يَا رَسُولَ اللَّهِ إِنَّ بَنِي جَعْفَرٍ تُصِيبُهُمُ الْعَيْنُ، فَأَسْتَرْقِي لَهُمْ؟ قَالَ: نَعَمْ فَلَوْ كَانَ شَيْءٌ سَابَقَ الْقَدَرَ، سَبَقَتْهُ الْعَيْنُ."],"takhrij":"حسن: رواه الترمذيّ (2059)، وابن ماجه (3510) كلاهما من حديث سفيان بن عيينة، عن عمرو بن دينار، عن عروة بن عامر، عن عبيد بن رفاعة الزُّرقيّ، قال: قالت أسماء، فذكرته.","grade":"حسن","chapter_ar":"باب لا شيء يسبق القدر","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Tirmidhī (2059) and Ibn Mājah (3510).","chapter_en":"Nothing Can Precede Divine Decree","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالقضاء والقدر","group_en":"Collection of Chapters Concerning Faith in Divine Decree and Predestination","part_no":2,"group_no":12,"chapter_no":3,"content":{"translation":{"en":["Asmāʾ bint ʿUmays may Allah be pleased with her said: “O Messenger of Allah, the children of Jaʿfar are affected by the evil eye. Should I seek ruqyah for them?” He replied: “Yes. If anything could precede Divine Decree, the evil eye would have preceded it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (2059)، وابن ماجه (3510)."},{"num":992,"demo":false,"sanad":"","matn":["عَنْ عُبَادَةَ بْنِ الصَّامِتِ أَنَّهُ قَالَ لِابْنِهِ: يَا بُنَيَّ إِنَّكَ لَنْ تَجِدَ طَعْمَ حَقِيقَةِ الْإِيمَانِ حَتَّى تَعْلَمَ أَنَّ مَا أَصَابَكَ لَمْ يَكُنْ لِيُخْطِئَكَ، وَمَا أَخْطَأَكَ لَمْ يَكُنْ لِيُصِيبَكَ، سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ أَوَّلَ مَا خَلَقَ اللَّهُ الْقَلَمَ فَقَالَ لَهُ: اكْتُبْ قَالَ: رَبِّ وَمَاذَا أَكْتُبُ؟ قَالَ: اكْتُبْ مَقَادِيرَ كُلِّ شَيْءٍ حَتَّى تَقُومَ السَّاعَةُ، يَا بُنَيَّ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ مَاتَ عَلَى غَيْرِ هَذَا فَلَيْسَ مِنِّي."],"takhrij":"حسن: رواه أبو داود (4700) عن جعفر بن مسافر الهذليّ، حدّثنا يحيى بن حسّان، حدّثنا الوليد بن رباح، عن إبراهيم بن أبي عبلة، عن أبي حفصة، قال: قال عبادة بن الصّامت لابنه، فذكر الحديث.","grade":"حسن","chapter_ar":"باب أول ما خلق الله القلم وأمره أن يكتب مقادير كل شيء حتى تقوم الساعة","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Abū Dāwūd (4700).","chapter_en":"The First Thing Allah Created Was the Pen, and He Commanded It to Write the Decrees of Everything Until the Hour Is Established","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالقضاء والقدر","group_en":"Collection of Chapters Concerning Faith in Divine Decree and Predestination","part_no":2,"group_no":12,"chapter_no":4,"content":{"translation":{"en":["ʿUbādah ibn al-Ṣāmit may Allah be pleased with him said to his son: “My son, you will never taste the true reality of faith until you know that whatever befell you could never have missed you and whatever missed you could never have befallen you. I heard the Messenger of Allah ﷺ say: ‘Indeed, the first thing Allah created was the Pen. He said to it: “Write.” It said: “My Lord, what shall I write?” He said: “Write the decrees of everything until the Hour is established.”’ My son, I heard the Messenger of Allah ﷺ say: ‘Whoever dies upon anything other than this is not from me.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4700)."},{"num":993,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ أَنَّهُ كَانَ يُحَدِّثُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ أَوَّلَ مَا خَلَقَ اللَّهُ الْقَلَمُ، وَأَمَرَهُ أَنْ يَكْتُبَ كُلَّ شَيْءٍ يَكُونُ."],"takhrij":"صحيح: رواه أبو يعلى (2329) عن أحمد بن جميل المروزيّ، حدّثنا عبدالله بن المبارك، عن رباح بن زيد، عن عمر بن حبيب المكيّ، عن القاسم بن أبي بزة، عن سعيد بن جبير، عن ابن عباس، فذكر مثله.","grade":"صحيح","chapter_ar":"باب أول ما خلق الله القلم وأمره أن يكتب مقادير كل شيء حتى تقوم الساعة","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Yaʿlā (2329).","chapter_en":"The First Thing Allah Created Was the Pen, and He Commanded It to Write the Decrees of Everything Until the Hour Is Established","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالقضاء والقدر","group_en":"Collection of Chapters Concerning Faith in Divine Decree and Predestination","part_no":2,"group_no":12,"chapter_no":4,"content":{"translation":{"en":["Ibn ʿAbbās may Allah be pleased with them used to narrate that the Messenger of Allah ﷺ said: “Indeed, the first thing Allah created was the Pen, and He commanded it to write everything that will occur.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[8196],"tks":"صحيح: رواه أبو يعلى (2329)."},{"num":994,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: أَوَّلُ مَا خَلَقَ اللَّهُ تَعَالَى الْقَلَمُ، فَأَخَذَهُ بِيَمِينِهِ وَكِلْتَا يَدَيْهِ يَمِينٌ . قَالَ: فَكَتَبَ الدُّنْيَا وَمَا يَكُونُ فِيهَا مِنْ عَمَلٍ مَعْمُولٍ بِرٍّ أَوْ فُجُورٍ، رَطْبٍ أَوْ يَابِسٍ، فَأَحْصَاهُ عِنْدَهُ فِي الذِّكْرِ . فَقَالَ: اقْرَؤُوا إِنْ شِئْتُمْ: ﴿هَذَا كِتَابُنَا يَنْطِقُ عَلَيْكُمْ بِالْحَقِّ إِنَّا كُنَّا نَسْتَنْسِخُ مَا كُنْتُمْ تَعْمَلُونَ﴾ [سورة الجاثية: 29]، فَهَلْ تَكُونُ النُّسْخَةُ إِلَّا مِنْ شَيْءٍ قَدْ فُرِغَ مِنْهُ."],"takhrij":"حسن: رواه ابنُ أبي عاصم في السنة (106) عن ابن المصفى، ثنا بقية، حدّثني أرطاة بن المنذر، عن مجاهد بن جبير، عن ابن عمر، فذكر مثله.","grade":"حسن","chapter_ar":"باب أول ما خلق الله القلم وأمره أن يكتب مقادير كل شيء حتى تقوم الساعة","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Ibn Abī ʿĀṣim in al-Sunnah (106).","chapter_en":"The First Thing Allah Created Was the Pen, and He Commanded It to Write the Decrees of Everything Until the Hour Is Established","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالقضاء والقدر","group_en":"Collection of Chapters Concerning Faith in Divine Decree and Predestination","part_no":2,"group_no":12,"chapter_no":4,"content":{"translation":{"en":["Ibn ʿUmar, may Allah be pleased with them, said: I heard the Messenger of Allah ﷺ say: “The first thing Allah Most High created was the Pen. He took it in His right Hand—and both of His Hands are right. It wrote the world and everything that would occur in it of deeds performed: righteousness or wickedness, wet or dry. He recorded it with Him in the Record. Then he said: ‘Recite, if you wish: “This is Our Record, speaking against you with the truth. Indeed, We used to record whatever you did.”’ [Sūrat al-Jāthiyah 45:29] Can a copy be made except from something that has already been completed?”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن أبي عاصم في السنة (106)."},{"num":995,"demo":false,"sanad":"","matn":["عَنْ يَحْيَى بْنِ يَعْمَرَ، قَالَ: كَانَ أَوَّلَ مَنْ قَالَ فِي الْقَدَرِ بِالْبَصْرَةِ: مَعْبَدٌ الْجُهَنِيُّ، فَانْطَلَقْتُ أَنَا وَحُمَيْدُ بْنُ عَبْدِ الرَّحْمَنِ الْحِمْيَرِيُّ، حَاجَّيْنِ أَوْ مُعْتَمِرَيْنِ، فَقُلْنَا: لَوْ لَقِينَا أَحَدًا مِنْ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَسَأَلْنَاهُ عَمَّا يَقُولُ هَؤُلَاءِ فِي الْقَدَرِ، فَوُفِّقَ لَنَا عَبْدُ اللَّهِ بْنُ عُمَرَ بْنِ الْخَطَّابِ دَاخِلًا الْمَسْجِدَ، فَاكْتَنَفْتُهُ أَنَا، وَصَاحِبِي، أَحَدُنَا عَنْ يَمِينِهِ وَالآخَرُ عَنْ شِمَالِهِ، فَظَنَنْتُ أَنَّ صَاحِبِي سَيَكِلُ الْكَلَامَ إِلَيَّ، فَقُلْتُ: أَبَا عَبْدِ الرَّحْمَن، إِنَّهُ قَدْ ظَهَرَ قِبَلَنَا نَاسٌ يَقْرَءُونَ الْقُرْآنَ، وَيَتَقَفَّرُونَ الْعِلْمَ (أَيْ يَطْلُبُونَه)، وَذَكَرَ مِنْ شَأْنِهِمْ، وَأَنَّهُمْ يَزْعُمُونَ أَنْ لَا قَدَرَ، وَأَنَّ الأَمْرَ أُنُفٌ (أَيْ مُسْتَأْنَفٍ، لَمْ يَسْبِقْ بِهِ قَدْرَ، وَلَا عِلْمَ مِنَ اللَّهِ تَعَالَى، وَإِنَّمَا يَعْلَمُهُ بَعْدَ وُقُوعِهِ)؟ قَالَ: فَإِذَا لَقِيتَ أُولَئِكَ، فَأَخْبِرْهُمْ أَنِّي بَرِيءٌ مِنْهُمْ، وَأَنَّهُمْ بُرَآءُ مِنِّي، وَالَّذِي يَحْلِفُ بِهِ عَبْدُ اللَّهِ بْنُ عُمَرَ، لَوْ أَنَّ لِأَحَدِهِمْ، مِثْلَ أُحُدٍ ذَهَبًا، فَأَنْفَقَهُ مَا قَبِلَ اللَّهُ مِنْهُ، حَتَّى يُؤْمِنَ بِالْقَدَرِ، ثُمَّ قَالَ: حَدَّثَنِي أَبِي عُمَرُ بْنُ الْخَطَّابِ، قَالَ: بَيْنَمَا نَحْنُ عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ، إِذْ طَلَعَ عَلَيْنَا رَجُلٌ شَدِيدُ، بَيَاضِ الثِّيَابِ. فَذَكَرَ الْحَدِيثَ بِطُولِهِ، وَفِيهِ: وَتُؤْمِنَ بِالْقَدَرِ خَيْرِهِ وَشَرِّهِ."],"takhrij":"صحيح: رواه مسلم في الإيمان (8) من طرق عن كهمس، عن عبدالله بن بريدة، عن يحيى بن يعمر، فذكره.","grade":"صحيح","chapter_ar":"باب أول من تكلم في القدر","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim in the Book of Faith (8).","chapter_en":"The First Person to Speak in Denial of Divine Decree","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالقضاء والقدر","group_en":"Collection of Chapters Concerning Faith in Divine Decree and Predestination","part_no":2,"group_no":12,"chapter_no":5,"content":{"translation":{"en":["Yaḥyā ibn Yaʿmar said: The first person in Baṣrah to speak in denial of Divine Decree was Maʿbad al-Juhanī. So Ḥumayd ibn ʿAbd al-Raḥmān al-Ḥimyarī and I set out for Ḥajj or ʿUmrah and said: “If only we could meet one of the Companions of the Messenger of Allah ﷺ and ask him about what these people are saying concerning Divine Decree.” We were granted the opportunity to meet ʿAbdullāh ibn ʿUmar may Allah be pleased with them as he was entering the mosque. My companion and I stood on either side of him, one on his right and the other on his left. I thought my companion would leave the speaking to me, so I said: “O Abū ʿAbd al-Raḥmān, some people have appeared among us who recite the Qurʾān and seek deeply after knowledge”—and he mentioned their condition—“yet they claim that there is no Divine Decree and that events occur newly, without having been previously decreed.” He said: “When you meet those people, tell them that I am free of them and they are free of me. By the One by whom ʿAbdullāh ibn ʿUmar swears, if one of them possessed gold equivalent to Mount Uḥud and spent all of it, Allah would not accept it from him until he believed in Divine Decree.” Then he said: “My father, ʿUmar ibn al-Khaṭṭāb may Allah be pleased with him, narrated to me: ‘While we were sitting with the Messenger of Allah ﷺ one day, a man appeared before us whose clothing was intensely white…’” Then he narrated the lengthy ḥadīth, in which occurs: “And that you believe in Divine Decree—its good and its evil.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (8)."},{"num":996,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: جَاءَ مُشْرِكُو قُرَيْشٍ يُخَاصِمُونَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْقَدَرِ، فَنَزَلَتْ: ﴿يَوْمَ يُسْحَبُونَ فِي النَّارِ عَلَى وُجُوهِهِمْ ذُوقُوا مَسَّ سَقَرَ (48) إِنَّا كُلَّ شَيْءٍ خَلَقْنَاهُ بِقَدَرٍ (49)﴾ [سورة القمر: 48، 49]."],"takhrij":"صحيح: رواه مسلم في القدر (2656) من طرق عن وكيع، عن سفيان، عن زياد بن إسماعيل، عن محمد بن عبَّاد بن جعفر المخزوميّ، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن الكلام والمخاصمة والخوض في القدر","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2657).","chapter_en":"The Prohibition of Disputing, Arguing, and Delving Into Divine Decree","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالقضاء والقدر","group_en":"Collection of Chapters Concerning Faith in Divine Decree and Predestination","part_no":2,"group_no":12,"chapter_no":6,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, said: The polytheists of Quraysh came disputing with the Messenger of Allah ﷺ concerning Divine Decree, so the following was revealed: “On the Day they will be dragged into the Fire upon their faces: ‘Taste the touch of Saqar!’ Indeed, We have created everything according to a decree.” [Sūrat al-Qamar 54:48–49]"]}},"tuhfa":{},"full":1,"rep":[1072,13457],"tks":"صحيح: رواه مسلم (2656)."},{"num":997,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ قَالَ: خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى أَصْحَابِهِ، وَهُمْ يَخْتَصِمُونَ فِي الْقَدَرِ، فَكَأَنَّمَا يُفْقَأُ فِي وَجْهِهِ حَبُّ الرُّمَّانِ مِنِ الْغَضَبِ، فَقَالَ: بِهَذَا أُمِرْتُمْ، أَوْ لِهَذَا خُلِقْتُمْ تَضْرِبُونَ الْقُرْآنَ بَعْضَهُ بِبَعْضٍ، بِهَذَا هَلَكَتِ الْأُمَمُ قَبْلَكُمْ.","قَالَ: فَقَالَ عَبْدُ اللَّهِ بْنُ عَمْرٍو: مَا غَبَطْتُ نَفْسِي بِمَجْلِسٍ تَخَلَّفْتُ فِيهِ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، مَا غَبَطْتُ نَفْسِي بِذَلِكَ الْمَجْلِسِ وَتَخَلُّفِي عَنْهُ."],"takhrij":"حسن: رواه ابن ماجه (85) عن علي بن محمد، قال: حدّثنا أبو معاوية، قال: حدّثنا داود بن أبي هند، عن عمرو بن شعيب، عن أبيه، عن جدّه، فذكره.","grade":"حسن","chapter_ar":"باب النهي عن الكلام والمخاصمة والخوض في القدر","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Ibn Mājah (85).","chapter_en":"The Prohibition of Disputing, Arguing, and Delving Into Divine Decree","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالقضاء والقدر","group_en":"Collection of Chapters Concerning Faith in Divine Decree and Predestination","part_no":2,"group_no":12,"chapter_no":6,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ, may Allah be pleased with them, said: The Messenger of Allah ﷺ came out to his Companions while they were disputing concerning Divine Decree. It was as though pomegranate seeds were bursting upon his face from anger. He said: “Is this what you were commanded to do?! Or is this what you were created for?! You are setting one part of the Qurʾān against another! This is how the nations before you were destroyed.”","ʿAbdullāh ibn ʿAmr, may Allah be pleased with them, said: “I never felt happier about having missed a gathering of the Messenger of Allah ﷺ than I felt about having missed that gathering.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (85)."},{"num":998,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أُخِّرَ كَلَامٌ فِي الْقَدَرِ لِشِرَارِ هَذِهِ الْأُمَّةِ."],"takhrij":"حسن: رواه ابن أبي عاصم في السنة (350) عن الحسن بن علي، ثنا أبو عاصم، عن عنبسة، عن ابن شهاب، عن سعيد بن المسيب، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب النهي عن الكلام والمخاصمة والخوض في القدر","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Ibn Abī ʿĀṣim in al-Sunnah (350) and al-Bazzār in Kashf al-Astār (2179).","chapter_en":"The Prohibition of Disputing, Arguing, and Delving Into Divine Decree","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالقضاء والقدر","group_en":"Collection of Chapters Concerning Faith in Divine Decree and Predestination","part_no":2,"group_no":12,"chapter_no":6,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Disputation concerning Divine Decree was delayed until the worst people of this Ummah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن أبي عاصم في السنة (350)، والبزار في كشف الأستار (2179)."},{"num":999,"demo":false,"sanad":"","matn":["عَنْ نَافِعٍ، أَنَّ رَجُلًا أَتَى ابْنَ عُمَرَ فَقَالَ: إِنَّ فُلَانًا يُقْرِأُ عَليْكَ السَّلَامَ قَالَ: إِنَّهُ بَلَغَنِي أَنَّهُ قَدْ أَحْدَثَ، فَإِنْ كَانَ قَدْ أَحْدَثَ فَلَا تُقْرِئْهُ مِنِّي السَّلَامَ، فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: يَكُونُ فِي أُمَّتِي أَوْ فِي هَذِهِ الْأُمَّةِ مَسْخٌ وَخَسْفٌ وَقَذْفٌ، وَذَلِكَ فِي أَهْلِ الْقَدَرِ."],"takhrij":"حسن: رواه الترمذيّ (2152)، وابن ماجه (4061) كلاهما عن محمد بن بشار، حدّثنا أبو عاصم، حدّثنا حيوة بن شريح، أخبرني أبو صخر، حدّثني نافع، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في ذم القدرية","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Tirmidhī (2152) and Ibn Mājah (4061).","chapter_en":"What Has Been Reported Concerning the Censure of the Qadariyyah","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالقضاء والقدر","group_en":"Collection of Chapters Concerning Faith in Divine Decree and Predestination","part_no":2,"group_no":12,"chapter_no":7,"content":{"translation":{"en":["Nāfiʿ reported: A man came to Ibn ʿUmar may Allah be pleased with them and said: “So-and-so sends you greetings of peace.” Ibn ʿUmar replied: “It has reached me that he has introduced an innovation. If he has indeed done so, then do not convey my greetings of peace to him, for I heard the Messenger of Allah ﷺ say: ‘There will occur in my Ummah—or in this Ummah—transformation, sinking into the earth, and pelting from above, and that will be among the people of Divine Decree.’”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[15989],"tks":"حسن: رواه الترمذي (2152)، وابن ماجه (4061)."}]);